L["Intro Text"] = "有些故事始於一封信、一則傳聞、一名失蹤的旅人，或是在城鎮邊緣被人低聲道出的一個名字。\n\nStory Mode 會收集這些故事，並逐章為你展開：從哪裡開始、還有什麼在等著你，以及你已經見證過的一切。\n\n完成的章節會保存在你的日誌中，靜靜記錄你遇見的人、面對的險境，以及值得銘記的名字。\n\n重溫你的冒險。"
L["Intro Text Complete"] = "所有標記的故事都已完成。信件、警告、失落的名字、隱身幕後的贊助者、地城之門、家族舊債與奇異的寶藏，如今全都收錄在你的日誌之中。\n\n這絕非易事。你追隨每一條線索，回應每一次召喚，將每個章節走到最後，直到零散的傳聞化為一份由你親手掙得的功績紀錄。\n\n就讓這本日誌作為證明：這些故事不只是被你發現而已。它們被完成、被銘記，也成為你冒險的一部分。"

