L["Scarlet Link Compare Format"] = "對方的帳簿：|cffe62929%d|r。你的：|cffffd200%d|r。"
L["Scarlet Ledger Korgal"] = "邁文‧考加爾曾為喪鐘鎮的死者捎來消息。他的死訊，卻不會有人替他傳遞。"
L["Scarlet Ledger Perrine"] = "派瑞恩隊長曾在布瑞爾近在眼前之處操練部下。如今操練已經停止。"
L["Scarlet Ledger Vachon"] = "瓦松隊長的營地依然矗立，營中卻已沒有任何東西還站著。"
L["Scarlet Ledger Melrache"] = "麥拉其隊長曾向部下保證，聖光會庇護他們。聖光卻只是旁觀。"
L["Scarlet Ledger Balnazzar"] = "「大十字軍」不過是一件法袍。你已經見過穿著它的是什麼東西。佈道聲卻依舊迴盪。"
L["Scarlet Ledger Radley"] = "獵人萊德雷追蹤過這片田野上每一個會動的東西。他卻從沒聽見你靠近。"
L["Scarlet Ledger Durgen"] = "騎士杜爾根在壁爐谷的旗幟下出征。他的馬回來了，他卻沒有。"
L["Scarlet Ledger Abbendis"] = "阿比迪斯將軍躲在高牆後統領提爾之手。高牆總有盡頭。"
L["Scarlet Ledger BenedictusVoss"] = "高階祭司本尼迪塔斯‧佛斯將自己的女兒獻給了信條。那筆債，輪不到你來討。"
L["Scarlet Ledger Thalnos"] = "血法師薩爾諾斯守著他教團最古老的秘密。墳墓卻沒替他守住任何一個。"
L["Scarlet Ledger Vishas"] = "審問者韋沙斯再也不會提問了。你卻依然聽得見沃瑞爾的聲音。"
L["Scarlet Ledger Loksey"] = "馴犬者洛克希死在他的獵犬之間。牠們為他哀悼，比十字軍更加真心。"
L["Scarlet Ledger Doan"] = "秘法師杜安守護著不准任何人閱讀的書。如今圖書館更安靜了。"
L["Scarlet Ledger Herod"] = "赫洛德，血色勇士。新兵們曾高呼他的名字。如今已無人歡呼。"
L["Scarlet Ledger Mograine"] = "雷諾‧莫格萊尼倒在他自己的祭壇前。無論他想贖的是什麼罪，都還不夠。"
L["Scarlet Ledger Fairbanks"] = "高階審判官法爾班克斯被封在假石牆後。十字軍總是把真相埋葬兩次。"
L["Scarlet Ledger Whitemane"] = "她呼喚聖光，聖光回應了她。你已經不再追問為什麼。"
L["Scarlet Ledger Courier"] = "紅衣信差的信，如今再也送不到任何地方。"
L["Scarlet Ledger Demetria"] = "血色神諭者預見了許多事。卻沒預見這條路，也沒預見你。"
L["Scarlet Section 100"] = "一個人的戰爭"
L["Scarlet Section 250"] = "節奏"
L["Scarlet Section 500"] = "鏡子"
L["Scarlet Section 1000"] = "祭司之女"
L["Scarlet Tab Body 250"] = "這場戰爭如今有了節奏。你知道狂熱者的禱詞在半途中斷時是什麼聲音。你知道他們巡邏哪些道路，又已經清空了哪些農舍。在提里斯法的某處，那位老婦人的提燈已經熄滅——你經過它曾經亮著的那扇窗台，腳步卻沒有停下。\n\n你告訴自己，這些算術依然有意義。你只是不再核對總數了。"
L["Scarlet Tab Body 500"] = "你已不再記得那些面孔。紅色外袍、銀色烈焰、被打斷的禱詞——這些細節一出現就已自動歸檔。讓你不安的不是數字，而是殺戮變得如此乾淨俐落：不再有憤怒，也不再有悲傷。只剩下帳簿，等著被結清。\n\n懷特邁恩的狂熱者相信，篤定就等於正義。在最糟的夜晚，你還來不及說出兩者的差別，就已沉沉睡去。"
L["Scarlet Tab Body 1000"] = "十字軍不只招募信徒，也親手養育他們。在你清空的營地裡、在你沒有留下的信件中，有個名字開始浮現：一位祭司的女兒，在修道院的高牆後長大，被教導焚燒死者時絕不退縮。莉莉安。她的父親，高階祭司本尼迪塔斯‧佛斯，像其他人繳納什一稅那樣，把自己的孩子獻給了信條。據說她能雙手合十、宛如祈禱般殺死一個人。據說她從未問過一次為什麼。\n\n總有一天，十字軍會看著她，看見它在每個無法利用之人身上看見的東西：感染。那天發生的一切都不會是你造成的——但你會比世上任何活著的人都更明白。\n\n記住佛斯這個名字。帳簿和它之間還沒結束。你也一樣。"
L["Scarlet Tab Body"] = "你並不是一開始就想與他們為敵。\n\n一切始於無聲之間。你碰巧經過提里斯法一間被燒毀的農舍。一位老婦人對著她為兒子點亮的提燈哭泣。她說，他穿上了紅色外袍，從此不再回她的信。十字軍教了他一段新的禱詞，而那段禱詞裡容不下她的名字。\n\n接著，是一個躲在南海鎮外蘆葦叢裡的男孩，頭髮上沾著禮拜堂的灰燼。然後是一名在路上被正義之劍砍傷、血流不止的商人。再來是一個倒在自家門前的農夫。你告訴自己這只是巧合。但每當一面紅色旗幟映入眼簾，你的手總比你的念頭先動。每砍倒一名血色十字軍，就越不像在打仗，而更像在算術——向一個披著銀色光芒的謊言，一筆一筆清算欠債。\n\n你沒有在任何信裡寫下這些。沒有指揮官指派你這麼做。沒有命令，沒有特許，沒有誓言。只有一筆默默記下、不斷增長的帳。\n\n你也是一名「血色十字軍」，只是取這個詞更古老的含義：不是他們的一員，而是與他們為敵的那一個。你砍倒的每一件紅色外袍，都是又一個被添進帳簿的名字，而那本帳簿，只有你讀得懂。"

