L["A \"Humble\" Request"] = "「謙卑」的請求"
L["A Beastly Expedition"] = "狂亂的探險"
L["A Better Future"] = "更好的未來"
L["A Big Score"] = "大幹一場"
L["A Bit of Chaos"] = "一丁點混亂"
L["A Bit of Espionage"] = "一點諜報"
L["A Bitter Reunion"] = "苦澀的重聚"
L["A Body of Evidence"] = "肉體證據"
L["A Brewing Situation"] = "釀酒情況"
L["A Burden Shared"] = "有難同當"
L["A Burning Distraction"] = "縱火作亂"
L["A Challenge From Our Enemies"] = "來自敵人的挑戰"
L["A Change of Seasons"] = "季節更迭"
L["A Chilling Summons"] = "冰冷的召喚"
L["A Cold Front Approaches"] = "冷鋒逼近"
L["A Conjuror's Duty"] = "咒術師的職責"
L["A contagion strikes the Broken Shore. Cure the plague, recruit Aelthalyste, and seek the High Priest's Seeker mount."] = "一場疫病侵襲了破碎海岸。治癒瘟疫、招募艾薩萊斯特，並尋找高階祭司的追尋者坐騎。"
L["A courier brought word of Thas'dorah — the ancestral bow of the Windrunner family, carried by Alleria into the Twisting Nether and lost for decades. You followed the trail through ancient elven ruins, fighting off demons who sought to claim its power. The bow sang in your hands when you drew it, as if it had been waiting for a worthy archer all along."] = "一名信差帶來了薩斯多拉的消息——那是風行者家族的祖傳之弓，由艾蘭里亞帶入扭曲虛空後失落了數十年。你循著線索穿越古老的精靈遺跡，擊退企圖奪取其力量的惡魔。當你拉開弓弦時，這把弓在你手中歌唱，彷彿它一直都在等待一位配得上它的弓箭手。"
L["A Courteous Guest"] = "謙恭來客"
L["A Covert Operation"] = "秘密行動"
L["A cryptic summons led you into the sewers beneath Dalaran, where Lord Jorach Ravenholdt revealed The Uncrowned — a secret order of assassins operating outside the law. You proved your worth in the shadows and claimed a blade befitting the order's newest operative."] = "一則隱晦的召喚將你帶到達拉然地底的下水道，喬拉齊‧拉文霍德領主在那裡向你揭露了無冕者——一個遊走於法律之外的秘密刺客組織。你在暗影中證明了自己的價值，並取得一把配得上組織最新成員的利刃。"
L["A Culling of Souls"] = "靈魂獻祭"
L["A Curious Contagion"] = "奇怪的疫病"
L["A curious contagion swept the Broken Shore — a plague that twisted both body and spirit. Aelthalyste, a banshee who had rediscovered her faith, helped you trace the disease to its source, craft a cure, and administer it to the fallen. With the contagion contained and Aelthalyste as your newest champion, you answered a final call to the Sunken Vault, where a creature of pure Light awaited — the High Priest's Seeker, a mount that would carry you above the battlefield."] = "一場奇怪的疫病席捲了破碎海岸——這種瘟疫同時扭曲了肉體與靈魂。重拾信仰的女妖艾薩萊斯特協助你追查疫病源頭、調製解藥，並為倒下的人施藥。疫病受到控制，艾薩萊斯特也成了你最新的勇士，你隨後回應了最後一次召喚，前往沉沒寶庫，一隻純粹由聖光構成的生物正在那裡等候——高階祭司的追尋者，一匹將載你翱翔於戰場之上的坐騎。"
L["A Cycle of Hatred"] = "憎恨的輪迴"
L["A damaged Titan Keeper has been protecting the swamp's darkest secret — a proto-god of blood and shadow sealed beneath the earth."] = "一位受損的泰坦看守者一直守護著這片沼澤最黑暗的秘密——一個被封印在地底、由鮮血與暗影構成的原始神祇。"
L["A Dance With Dragons"] = "與龍共舞"
L["A Daring Rescue"] = "即刻救援"
L["A dark curse has fallen over Drustvar. Lord Waycrest has vanished, his lady has withdrawn behind manor walls, and old stories about witches have begun walking through the woods again.\n\nJoin Lucille Waycrest and the Order of Embers as they follow the coven's trail through cursed villages, haunted fens, and a land where buried grudges have a way of clawing back to the surface."] = "黑暗的詛咒籠罩了佐司瓦。威奎斯特領主下落不明，他的夫人退居莊園高牆之後，而那些關於女巫的古老故事，又開始在林間遊蕩。\n\n加入露西爾‧威奎斯特與燼火會，追隨巫團的蹤跡，穿越受詛咒的村莊與鬧鬼的沼地，走進一片被埋藏的宿怨總會爬回地表的土地。"
L["A Daughter's Embrace"] = "女兒的擁抱"
L["A Deadly New Ally"] = "致命的新盟友"
L["A Defias plot has surfaced inside Stormwind's own walls, and Master Shaw needs someone he can trust to follow it to the source. The old grievances that shaped the Deadmines have not vanished just because the kingdom moved on.\n\nTrace the conspiracy through Stormwind's streets and forgotten debts, and decide what kind of human history is worth honoring when the past asks to be heard again."] = "迪菲亞的陰謀在暴風城的城牆內浮上檯面，蕭大師需要一個值得信任的人追查到底。造就死亡礦坑的那些宿怨，並沒有因為王國向前邁進就此消失。\n\n循著陰謀穿越暴風城的街道與被遺忘的舊債，並在過去再次要求被聆聽之時，決定哪一段人類歷史值得尊崇。"
L["A Desecrated Temple"] = "被褻瀆的神殿"
L["A Display of Power"] = "展示權力"
L["A dying sprite's plea reveals mogu rituals at the Terrace of Ten Thunders and the spirits trapped beneath them."] = "一隻垂死小精靈的懇求，揭露了魔古族在十方雷殿進行的儀式，以及被囚禁在其下的靈魂。"
L["A Final Offer"] = "最後提議"
L["A Fitting Reward"] = "合適的獎勵"
L["A Forlorn Hope"] = "微弱的希望"
L["A Friend of the Frogs"] = "青蛙之友"
L["A Friendly Accord"] = "好心提議"
L["A Gathering of Champions"] = "勇士雲集"
L["A girl is singing by herself at an empty homestead. She asks you to find her stuffed animals for a tea party. As you collect each one, she recites little rhymes about what happened to the people who used to live here. The rhymes are not comforting."] = "一個女孩獨自在空無一人的農莊裡唱歌。她請你幫忙找回她的布偶，好舉辦一場下午茶會。每當你找到一隻，她就會念出一段小小的童謠，講述曾經住在這裡的人們遭遇了什麼。那些童謠一點也不令人安心。"
L["A Glade Defense"] = "林地防禦"
L["A Glimpse of Terror"] = "一窺恐懼"
L["A Glorious Reunion"] = "凱旋歸來"
L["A goblin named Patch and a crew of demolitions experts blast a way through the blood troll defenses."] = "一個名叫派奇的哥布林帶著一群爆破專家，炸開了一條穿過血食人妖防線的路。"
L["A Godly Invitation"] = "誠摯邀請"
L["A Golden Ticket"] = "金色信箋"
L["A Grim Portent"] = "恐怖惡兆"
L["A Growing Crisis"] = "惡化的危機"
L["A Hero Remains"] = "英雄尚存"
L["A Hero's Weapon"] = "適合英雄的武器"
L["A hooded figure is paying coin inside the Scarlet Halls — silver for Scarlet blood. She wants their membership records. She calls herself the Hooded Crusader, and she is very thorough."] = "一個戴著兜帽的身影在血色大廳裡出錢懸賞——以白銀換取血色十字軍的血。她想要他們的成員名冊。她自稱戴頭罩的十字軍，而且做事非常徹底。"
L["A hooded priestess summons you to Netherlight Temple, where Alonsus Faol — the founder of the priesthood — reveals himself."] = "一名戴著兜帽的女祭司召喚你前往虛空之光神殿，牧師體系的創始者阿隆索斯‧法奧在那裡現身。"
L["A Humble Offering"] = "微薄的供品"
L["A Hungry Heritage"] = "飢餓的遺產"
L["A Legend You Can Hold"] = "手握傳說兵器"
L["A Lesson in Humility"] = "一堂謙遜的課程"
L["A Lesson in Witch Hunting"] = "獵巫課程"
L["A Light in the Darkness"] = "闇境明燈"
L["A Line in the Sand"] = "狂沙陣線"
L["A little girl stands alone at Glenbrook Homestead, singing a nursery rhyme about her empty village. The chimneys are still warm, the tables are still set, and the silence feels much too fresh.\n\nShe only wants help preparing a tea party: a few toys, a missing cat, and one more guest. In Drustvar, even the smallest errands can carry a shadow longer than the road ahead."] = "一個小女孩獨自站在谷溪村，唱著一首關於她空蕩村莊的童謠。煙囪還是溫的，餐桌還擺著餐具，那份寂靜卻新得令人不安。\n\n她只想要有人幫忙準備一場下午茶會：幾件玩具、一隻走失的貓，還有再一位客人。在佐司瓦，就連最小的差事，也可能拖著比前路更長的陰影。"
L["A Local Guide"] = "當地嚮導"
L["A Long Walk"] = "漫漫長路"
L["A Mage's Weapon"] = "法師的武器"
L["A Magical Glow"] = "魔法光芒"
L["A Mark For A Protector"] = "保衛者的印記"
L["A Matter of Finesse"] = "巧技神工"
L["A Message From Ly'leth"] = "來自黎利斯的訊息"
L["A Message From Our Enemies"] = "來自敵人的訊息"
L["A Message of Blood and Fire"] = "血與火的訊息"
L["A Mile in My Shoes"] = "穿我的鞋走一哩路"
L["A More Wretched Hive of Scum and Villainy"] = "更多混帳和惡棍的巢穴"
L["A mysterious courier delivers an urgent summons to the sewers beneath Dalaran, where a secret order of assassins watches from the shadows."] = "一名神秘的信差送來緊急召喚，要你前往達拉然地底的下水道，一個秘密刺客組織正在那裡的暗影中注視著一切。"
L["A mysterious paladin appeared with word of the Silver Hand — the holy mace wielded by the first paladins of Lordaeron. You followed the trail through ancient crypts and sacred sites, facing trials that tested your faith as much as your strength. The Silver Hand pulsed with warmth when you finally held it, and the spirits of the original knights seemed to nod in approval."] = "一位神秘的聖騎士帶來了白銀之手的消息——那是羅德隆第一批聖騎士揮舞過的聖錘。你循著線索穿越古老的墓穴與聖地，面對既考驗信仰、也考驗力量的試煉。當你終於握住白銀之手時，它散發出溫暖的脈動，最初那些騎士的靈魂似乎也點頭表示認可。"
L["A mysterious priestess led you through a portal to Netherlight Temple, a sanctuary floating in the Twisting Nether between the forces of Light and Void. There, Alonsus Faol — the man who had founded the original priesthood of Lordaeron — revealed he had survived as an undead, guiding the faith from the shadows for centuries. Prophet Velen stood beside him, and together they asked you to lead a new Conclave. Calia Menethil and High Priestess Ishanah pledged as your first champions."] = "一名神秘的女祭司帶你穿過傳送門，來到虛空之光神殿——一座漂浮在扭曲虛空中、介於聖光與虛空兩股力量之間的聖所。在那裡，羅德隆最初牧師體系的創始者阿隆索斯‧法奧揭露，他以不死之身存活了下來，數百年來一直在暗中引導著信仰。預言者費倫站在他身旁，兩人請你領導新的議會。卡莉雅‧米奈希爾與高階祭司依莎娜宣誓成為你的首批勇士。"
L["A Nation Divided"] = "王國分裂"
L["A Nation United"] = "團結的王國"
L["A New Beginning"] = "新的開始"
L["A New Order"] = "新的組織"
L["A New Tradition"] = "全新傳統"
L["A New Vision"] = "新的幻象"
L["A Pact of Necessity"] = "必要的盟友"
L["A Pact With Death"] = "與死亡的契約"
L["A Particularly Potent Potion"] = "特別強效的藥水"
L["A People in Need of Healing"] = "需要治癒的人民"
L["A People Shattered"] = "破碎之民"
L["A Perfect Match"] = "絕配"
L["A Personal Request"] = "私人要求"
L["A pirate legend speaks of cursed cutlasses buried with their last captain. Fleet Admiral Tethys knows the way."] = "海盜傳說中提到，一對受詛咒的彎刀與它們最後的船長一同埋葬。艦隊上將瑟希斯知道該怎麼去。"
L["A Plea to Revendreth"] = "向瑞文崔斯求助"
L["A Plea to the Harvesters"] = "給收割者的請求"
L["A Promise of Earth"] = "大地的誓言"
L["A Proper Disguise"] = "上流偽裝"
L["A Proper Weapon"] = "適當的武器"
L["A Pungent Solution"] = "我加了洋蔥"
L["A Re-Warding Effort"] = "結界重啟效應"
L["A Reflection of Truth"] = "真相的倒影"
L["A Revealing Missive"] = "信中玄機"
L["A Ring Reforged"] = "重整議會"
L["A Ring Unbroken"] = "重塑陶土議會"
L["A Royal Escort"] = "護送皇室"
L["A Royal Key"] = "皇家鑰匙"
L["A Scarlet Letter"] = "血色書信"
L["A Second Weapon"] = "第二件武器"
L["A secret order of rogues operates from the shadows beneath Dalaran. The Uncrowned do not rule kingdoms, but they know where every kingdom keeps its secrets.\n\nAs the order's newest blade in the dark, gather legendary tools, follow a conspiracy through trusted halls, and learn who can still be trusted when everyone is trained to lie."] = "一個盜賊秘密組織在達拉然地底的暗影中運作。無冕者不統治任何王國，卻知道每個王國把秘密藏在哪裡。\n\n身為組織中最新的暗影之刃，你將蒐集傳奇工具，追查一樁滲透進可信殿堂的陰謀，並在每個人都受過說謊訓練的世界裡，弄清楚還有誰值得信任。"
L["A secret society of rogue mages is hoarding dangerous knowledge. Infiltrate their ranks with Ravandwyr and Esara Verrinde."] = "一群叛離的法師組成秘密結社，私藏危險的知識。與羅樊德威和伊薩菈‧薇琳德一同潛入他們之中。"
L["A Short Fuse"] = "一觸即發"
L["A Signal in Storm Peaks"] = "風暴群山的訊號"
L["A Simple Experiment"] = "簡單的實驗"
L["A Simple Plan"] = "簡單的計畫"
L["A Slight Detour"] = "繞個路"
L["A Small Retreat"] = "前往烈日石居"
L["A Sound Plan"] = "周全的計畫"
L["A Special Delivery"] = "特別快遞"
L["A Steady Ballast"] = "穩固的後盾"
L["A Steady Hand"] = "穩健的手"
L["A Stroll Through a Cemetery"] = "墓地的閒逛"
L["A Strong Back"] = "堅強的背"
L["A Strong Right Hand"] = "得力助手"
L["A Summon to Orgrimmar"] = "奧格瑪的召見"
L["A Summons From Moonglade"] = "來自月光林地的傳喚"
L["A Tale of Valor"] = "英勇的故事"
L["A Taste of Freedom"] = "自由的滋味"
L["A Tea Party"] = "一場下午茶會"
L["A Terrible Loss"] = "可怕的損失"
L["A Test of Endurance"] = "耐力試煉"
L["A Thirst For Blood"] = "嗜血渴望"
L["A Thorn in Our Side"] = "我們的眼中釘"
L["A Time of Revelation"] = "揭曉時刻"
L["A Tribute for Death"] = "獻給死亡的供品"
L["A True Loa Feast"] = "真正的羅亞盛宴"
L["A Tundra Conundrum"] = "凍原難題"
L["A United Force"] = "團結的力量"
L["A United Front"] = "聯合戰線"
L["A val'kyr claims you worthy of Odyn's attention. You ascend to Skyhold, the warrior paradise above the clouds, and take up a weapon of legend."] = "一位華爾琪宣稱你值得歐丁關注。你登上擎天堡——雲端之上的戰士樂土，並拿起一把傳奇武器。"
L["A Very Special Kind of Fuel"] = "一種很特殊的燃料"
L["A Visit to the Doctor"] = "探訪博士"
L["A Visit with Lorewalker Cho"] = "與博學行者阿洲的會面"
L["A Voice in the Dark"] = "黑暗中的聲音"
L["A Walk with Ghosts"] = "與幽魂同行"
L["A Warrior's Death"] = "戰士之死"
L["A Way Out"] = "脫逃之路"
L["A Weapon of Old"] = "古老的武器"
L["A Weather Eye"] = "獵鷹之眼"
L["A Well Placed Portal"] = "定位精確的傳送門"
L["A Window to the Past"] = "往事追憶"
L["A Worthy Blade"] = "絕世武器"
L["A Worthy Offering"] = "誠心的祭品"
L["A'dal"] = "阿達歐"
L["Abby has vanished. You find a village register — nearly every name crossed out. Three people may still be alive: the Hayeses and Samuel Hawthorne. They are not. Then Abby reappears, lights the candles, pours the tea, and introduces the last guest."] = "艾比不見了。你找到一本村莊名冊——幾乎每個名字都被劃掉了。可能還有三個人活著：海斯夫婦和山繆‧霍桑。但他們都已不在人世。接著艾比再度現身，點亮蠟燭、倒好茶，介紹最後一位客人。"
L["Abby Lewis"] = "艾比‧路易斯"
L["Abby Lewis stood alone at Glenbrook Homestead, singing softly to herself. The houses were abandoned. The village was silent. She said she just wanted friends for a tea party — three stuffed animals: Mr. Munchykins, Trunksy, and Mayor Striggs. You found them, each one near a place where something had clearly gone very wrong. Abby appeared each time to recite a cheerful little rhyme. The rhymes were about the dead."] = "艾比‧路易斯獨自站在谷溪村，輕聲對自己唱歌。房屋已遭遺棄，村莊一片死寂。她說她只是想找朋友來參加下午茶會——三隻布偶：嚼嚼先生、象鼻寶和史崔格斯鎮長。你找到了它們，每一隻都在某個顯然出了大事的地方附近。每一次，艾比都會出現，念一段歡快的小童謠。那些童謠講的都是死者。"
L["Above the ice, at the roof of the world, the Frozen Throne waits. The Ashen Verdict — Argent Crusade and Ebon Blade, bound by a single purpose — stands at the citadel's door. Highlord Tirion Fordring lifts the Ashbringer. Every victory in Northrend, every fallen soldier, every mile of ground bought in blood has led here. One way or another, the reign of Arthas Menethil ends at the summit."] = "在冰原之上、世界之巔，冰封王座靜靜等待。灰燼裁決軍——銀白十字軍與黯刃騎士團為了同一個目標而結盟——就站在城塞門前。大領主提里奧‧弗丁高舉灰燼使者。北裂境的每一場勝利、每一名倒下的士兵、每一里以鮮血換來的土地，都通往這裡。無論結局如何，阿薩斯‧米奈希爾的統治都將在峰頂終結。"
L["Absalan the Pious"] = "虔誠的亞柏薩倫"
L["Absolon"] = "阿布撒隆"
L["Ace Pilot Stormcog"] = "王牌飛行員風輪"
L["Acherus / Broken Isles"] = "亞榭洛 / 破碎群島"
L["Acid Beats Paper"] = "酸液能贏紙張"
L["Acid Rain"] = "酸雨"
L["Actions on Azeroth"] = "艾澤拉斯總動員"
L["Additional Accoutrements"] = "額外配備"
L["Admiral Taylor"] = "泰勒上將"
L["Advancing the War Effort"] = "增加戰爭援助"
L["Advisor Belgrum"] = "顧問貝爾格拉姆"
L["Advisor Sevel"] = "預言者沙費歐"
L["Aegira"] = "艾綺菈"
L["Aegrim's Study"] = "艾格林的書房"
L["Aelthalyste"] = "艾薩萊斯特"
L["Aerylia"] = "艾蕊莉雅"
L["Aethas Sunreaver"] = "埃薩‧奪日者"
L["After Baine's rescue, the Horde fractured completely. Some followed Saurfang to Razor Hill, others remained loyal to Sylvanas in Orgrimmar. The stage was set for the final confrontation — not between Alliance and Horde, but within the Horde itself."] = "貝恩獲救後，部落徹底分裂。有些人追隨薩魯法爾前往剃刀嶺，其他人則留在奧格瑪效忠希瓦娜斯。最終對決的舞台已經就緒——不是聯盟與部落之間，而是部落內部。"
L["After the fall of Lordaeron, Saurfang had surrendered to the Alliance rather than flee with Sylvanas. Now Nathanos was dispatched to retrieve him — or ensure he stayed quiet. You tracked the old orc through layers of Alliance intelligence, pieced together where he was held, and extracted him. Saurfang walked out of Stormwind on his own two feet, not as anyone's prisoner. He thanked Nathanos without warmth. Whatever he was planning, it wasn't a return to Sylvanas's service."] = "羅德隆淪陷後，薩魯法爾選擇向聯盟投降，而非與希瓦娜斯一同撤退。如今納薩諾斯奉命把他帶回來——或確保他永遠閉嘴。你循著層層聯盟情報追蹤這名老獸人，拼湊出他被關押的地點，並將他救了出來。薩魯法爾靠著自己的雙腳走出暴風城，不是任何人的囚犯。他向納薩諾斯道謝，語氣毫無溫度。無論他在計畫什麼，都不是重新為希瓦娜斯效力。"
L["Against Magatha's Will"] = "違背瑪加薩的意願"
L["Against the Giants"] = "抵抗巨人族"
L["Agent Render"] = "探員倫德"
L["Aggra"] = "阿格拉"
L["Agmar's Hammer"] = "阿格瑪之錘"
L["Agony Abounds"] = "痛苦無邊"
L["Aka'magosh"] = "祝福你與你的同伴"
L["Alchemist Korlya"] = "鍊金師寇里拉"
L["Aldrachi Warblades"] = "奧達奇戰刃"
L["Alexstrasza the Life-Binder"] = "『生命守縛者』雅立史卓莎"
L["All Aboard!"] = "全體登船！"
L["All Along the Waterways"] = "水道漫延"
L["All Hail Roanauk!"] = "全體向隆諾克致敬!"
L["All In"] = "背水一戰"
L["All the threads came together when the Legion launched a full assault on Dalaran itself, breaching the Violet Hold with demonic forces. Halduron Brightwing helped you forge new weapons and prepare defenses, while Shandris Feathermoon rallied reinforcements. You led the Unseen Path into the Violet Hold and faced Hakkar the Houndmaster in a battle that shook the city. When the demon fell, Emmarel Shadewarden bestowed upon you the title of Huntmaster — the highest honor the Unseen Path could give."] = "當軍團對達拉然本身發動全面進攻、以惡魔大軍攻破紫羅蘭堡時，所有線索終於匯聚在一起。赫杜倫‧亮翼協助你打造新武器並整備防禦，珊蒂斯‧羽月則召集援軍。你率領隱秘之道進入紫羅蘭堡，在一場撼動全城的戰鬥中對上『馴犬者』哈卡爾。惡魔倒下後，艾瑪芮爾‧影衛授予你「狩獵大師」的頭銜——這是隱秘之道所能給予的最高榮譽。"
L["All We Can Spare"] = "最後餘力"
L["Allari the Souleater"] = "『噬魂者』艾萊莉"
L["Allegiance of Flame"] = "忠於烈焰"
L["Alliance"] = "聯盟"
L["Alliance city call-up"] = "聯盟主城徵召"
L["Allies of the Light"] = "聖光的盟友"
L["Alonsus Faol"] = "阿隆索斯‧法奧"
L["Alonsus Faol sensed whispers in the Void — disturbances emanating from Azsuna that threatened the balance of Netherlight Temple itself. Prophet Velen sent his best: Zabra Hexx, a shadow priest of the Darkspear, and Yalia Sagewhisper, a Pandaren healer of quiet wisdom. Together you investigated the source, dealing with murloc mind control and disrupted ley lines. Both proved their worth and joined your Conclave as champions."] = "阿隆索斯‧法奧察覺虛空中傳來低語——源自艾蘇納的擾動，威脅著虛空之光神殿本身的平衡。預言者費倫派出了他最優秀的人選：暗矛部族的暗影牧師薩布拉‧海克斯，以及沉靜睿智的熊貓人治療者雅里亞‧賢語者。你們一同追查源頭，處理魚人的精神控制與遭到擾亂的地脈。兩人都證明了自身的價值，並以勇士身分加入你的議會。"
L["Alonsus Faol spoke of Natalie Seline — a brilliant priest who had studied the Void so deeply that it had consumed her. She was trapped in a shadow realm between worlds, and only you could reach her. With Micah Belford guiding you through the darkness, you entered the Void itself and found Seline — transformed, but not lost. She returned to the Conclave carrying shadows that whispered secrets even the Light could not reveal."] = "阿隆索斯‧法奧提到了娜塔莉‧瑟琳——一位才華洋溢的牧師，她對虛空的研究太過深入，最終被虛空吞噬。她被困在世界之間的暗影領域，只有你能接觸到她。在米佳‧貝福德的引導下，你穿越黑暗，踏入虛空本身，找到了瑟琳——她已經改變，卻沒有迷失。她回到議會，身上的暗影低語著連聖光都無法揭示的秘密。"
L["Alonsus Faol spoke of T'uure — a crystal of pure Light created by the naaru themselves, said to be a beacon that could pierce any darkness. You followed a vindicator's plea to its resting place and fought through the shadows to claim it. When T'uure's light filled the room, every wound healed, every doubt faded, and the darkness recoiled."] = "阿隆索斯‧法奧提到了圖雷——一顆由那魯親手創造、純粹由聖光構成的水晶，據說是一座能穿透任何黑暗的燈塔。你循著一位復仇者的懇求來到它的安息之地，殺出暗影重圍將它取回。當圖雷的光芒充滿整個房間時，所有傷口癒合，所有疑慮消散，黑暗也隨之退縮。"
L["Alpha Bat"] = "蝙蝠群首"
L["Already Among Us"] = "滲透進來的敵人"
L["Altar Keeper Biehn"] = "祭壇看守者畢恩"
L["Aluneth, Greatstaff of the Magna"] = "亞魯涅斯，尊者之杖"
L["Amal'thazad"] = "艾默薩札德"
L["Amal'thazad's Message"] = "艾默薩札德的訊息"
