L["Ammunition Acquisition"] = "獲取彈藥"
L["Among Us"] = "有內鬼"
L["Amped for Revolt!"] = "大反擊!"
L["An Air of Worry"] = "令人擔憂的氣味"
L["An Airtight Alibi"] = "完美的不在場證明"
L["An Ample Supply"] = "綽綽有餘"
L["An Ancient Legend"] = "古老的傳說"
L["An ancient vrykul artifact holds the key to unmasking the enemy. The search leads through the haunted halls of Black Rook Hold."] = "一件古老的維酷人神器握有揭穿敵人真面目的關鍵。搜尋之路將穿越玄鴉堡鬧鬼的廳堂。"
L["An Artificer's Appeal"] = "工藝師的請求"
L["An eagle leads you to Trueshot Lodge, where the Unseen Path — an ancient order of hunters — calls you to serve as champion."] = "一隻老鷹引領你來到神獵廳，古老的獵人組織隱秘之道在那裡召喚你擔任他們的勇士。"
L["An Elven Problem"] = "精靈的麻煩"
L["An End And A Beginning"] = "開頭與尾聲"
L["An End to the Suffering"] = "苦難的終點"
L["An Explosive Entrance"] = "火爆登場"
L["An Important Heirloom"] = "重要傳家寶"
L["An Improvised Arsenal"] = "臨時武器"
L["An Old Ally"] = "過去的盟友"
L["An Old Wound"] = "舊傷口"
L["An Undead's Best Friend"] = "不死生物的忠實朋友"
L["An Uneventful Stroll"] = "平靜的散步"
L["An Unexpected Advantage"] = "意外的優勢"
L["An Unexpected Message"] = "意想不到的訊息"
L["An unexpected message revealed the location of Felo'melorn — the legendary sword of the Sunstrider dynasty, lost when Kael'thas fell. You traced it to the frozen depths of Icecrown, where it had lain since Arthas shattered it in single combat. You reforged the blade in phoenix fire and carried it from the ice, its flames burning hotter than ever — as if centuries of cold had only made it angrier."] = "一則意想不到的訊息揭露了斐洛梅隆的下落——那是逐日者王朝的傳奇之劍，在凱爾薩斯殞落時失落。你追查到寒冰皇冠冰封的深處，自從阿薩斯在單挑中將它擊碎後，它就一直躺在那裡。你以鳳凰之火重鑄這把劍，將它從冰中帶出，它的火焰燃燒得比以往更加熾烈——彷彿數百年的寒冷只讓它更加憤怒。"
L["An Unexpected Visitor"] = "出乎意料的訪客"
L["An unexpected visitor brought troubling news — a secret society called the Empyrean Society was gathering forbidden knowledge across the Broken Isles. Ravandwyr, apprentice to the missing Archmage Vargoth, led you on a covert infiltration of their ranks. With Esara Verrinde's help, you discovered the Society had been experimenting with powers far beyond their control. You shut them down from the inside, but the trail left behind raised a darker question — where was Archmage Vargoth?"] = "一位出乎意料的訪客帶來令人不安的消息——一個名為穹天會的秘密結社，正在破碎群島各地蒐集禁忌知識。羅樊德威是失蹤的大法師瓦戈斯的學徒，他帶領你秘密滲透這個組織。在伊薩菈‧薇琳德的協助下，你發現穹天會一直在實驗遠超他們所能控制的力量。你從內部瓦解了他們，但留下的線索引出一個更黑暗的問題——大法師瓦戈斯究竟在哪裡？"
L["An Unlikely Ally"] = "出乎意料的盟友"
L["An Unlikely Informant"] = "意外的線人"
