L["Ancient Curses"] = "遠古詛咒"
L["Ancient Magic"] = "上古魔法"
L["Ancient Mana"] = "上古法力"
L["Ancient Power"] = "上古之力"
L["Ancient Statue"] = "遠古雕像"
L["Ancient Tablet"] = "古老石板"
L["And a Heavy Fist"] = "還有沉重的拳"
L["And Justice For All"] = "伸張正義"
L["And They Will Tremble"] = "讓他們聞風喪膽"
L["Anduin Wrynn"] = "安杜因‧烏瑞恩"
L["Anduin's Decision"] = "安杜因的決定"
L["Angrathar. The black gate beyond which the Lich King's frozen fortress waits. Bolvar Fordragon has gathered every shield the Alliance can spare. Dragons circle above. Somewhere to the east, the Horde marches its own road to the same gate. Ahead, the Scourge stands in ranks that do not end. This is the road to the Lich King's door."] = "安格拉薩。在那道黑門之後，巫妖王的冰封要塞正等待著。伯瓦爾‧弗塔根已集結聯盟所能調派的每一面盾牌。巨龍在上空盤旋。東方某處，部落正沿著自己的道路向同一道門進軍。前方，天譴軍團列陣而立，無窮無盡。這是通往巫妖王門前的道路。"
L["Angrathar. The Wrathgate. The final road to the Lich King's own door. Saurfang the Younger takes point, every Orc behind him blood-mad and ready for the reckoning. Somewhere to the west, the Alliance marches under a brittle truce toward the same gate. Above, dragons circle on wings of red flame. Whatever happens at this gate, the world will remember it."] = "安格拉薩。天譴之門。通往巫妖王門前的最後一條路。小薩魯法爾一馬當先，他身後的每一名獸人都殺紅了眼，準備迎接清算。西方某處，聯盟在脆弱的休戰協議下朝同一道門進軍。上空，巨龍展開赤紅烈焰般的雙翼盤旋。無論這道門前發生什麼，世界都將銘記。"
L["Angus Ballaster"] = "安格斯‧巴拉斯特"
L["Angus Ironfist"] = "安格斯‧鐵拳"
L["Anima Attrition"] = "靈魄耗損"
L["Annie Warren"] = "安妮‧華倫"
L["Another Arcan'dor Closes..."] = "奧肯多爾再現"
L["Answer Baine Bloodhoof's call as the spirit realm and the living world begin to drift dangerously out of alignment. Across Mulgore and Thunder Bluff, the elders still remember an age before the Horde, and the ancestors have not gone silent.\n\nWalk with the spiritwalkers, restore rites interrupted by years of war, and listen for the balance between the living, the dead, and the land beneath your hooves."] = "回應貝恩‧血蹄的召喚，因為靈界與生者的世界正開始危險地偏離平衡。在莫高雷與雷霆崖，長者們仍記得部落成立之前的年代，而祖靈也從未沉默。\n\n與靈魂行者同行，恢復因多年戰爭而中斷的儀式，並聆聽生者、亡者與你蹄下大地之間的平衡。"
L["Answer Tess Greymane's call when the Nightbane begin to reappear in Duskwood and near the borders of the Emerald Dream. The Gilneans are a kingdom in exile, and the curse that gave them a second face has not stopped reshaping them.\n\nHunt through fog and shadow, confront the pull of the worgen curse, and uphold the discipline that has kept Gilnean tradition alive since Greymane Wall fell."] = "當夜禍開始重現於暮色森林與翡翠夢境邊緣時，回應黛絲‧葛雷邁恩的召喚。吉爾尼斯人是一個流亡中的王國，而賦予他們第二張面孔的詛咒，仍未停止重塑他們。\n\n在迷霧與暗影中狩獵，直面狼人詛咒的拉扯，並堅守自葛雷邁恩之牆倒下以來，讓吉爾尼斯傳統延續至今的紀律。"
L["Answer the Call"] = "回應呼喚"
L["Answer the Clarion Call from Maiev Shadowsong, who has heard rumors of demonic activity older than the Burning Legion's last invasion. The trail leads into Felwood and the Emerald Dream's borderlands, where corruption has roots ten thousand years deep.\n\nFollow the Wardens into old shadows, face threats tied to ancient Kaldorei memory, and stand with a people still carrying loss beneath the light of Elune."] = "回應瑪翼夫‧影歌的號角召喚，她聽聞有比燃燒軍團上一次入侵還要古老的惡魔活動。線索通往費伍德森林與翡翠夢境的邊陲地帶，那裡的腐化已扎根一萬年之深。\n\n追隨守望者深入古老的陰影，面對與遠古卡多雷記憶相連的威脅，並與一個在伊露恩之光下仍背負著傷痛的民族並肩作戰。"
L["Answering Aggression"] = "制暴行動"
L["Answers Unknown"] = "答案未知"
L["Anvil-Thane Thurgaden"] = "鐵砧族長索爾加登"
L["Apata Highmountain told the tale of Talonclaw — an eagle spear wielded by the greatest hunters of Highmountain since the age of the titans. You climbed into the highest peaks and proved yourself in trials of survival, tracking, and combat. When you claimed Talonclaw from its ancient resting place, the spirits of past hunters looked on with approval."] = "雅帕塔‧高嶺講述了鷹爪的故事——自泰坦時代以來，高嶺最偉大的獵人們所揮舞的鷹之長矛。你攀上最高的山峰，在求生、追蹤與戰鬥的試煉中證明了自己。當你從古老的安息之地取回鷹爪時，歷代獵人的靈魂都投以讚許的目光。"
L["Apocalypse"] = "天啟"
L["Aponi Brightmane"] = "阿波尼‧亮鬃"
L["Aponi Brightmane studied the Codex of Command but needed a demon's mind to crack its encryption. The answer came from an unlikely source — a demon prisoner in the Violet Hold. Delas Moonfang, a night elf priestess drawn to the paladin's path, helped translate the demonic text. What you found inside chilled your blood: the Legion had captured Aponi Brightmane and was holding her on Niskara. The invasion plans were clear — and so was your next move."] = "阿波尼‧亮鬃研究著《號令法典》，但需要一個惡魔的心智才能破解其中的密碼。答案來自意想不到之處——紫羅蘭堡中的一名惡魔囚犯。受聖騎士之道吸引的夜精靈女祭司德菈絲‧月牙協助翻譯了惡魔文字。你在其中發現的內容令你血液凍結：軍團俘虜了阿波尼‧亮鬃，將她囚禁在尼斯卡拉。入侵計畫一清二楚——你的下一步也是。"
L["Aponi's Trail"] = "阿波尼的蹤跡"
L["Apostate Liberation"] = "解放叛徒"
L["Apothecary Keever"] = "藥劑師基佛"
L["Apprentice Beruun"] = "學徒貝魯恩"
L["Apprentice Nelphi"] = "學徒納爾菲"
L["Arcan'dor, Gift of the Ancient Magi"] = "奧肯多爾，遠古魔導師之禮賜"
L["Arcane Communion"] = "秘法共融"
L["Arcane Thirst"] = "秘法飢渴"
L["Arcanist Kel'danath"] = "秘法師克達納茲"
L["Arcanist Valtrois"] = "秘法師薇兒塔"
L["Archdruid Hamuul Runetotem"] = "大德魯伊哈繆爾‧符文圖騰"
L["Archdruid Hamuul Runetotem's summons led you to Moonglade, where Malfurion Stormrage revealed the Emerald Dreamway — ancient paths woven through the Dream itself. Keeper Remulos guided you through to the Dreamgrove, a sanctuary hidden in Val'sharah. There, Rensar Greathoof asked you to claim an artifact weapon and plant the Seed of Ages, binding your fate to the land. You ascended the Cenarion Circle as its newest Archdruid."] = "大德魯伊哈繆爾‧符文圖騰的召喚將你帶到月光林地，瑪法里恩‧怒風在那裡揭示了翡翠夢途——貫穿夢境本身的古老道路。守衛者雷姆洛斯引導你前往夢境林地，一處隱藏在維爾薩拉的聖所。在那裡，蘭薩‧巨蹄請你取得一把神器武器並種下遠古種子，將你的命運與這片土地相繫。你晉升為塞納里奧議會最新的大德魯伊。"
L["Archdruid's Campaign"] = "大德魯伊戰役"
L["Archimonde, The Defiler"] = "『污染者』阿克蒙德"
L["Archmage Kalec"] = "大法師卡雷克"
L["Archmage Khadgar"] = "大法師卡德加"
L["Archmage Melis"] = "大法師梅莉絲"
L["Archmage Modera"] = "大法師莫德菈"
L["Archmage Omniara"] = "大法師歐妮雅拉"
L["Archmage Vargoth"] = "大法師瓦戈斯"
L["Archmage Vargoth has vanished. Khadgar leads the search through his retreat, but a darker threat lurks behind his disappearance."] = "大法師瓦戈斯失蹤了。卡德加帶領眾人在他的隱居處展開搜尋，但他的失蹤背後潛藏著更黑暗的威脅。"
L["Archmage Vargoth's Retreat"] = "大法師瓦戈斯居所"
L["Archmage's Campaign"] = "大法師戰役"
L["Argent Aid"] = "銀色的十字軍"
L["Argent Vanguard"] = "銀白先鋒駐地"
L["Arko'narin Starshade"] = "亞科納琳‧星影"
L["Arluin"] = "亞魯因"
L["Arluin's Request"] = "亞魯因的請求"
L["Armies of Legionfall"] = "軍團之殞部隊"
L["Arming Dalaran"] = "武裝達拉然"
L["Arming the Army"] = "武裝軍隊"
L["Arming the Rebels"] = "武裝反抗軍"
L["Armor Fit For A Deathlord"] = "死亡領主護甲"
L["Armor Stand"] = "盔甲架"
L["Army of the Damned"] = "詛咒軍團"
L["Arom's Stand became the Order's new headquarters. Inquisitor Sterntide — one of the few who still remembered the old ways — gave you a crash course in witch hunting: silver weapons for the cursed, fire for the wicker, and sharp thinking for the witches themselves. You rooted out hidden dealings in the camp, exposed infiltrators wearing friendly faces, and trained new guards to replace the corrupted ones. When Lucille raised the Order's banner over Arom's Stand, the message was clear — the witches had hunted long enough. Now they were the prey."] = "亞羅姆之地成為燼火會的新總部。審判官斯騰泰德——少數仍記得古老方法的人之一——為你上了一堂獵巫速成課：銀製武器對付受詛咒者，火焰對付柳條傀儡，敏銳的頭腦則用來對付女巫本身。你揪出營地中暗藏的勾當，揭穿戴著友善面孔的滲透者，並訓練新的守衛取代那些已遭腐化的人。當露西爾在亞羅姆之地升起燼火會的旗幟時，訊息再清楚不過——女巫們狩獵得夠久了。現在，她們成了獵物。"
L["Arthas died at the Frozen Throne. The moment he fell, the power of the Lich King's realm rippled outward — and Sylvanas, like every Forsaken sustained by that dark energy, briefly stopped. She died on her feet, alone at the pinnacle of Icecrown. A Val'kyr named Annhylde gave her life to pull her back. Sylvanas opened her eyes to wind and ice and herself, inexplicably, still breathing. She looked out at nothing for a long time. Then she went back to work. She never explained what she had seen. But the Val'kyr — the ones who would spend their own lives to keep her alive — suddenly became very important to her. Now she knew why."] = "阿薩斯死在冰封王座上。就在他倒下的那一刻，巫妖王領域的力量向外擴散——而希瓦娜斯，就像每一個靠那股黑暗能量維生的被遺忘者一樣，短暫地停止了。她站著死去，孤身一人在寒冰皇冠之巔。一位名叫安希德的華爾琪犧牲自己的生命，將她拉了回來。希瓦娜斯睜開雙眼，迎向寒風與冰雪，以及莫名其妙仍在呼吸的自己。她久久凝望著虛無。然後，她回到了工作中。她從未解釋自己看見了什麼。但那些願意犧牲自己生命讓她活下去的華爾琪，突然對她變得非常重要。如今她明白原因了。"
L["Arthas Menethil"] = "阿薩斯‧米奈希爾"
L["Arzaal"] = "阿爾札"
L["As Strong As Our Will"] = "如同我們的意志一般堅強"
L["Ascendant of Flames"] = "焰火騰侯"
L["Ascending The Circle"] = "晉級擢升"
L["Ask and You Shall Receive"] = "求必有得"
L["Asking a Favor"] = "尋求協助"
L["Assassin Entrapment"] = "誘捕刺客"
