L["Assault on Violet Hold: The Fel Lexicon"] = "紫羅蘭堡之襲：魔化詞典"
L["Assault the Scarlet Monastery to raise the third Horseman — High Inquisitor Whitemane, your oldest enemy turned servant."] = "攻打血色修道院，喚起第三位騎士——高階審判官懷特邁恩，你昔日的宿敵，如今成了你的僕從。"
L["Assemble the Forsaken"] = "召集被遺忘者"
L["Assessing the Enemy"] = "評估敵人"
L["Asset Security"] = "資產保全"
L["Assisting the Archmage"] = "協助大法師"
L["At Arom's Stand, recruit and train the first new Inquisitors. Learn the old ways of witch hunting — silver, fire, and sharp thinking."] = "在亞羅姆之地招募並訓練第一批新任審判官。學習古老的獵巫之道——白銀、火焰與敏銳的頭腦。"
L["At Odyn's command, you rallied the finest warriors the world had to offer. Finna Bjornsdottir and Ragnvald Drakeborn pledged their blades to your cause. Under Skyseer Ghrent's guidance, you recruited troops, dispatched them to the Broken Isles, and established Skyhold as a true war machine — Einar the Runecaster fortifying your forces with ancient vrykul magic."] = "奉歐丁之命，你召集了世上最優秀的戰士。芬娜‧比昂多特與拉格瓦德‧龍裔向你的大業獻上他們的刀劍。在占天者甘特的指引下，你招募部隊、將他們派往破碎群島，並把擎天堡打造成一台真正的戰爭機器——『符文使』埃納爾則以古老的維酷人魔法強化你的部隊。"
L["At the Bottom of the Sea"] = "海底深處"
L["At the Maelstrom's edge, the Earthen Ring struggles to keep Azeroth from tearing apart. The elements are restless, wounded, and not always willing to answer.\n\nAs Farseer, seek the elemental lords, restore balance where the world is breaking, and hold the center while the Legion tries to pull everything apart."] = "在大漩渦邊緣，大地之環竭力阻止艾澤拉斯分崩離析。元素們躁動不安、身受重創，也不總是願意回應。\n\n身為先知，你將尋找元素領主，在世界崩裂之處恢復平衡，並在軍團試圖將一切撕裂之際守住核心。"
L["At the northern edge of the forest, a wounded sprite led you into an older, stranger grief. The mogu had bound spirits into vessels, rituals, and stone. Pei-Zhi needed those cycles broken before the dead were consumed by someone else's ambition. You shattered simulacrums, gathered ritual artifacts, released wayward spirits, returned beasts to nature, and offered the humility the terrace demanded. To bridge earth and sky, you had to answer the past without trying to own it."] = "在森林北緣，一隻受傷的小精靈將你引入一段更古老、更奇異的哀傷之中。魔古族將靈魂束縛在容器、儀式與石頭之中。培志需要你打破這些循環，以免亡者被他人的野心吞噬。你擊碎了擬像，蒐集了儀式神器，釋放了迷途的靈魂，讓野獸回歸自然，並獻上這座殿台所要求的謙卑。要橋接天地，你必須回應過去，而不是試圖佔有它。"
L["At the Source"] = "追本溯源"
L["At Tian Monastery, training means discipline, hospitality, a proper weapon, and learning not to solve every problem as a soldier."] = "在天僧寺，修行意味著紀律、待客之道、一把合適的武器，以及學會不再像士兵那樣解決每一個問題。"
