L["Baine Bloodhoof"] = "貝恩‧血蹄"
L["Baine Bloodhoof has decided Derek Proudmoore cannot be used as a weapon against his own family and asks for your help freeing him. The plan runs through Plunder Harbor under false colors, with Thomas Zelling — the very tidesage Lilian helped raise — guiding the escape from the inside. When Baine and Zelling are punished for their defiance, Lilian says nothing to Sylvanas. She tells Zelling's family he died a hero. Then the War Campaign rolls on regardless — Warfang Hold needs securing, and Nathanos is already planning the next move."] = "貝恩‧血蹄認為不能把德瑞克‧普勞德摩爾當作對付他自己家人的武器，並請你協助解救他。計畫是打著假旗號潛入劫掠港，並由湯瑪斯‧澤靈——正是莉莉安協助喚起的那位潮汐賢者——從內部引導這次脫逃。當貝恩和澤靈因違抗命令而受罰時，莉莉安對希瓦娜斯一言不發。她告訴澤靈的家人，他死得像個英雄。接著，戰役依舊繼續推進——戰牙堡需要確保，而納薩諾斯已經在策劃下一步。"
L["Baine Bloodhoof is to be executed. Lor'themar has gathered allies to defy the Warchief and save the Tauren chieftain."] = "貝恩‧血蹄即將被處決。洛索瑪已召集盟友，打算違抗大酋長、拯救這位牛頭人酋長。"
L["Baine Bloodhoof looked at Derek Proudmoore — raised, hollowed out, aimed at his own kin — and decided he would not be part of it. He asked for your help. Thomas Zelling, the tidesage whose raising Lilian had stood witness to in Stormsong, helped guide Derek out from the inside. They freed him.\n\nSylvanas had Baine arrested and Zelling killed. Lilian said nothing aloud. Later, quietly, she went to Zelling's family and told them he had died a hero. It was not defiance. It was a choice. Small enough that no one noticed. Large enough that she did.\n\nAnd then the war moved on. Warfang Hold needed to be secured for a leadership summit. Boss Mida handled the SI:7 spies and the gate-crashers. Nathanos arrived to make a display of the Horde's strength. The machine kept turning, indifferent to what had just been lost."] = "貝恩‧血蹄看著德瑞克‧普勞德摩爾——被喚起、被掏空，矛頭指向他自己的親人——決定不參與其中。他請求你的協助。湯瑪斯‧澤靈，那位莉莉安曾在斯陀頌恩見證其被喚起的潮汐賢者，協助從內部將德瑞克引導出來。他們救出了他。\n\n希瓦娜斯下令逮捕貝恩，並處死了澤靈。莉莉安沒有說出任何話。後來，她悄悄找到澤靈的家人，告訴他們他死得像個英雄。那不是反抗，而是一個選擇。小到沒有人察覺。大到她自己察覺了。\n\n接著，戰爭繼續前進。戰牙堡必須確保安全，以便舉行領袖高峰會。米達老闆負責處理軍情七處的間諜與不速之客。納薩諾斯抵達，要展示部落的力量。這部機器持續運轉，對剛剛失去的一切漠不關心。"
