L["Belath's intelligence pointed to a Legion commander hiding in Stormheim. Malace Shade tracked the demon through vrykul lands while you disrupted their rune networks. The trail led to Niskara — a demon world that could only be reached by jumping the Fel Hammer through a portal. You forged deadlier warglaives, fueled the ship's engines with demonic power, and launched the invasion. On Niskara, you cut through the Legion's defenses, destroyed their command structure, and earned the title of Slayer — the demon hunters' highest honor."] = "貝拉斯的情報指出，一名軍團指揮官藏身於斯鐸海姆。瑪莉斯‧暗影在維酷人的土地上追蹤這名惡魔，你則負責破壞他們的符文網絡。線索指向尼斯卡拉——一個只能讓魔化之錘號穿越傳送門躍遷才能抵達的惡魔世界。你鍛造出更致命的戰刃，以惡魔之力為艦船引擎提供燃料，並發動入侵。在尼斯卡拉，你突破軍團的防線、摧毀他們的指揮體系，贏得了「屠魔者」的頭銜——惡魔獵人的最高榮譽。"
L["Belmont's Report"] = "貝爾蒙特的報告"
L["Beneath Dalaran lies the Hall of the Guardian, seat of the ancient Tirisgarde: mages sworn to protect Azeroth from magical threats that ordinary armies cannot understand.\n\nAs the order's newest Archmage, investigate hidden enemies, recover lost allies, and defend the Kirin Tor from dangers that wear familiar faces."] = "達拉然地底坐落著守護者殿堂，那是古老的提里斯守護會的據點：這些法師宣誓保護艾澤拉斯，抵禦尋常軍隊無法理解的魔法威脅。\n\n身為組織最新的大法師，你將調查隱藏的敵人、找回失散的盟友，並保護祈倫托免受那些頂著熟悉面孔的危險。"
L["Beneath Light's Hope Chapel lies the Sanctum of Light, where the Knights of the Silver Hand reform under your command. The Legion threatens every oath the order was built to keep.\n\nAs Highlord, unite paladins of many traditions, investigate demonic plans, and bring the Light into battles where hope has started to thin."] = "聖光之願禮拜堂地底坐落著聖光會堂，白銀之手騎士團將在你的號令下重組。軍團威脅著這個騎士團所誓守的每一個誓言。\n\n身為大領主，你將團結各種傳統的聖騎士，調查惡魔的計畫，並將聖光帶入希望逐漸稀薄的戰場。"
