L["Boarding the Skybreaker is the moment Icecrown changes scale. High Captain Justin Bartlett runs the deck. Sky-Commander Keller handles the flight line. Absalan the Pious blesses every salvo. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Scourge vanguard once mauled the 7th Legion's first landing. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the tinker Kibli Killohertz and his lightning-based sarcasm. Farther west, past the Valley of Lost Hope, Thassarian cracks open the Desolation Gate with borrowed Scourge ordnance and a half-broken jumpbot. By the time the Skybreaker swings east again, the Guardians of Corp'rethar are already in the crosshairs."] = "登上破天者號，是寒冰皇冠戰局規模轉變的時刻。提督賈斯汀‧巴特勒掌管甲板。天空指揮官凱勒負責飛行隊。虔誠的亞柏薩倫為每一輪齊射祈福。第一次出擊降落在依米海姆，天譴軍團正在那裡開採薩鋼。第二次轉向西方的破碎前線，一支天譴軍團先鋒曾在那裡重創第七軍團的首波登陸部隊。之後便是一連串苦戰：「刺探」、「抵抗巨人族」、污敗的寇普羅斯，還有工匠碁伯里‧基羅赫茲和他帶電的冷嘲熱諷。再往西，越過失落希望之谷，薩沙理安用借來的天譴軍團軍械和一台半壞的跳躍機器人，炸開了荒寂之門。等破天者號再次轉向東方時，寇普瑞薩的守衛者早已進入瞄準範圍。"
L["Bodies are turning up across the Broken Isles, and the trail leads to a chilling conspiracy deep within SI:7 itself."] = "屍體在破碎群島各處陸續出現，線索直指軍情七處內部一樁令人膽寒的陰謀。"
L["Bodies started appearing across the Broken Isles — agents killed with surgical precision. The trail led you through a web of betrayal reaching into SI:7 itself. Working with Fleet Admiral Tethys and Marin Noggenfogger, you gathered evidence and allies while throwing SI:7 off your scent, uncovering a conspiracy far deeper than anyone suspected."] = "破碎群島各處開始出現屍體——都是被以外科手術般精準手法殺害的特務。線索引領你穿過一張深入軍情七處內部的背叛之網。你與艦隊上將瑟希斯和馬林‧諾格弗格合作，一邊蒐集證據與盟友，一邊擺脫軍情七處的追查，揭開了一樁遠比任何人想像都更深的陰謀。"
