L["Brewmaster Blanche fell to a Legion poison on the Broken Shore, her spirit lingering to guide you. You brewed a cure from fel ingredients, saved who you could, and secured the Shore for the monks. Then came word of Ban-Lu — a celestial tiger who had served every Grandmaster since the order's founding. Master Bu led you across Pandaria following the tiger's trail through history: his shadow in the Jade Forest, his river in the Valley, his trial at the peak. When Ban-Lu finally appeared, he spoke — and declared you worthy. The Grandmaster had found a companion."] = "釀酒大師白蘭琪在破碎海岸中了軍團的劇毒而倒下，她的靈魂徘徊不去，引導著你。你用魔化材料釀出解藥，救下能救的人，並為武僧們確保了這片海岸。接著傳來班魯的消息——一頭自武僧組織創立以來便侍奉歷代宗師的天界猛虎。卜大師帶領你走遍潘達利亞，循著這頭猛虎在歷史中留下的足跡：他在翠玉林的身影、他在峽谷中的河流、他在峰頂的試煉。當班魯終於現身時，他開口說話——宣告你足以勝任。宗師找到了自己的夥伴。"
L["Brick By Brick"] = "一磚一瓦"
L["Bridgeport Investigation"] = "調查橋梁港"
L["Bring Home the Beacon"] = "帶回信標"
L["Bring the Boom"] = "炸個痛快"
L["Broken Warriors"] = "破碎者"
L["Brother Keltan"] = "凱爾坦修士"
L["Build the Illidari's strength on the Fel Hammer. Recruit champions, train troops, and prove yourself leader of the demon hunters."] = "在魔化之錘號上壯大伊利達瑞的實力。招募勇士、訓練部隊，並證明你足以領導惡魔獵人。"
L["Build the order hall's strength by recruiting legendary rogues as champions and establishing operations throughout the Broken Isles."] = "招募傳奇盜賊擔任勇士，並在破碎群島各地建立行動據點，壯大職業大廳的實力。"
L["Build, test, and defend the X-52 while goblin politics and greed explode all around you."] = "在哥布林的權謀與貪婪四處爆炸之際，建造、測試並守護X-52。"
L["Building Our Troops"] = "建立我們的部隊"
L["Buried Power"] = "埋藏的力量"
L["Burn Doctor Olakin Sainrith's plague lab, save Father Kamaros's people, and finish the Runesmiths' work."] = "燒毀歐拉金‧聖瑞斯博士的瘟疫實驗室，拯救卡瑪洛斯神父的人民，並完成符文鐵匠未竟的工作。"
L["Burning Down the House"] = "燒為平地"
L["Burning Within"] = "內藏火焰之力"
L["Business, betrayal, and big explosions: a proper goblin story. You helped Hobart finish the X-52, survived every reckless test, crushed Gallywix's takeover, and earned the right to wear the pride of Kezan."] = "生意、背叛和大爆炸：一個道地的哥布林故事。你協助荷巴爾特完成X-52，熬過每一次魯莽的測試，粉碎了加里維克斯的奪權企圖，贏得了披上凱贊榮耀的資格。"
L["Buyers Wanted!"] = "誠徵買主！"
L["Bwon Voyage"] = "伯昂首闊步"
L["Bwonsamdi"] = "伯昂撒姆第"
L["By Any Means"] = "不擇手段"
L["By Fire Be Purged"] = "以火淨化"
L["Cages For All Occasions"] = "插翅難飛"
L["Calamity Jade"] = "玉石災害"
L["Calia Menethil"] = "卡莉雅‧米奈希爾"
L["Call of the Illidari"] = "伊利達瑞的呼喚"
L["Call of The Uncrowned"] = "無冕者的召喚"
L["Call of the Wilds"] = "荒野的呼喚"
L["Call to Lordaeron"] = "羅德隆的召喚"
L["Calling Hilaire Home"] = "把希萊爾叫回來"
L["Calydus"] = "卡萊德斯"
L["Calydus pointed you toward Ulthalesh — the Deadwind Harvester, a scythe of terrible power that had reaped souls for millennia. You followed the curse through Deadwind Pass, where the Dark Riders still haunted the roads. In their shadowed lair, you tore Ulthalesh from their grasp. The scythe's whispers joined the chorus in your mind — a weapon that was never truly silent."] = "卡萊德斯指引你找到烏薩雷斯——逆風收割者，一把數千年來收割靈魂、擁有可怕力量的鐮刀。你循著詛咒穿越逆風小徑，黑暗騎士仍在那裡的道路上遊蕩。在他們陰暗的巢穴中，你從他們手中奪下了烏薩雷斯。鐮刀的低語加入了你腦海中的合唱——這是一把從未真正沉默過的武器。"
L["Calydus revealed the location of the Scepter of Sargeras — a weapon capable of tearing holes between dimensions, wielded by the Dark Titan's own lieutenants. You found it sealed in a vault warded against mortal hands. But a warlock's hands were never quite mortal. You broke the wards, claimed the Scepter, and felt the fabric of reality shudder around you. The power to break worlds was now in your grip."] = "卡萊德斯揭露了薩格拉斯權杖的所在——一把能在次元之間撕開裂口的武器，曾由黑暗泰坦的副官們揮舞。你發現它被封存在一座設有防護、拒絕凡人之手的寶庫中。但術士的手從來就不完全屬於凡人。你破除防護，取得權杖，感覺到現實的結構在你周圍顫抖。毀滅世界的力量，如今就握在你手中。"
L["Calydus spoke of the Skull of the Man'ari — an eredar artifact of staggering summoning power. The ritual reagents alone were dangerous enough to kill a lesser warlock. You gathered them, performed the summoning, and wrested the Skull from the eredar lord who guarded it. The Skull's eyes glowed with malevolent intelligence, as if the demon trapped within was already planning its next move."] = "卡萊德斯提到了瑪拉瑞之顱——一件擁有驚人召喚之力的埃雷達爾神器。光是儀式所需的材料，就足以殺死一名較弱的術士。你蒐集齊全，進行召喚，並從守護它的埃雷達爾領主手中奪下了這顆頭顱。顱骨的雙眼閃爍著惡意的智慧，彷彿被困在其中的惡魔已經在計畫下一步。"
