L["Chief Kah Kah"] = "卡卡酋長"
L["Chief Plaguebringer Middleton"] = "首席瘟疫使者米道頓"
L["Chief Plaguebringer Middleton has been busy in the Carrion Fields. He has something new to test — a blight meant to undo the Scourge where steel cannot reach. The formula wants a subject. Middleton smiles through gritted teeth and swears the first dose is always the worst. Whatever the Apothecaries are cooking under the Horde's banner, it may reshape this war."] = "首席瘟疫使者米道頓一直在腐肉平原忙個不停。他有新東西要測試——一種能在刀劍觸及不到之處瓦解天譴軍團的瘟疫。這個配方需要一名實驗對象。米道頓咬著牙微笑，發誓第一劑總是最難受的。無論藥劑師們在部落的旗幟下調製著什麼，都可能改變這場戰爭的面貌。"
L["Chief Telemancer Oculeth"] = "首席傳送師歐庫雷斯"
L["Chieftain Hatuun"] = "哈圖恩族長"
L["Cho slows the Horde campaign long enough to teach the land's memory, then the hozen pull you back into motion."] = "周放緩了部落的攻勢，讓你得以了解這片土地的記憶，隨後猴人又把你拉回行動之中。"
L["Chon Po Stormstout"] = "程波‧風暴烈酒"
L["Choppertunity"] = "有機可乘"
L["Chosen by Odyn himself, you ascend to Skyhold: the legendary warrior paradise above the clouds. The Valarjar measure worth in courage, scars, and the battles a champion is still willing to fight.\n\nAs Battlelord, recover ancient symbols of war, seek alliances with titan-forged powers, and lead warriors who believe glory is something earned in motion."] = "你受到歐丁親自揀選，登上擎天堡：雲端之上傳說中的戰士樂土。華爾拉亞以勇氣、傷疤，以及勇士仍願意投身的戰鬥來衡量一個人的價值。\n\n身為戰帥，你將奪回古老的戰爭象徵，尋求與泰坦鑄造之力結盟，並率領那些相信榮耀必須在行動中贏取的戰士。"
L["Chromie"] = "克羅米"
L["Chromie of the Bronze Dragonflight sends you back to Stratholme, to a day history remembers in silence. The Infinite Dragonflight would rewrite this moment. Yours is the harder task: walk beside a young Prince Arthas Menethil and keep time honest, whatever price the past demands."] = "青銅龍軍團的克羅米將你送回斯坦索姆，回到歷史以沉默銘記的那一天。永恆龍軍團想改寫這一刻。你的任務更加艱難：與年輕的阿薩斯‧米奈希爾王子同行，守護時間的真實，無論過去要求付出什麼代價。"
L["Cities in Dust"] = "塵湮之城"
L["Citizens' Army"] = "平民軍隊"
L["Claim the Ashbringer, the legendary blade that burned with holy fire and shattered the Scourge."] = "取得灰燼使者，那把燃燒著神聖火焰、擊潰天譴軍團的傳奇之劍。"
L["Claim the Fists of the Heavens, a pair of enchanted handwraps charged with the fury of storms."] = "取得天堂之拳，一對蘊含風暴之怒的附魔裹手。"
L["Claim Xal'atath, a dagger that whispers with the voice of the Void and remembers the Black Empire that ruled before the titans."] = "取得薩拉塔斯，一把以虛空之聲低語的匕首，它仍記得泰坦到來之前統治世界的黑暗帝國。"
L["Claws of Ursoc"] = "厄索克之爪"
L["Clear the Air"] = "一掃而空"
L["Clear Victory"] = "毋庸置疑的勝利"
L["Clear-Cutting"] = "清理一番"
L["Climb the spire of Icecrown Citadel and write the last page of Arthas Menethil's story."] = "攀上冰冠城塞的尖塔，寫下阿薩斯‧米奈希爾故事的最後一頁。"
L["Cloak and Dagger"] = "影襲"
L["Cloaked in Moonshade"] = "披上月影"
L["Close Enough"] = "近在咫尺"
L["Closing In"] = "步步逼近"
