L["Communication Orbs"] = "通訊球"
L["Communing With Malorne"] = "與瑪洛尼聯繫"
L["Complete Armies of Legionfall on the Broken Shore, then return to the Hall of Shadows to begin the final class mount chapter."] = "在破碎海岸完成軍團之殞部隊，然後回到暗影大廳，開始最終的職業坐騎章節。"
L["Complete the Forsaken Heritage questline as an Undead character. Requires having sided with Sylvanas during the war campaign."] = "以不死族角色完成被遺忘者傳承任務線。需要在戰役中站在希瓦娜斯這一邊。"
L["Complete the Horde War Campaign introduction and travel to Zuldazar to unlock this chapter."] = "完成部落戰役的開場並前往祖達薩，即可解鎖此章節。"
L["Complete the Horde War Campaign through Stormsong Valley to unlock this chapter."] = "完成部落戰役中斯陀頌恩谷地的部分，即可解鎖此章節。"
L["Complete the Kul Tiras intro and War Campaign chapters to unlock, then speak with Mathias Shaw in Proudmoore Keep."] = "完成庫爾提拉斯的開場與戰役章節即可解鎖，接著前往普勞德摩爾城堡與馬希亞斯‧蕭交談。"
L["Complete the Silver Hand's reformation. Recruit Arator and Lothraxion, and accept the title of Highlord."] = "完成白銀之手的重組。招募阿拉特與洛斯拉賽恩，並接受大領主的頭銜。"
L["Complete the Zereth Mortis campaign and defeat the Jailer in the Sepulcher of the First Ones raid."] = "完成澤瑞斯莫提斯戰役，並在首創者聖塚團隊副本中擊敗獄主。"
L["Confront Mueh'zala's influence, recover forgotten loa, and complete a Trial of the Loa worthy of the Darkspear."] = "對抗穆札拉的影響，找回被遺忘的洛阿，並完成一場配得上暗矛的洛阿試煉。"
L["Confrontation at the Black Temple"] = "黑暗神廟對峙"
L["Consular Celestos"] = "賽勒斯多領事"
L["Consulting Our Allies"] = "諮詢盟友"
L["Containment Procedure"] = "隔離程序"
L["Continuing the Cure"] = "繼續提供解藥"
L["Controlling the Situation"] = "控制情況"
L["Convincin' Old Yancey"] = "說服老楊希"
L["Cook Torka"] = "廚師托爾卡"
L["Coprous the Defiled"] = "污敗的寇普羅斯"
L["Corlain was a nightmare — hexed citizens wandered the streets, ruinous rituals played out in every alley, and the coven's strongest witches guarded the approach to the manor. You cut through them all. Lucille led the final charge to the gates of Waycrest Manor itself, where her mother — Lady Waycrest, consumed by Gorak Tul's power — waited in the depths. In the dungeon beneath the manor, you faced the fallen mother and broke the Drust king's hold on her. The curse over Drustvar shattered like glass. Lucille knelt beside her mother's body, the heir of a house that would rebuild. The witchwood was silent at last."] = "寇連恩宛如一場噩夢——中了妖術的居民在街上遊蕩，每條小巷裡都在上演毀滅性的儀式，巫團最強大的女巫則把守著通往莊園的道路。你殺穿了她們全部。露西爾率領最後的衝鋒，直抵威奎斯特莊園的大門，她的母親——被勾拉圖爾的力量吞噬的威奎斯特夫人——就在深處等待。在莊園底下的地城中，你面對這位墮落的母親，打破了德魯斯之王對她的掌控。籠罩佐司瓦的詛咒如玻璃般粉碎。露西爾跪在母親的遺體旁，她是一個終將重建的家族的繼承人。巫覡之林終於歸於寂靜。"
L["Corner Crossing"] = "調查路口"
L["Cornering Gor'krosh"] = "逼退戈克洛許"
