L["Dalaran / Broken Isles"] = "達拉然 / 破碎群島"
L["Danica the Reclaimer"] = "『接引者』丹妮卡"
L["Danica the Reclaimer appeared to you in Dalaran bearing a message from Odyn himself — the All-Father had been watching, and he found you worthy. You ascended to Skyhold, the legendary warrior paradise suspended above the clouds, where Odyn named you champion of the Valarjar and bade you claim an artifact weapon fit for the battles ahead."] = "『接引者』丹妮卡出現在達拉然，帶來歐丁親自捎來的訊息——眾神之父一直在注視著你，並認為你夠格。你登上擎天堡，那懸浮在雲端之上的傳奇戰士樂土，歐丁在那裡任命你為華爾拉亞的勇士，並命你取得一把足以應付未來戰鬥的神器武器。"
L["Darion Mograine revealed the Lich King's plan — to raise the Four Horsemen, death knights of legendary power, to serve as the Ebon Blade's vanguard. The first was Nazgrim, the Horde general who fell defending the gates of Orgrimmar. You tore his spirit from the grave and bound it in service. Thassarian and Nazgrim pledged as your champions, and the order's forces began to take shape — troops recruited, missions dispatched, and a war machine built from bone and shadow."] = "達瑞安‧莫格萊尼揭露了巫妖王的計畫——喚起四騎士，這些擁有傳奇力量的死亡騎士將擔任黯刃騎士團的先鋒。第一位是納茲格寧姆，那位在保衛奧格瑪大門時陣亡的部落將軍。你將他的靈魂從墳墓中扯出，束縛其為你效力。薩沙理安與納茲格寧姆宣誓成為你的勇士，騎士團的軍力開始成形——招募部隊、派遣任務，一台以白骨與暗影打造的戰爭機器就此誕生。"
L["Darion Mograine spoke of Frostmourne — the Lich King's blade, shattered atop Icecrown Citadel. Its shards still radiated power, and the call of Icecrown pulled you north. In the frozen throne room, you gathered the remnants and reforged them into the Blades of the Fallen Prince — twin runeblades that carried echoes of Arthas, Ner'zhul, and every soul the original sword had devoured."] = "達瑞安‧莫格萊尼提到了霜之哀傷——巫妖王之劍，在冰冠城塞頂端被擊碎。它的碎片依然散發著力量，寒冰皇冠的呼喚將你引向北方。在冰封的王座廳中，你收集殘骸，將它們重鑄成墮落王子之刃——一對承載著阿薩斯、耐奧祖，以及原劍所吞噬的每一個靈魂之回音的雙持符文劍。"
L["Dark Iron Machinations"] = "黑鐵詭計"
L["Dark Ranger Alina"] = "黑暗遊俠奧麗娜"
L["Dark Ranger Velonara"] = "黑暗遊俠薇蘿娜拉"
L["Dark Ranger Vorel"] = "黑暗遊俠沃瑞"
L["Dark Secrets and Shady Deals"] = "黑暗秘密，沆瀣一氣"
L["Darkhaven's crisis brought you into the shadow of Castle Nathria. Lord Chamberlain showed you the Stoneborn, Revendreth's gargoyle guardians, and carried your request to the Harvesters. Then you met Sire Denathrius: ancient, immaculate, and utterly certain of his own necessity. He promised aid, but only after you helped him discipline the rebellion tearing through his realm. His authority filled the court like perfume and poison. Revendreth's nobles bowed. The Stoneborn obeyed. And for the moment, you were expected to do the same."] = "暗港的危機將你帶入納撒亞城的陰影之下。宮務大臣向你展示了瑞文崔斯的石像鬼守護者石源魔，並將你的請求轉達給收割者。接著你見到了戴納瑟斯王：古老、完美無瑕，並對自身的不可或缺深信不疑。他承諾提供援助，但前提是你得先幫他整頓那場撕裂他領域的叛亂。他的權威如香水與毒藥般瀰漫整個宮廷。瑞文崔斯的貴族們躬身行禮。石源魔唯命是從。而此刻，你也被期待照做。"
L["Darkheart Thicket"] = "暗心灌木林"
L["Darkheart Thicket: Nightmare Oak"] = "暗心灌木林：夢魘橡木"
L["Darkheart Thicket: The Nightmare Lash"] = "暗心灌木林：夢魘之鞭"
L["Darkrider Arly"] = "黑騎兵亞爾利"
L["Darkspeaker R'khem"] = "暗語者睿克漢"
L["Daughter of the Sea"] = "海洋之女"
L["Dawn's Blossom"] = "晨綻"
L["Dawn's Blossom slowed the campaign down long enough for you to see the people under it. Cho, Toya, and the villagers asked for something different than victory. An Windfur's missing cubs led to the Jade Witch and a curse hiding behind a grandmother's smile. The Goldendraft and Wanderbrew families needed courage more than soldiers, and the Arboretum needed ink, color, and permission before a marriage could heal an old feud. It was not a detour. It was the point: Pandaria was full of lives that had nothing to do with the Alliance or Horde until the war made everything their problem."] = "晨綻讓戰事放慢了腳步，讓你看見戰火之下的人們。周、托亞與村民們所求的並非勝利。安‧風毛走失的幼崽引出了翠玉女巫，以及藏在一位老奶奶笑容背後的詛咒。金釀家族與漫遊釀家族需要的是勇氣，而不是士兵；植物園則需要墨水、色彩與一份許可，一場婚禮才能化解一段舊怨。這不是繞遠路。這正是重點：潘達利亞充滿了與聯盟或部落毫無關係的生命，直到戰爭讓一切都成了他們的問題。"
L["Dazar'alor"] = "達薩亞洛"
