L["Debt Collection!"] = "討債！"
L["Debt Repaid"] = "清償前債"
L["Decipher the Legion's Codex of Command. The Violet Hold holds a demon who can translate it — but at what cost?"] = "解讀軍團的《號令法典》。紫羅蘭堡關著一名能翻譯它的惡魔——但代價是什麼？"
L["Deciphering the Letter"] = "解讀密函"
L["Deep beneath the earth, a titan research facility holds the worst mistake the Pantheon ever made. G'huun has to die."] = "在地底深處，一座泰坦研究設施裡藏著萬神殿犯下最嚴重的錯誤。古翰必須死。"
L["Deep Dive"] = "深海潛水"
L["Deep Doubts, Deep Wisdom"] = "深沉的疑惑，深遠的智慧"
L["Deep in the Bowels of The Underhalls"] = "深入地下大廳"
L["Deep in the mountains of Highmountain lay a shield forged from a scale of Neltharion, the Earth-Warder — before madness claimed him and he became Deathwing. You braved the ancient caverns and faced the guardians left behind to protect it. The Scale of the Earth-Warder was heavier than any shield you had ever held, but it was unyielding — and so were you."] = "高嶺的山脈深處，藏著一面以大地守護者奈薩里奧的鱗片鑄成的盾牌——那是在他陷入瘋狂、化身死亡之翼之前的事。你勇闖古老的洞窟，面對留下來守護它的守衛者。大地守護者之鱗比你拿過的任何盾牌都還要沉重，但它堅不可摧——你也一樣。"
L["Deep in the Swamp"] = "沼澤深處"
L["Deep in the tunnels beneath Suramar, you found Arcanist Kel'danath on the edge of withering, his brilliant mind nearly consumed by mana starvation. You fought through packs of feral withered to reach him, recovering his scattered research notes and the remnants of his arcane experiments. His knowledge of ancient Nightborne magic proved invaluable to the growing rebellion."] = "在蘇拉瑪爾地底的隧道深處，你發現秘法師克達納茲正處於凋萎的邊緣，他聰穎的心智幾乎被魔力飢渴吞噬殆盡。你殺穿成群的野性凋萎者來到他身邊，找回他散落的研究筆記和秘法實驗的殘留物。他對古代夜裔魔法的知識，對日益壯大的反抗軍而言無比珍貴。"
L["Deeper into the Woods"] = "深入森林"
L["Deepholm stirs with twilight corruption. Seek Therazane the Stonemother and purge the Twilight's Hammer from her domain."] = "地深之源因暮光的腐化而騷動。尋找石母瑟拉贊恩，將暮光之錘從她的領域中清除。"
