L["Defense of the Fel Hammer"] = "保衛魔錘號"
L["Defense of Tian Monastery"] = "保衛天僧寺"
L["Defiance"] = "挑戰"
L["Delas Moonfang"] = "德菈絲‧月牙"
L["Delegation"] = "外包業務"
L["Deliverance from the Pit"] = "逃離深淵"
L["Delivery for Kasea"] = "給凱曦的快遞"
L["Delve into a demonic vault to claim a pair of shadow-forged blades that hunger for souls."] = "深入一座惡魔寶庫，取得一對渴求靈魂、以暗影鍛造的利刃。"
L["Delve into Ironforge's deepest archives with Brann Bronzebeard, who has kept the chronicles longer than most dwarves have been alive. An old relic of the Bronzebeard line has been broken and scattered across roads with long memories.\n\nWalk those roads again, recover what was lost, and return to the great anvils where dwarven legacy is measured in craft, stubbornness, and stone."] = "與布萊恩‧銅鬚一同深入鐵爐堡最深處的檔案庫，他記錄編年史的時間，比大多數矮人活著的歲月還要長。一件銅鬚血脈的古老遺物已經破碎，散落在一條條擁有悠長記憶的道路上。\n\n再次踏上那些道路，找回失落之物，並回到那些偉大的鐵砧前——在那裡，矮人的傳承是以工藝、固執與岩石來衡量的。"
L["Demonic Improvements"] = "改魔歸正"
L["Demonic Runes"] = "惡魔符文"
L["Demons Among Us"] = "惡魔四伏"
L["Denathrius sends you after the Accuser, a rebel Harvester whose sinstone may prove she is no righteous dissenter."] = "戴納瑟斯派你去追捕控訴者，一名叛變的收割者，她的罪石或許能證明她並非正直的異議者。"
L["Derek Proudmoore had barely been hauled out of the sea before Sylvanas found a use for him — not as a weapon yet, but as bait. The Kul Tiran fleet chased his ghost while you and Nathanos hit Stormsong Monastery. Thomas Zelling, the tidesage whose raising Lilian had stood witness to, guided you from inside. He was doing what he was told. So was she. The Horde got its scepter. Lilian got her champion tabard. No one asked if any of it was right."] = "德瑞克‧普勞德摩爾才剛被從海裡拖出來，希瓦娜斯就為他找到了用途——還不是當作武器，而是當作誘餌。庫爾提拉斯人的艦隊追逐著他的幽影，而你與納薩諾斯則突襲了斯陀頌恩修道院。湯瑪斯‧澤靈，那位莉莉安曾見證其被喚起的潮汐賢者，從內部為你們引路。他只是照命令行事。她也是。部落拿到了權杖。莉莉安拿到了她的勇士外袍。沒有人問過這一切是否正確。"
L["Derek Proudmoore's body is put to use before Lilian ever gets her orders: the Horde deploys him as bait to draw Kul Tiran warships away from Boralus, then drives a strike force into Stormsong Monastery to seize the Abyssal Scepter. Thomas Zelling — raised against his will just weeks ago — now fights for the Horde from inside the monastery walls. Lilian watches what the war makes of people."] = "莉莉安還沒接到命令，德瑞克‧普勞德摩爾的遺體就已經被派上用場：部落把他當作誘餌，將庫爾提拉斯人的戰艦引離波拉勒斯，接著派遣突擊部隊攻入斯陀頌恩修道院，奪取深淵權杖。湯瑪斯‧澤靈——幾週前才違背自身意願被喚起——如今在修道院的高牆內為部落而戰。莉莉安看著戰爭把人變成了什麼。"
L["Descend into the depths to recover Sharas'dal, a scepter that commands the tides themselves."] = "深入深海，取回沙拉斯達爾，一把能號令潮汐本身的權杖。"
L["Desperate Strike"] = "破釜沉舟"
