L["Dread Infiltrators"] = "驚懼滲透者"
L["Dread Priming"] = "驚恐的準備"
L["Dreadscar Rift / Broken Isles"] = "懼痕裂隙 / 破碎群島"
L["Dreadtick Combustion"] = "炸掉吸血蟲"
L["Dredhollow"] = "掘息坑"
L["Dress in Scarlet cloth, take the Vault for the Ebon Blade, and ride up to Malykriss to kill four riders."] = "穿上血色十字軍的衣袍，為黯刃騎士團奪下寶庫，再前往瑪利克里斯斬殺四名騎士。"
L["Drust Do It."] = "佐司瓦非看不可"
L["Drustfall"] = "佐司特的敗亡"
L["Drustvar"] = "佐司瓦"
L["Duke August Foehammer"] = "奧古斯特‧敵錘公爵"
L["Duke Lankral"] = "蘭克洛公爵"
L["Duke Lankral appeared in Dalaran with an urgent summons — the Knights of the Ebon Blade needed you at Acherus. The Ebon Hold floated above the Broken Isles like a fortress of iron and frost, and Highlord Darion Mograine spoke of a pact of necessity: the living would fight the Legion their way, and the dead would fight it theirs. You claimed an artifact weapon forged for death itself."] = "蘭克洛公爵帶著緊急召喚出現在達拉然——黯刃騎士團需要你前往亞榭洛。黯黑堡如一座鋼鐵與寒霜築成的要塞，漂浮在破碎群島上空，大領主達瑞安‧莫格萊尼談起了一份出於必要的協議：生者以他們的方式對抗軍團，亡者則以亡者的方式。你取得了一把為死亡本身而鍛造的神器武器。"
L["Duke Lankral summons you to Acherus, where the Ebon Blade prepares for a war that only the dead can fight."] = "蘭克洛公爵召你前往亞榭洛，黯刃騎士團正在那裡準備一場只有亡者才能打的戰爭。"
L["Duke Lankral told of the Maw of the Damned — a vampiric greataxe that drank the blood of its enemies and fed it to its wielder. The weapon had been lost in a Legion stronghold, guarded by demons who had learned to fear it. You stormed their fortress and tore the Maw from the hands of its demonic captor. The axe drank deep on the way out."] = "蘭克洛公爵講述了遭譴者之顎——一把吸血的巨斧，會吸取敵人的鮮血，再將之餵給持有者。這把武器遺失在軍團的一座據點中，由早已學會畏懼它的惡魔看守。你攻入他們的要塞，從惡魔看守者手中奪下了遭譴者之顎。離開的路上，這把斧頭痛飲了一番。"
L["Durak"] = "杜洛卡"
L["Dvalen Ironrune"] = "德瓦倫‧鐵符文"
L["Dying Berserker"] = "垂死的狂戰士"
L["Earthen Blessing"] = "大地祝福"
L["Eastern Escape"] = "東向脫逃"
L["Eating Before the Meeting"] = "會議前的點心"
