L["Ebonchill"] = "黯冰"
L["Echelon"] = "艾可隆"
L["Echo Isles / Northern Stranglethorn"] = "回音群島 / 北荊棘谷"
L["Echoes of Tortured Souls"] = "受苦靈魂的回聲"
L["Eekle Eekle"] = "伊果伊果"
L["Einar the Runecaster"] = "『符文使』埃納爾"
L["Either With Us"] = "不是朋友"
L["Eitrigg"] = "伊崔格"
L["Elder Lusshan"] = "長者廬山"
L["Elder Sage Rain-Zhu"] = "大賢者雨竹"
