L["Eliminate the Competition"] = "消滅競爭者"
L["Elisande seals Suramar's gates and tightens her grip. The resistance must find a way through the lockdown."] = "伊莉珊德封鎖了蘇拉瑪爾的城門，並收緊了她的掌控。反抗軍必須找到突破封鎖的方法。"
L["Elisande struck back with the full power of the Nightwell, warping time itself to halt the rebellion's advance. You worked with Valtrois to investigate the temporal distortions, scouted breaches in the Nighthold's defenses, and uncovered how the Grand Magistrix channeled the Nightwell's energy through ancient seals. Breaking those seals would be the key to reaching her."] = "伊莉珊德以暗夜之井的全部力量反擊，扭曲時間本身以阻止反抗軍的推進。你與瓦特羅伊一同調查時間扭曲，偵察暗夜堡防禦中的破口，並揭開大魔導師如何透過古老的封印引導暗夜之井的能量。打破那些封印，將是接近她的關鍵。"
L["Elisande's forces captured and experimented on nightfallen prisoners, transforming them into felborne abominations. You stormed the Felsoul experiments alongside Kel'danath and Oculeth, freeing those who could still be saved and putting down those who could not. The horrors you witnessed only strengthened the resolve of every rebel who fought beside you."] = "伊莉珊德的部隊俘虜了夜落者囚犯並以他們進行實驗，將他們變成魔化的憎惡體。你與克達納茲和奧庫雷斯一同突襲魔魂實驗場，解救了還有救的人，並了結了無法挽回的人。你所目睹的恐怖景象，只讓每一位與你並肩作戰的反抗者更加堅定決心。"
L["Elisande's Retort"] = "伊莉珊德的反擊"
L["Embodiment"] = "具現化"
L["Emerald Dragon Tears"] = "翡翠龍之淚"
L["Emergency Efforts"] = "緊急出動"
L["Emergency Response"] = "緊急回應"
L["Emissary"] = "密使"
L["Emissary Brighthoof"] = "特使亮蹄"
L["Emmarel Shadewarden"] = "艾瑪芮爾‧影衛"
L["Empire of Dirt"] = "下流的帝國"
L["Empower the Council's soul reserves. Dungeon delves, mad alchemists, and the question: who is truly worthy of power?"] = "強化議會的靈魂儲備。探索地城、對付瘋狂的鍊金術師，並思考一個問題：誰才真正配得上力量？"
L["Empty Package"] = "空包裹"
L["Empyrean Society Report"] = "秘天學會報告"
L["Ending the Blood Trolls"] = "消滅鮮血食人妖"
L["Ending the Crescent Curse"] = "終止月牙詛咒"
L["Ending the Inquisitor"] = "審判官的終結"
L["Enemies Within"] = "內賊"
L["Enter Nightmare"] = "進入夢魘"
L["Enter the Crimsonwood, face Gorak Tul's grand rite, and drive a stake into the heart of the Drust king's power."] = "進入緋紅森林，面對勾拉圖爾的盛大儀式，將木樁刺入德魯斯之王力量的核心。"
L["Enter the dungeon, cleanse Yu'lon's sacred temple, and destroy the Sha of Doubt where it has taken root."] = "進入地城，淨化玉瓏的神聖殿堂，在疑惑之煞紮根之處將它摧毀。"
L["Enter the Firelands and negotiate with Smolderon, the new Firelord, to secure the fire elementals' allegiance."] = "進入火源之界，與新任火焰領主斯莫德隆談判，以確保火元素的效忠。"
L["Enter the Nightmare itself to relive the War of the Ancients and awaken Malorne, the great white stag, to fight once more."] = "進入夢魘本身，重溫上古之戰，並喚醒偉大的白色雄鹿瑪洛尼，讓他再次投入戰鬥。"
L["Envoy of the Alliance"] = "聯盟特使"
L["Ephemeral Manastorm Projector"] = "瞬效法力風暴發射器"
L["Epilogue (Sylvanas Loyalists)"] = "尾聲（希瓦娜斯效忠者）"
L["Ernest Carlisle"] = "恩尼斯特‧卡萊爾"
L["Erunak Stonespeaker called you to the deeps — Sharas'dal, the Scepter of Tides, had been sensed stirring beneath the ocean floor. You descended into the crushing darkness where water elementals guarded the weapon with fierce devotion. The Scepter of Tides chose to rise with you, and the seas themselves seemed to bow as you surfaced."] = "伊魯納克‧石語者召喚你前往深海——有人感應到潮汐權杖沙拉斯達爾正在海床下甦醒。你潛入令人窒息的黑暗深處，水元素們以狂熱的忠誠守護著這把武器。潮汐權杖選擇與你一同升起，當你浮出水面時，大海彷彿也向你低頭致敬。"
L["Esara Verrinde"] = "伊薩菈‧薇琳德"
L["Essence of Plague"] = "瘟疫精華"
L["Essence Triangulation"] = "量測精華"
L["Establish a supply of ancient mana to sustain the nightfallen rebels and prevent them from withering."] = "建立遠古魔力的供應，以維持夜落者反抗軍的生存，避免他們凋萎。"
L["Establishing a Connection"] = "建立聯繫"
L["Establishing Superiority"] = "先聲奪人"
L["Establishing The Uncrowned"] = "建立無冕者"
L["Eternal Unrest"] = "永遠不得安息"
L["Eternal Vigil"] = "永恆之惕"
L["Evelyn Pare"] = "伊芙琳‧佩爾"
L["Ever Eastward"] = "一路東去"
L["Everburning"] = "永燃不滅"
L["Everything Contained"] = "一切盡已封印"
L["Everything In Its Place"] = "諸事皆好"
L["Examining the Epitaphs"] = "查看碑文"
L["Exarch Maladaar"] = "瑪拉達爾主教"
L["Excision"] = "切除"
L["Executor Zygand"] = "執行官塞加德"
L["Exodar / Outland / Bloodmyst Isle"] = "艾克索達 / 外域 / 血謎島"
L["Experimental Instability"] = "實驗的未知性"
L["Exploiting an Opening"] = "趁隙突破"
L["Explore ancient ley line tunnels beneath Suramar, discovering forgotten power that could turn the tide."] = "探索蘇拉瑪爾地底古老的地脈隧道，發現足以扭轉局勢的被遺忘之力。"
L["Explosives in the Foundry"] = "鑄造場的炸藥"
L["Explosivity"] = "爆炸物"
L["Eye of Azshara: A Magical Affliction"] = "艾薩拉之眼：魔法之痛"
L["Eye of Azshara: The Frozen Soul"] = "艾薩拉之眼：冰凍之魂"
L["Face Grand Magistrix Elisande herself as she unleashes the power of the Nightwell against the rebellion."] = "直面大魔導師伊莉珊德本人，她正釋放暗夜之井的力量對抗反抗軍。"
L["Face to Face With Consequence"] = "面對後果"
L["Falconhurst is under siege. Break the hag's hold on the village, forge weapons of old, and learn to fight the Drust with fire."] = "獵鷹之巢正遭受圍攻。打破巫婆對村莊的掌控，鍛造古老的武器，並學會用火焰對抗德魯斯。"
L["Falconhurst was overrun — a hag had enslaved the village, and wicker monsters patrolled the streets. Inquisitor Cleardawn led the charge: you broke the hag's spell, freed the villagers, and held the barricade against waves of cursed attackers. Warren Ashton, the village blacksmith, remembered the old ways — weapons of silver and iron, blessed in ember. You forged an arsenal from his teachings and learned the most important lesson of all: the Drust feared fire. With blessed blades and burning brands, you were ready for the Crimsonwood."] = "獵鷹之巢已被攻陷——一名巫婆奴役了整個村莊，柳條怪物在街道上巡邏。審判官科利爾東率先衝鋒：你破除了巫婆的咒語，解救村民，並在一波波受詛咒的攻擊者面前守住了路障。村裡的鐵匠華倫‧艾希頓記得古老的方法——以白銀與鐵鑄成、在餘燼中祝福過的武器。你依照他的教導打造出一整套軍械，並學到了最重要的一課：德魯斯畏懼火焰。帶著受祝福的刀刃與燃燒的火把，你已準備好前往緋紅森林。"
L["Fall Back!"] = "撤退!"
L["Fall of the Lich King"] = "巫妖王的殞落"
L["Fallen Idols"] = "空虛的塑像"
L["False Orders"] = "假命令"
L["Family Heirlooms"] = "傳家寶"
L["Family Tree"] = "族譜"
L["Fancy Lads and Buccaneers"] = "放蕩不羈的小夥子與海盜"
L["Fangs of Ashamane"] = "亞夏曼之牙"
L["Fangs of the Devourer"] = "吞噬者之牙"
L["Faol warned you about Light's Wrath — a staff of such devastating holy power that the Kirin Tor had sealed it in the Nexus Vault, deeming it too dangerous for any mortal. But desperate times demanded desperate weapons. You breached the Vault's defenses and claimed the staff, feeling its barely contained fury surge through you. Light's Wrath was not a gentle weapon — it was the Light's anger given form."] = "法奧警告你提防聖光之怒——一把擁有毀滅性神聖力量的法杖，祈倫托將它封存在奧核寶庫中，認為它對任何凡人來說都太過危險。但非常時期需要非常的武器。你突破寶庫的防禦，取得這把法杖，感受到它勉強壓抑的怒火在你體內奔湧。聖光之怒不是一把溫和的武器——它是聖光的憤怒化為實體。"
L["Farseer Aggralan"] = "先知阿格拉蘭"
L["Farseer Nobundo"] = "先知諾柏多"
L["Farseer's Campaign"] = "先知戰役"
L["Farseer's Raging Tempest"] = "先知的狂怒風暴"
