L["Field Evaluation"] = "實戰評估"
L["Field Repairs"] = "戰地搶修"
L["Fight through cursed Corlain, storm Waycrest Manor, and confront Lady Waycrest and Gorak Tul in the dungeon's depths."] = "殺穿受詛咒的寇連恩，突襲威奎斯特莊園，並在地城深處對抗威奎斯特夫人與勾拉圖爾。"
L["Fighting With Fire"] = "火攻"
L["Final Exit"] = "最後的出口"
L["Finality"] = "結局"
L["Find Ebonchill, the staff of Alodi — the first Guardian of Tirisfal — frozen in time within a pocket dimension."] = "找到黯冰——第一位提里斯法守護者艾洛迪的法杖，它在一個異次元空間中被凍結於時間裡。"
L["Find Lulubelle Fizzlebang in Stormheim, coerce a demon confession, and complete the Council's final selection."] = "前往斯鐸海姆尋找露露貝兒‧菲斯巴恩，逼迫惡魔招供，並完成議會的最終選拔。"
L["Find the Ancient Hero"] = "尋找遠古英雄"
L["Find the Boy"] = "尋找小樓"
L["Find the Scepter of Sargeras, a weapon that can tear rifts between worlds with a single strike."] = "找到薩格拉斯權杖，一把一擊便能在世界之間撕開裂隙的武器。"
L["Finding Ebonchill"] = "尋找黯凜"
L["Finding Fizzlebang"] = "尋找菲斯巴恩"
