L["Finish Me!"] = "給我個痛快!"
L["Finish Them!"] = "解決他們！"
L["Finishing the Job"] = "完成工作"
L["Finna Bjornsdottir"] = "芬娜‧比昂多特"
L["Fire Is Always the Answer"] = "火是唯一的解答"
L["Firelord Smolderon"] = "火焰之王斯莫德隆"
L["First Arcanist Thalyssra"] = "首席秘法師薩莉瑟拉"
L["First Contact"] = "第一次接觸"
L["First Legion Forward Camp"] = "第一軍團前線營地"
L["Fists of the Heavens"] = "天堂之拳"
L["Fit For a Pirate"] = "海盜專用"
L["Fizzi Tinkerbow"] = "斐姬‧修弓"
L["Fleet Admiral Tethys"] = "艦隊上將瑟希斯"
L["Fleet Admiral Tethys told the tale of the Dreadblades — cursed cutlasses that brought ruin to every captain who wielded them. You sailed to the burial site and pried them from the skeletal grip of their last owner, accepting the curse along with the power. The sea itself seemed to shudder as you brought them aboard."] = "艦隊上將瑟希斯講述了恐懼之刃的故事——一對為每一位揮舞它們的船長帶來毀滅的受詛咒彎刀。你航向埋葬之地，從它們最後一位主人的骷髏手中撬下了它們，連同力量一起接受了詛咒。當你把它們帶上船時，大海本身似乎也為之顫抖。"
L["Fletcher's Hollow is cursed — villagers turned to wicker constructs. Track the three witch sisters responsible and expose their matron."] = "造箭師谷地受到了詛咒——村民們都變成了柳條構造體。追蹤罪魁禍首的三名女巫姊妹，揭露她們的女首領。"
L["Fletcher's Hollow was worse than Fallhaven. The curse here had turned villagers into wicker constructs — living husks of thorns and hatred. Lucille led you through the ruins, saving who you could and putting down those beyond help. The trail pointed to three witch sisters working in concert. You charmed the lifeless, followed a revealing missive, and tracked the murderous matron to her lair. With the coven cell destroyed and an airtight alibi for who was truly behind the corruption, the pattern became clear — this was no scattered curse. It was organized. It was a war."] = "造箭師谷地的情況比落港村更糟。這裡的詛咒把村民變成了柳條構造體——由荊棘與仇恨構成的活軀殼。露西爾帶領你穿越廢墟，救下能救的人，了結無法挽回的人。線索指向三名聯手行動的女巫姊妹。你迷惑了無生命之物，跟隨一封揭露真相的信函，追蹤那名殺人如麻的女首領到她的巢穴。隨著巫團的這個分支被摧毀，誰才是腐化的真正幕後黑手也有了無懈可擊的證明，整個模式變得清晰——這不是零星的詛咒。它是有組織的。這是一場戰爭。"
L["Flockmaster Sergio"] = "獸群大師塞吉歐"
L["Flow Control"] = "流量控制"
L["Flying Colors"] = "火樹銀花"
L["Flynn Fairwind"] = "弗林‧晴風"
L["Focusing the Energies"] = "集中能量"
L["Fog of War"] = "戰爭迷霧"
L["Follow Matthias Lehner through Arthas' own memories to the foot of the citadel and Tirion's final gambit."] = "跟隨米希阿斯‧薩爾奈穿越阿薩斯本人的記憶，來到城塞腳下，見證提里奧最後的豪賭。"
L["Follow old friends across Pandaria, retracing the journey that shaped the Wandering Isle and the pandaren who left it behind. The mists have lifted, the war has moved on, and a new generation needs to understand what its elders carried into exile.\n\nWalk the slopes of Kun-Lai, sit at the brewmaster's hearth in the Valley of the Four Winds, and listen to stories the rest of the world has only just begun to hear."] = "跟隨老朋友走遍潘達利亞，重溫那段塑造了漂流島以及離開它的熊貓人的旅程。迷霧已經散去，戰爭已經遠去，而新的一代需要了解長輩們帶入流亡的是什麼。\n\n走上崑萊山的山坡，坐在四風峽釀酒大師的爐火旁，聆聽世界其他地方才剛開始聽聞的故事。"
L["Following In His Footsteps"] = "跟隨他的腳步"
L["Following the Curse"] = "追查詛咒"
L["For Gnomeregan!"] = "為了諾姆瑞根！"
L["For those who once swore loyalty to the Banshee Queen, a final message arrives — not to excuse the past, but to acknowledge it. The Forsaken move forward, but the echoes of old vows still linger in the ruins of Lordaeron."] = "對於曾經宣誓效忠女妖之王的人們，最後一則訊息送達了——不是為過去開脫，而是承認它。被遺忘者繼續向前邁進，但舊日誓言的回音仍在羅德隆的廢墟中縈繞。"
L["Forcing Fate's Hand"] = "施放天命之手"
L["Foreman Mann"] = "工頭蔓恩"
L["Foreman Raike"] = "工頭雷克"
L["Forensic Science"] = "鑑識科學"
L["Forfeit Souls"] = "喪失靈魂"
L["Forging the Armor"] = "鑄造護甲"
L["Forgotten Shadows"] = "被遺忘的暗影"
L["Fortifying the Temple"] = "強化神殿防禦"
L["Forward Camp is the last flat ground on the way to the citadel. Sappers finish what the bomb chain started. Sky-Commander Keller and Sky-Commander Ichman land their gunship crews to patch what the bombing shook loose. Matthias Lehner, the voice from the saronite pits, begins to speak plainly — and sends you into the Army of the Damned, into the wreckage beneath Sindragosa's broken hill, and into the futility of a hero's last charge. Everything he shows you has the shape of a confession."] = "前線營地是通往城塞路上最後一塊平地。工兵們完成了連鎖爆破所開啟的工作。天空指揮官凱勒與天空指揮官艾奇曼讓他們的砲艇船員降落，修補轟炸所震鬆的一切。米希阿斯‧薩爾奈，那個來自薩鋼礦坑的聲音，開始直言不諱——他把你送進詛咒軍團之中，送進辛德拉苟莎崩毀山丘下的殘骸，送進一位英雄最後衝鋒的徒勞。他讓你看見的一切，都帶著告解的形狀。"
L["Four dungeons. Four keys. Harlan Sweete and his pirates in Freehold, Overseer Korgus in Tol Dagor, Vol'zith the Whisperer beneath the Shrine of the Storm, the Drust Gorak Tul in Waycrest Manor — all of them fell. The Kul Tiran fleet, locked away by enemies and time and a nation that had stopped believing in itself, was free again. Then came the Siege of Boralus: Priscilla Ashvane, revealed as the architect of Kul Tiras's rot, made her last stand in the harbor. She fell too.\n\nIn Unity Square, Katherine Proudmoore stood before her daughter for the first time in years. She spoke the words no one had expected her to say: she stepped aside. She named Jaina Lord Admiral. She called her back — not as a Kul Tiran returning home, but as the heir to a seat her mother had been keeping warm. The fleet sailed. The song that Jaina's father had sung to her as a child played across the harbor."] = "四座地城。四把鑰匙。自由港的哈蘭‧史威特與他的海盜們、托達戈爾的監督者寇格斯、風暴聖壇之下的『低語者』沃澤斯、威奎斯特莊園的德魯斯人勾拉圖爾——全都倒下了。被敵人、時間，以及一個不再相信自己的國家所封鎖的庫爾提拉斯艦隊，終於重獲自由。接著是波拉勒斯圍城戰：被揭露為庫爾提拉斯腐敗根源的普莉希拉‧艾胥凡，在港口做出最後的抵抗。她也倒下了。\n\n在聯合廣場上，凱瑟琳‧普勞德摩爾多年來第一次站在女兒面前。她說出了沒有人預料到的話：她選擇退位。她任命珍娜為海軍上將。她召喚她回來——不是以一名歸鄉的庫爾提拉斯人身分，而是以繼承人的身分，接掌母親一直為她保留的位子。艦隊揚帆啟航。珍娜的父親在她小時候唱給她聽的那首歌，在港口上空響起。"
L["Fractured Forces"] = "破敗的部隊"
L["Fragments of Disaster"] = "災禍碎片"
L["Frazzle Geargrinder"] = "芙芮索‧齒磨"
L["Free Your Mind"] = "解放你的心靈"
L["Freeing Our Brothers"] = "解放我們的弟兄"
L["Friends in Cages"] = "朋友受困"
L["Friends On the Outside"] = "外頭的朋友"
L["Friends With Benefits"] = "禮尚往來"
L["Fringe Science Benefits"] = "邊緣科學的好處"
L["From Acherus: The Ebon Hold, the Knights of the Ebon Blade wage their own war against the Burning Legion. The order has no king. It has a Deathlord, and the Deathlord is you.\n\nRaise champions from graveyards across history, gather an army that does not fear death, and decide how far the Ebon Blade is willing to go when the living world needs monsters on its side."] = "黯刃騎士團從亞榭洛：黯黑堡出發，對燃燒軍團發動屬於他們自己的戰爭。這個騎士團沒有國王。它有一位死亡領主，而那位死亡領主就是你。\n\n從歷史上的各個墓地喚起勇士，集結一支不畏死亡的大軍，並決定當生者的世界需要怪物站在它這一邊時，黯刃騎士團願意走得多遠。"
L["From Dreadscar Rift, a pocket of the Twisting Nether claimed by force, the Council of the Black Harvest commands demons to fight demons. It is dangerous work, which is exactly why warlocks are suited to it.\n\nAs Netherlord, rebuild the council, bargain with powers that should not be trusted, and prove that a stolen weapon can still be aimed."] = "黑暗收割議會從懼痕裂隙——一處以武力奪下的扭曲虛空口袋空間——號令惡魔去對抗惡魔。這是危險的工作，而這正是術士適合它的原因。\n\n身為虛空領主，你將重建議會，與不該信任的力量討價還價，並證明一把偷來的武器依然可以瞄準目標。"
L["From the Depths of Azjol-Nerub"] = "從阿茲歐-奈幽的深處"
L["From the Fel Hammer on Mardum, the Illidari wage war against the Burning Legion with the very weapons of the enemy. Their methods are feared, their purpose is absolute, and their enemies know them well.\n\nAs the chosen Slayer, unite the demon hunters, reclaim old ground, and carry the fight into places where fel fire has ruled for ages."] = "伊利達瑞從馬爾頓上的魔化之錘號出發，以敵人的武器對燃燒軍團開戰。他們的手段令人畏懼，他們的目標毫不動搖，而他們的敵人對他們再熟悉不過。\n\n身為天選的屠魔者，你將團結惡魔獵人，奪回昔日的領土，並將戰火帶入魔化烈焰已統治多年的地方。"
L["From Trueshot Lodge high in the mountains, the Unseen Path watches over Azeroth. Its hunters know the old trails, the hidden passes, and the signs most armies march past without seeing.\n\nAs the order's newest champion, recruit legendary trackers, root out Legion threats, and defend the wild places and cities that still need sharp eyes on the horizon."] = "隱秘之道從高山上的神獵廳守望著艾澤拉斯。這個組織的獵人熟知古老的小徑、隱密的隘口，以及大多數軍隊行軍而過卻視而不見的徵兆。\n\n身為組織最新的勇士，你將招募傳奇追蹤者，剷除軍團的威脅，並守護那些仍需要銳利目光凝望地平線的荒野與城市。"
L["From Whence They Came"] = "從何而來"
L["Frostmourne"] = "霜之哀傷"
L["Frozen Memories"] = "冰封的記憶"
L["Fu Zan, the Wanderer's Companion"] = "伏贊，流浪者的夥伴"
L["Full Might of the Elves"] = "精靈全力出擊"
L["Fun With Landmines"] = "踩地雷"
L["Furious Familiars"] = "狂怒的動物"
L["Furious Fowl"] = "憤怒鳥"
L["Futility"] = "毫無意義"
L["G.E.A.R. Up"] = "地精天兵上陣"
L["G'Hanir, the Mother Tree"] = "基漢尼爾，母樹"
L["Gaining the Upper Hand"] = "搶得先機"
L["Gakin the Darkbinder"] = "『黑暗縛靈師』加金"
L["Gakin the Darkbinder dispatched troops while Ritssyn uncovered troubling archives — bloodstones were appearing across the Broken Isles, corrupting the land with fel energy. You traveled to Azsuna where Kira Iresoul was already investigating. Together you traced the bloodstone bandits to their source, tested a theory on the stones' hunger for blood, and repaid the debt with fire. Jubeka Shadowbreaker and Zinnin Smythe joined the Council as champions. A daring rescue followed — the Council looked after its own."] = "『黑暗縛靈師』加金負責派遣部隊，瑞特辛則發現了令人不安的檔案——血石正在破碎群島各地出現，以魔化能量腐化大地。你前往艾蘇納，琪拉‧怒魂早已在那裡展開調查。你們一同追查血石強盜的源頭，測試了一項關於血石渴求鮮血的理論，並以火焰償還了這筆債。裘貝卡‧破影者與辛尼‧斯麥瑟以勇士身分加入議會。隨後展開了一場即刻救援——議會總會照顧自己人。"
L["Galakrond and the Scourge"] = "葛拉克朗與天譴軍團"
L["Galgar's Cactus Apple Surprise..."] = "戈加爾的仙人掌鮮果飲…"
L["Garona Halforcen"] = "迦羅娜‧半血"
L["Garrosh sent the Horde to seize whatever had been hidden in the mists. Instead, Hellscream's Fist fell burning into the Jade Forest. Nazgrim drove the survivors forward with fire and discipline, but the first victory curdled quickly. Taran Zhu named the consequence of the Horde's fury: sha. The Horde regrouped at Honeydew Village, pulled its scattered officers out of danger, and learned that Pandaria would answer violence with something far older than either faction expected."] = "卡爾洛斯派遣部落奪取迷霧中隱藏的一切。結果，地獄吼之拳號卻燃燒著墜入翠玉林。納茲格寧姆以火焰與紀律驅策倖存者前進，但最初的勝利很快就變了調。塔蘭‧祝點明了部落怒火的後果：煞。部落在甘露村重整旗鼓，將四散的軍官救出險境，並明白潘達利亞將以遠比任何陣營預期都更古老的力量來回應暴力。"
L["Gates of the Nighthold"] = "暗夜堡大門"
L["Gathering of the Storms"] = "風暴交會"
L["Gauging Our Progress"] = "衡量進度"
L["Geirrvif"] = "蓋爾維孚"
L["General Draven"] = "德瑞文將軍"
L["General Nazgrim"] = "納茲格寧姆將軍"
L["Generosity Abounds"] = "慷慨大放送"
L["Genn Greymane"] = "吉恩‧葛雷邁恩"
L["Gentle Mother Hanae"] = "溫柔的漢妮媽媽"
L["Get Back Here!"] = "快回來!"
L["Get the Key"] = "取得鑰匙"
L["Get to Ymirheim!"] = "前進依米海姆!"
L["Get Your Bearings"] = "熟悉環境"
