L["Gilneas survived exile through loyalty, discipline, and the will to endure. By facing the darkness within and without, you helped carry that legacy forward."] = "吉爾尼斯憑藉忠誠、紀律與堅忍的意志，熬過了流亡。透過直面內在與外在的黑暗，你協助將這份傳承延續下去。"
L["Give Me Fuel, Give Me Fire"] = "給我燃料，給我火焰"
L["Giving It All We've Got"] = "能量全開"
L["Glenbrook Homestead, Drustvar"] = "谷溪村（佐司瓦）"
L["Gnomercy!"] = "無情地精！"
L["Gnomeregan"] = "諾姆瑞根"
L["Gnomeregan's Finest"] = "諾姆瑞根的最強高手"
L["Go with Honor, Friend"] = "願榮耀伴你同行，朋友"
L["Goldrinn"] = "戈德林"
L["Good Fiery Boy"] = "熱情的好孩子"
L["Good For Something?"] = "有什麼好料的?"
L["Gorkun Ironskull"] = "葛剛‧鐵顱"
L["Grab and Go"] = "連抓帶跑"
L["Grand Anchorite Almonen"] = "大隱士艾蒙南"
L["Grand Artificer Romuul"] = "大工藝師羅穆爾"
L["Grand Executor Mortuus"] = "總執行官莫吐斯"
L["Grand Magistrix Elisande sealed the city, sending her Duskwatch to crush any hint of dissent. The crackdown was swift and merciless. You fought through patrols and barricades to evacuate nightfallen sympathizers before they could be captured, but not everyone made it out. As the gates slammed shut, the rebellion was forced deeper underground."] = "大魔導師伊莉珊德封鎖了城市，派出她的暮衛去粉碎任何異議的苗頭。鎮壓來得迅速而無情。你殺穿巡邏隊與路障，在夜落者同情者被捕前將他們撤離，但並非每個人都逃了出來。隨著城門重重關上，反抗軍被迫轉入更深的地下。"
L["Grandmaster's Campaign"] = "宗師戰役"
L["Greatmother Icemist"] = "主母冰霧"
L["Greatmother Icemist weeps over a quiet fire. Her son is chained somewhere beneath this frozen plain, and her daughter Banthok is ready to cut every Anub'ar web in the world to bring him home. The Taunka are a proud and wounded people, shaggy cousins to the Tauren whose strength the Scourge has long bled for sport. If they rise again, they rise with the Horde."] = "主母冰霧在靜靜燃燒的火堆旁哭泣。她的兒子被鎖在這片冰原下的某處，而她的女兒班索克準備斬斷世上每一張阿努巴爾的蛛網，只為帶他回家。坦卡族是個驕傲又傷痕累累的民族，他們是牛頭人毛髮濃密的近親，長久以來天譴軍團以讓他們流血為樂。若他們再次崛起，必將與部落並肩。"
L["Green Technology"] = "綠色科技"
L["Green-ish Energy"] = "綠綠的能量"
L["Grif Wildheart spoke of Titanstrike — a rifle of immense power forged by Mimiron himself in the halls of Ulduar. You embarked on a beastly expedition to recover the weapon, facing titan constructs and wild guardians. When you finally held Titanstrike, its mechanisms hummed with the power of a thousand storms."] = "格瑞夫講述了泰坦之擊的故事——一把由彌米倫親手在奧杜亞的殿堂中鍛造、擁有無窮力量的步槍。你展開一場野性遠征以取回這把武器，面對泰坦構造體與狂野的守護者。當你終於握住泰坦之擊時，它的機械裝置嗡嗡作響，蘊含著千場風暴的力量。"
L["Grim Tidings"] = "無情消息"
L["Grip of Nightmare"] = "夢魘之握"
L["Grommash Hold, Orgrimmar"] = "葛羅瑪許堡（奧格瑪）"
L["Grookin Hill"] = "葛魯山丘"
L["Grookin Hill roared to life in exactly the way a hozen fortress would: loud, improvised, and enthusiastic about explosives. Chief Kah Kah had given the Horde a foothold, but Nazgrim still needed scouts, maps, and pressure against the Alliance. Rivett sent messages through ridiculous means, Shokia and the scouts reported enemy positions, and the Horde learned how the jinyu, SI:7, and Alliance soldiers fit together. By the end, Guerrillas in our Midst became Burning Down the House. The hozen pact held, and the road to Dawn's Blossom opened through smoke."] = "葛魯山丘以猴人要塞應有的方式熱鬧了起來：吵鬧、隨性，而且對炸藥充滿熱情。卡卡酋長為部落提供了立足點，但納茲格寧姆仍需要斥候、地圖，以及對聯盟的施壓。理弗特用荒唐可笑的方式傳遞訊息，修基雅與斥候們回報敵軍位置，部落也弄清楚了錦魚人、軍情七處與聯盟士兵是如何互相配合的。到最後，「搜索游擊隊」變成了「燒為平地」。猴人的盟約維持住了，通往晨綻的路也在硝煙中打開。"
L["Ground Commander Koup"] = "地面指揮官庫普"
L["Ground Commander Xutjja"] = "地面指揮官蘇加"
L["Groundskeeper Wu"] = "園丁老吳"
L["Grovebound"] = "返回林地"
L["Growing Power"] = "力量漸增"
L["Grumnus Steelshaper"] = "格魯努斯‧削鋼"
L["Guerrillas in our Midst"] = "搜索游擊隊"
L["Guided by Kel'danath's research, you descended into ancient caverns beneath Suramar, where moonlight filtered through crystal and the memories of the city's founding still lingered. You discovered the hidden legacy of Valewalker Farodin and the Arcan'dor — a tree of immense power that might hold the key to curing the nightfallen's addiction to the Nightwell."] = "在凱爾達納斯的研究指引下，你深入蘇拉瑪爾地底的遠古洞窟。月光穿透水晶灑落，這座城市建立之初的記憶仍縈繞不去。你發現了谷行者費羅丁的隱密遺產，以及阿坎多爾——一棵蘊藏無窮力量的巨樹，或許正是治癒夜落精靈對夜井成癮的關鍵。"
L["Gunpowder Research"] = "火藥研究"
L["Guts and Gore"] = "腸與血"
L["Halduron Brightwing"] = "赫杜倫‧亮翼"
L["Halford Wyrmbane"] = "海弗德‧龍禍"
L["Hall of the Guardian / Broken Isles"] = "守護者殿堂 / 破碎群島"
L["Halls of Valor"] = "英靈殿"
L["Halls of Valor: Odyn's Cauldron"] = "英靈殿：歐丁之鍋"
L["Halls of Valor: The Brewmaster"] = "英靈殿：釀酒大師"
L["Halting the Empire's Fall"] = "阻止帝國覆滅"
L["Hamuul Runetotem sends an urgent summons. Through the Emerald Dreamway, you discover the Dreamgrove and take up a weapon of legend."] = "哈繆‧符文圖騰緊急召喚你。你穿越翡翠夢途，發現了夢林，並拿起一把傳說武器。"
L["Hanzabu"] = "漢札布"
L["Hanzabu leads you to Bwonsamdi, loa of death, deep in his Necropolis. He will fight the blood trolls — for one million souls."] = "漢札布帶你深入伯昂撒姆第的亡者之城，去見這位死亡洛阿。他願意對抗血食人妖——代價是一百萬個靈魂。"
L["Hanzabu, servant of the death loa, led you into Bwonsamdi's Necropolis — a place where the veil between the living and the dead was thin enough to talk through. Bwonsamdi was many things: charming, unsettling, and entirely in control of any room he entered. He had watched the blood trolls desecrate his death shrines and steal souls that were owed to him. He was not pleased. The deal he offered was simple — his power in exchange for one million souls delivered to his realm. You cleansed his temple of spirits who had fled to G'huun, repelled Grand Ma'da Ateena's interruption of the sealing ritual, and sealed the pact. A deal with a death loa is not something you walk back from."] = "漢札布是死亡洛阿的僕從，他帶你進入伯昂撒姆第的亡者之城——在這裡，生者與死者之間的帷幕薄得足以隔著它交談。伯昂撒姆第有許多面貌：迷人、令人不安，而且不論走進哪個房間，總能完全掌控全場。他眼看著血食人妖褻瀆他的死亡神壇，偷走本該歸他所有的靈魂。他很不高興。他開出的條件很簡單——他的力量，換取送進他領域的一百萬個靈魂。你淨化了他的神殿，驅逐那些投靠古翰的靈魂，擊退大族長艾提娜對封印儀式的干擾，締結了契約。與死亡洛阿的交易，一旦成立就無法回頭。"
L["Hao Mann"] = "郝‧蔓恩"
L["Harmful If Swallowed"] = "服用會有副作用"
L["Harnessing Power"] = "駕馭力量"
L["Hatred's Focus"] = "憎恨的集核"
L["He Who Walks in the Light"] = "行聖光之道"
L["He's Gone to Pieces"] = "他被大卸八塊了"
L["Head of the Viper"] = "臭蛇之首"
L["Heart of Lukou"] = "盧考之心"
L["Heart of the Issue"] = "麻煩源頭"
L["Held Captive!"] = "救苦救難"
L["Hellscream's Fist crashes into Pandaria, leaving Nazgrim to turn wreckage, survivors, and frightened locals into a foothold."] = "地獄吼之拳墜落在潘達利亞，納茲格寧姆只能把殘骸、倖存者和驚恐的當地居民，整合成一處立足點。"
L["Help Chief Telemancer Oculeth restore the teleportation network, opening new paths across Suramar."] = "協助首席傳送師歐庫雷斯修復傳送網路，開闢橫跨蘇拉瑪爾的新路徑。"
L["Helping the Cause"] = "一臂之力"
L["Helya's Horn"] = "黑爾雅的號角"
L["Hemet Nesingwary"] = "赫米特‧奈辛瓦里"
L["Hemet Nesingwary joined the hunt in Highmountain, his expertise invaluable as you tracked the Legion's movements. But the true threat emerged in Azsuna — leyworms corrupted by demonic energy, twisting the beasts of the land into weapons. Working with Kira Iresoul, you lured out the source of the corruption and tamed it, proving that a hunter's bond with nature was stronger than any demon's magic."] = "赫米特‧奈辛瓦里加入了高嶺的狩獵行動，在你追蹤燃燒軍團的動向時，他的專業發揮了莫大的作用。然而真正的威脅出現在艾蘇納——遭惡魔能量腐化的地脈蟲，正把這片土地上的野獸扭曲成武器。你與琪拉‧怒魂聯手引出腐化的源頭並將其馴服，證明了獵人與自然之間的羈絆，比任何惡魔魔法都更加強大。"
L["Herald Their Demise"] = "他們的死亡信使"
L["Herding Goats"] = "圍捕山羊"
L["Heritage o' the Dark Iron"] = "黑鐵的傳承"
L["Heritage of Draenor"] = "德拉諾的傳承"
L["Heritage of Gilneas"] = "吉爾尼斯的傳承"
L["Heritage of Gnomeregan"] = "諾姆瑞根的傳承"
