L["Heritage of the Bronzebeard"] = "銅鬚的傳承"
L["Heritage of the Darkspear"] = "暗矛的傳承"
L["Heritage of the Draenei"] = "德萊尼的傳承"
L["Heritage of the Forsaken"] = "被遺忘者的傳承"
L["Heritage of the Kaldorei"] = "卡多雷的傳承"
L["Heritage of the Shu'halo"] = "修哈洛的傳承"
L["Heritage of the Sin'dorei"] = "辛多雷的傳承"
L["Heritage of the Wandering Isle"] = "漂流島的傳承"
L["Hexecutioner"] = "斬巫除邪"
L["Hidden Dealings"] = "暗中行事"
L["Hiding In Plain Sight"] = "隱匿行蹤"
L["High Artificer Ataanya"] = "高階工藝師阿潭雅"
L["High Captain Justin Bartlett"] = "提督賈斯汀‧巴特勒"
L["High Commander Halford Wyrmbane"] = "高階指揮官海弗德‧龍禍"
L["High Elder Cloudfall"] = "高階長者雲落"
L["High Executor Darthalia"] = "高階執行官達薩利亞"
L["High Executor Derrington"] = "高階執行官德靈頓"
L["High Overlord Saurfang"] = "薩魯法爾霸王"
L["High Priest of Netherlight"] = "虛空之光大祭司"
L["High Priest's Campaign"] = "高階牧師戰役"
L["Highlord Bolvar Fordragon"] = "大領主伯瓦爾‧弗塔根"
L["Highlord Bolvar Fordragon leads you up the spiral of Wyrmrest Temple. Alexstrasza the Life-Binder has watched the war in Dragonblight with ancient, weary eyes. She owes the Alliance nothing. She owes the living everything. If she can be moved, her fire will answer for Azeroth's dead — and a ruby wing will carry you over ground no army could cross."] = "大領主伯瓦爾‧弗塔根帶你登上龍眠神殿的螺旋階梯。『生命守縛者』雅立史卓莎以古老而疲憊的雙眼，注視著龍骨荒野的戰事。她不欠聯盟什麼，卻欠所有生者一切。若能打動她，她的烈焰將為艾澤拉斯的亡者討回公道——而一雙赤紅之翼將載你飛越任何軍隊都無法跨越的大地。"
L["Highlord Darion Mograine"] = "大領主達瑞安‧莫格萊尼"
L["Highlord Demitrian"] = "大領主德米提恩"
L["Highlord Tirion Fordring"] = "大領主提里奧‧弗丁"
L["Highlord's Campaign"] = "大領主戰役"
L["Highlord's Golden Charger"] = "大領主的金色戰馬"
L["Highmountain Hunters"] = "高嶺獵人"
L["Hir'eek, the Bat Loa"] = "蝙蝠羅亞，希爾雷克"
L["Hired Help"] = "有錢能使鬼推磨"
L["Hobart Grapplehammer"] = "荷巴爾特‧繫錘"
L["Hobart Grapplehammer has a masterpiece, a deadline, and a former employer determined that neither will reach completion. Trade Prince Gallywix has eyes everywhere, and the workshop where the work has to happen is exactly as glamorous as Crapopolis sounds.\n\nReunite old allies, outplay better-funded saboteurs, and keep one bombastic invention from being seized, sold, stolen, exploded, or all four in sequence."] = "荷巴爾特‧繫錘手上有一件傑作、一個截止期限，還有一位決心讓兩者都無法完成的前老闆。貿易親王加里維克斯耳目遍布各處，而必須完成這項工作的工坊，就跟「廢坑市集」這個名字聽起來一樣光鮮亮麗。\n\n重聚昔日盟友，智勝財力更雄厚的破壞者，並確保一項浮誇的發明不會被奪走、賣掉、偷走、炸毀，或是依序經歷以上四種下場。"
L["Hodir"] = "霍迪爾"
L["Hold The Barricade!"] = "守住路障！"
L["Hold Wintergarde Keep against the tide rolling down from Naxxramas."] = "守住溫特加德要塞，抵擋從納克薩瑪斯席捲而來的大軍。"
L["Holgar Stormaxe"] = "霍加爾‧雷斧"
L["Homecoming"] = "重返家園"
L["Honeydew Village"] = "甘露村"
L["Honor Above All Else"] = "榮譽至上"
