L["Hope For a Cure"] = "解藥的希望"
L["Hope They Can't Swim"] = "希望他們不會游泳"
L["Hope Within the Emerald Nightmare"] = "翡翠夢魘中的一絲希望"
L["Hope Yet Remains"] = "希望尚存"
L["Horde"] = "部落"
L["Hostage Situation"] = "充當人質"
L["Hot Pursuit"] = "緊追不捨"
L["House of Plagues"] = "瘟疫家族"
L["House Waycrest"] = "威奎斯特家族"
L["How It's Made: Arcwine"] = "製作過程：秘能酒"
L["How to Be a Blood Troll"] = "如何當個鮮血食人妖"
L["How to Repair a Titan Keeper"] = "如何修復泰坦守衛者"
L["Hozen Aren't Your Friends, Hozen Are Your Enemies"] = "猴人不是朋友，猴人是敵人"
L["Hudson Crawford"] = "哈德森‧克勞福"
L["Hue"] = "色澤"
L["Hungry Work"] = "飢餓難耐"
L["Hunt a Legion commander through Stormheim, prepare the Fel Hammer for interdimensional travel, and invade the demon world Niskara."] = "在斯鐸海姆追獵一名燃燒軍團指揮官，為魔錘做好跨次元航行的準備，並進攻惡魔世界尼斯卡拉。"
L["Hunt down the Twinblades of the Deceiver — warglaives forged in felfire and wielded by a champion of the Legion."] = "追獵欺詐者雙刃——以魔火鍛造、由燃燒軍團勇士揮舞的戰刃。"
L["Hunt the Hunter"] = "追捕獵人"
L["Hunt the legendary hero-slayer in Stormheim to claim a pair of rune-etched swords forged for the fury of battle."] = "前往斯鐸海姆追獵傳奇的英雄殺手，奪取一對為戰鬥狂怒而鍛造的符文雙劍。"
L["Huntmaster's Campaign"] = "狩獵大師戰役"
L["Husshun, the Wizened"] = "乾癟的賀司涵"
L["Hymdall"] = "海姆達爾"
L["I Am Forsaken"] = "我是被遺忘者"
L["I Am the Slayer!"] = "我是斬魔者！"
L["I Don't Get My Hands Dirty"] = "髒事換人做"
L["I Have an Idea, But First..."] = "我有個點子，但首先..."
L["I Have No Jade And I Must Scream"] = "無玉狂嘯"
L["I'll Just Leave This Here"] = "就放在這裡"
L["I'm Not Dead Yet!"] = "我還沒死!"
L["I'm Smelting... Smelting!"] = "我熔...熔化了!"
L["I've Got What You Need"] = "我有你需要的東西"
L["Icecrown Citadel"] = "冰冠城塞"
L["Icecrown's End"] = "寒冰皇冠的終局"
L["Idol of the Wilds"] = "荒野塑像"
L["If He Cannot Be Turned"] = "如果無法感化他"
L["If There Are Survivors..."] = "如果有生還者..."
L["If These Stones Could Speak"] = "如果這些石頭會說話"
L["If Words Don't Work..."] = "如果言語無效…"
L["Imbeciles Abound!"] = "到處都是白痴!"
L["Immortal Soul"] = "不朽之魂"
L["Impending Dooooooom!"] = "逼近的末末末末末日！"
L["Implements of Ill Intent"] = "惡意的陷阱"
L["Improper Burial"] = "非正式喪禮"
L["In ancient Drust ruins, Lucille discovers the Order of Embers — an old organization of witch hunters. She vows to rebuild it."] = "在古老的德魯斯遺跡中，露西爾發現了燼火會——一個歷史悠久的獵巫組織。她立誓要重建它。"
L["In Case of Ambush"] = "以防偷襲"
L["In Deep Slumber"] = "深深沉眠"
L["In Defense of Dalaran"] = "保護達拉然"
L["In Gloom Hollow, the great frog loa Krag'wa hungers — and he is willing to fight if you can earn his trust. Become a friend of the frogs."] = "在幽暗谷，偉大的蛙之洛阿克拉格瓦正飢腸轆轆——只要你能贏得他的信任，他就願意出戰。去成為青蛙們的朋友吧。"
L["In Netherlight Temple, priests of the Light and the Void unite under one banner. Faith, shadow, discipline, and doubt all have a place when the world is facing annihilation.\n\nAs High Priest, bridge old divides, investigate zealots and lost allies, and hold together a conclave built from powers that do not always agree they should stand side by side."] = "在虛空之光神殿，聖光與虛無的牧師在同一面旗幟下團結。當世界面臨毀滅，信仰、暗影、戒律與懷疑都有一席之地。\n\n身為大主教，你要彌合舊有的分歧，調查狂熱分子與失蹤的盟友，並維繫一個由各方力量組成的議會——而這些力量未必認同彼此應該並肩而立。"
L["In Search of the Eye"] = "尋找鴉眼"
L["In Search of Wisdom"] = "尋找智慧"
L["In the Bag"] = "十足把握"
L["In the Business of Souls"] = "靈魂交易"
L["In the Forest Ward, the Venthyr teach humility by giving souls hope and then hunting them down. The Accuser helps you see the cruelty beneath the lesson."] = "在森林區，汎希爾先給予靈魂希望，再將其獵殺，藉此教導謙卑。控罪者幫助你看清這番教誨背後的殘酷。"
L["In the Hall of the Drust King"] = "勾拉圖爾的大廳"
L["In the Ruin of Rebellion"] = "在叛亂的廢墟中"
L["In the wake of the Peak of Serenity's fall, you prepared to strike back. The Fists of the Heavens — enchanted handwraps that crackled with storm energy — were said to channel the very fury of the skies. You fought through the Legion's forces to claim them, and with each punch, thunder rolled across the battlefield."] = "寂靜峰淪陷後，你準備展開反擊。據說天堂之拳——迸發著風暴能量的附魔裹手——能引導蒼穹本身的怒火。你殺出燃燒軍團的重圍奪得了它，每揮出一拳，雷聲便在戰場上隆隆迴響。"
L["In twilight shadows, Faol revealed the existence of Xal'atath — a blade forged in the age of the Black Empire, before even the titans came to Azeroth. The dagger whispered constantly, its voice ancient and knowing, full of secrets that could drive lesser minds mad. You claimed it from a twilight cult's grasp, and from that moment on, the whispers never stopped. Xal'atath remembered everything — and it wanted you to know."] = "在暮光的陰影中，法歐揭露了薩拉塔斯的存在——一把鍛造於黑色帝國時代的利刃，甚至早於泰坦降臨艾澤拉斯。這把匕首不停低語，聲音古老而洞悉一切，充滿足以讓心志薄弱者發狂的秘密。你從一個暮光教團手中奪下了它，從那一刻起，低語再也沒有停過。薩拉塔斯記得一切——而且它要你知道。"
L["Infiltrate the Nightborne wine trade, disrupting the flow of arcwine that keeps the populace loyal to the Grand Magistrix."] = "滲透夜裔精靈的酒類貿易，阻斷讓民眾效忠大博學者的秘法酒流通。"
L["Infiltrate the Scarlet Onslaught, the fanatical remnant of the Scarlet Crusade, and recruit a defector to your cause."] = "滲透血色先鋒軍——血色十字軍的狂熱殘黨——並招募一名叛逃者加入你的陣營。"
L["Infiltrate Zalamar disguised as a blood troll. The bat loa Hir'eek has been corrupted — you must end the corruption and the loa with it."] = "偽裝成血食人妖潛入札拉瑪。蝙蝠洛阿希爾雷克已遭腐化——你必須終結這股腐化，連同洛阿一起。"
L["Infiltrating Our Enemies"] = "滲透敵人"
L["Information at Any Cost"] = "不計代價的消息"
L["Informing Our Allies"] = "通知我們的盟友"
L["Initiate Da-Nel"] = "學徒達奈"
L["Inkmaster Wei"] = "水墨大師老魏"
L["Inquisitor Cleardawn"] = "審判官科利爾東"
L["Inquisitor Cleardawn leads the southern campaign through the old roads, clearing Drust strongholds along the way."] = "審判官科利爾東率領南方戰役穿越古道，一路掃蕩德魯斯的據點。"
L["Inquisitor Cleardawn took command of the southern front. Through the old roads you marched — ancient paths the Drust had walked millennia before. The pieces of history you uncovered told a chilling story: the Drust had not simply been defeated in the past. They had been driven into hiding, and they had been waiting. You gave their soldiers an honorable discharge — the permanent kind — and pushed through to a clear victory. But the Drust ruins at Gol Osigr loomed ahead, and the fall of the Drust was far from over."] = "審判官科利爾東接掌了南方戰線的指揮。你穿過古道進軍——那是德魯斯在數千年前走過的古老路徑。你發掘的歷史碎片揭露了一段令人膽寒的故事：德魯斯在過去並非單純遭到擊敗，而是被迫藏匿起來，並一直在等待。你讓他們的士兵「光榮退役」——永久的那種——並一路推進，取得明確的勝利。但戈爾歐希的德魯斯遺跡已赫然在前，德魯斯的覆滅還遠未結束。"
L["Inquisitor Stelia's Sinstone"] = "審判官史黛拉的罪孽石"
L["Inquisitor Sterntide"] = "審判官斯騰泰德"
L["Inquisitor Vilhelm's Sinstone"] = "審判官維爾海姆的罪孽石"
L["Inside the Frozen Citadel"] = "進入冰凍城塞"
L["Instant Messaging"] = "即時通"
L["Instructor Myang"] = "講師崔眠"
L["Instructor Xann"] = "講師老詹"
L["Insurrection"] = "起義"
L["Insurrection: Crafting War"] = "起義：戰爭工坊"
L["Intense Concentration"] = "無比專注"
L["Interest Yah In A Pint?"] = "來一杯如何？"
L["Into Darkness"] = "深入黑暗"
L["Into Duskwood"] = "深入暮色森林"
L["Into Hostile Territory"] = "大敵當前"
L["Into Our Ranks"] = "加入我方"
L["Into the Crevasse"] = "深入裂隙"
L["Into the Crimsonwood"] = "深入緋紅森林"
L["Into The Darkness"] = "深入黑暗"
L["Into the Dragonblight"] = "前進龍骨荒野"
L["Into the Fold"] = "進入窪地"
L["Into The Frozen Heart Of Northrend"] = "深入北裂境的冰凍心臟"
L["Into the Heart of Tiragarde"] = "深入提拉加德內陸"
L["Into the Light"] = "走進聖光"
L["Into the Mists"] = "進入霧中"
L["Into the Oculus"] = "進入奧核之眼"
L["Into the Void"] = "深入虛無"
L["Into The Wild Green Yonder"] = "駭速快手"
L["Investigate bloodstone corruption in Azsuna. Kira Iresoul proves her worth as the Council recruits new champions."] = "調查艾蘇納的血石腐化。在議會招募新勇士之際，琪拉‧怒魂證明了自己的價值。"
L["Investigate conspiracy and betrayal tied to Stormwind's past and the Defias Brotherhood."] = "調查與暴風城的過往及迪菲亞兄弟會有關的陰謀與背叛。"
L["Investigate void disturbances in Azsuna alongside Zabra Hexx and Yalia Sagewhisper."] = "與薩布拉‧海克斯和雅里亞‧賢語者一同調查艾蘇納的虛無異象。"
L["Invitation of the Master"] = "主宰的邀請"
L["Invitation to the Spirit Festival"] = "靈魂節邀請函"
L["Iron-Body Ponshu"] = "鐵胴彭舒"
L["Iron-Body Ponshu received a desperate report — Tian Monastery was under attack. You rushed to its defense alongside Taran Zhu, the grim Shado-Pan lord, and The Monkey King, whose tricks proved as deadly as any blade. Instructor Myang held the line while you slowed the Legion's spread, and together you struck down the Hand of Keletress who led the assault. High Elder Cloudfall oversaw the monastery's rebuilding, and both Taran Zhu and The Monkey King pledged themselves as your champions."] = "鐵胴彭舒接獲一份緊急報告——天僧寺遭到攻擊。你與嚴峻的影潘領袖塔蘭‧祝，以及詭計和任何刀刃一樣致命的美猴王一同趕去救援。講師崔眠堅守防線，你則延緩燃燒軍團的擴散，最後你們聯手擊倒了率領攻勢的凱萊翠斯之手。高階長者雲落負責監督寺院的重建，塔蘭‧祝與美猴王也都誓言成為你的勇士。"
L["Iron-Body Ponshu revealed that Sheilun — the staff of Emperor Shaohao himself — had been hidden since the emperor used it to shroud Pandaria in mist ten thousand years ago. You followed the trail of ancient magic to its resting place, where Shaohao's mists still swirled protectively around the staff. When you claimed Sheilun, the mists parted willingly — as if the emperor had been waiting for someone to carry his burden."] = "鐵胴彭舒透露，謝倫——紹昊大帝的法杖——自從一萬年前大帝用它讓潘達利亞籠罩在迷霧中之後，便一直隱藏至今。你循著遠古魔法的痕跡找到它的安息之地，紹昊的迷霧仍在法杖周圍盤旋守護。當你取得謝倫時，迷霧欣然散開——彷彿大帝一直在等待有人來承擔他的重任。"
L["Iron-Body Ponshu spoke of a legend — the Storm Brew, a drink of such power it could turn the tide of any battle. The recipe was held by Aegira, a vrykul brewmaster who had perfected her craft in the Halls of Valor over centuries. You entered Odyn's domain, earned the right to brew alongside Aegira, and retrieved the ingredients from Odyn's own cauldron. The Storm Brew was unlike anything brewed on Azeroth — and with it, your weapon was reforged to its full power. The Grandmaster's campaign was complete."] = "鐵胴彭舒談到一則傳說——風暴蜜酒，一種威力強大到足以扭轉任何戰局的飲品。酒方掌握在艾綺菈手中，這位維酷人釀酒大師數百年來在英靈殿中不斷精進手藝。你進入歐丁的領域，贏得與艾綺菈一同釀酒的資格，並從歐丁自己的大鍋中取得材料。風暴蜜酒與艾澤拉斯上釀過的任何酒都截然不同——藉由它，你的武器得以重鑄，恢復了全部力量。宗師戰役就此完成。"
L["Iron-Body Ponshu told you of Fu Zan — a simple-looking staff that had been passed from wanderer to wanderer since the dawn of the monk tradition. It looked like a walking stick, but those who carried it found that no enemy could stand against them. You tracked it through remote monasteries and dangerous wilds, and when you took it up, it felt like an old friend settling into your hand."] = "鐵胴彭舒向你講述了福贊——一根外表樸實的法杖，自武僧傳統誕生之初，便在流浪者之間代代相傳。它看起來就像一根手杖，但持有它的人發現，沒有任何敵人能與之抗衡。你在偏遠的寺院與險惡的荒野間追尋它的蹤跡，當你拿起它時，它就像一位老朋友般，穩穩落入你的掌中。"
L["Ironforge / Dun Morogh / Loch Modan"] = "鐵爐堡 / 丹莫洛 / 洛克莫丹"
L["Isolating Zalamar"] = "孤立札拉瑪"
L["It Could Kill Us All"] = "它會殺了我們"
L["It Hungers for Blood"] = "嗜血的石頭"
L["It's All Fun and Games"] = "這是有趣的遊戲"
L["It's Called Borrowing"] = "借用一下"
L["It's Not a Spirit Festival Without Spirits"] = "靈魂節無酒不歡"
L["Iterating Upon Success"] = "再次成功"
L["Izzy"] = "伊茲"
L["Jace Darkweaver"] = "捷斯‧暗織者"
L["Jace Darkweaver told the story of the Aldrachi — a warrior race so fierce they defeated the demon lord Sargeras sent to enslave them. Rather than serve, they fell on their own blades. Those weapons had been lost for millennia, but Jace had found a lead. You followed it through a series of trials, establishing a connection to the blades through sheer will. The Aldrachi Warblades chose you — the first wielder since the race that forged them chose extinction over submission."] = "捷斯‧暗織者講述了奧達奇的故事——一個驍勇無比的戰士種族，曾擊敗薩格拉斯派來奴役他們的惡魔領主。他們寧死不屈，選擇倒在自己的刀刃上。這些武器已失落數千年，但捷斯找到了一條線索。你循線經歷一連串試煉，憑藉純粹的意志與刀刃建立連結。奧達奇戰刃選擇了你——自從鍛造它們的種族寧可滅絕也不願屈服以來，你是第一位持有者。"
L["Jaded Heart"] = "玉之心"
L["Jagged Shards"] = "鋸齒裂片"
L["Jailbreak"] = "越獄"
L["Jaina brought you to Kul Tiras aboard the Alliance fleet, and the moment she stepped off the ship she was surrounded by Proudmoore Guard acting on Katherine's orders. Her own mother had her arrested for treason. You were thrown in Tol Dagor prison alongside her — until Flynn Fairwind, a sailor with nothing to lose and excellent lock-picking instincts, got you both out. Cyrus Crestfall and the 7th Legion met you on the outside. The road to earning Kul Tiras back for the Alliance runs through three zones — and through a rift between mother and daughter that has been open for years."] = "珍娜搭乘聯盟艦隊帶你來到庫爾提拉斯，她一踏下船，就被奉凱瑟琳之命行事的普勞德摩爾衛隊成員團團包圍。她的親生母親以叛國罪將她逮捕。你和她一起被關進托達戈爾監獄——直到弗林‧晴風，一個無牽無掛、開鎖直覺一流的水手，把你們倆救了出去。塞勒斯‧克瑞斯福與第七軍團在外頭接應你們。要為聯盟贏回庫爾提拉斯，必須走過三個地區——還得跨越母女之間那道已存在多年的裂痕。"
L["Jaina Proudmoore"] = "珍娜‧普勞德摩爾"
L["Jaina Proudmoore brings the Alliance to Kul Tiras — and is immediately arrested by her own mother's guards the moment she sets foot on the docks. Katherine Proudmoore, Lord Admiral in her daughter's absence, has not forgiven Jaina for the death of her father Daelin. Jaina is imprisoned in Tol Dagor. You break out with the help of a disgraced sailor named Flynn Fairwind, surface in a Kul Tiras rebuilding itself from the inside out, and learn that three zones of unrest must be addressed before Kul Tiras will trust the Alliance — or her."] = "珍娜‧普勞德摩爾帶領聯盟來到庫爾提拉斯——卻在踏上碼頭的那一刻，就被自己母親的衛兵逮捕。在女兒離開期間擔任海軍上將的凱瑟琳‧普勞德摩爾，至今仍未原諒珍娜導致其父戴林之死。珍娜被囚禁在托達戈爾。你在名譽掃地的水手弗林‧晴風協助下越獄，回到一個正從內部重建的庫爾提拉斯，並得知必須先平息三個地區的動亂，庫爾提拉斯才會信任聯盟——或是信任她。"
L["Jaina Proudmoore was once Theramore's defender and the Alliance's most celebrated mage. When the Horde dropped a mana bomb on her city, she emerged from the wreckage transformed: her hair turned white, her grief hardened into fury, and old friendships began to fall away.\n\nWhen Battle for Azeroth begins, Jaina returns to Kul Tiras, the home that remembers her not as a hero, but as the daughter who let Daelin Proudmoore die. What follows is a journey through estrangement, politics, old guilt, and the question of whether a broken bond can still be mended."] = "珍娜‧普勞德摩爾曾是塞拉摩的守護者，也是聯盟最負盛名的法師。部落在她的城市投下法力炸彈後，她自廢墟中走出時已徹底改變：頭髮轉為雪白，悲痛凝結為憤怒，舊日的情誼也開始逐一離散。\n\n《決戰艾澤拉斯》揭開序幕時，珍娜回到庫爾提拉斯——這片故土記得的她不是英雄，而是那個任由戴林‧普勞德摩爾死去的女兒。接下來是一段穿越疏離、政治與舊日愧疚的旅程，也探問著一段破碎的羈絆是否還能修補。"
L["Jaina Proudmoore, now Lord Admiral, turns the Kul Tiran fleet against the Zandalari Empire. The plan: draw the Horde's forces deep into Nazmir with the Abyssal Scepter while the Alliance fleet strikes Zuldazar harbor from the south. Jaina personally freezes the harbor, and the Battle of Dazar'alor begins."] = "如今已成為海軍上將的珍娜‧普勞德摩爾，率領庫爾提拉斯艦隊對抗贊達拉帝國。計畫是：利用深淵權杖將部落的兵力引入納茲米爾深處，同時由聯盟艦隊從南方突襲祖達薩的港口。珍娜親手冰封港口，達薩亞洛之戰就此展開。"
L["Jarum Skymane"] = "賈朗‧天鬃"
L["Jeek Jeek"] = "吉克吉克"
L["Ji Firepaw"] = "紀‧火爪"
L["Ji Firepaw (Horde)"] = "紀‧火爪（部落）"
L["Join Maiev and the Wardens against old corruption and reclaim a symbol of night elf devotion."] = "與瑪翼夫及守望者並肩對抗古老的腐化，奪回一件象徵夜精靈虔誠信仰的聖物。"
L["Join the Gnomeregan Engineering and Aviation Reserve as it tests the most ambitious aircraft to leave a workshop since the Great War. Old Gnomeregan is still dangerous, and not every threat beneath the city is content to stay buried.\n\nRecruit specialists, salvage prototypes, and turn brilliant schematics into machines that actually fly, preferably with all limbs and eyebrows accounted for."] = "加入諾姆瑞根工程與航空後備隊（G.E.A.R.），測試自大戰以來駛出工坊的最具野心的飛行器。舊諾姆瑞根依然危機四伏，而城市底下的威脅，並非全都甘於長眠地底。\n\n招募專家、回收原型機，把天才的設計圖變成真正飛得起來的機器——最好還能保住所有的手腳和眉毛。"
L["Joining the Assault"] = "聯合作戰"
L["Jojo Ironbrow"] = "喬喬‧鐵頭"
L["Jorach's Calling"] = "喬拉齊的號召"
L["Jorhuttam"] = "約爾胡丹"
L["Jotunheim"] = "卓頓海姆"
L["Journey deep into the Emerald Dream to recover G'Hanir, the branch from which all world trees grew."] = "深入翡翠夢境，找回格哈尼爾——所有世界之樹萌生的源頭枝幹。"
L["Journey to Icecrown Citadel to reforge the shattered remnants of Frostmourne into twin runeblades."] = "前往冰冠城塞，將霜之哀傷的碎片重鑄為一對符文劍。"
L["Journey to Nazmir"] = "納茲米爾歷險記"
L["Journey to the ancient groves of Val'sharah to find a seed that could save the Arcan'dor."] = "前往維爾薩拉的遠古樹林，尋找一顆或許能拯救阿坎多爾的種子。"
L["Journey to the Broken Shore and the ruins of Stromgarde to claim the legendary two-handed sword once wielded by the troll-slaying king."] = "前往破碎海岸與激流堡的廢墟，奪取那位屠戮食人妖的國王曾揮舞的傳奇雙手劍。"
L["Journey to the Middle of Nowhere"] = "汪洋之行"
L["Journey to the ruins of Stromgarde to raise King Thoras Trollbane, the second Horseman, from his defiled grave."] = "前往激流堡的廢墟，將第二位騎士索拉斯‧托爾貝恩國王，從遭褻瀆的墳墓中喚起。"
L["Jubeka Shadowbreaker"] = "裘貝卡‧破影者"
L["Judgment"] = "審判"
L["Judgment Awaits"] = "審判將至"
L["Judgment Day Comes!"] = "審判日將臨!"
L["Jump-Capable"] = "躍傳功能"
L["Jungo, Herald of G'huun"] = "『古翰信使』疆苟"
L["Just for Safekeeping, Of Course"] = "只是保管而已，當然了"
L["Justicar Julia Celeste"] = "審判者茱利亞‧莎莉絲蒂"
L["Kai Wanderbrew"] = "凱‧蕩酒"
L["Kai-Lin Honeydew"] = "凱琳‧甘露"
L["Kalec's Plan"] = "卡雷克的計畫"
L["Kaltunk"] = "卡爾圖克"
L["Kanrethad Ebonlocke"] = "坎瑞薩德‧埃伯洛克"
L["Kasea Angerforge"] = "凱曦安格弗"
L["Katherine Proudmoore"] = "凱瑟琳‧普勞德摩爾"
L["Kathra'natir has possessed Meryl Felstorm. Storm the Oculus with Khadgar to save the Tirisgarde's founder and destroy the dreadlord."] = "卡斯拉納提爾附身於莫爾‧魔風。與卡德加一同突襲奧核之眼，拯救提里斯加德的創始人，並消滅那名恐懼魔王。"
L["Kayn Sunfury"] = "凱恩‧日怒"
L["Kayn Sunfury arranged the hunt for the Twinblades of the Deceiver — a pair of warglaives crackling with felfire, wielded by one of the Legion's own champions. You tracked the demon through shadowed ruins and claimed the blades in combat. They burned in your hands, eager for the blood of their former masters."] = "凱恩‧日怒安排了追獵欺詐者雙刃的行動——這對迸發魔火的戰刃，由燃燒軍團麾下的一名勇士揮舞。你穿過陰影籠罩的廢墟追蹤那名惡魔，在戰鬥中奪下了雙刃。它們在你手中燃燒，渴望著前主人的鮮血。"
L["Keep Yer Feet On The Ground"] = "腳踏實地"
L["Keep Your Friends Close"] = "常伴朋友身旁"
L["Keeper Remulos"] = "守衛者雷姆洛斯"
L["Keeper Remulos spoke of G'Hanir — the mother branch from which Nordrassil, Teldrassil, and every world tree had grown. It slumbered deep in the Emerald Dream, and the Nightmare sought to consume it. You ventured into the Dream's purest heart and returned with G'Hanir in hand, its leaves still green with the life of an entire world."] = "守衛者雷姆洛斯談起格哈尼爾——諾達希爾、泰達希爾以及每一棵世界之樹萌生的母枝。它沉睡在翡翠夢境深處，而夢魘意圖將它吞噬。你冒險進入夢境最純淨的核心，帶著格哈尼爾歸來，它的葉片依然翠綠，承載著整個世界的生命。"
L["Kel'danath's Legacy"] = "克達納茲的遺產"
L["Keritose Bloodblade"] = "凱力多斯‧血刃"
L["Keula"] = "珂烏菈"
L["Kevo ya Siti"] = "凱弗亞西帝"
L["Key members of the resistance have vanished. Search the city to find them before it's too late."] = "抵抗軍的重要成員失蹤了。在城中搜尋他們，以免為時已晚。"
L["Key members of the resistance vanished without a trace — taken in the night by Elisande's agents. You tracked them through Suramar's twisting streets, from soul cages to smuggler's routes, pulling allies from the jaws of captivity. The message was clear: the Grand Magistrix knew about the rebellion, and she was coming for them all."] = "抵抗軍的重要成員消失得無影無蹤——在夜裡被艾莉珊德的手下擄走。你在蘇拉瑪爾蜿蜒的街道上追蹤他們的下落，從靈魂囚籠到走私路線，將盟友從囚禁的魔掌中救出。訊息再清楚不過：大博學者已經知道叛亂的事，而她要將他們一網打盡。"
L["Khadgar's Discovery"] = "卡德加的發現"
L["Kibli Killohertz"] = "碁伯里‧基羅赫茲"
L["Kill Kher Shan"] = "殺死剋山"
L["Killing Two Scourge With One Skeleton"] = "一石二鳥"
L["Killohertz"] = "吉普利·基羅赫斯"
L["King of the Hill"] = "山丘之王"
L["King of the Mountain"] = "山脈之王"
L["King Varian's command sent you after the missing White Pawn: Prince Anduin Wrynn. The Skyfire found Pandaria and immediately found the Horde. Admiral Rogers turned the gunship into a weapon, Sully McLeary got you onto the ground, and Paw'don Village became the Alliance's first real foothold. Every step inland was paid for in smoke, wounded soldiers, stolen supplies, and the first glimpse of sha born from the armies' violence. By the time Ga'trul fell at Twinspire Keep, the Alliance had survived its landing - but Taylor and Anduin were still missing."] = "瓦里安國王一聲令下，派你去尋找失蹤的「白兵」：安杜因‧烏瑞恩王子。天火號找到了潘達利亞，也隨即撞上了部落。羅傑斯上將把砲艇化為武器，蘇利‧麥克利里讓你登上陸地，坡東村成為聯盟第一個真正的立足點。向內陸推進的每一步，都以硝煙、負傷的士兵與遭竊的補給為代價，你們也首度瞥見因兩軍暴力而生的煞。當加特魯在雙石要塞倒下時，聯盟已撐過了登陸——但泰勒和安杜因依然下落不明。"
L["Kira Iresoul"] = "琪拉‧怒魂"
L["Kitty?"] = "小貓咪？"
L["Knight-Captain Drosche"] = "騎士隊長德羅許"
L["Knights of the Ebon Blade"] = "黯刃騎士團"
L["Knock It Off!"] = "別打了！"
L["Knowing Our Enemy"] = "瞭解我們的敵人"
L["Knowledge is a Terrible Burden"] = "最沉重的負荷"
L["Koltira Deathweaver"] = "寇爾提拉‧亡織者"
L["Kor'kron Squad Leader"] = "柯爾克隆小隊長"
L["Kor'vas Bloodthorn"] = "珂娃絲‧血棘"
L["Kor'vas Bloodthorn calls you to the Fel Hammer on Mardum, where the Illidari prepare for war against the Legion."] = "珂娃絲‧血棘召喚你前往馬爾頓上的魔錘，伊利達瑞正在那裡準備對燃燒軍團開戰。"
L["Kor'vas Bloodthorn found you in Dalaran with an urgent message — the Illidari needed a leader. You answered the call and claimed a weapon forged from the demons' own power. On Mardum, the Fel Hammer became your stronghold — a Legion command ship turned against its former masters. With Kayn Sunfury at your side, you gazed through the Hunter's Gaze across the Broken Isles and directed the Illidari's wrath."] = "珂娃絲‧血棘帶著緊急訊息在達拉然找到你——伊利達瑞需要一位領袖。你響應了召喚，奪得一把以惡魔自身力量鍛造的武器。在馬爾頓，魔錘成了你的據點——一艘倒戈對付前主人的軍團指揮艦。在凱恩‧日怒的陪伴下，你透過獵者之眼遍覽破碎群島，指引伊利達瑞的怒火。"
L["Koukou's Rampage"] = "寇寇之怒"
L["Krag'wa the Terrible"] = "可怕的奎格瓦"
L["Kul Tiras"] = "庫爾提拉斯"
L["Kung Din"] = "鋼釘"
L["Kvaldir on Call"] = "科瓦迪爾準備就緒"
L["Lady Jaina Proudmoore"] = "珍娜‧普勞德摩爾女士"
L["Lady Jaina Proudmoore — or Lady Sylvanas Windrunner, if you ride under a darker banner — has found a door. Not a welcome one. A seam in the citadel's foundation, wide enough for a small party willing to see what they should not. Through the Forge of Souls. Through the Pit of Saron. Into the Halls of Reflection, where something waits that has been waiting a long time."] = "珍娜‧普勞德摩爾女士——若你在更黑暗的旗幟下作戰，則是希瓦娜斯‧風行者女士——找到了一道門。那並不是一扇歡迎你的門，而是城塞地基上的一道縫隙，寬度只夠讓一支願意目睹不該看見之物的小隊通過。穿過眾魂熔爐，穿過薩倫之淵，進入倒影大廳——那裡有某個東西，已經等待了很久。"
L["Lady Liadrin"] = "莉雅德倫女士"
L["Lady Liadrin and the blood elves of Silvermoon answer the call, joining the fight for their distant kin."] = "莉雅德倫女士與銀月城的血精靈響應號召，為遠方的同族加入戰鬥。"
L["Lady Lunastre"] = "路納斯特女士"
L["Lady Remor'za"] = "蕾茉薩女士"
L["Lady S'theno"] = "絲瑟諾女士"
L["Lady Sylvanas Windrunner"] = "希瓦娜斯‧風行者女士"
L["Lament of the Highborne"] = "貴族的輓歌"
L["Lashk"] = "拉斯克"
L["Lashk brought you to Torga, and what you found broke something in the air around you. The sea turtle loa — ancient beyond reckoning, the kind of creature that outlasted empires — had been slowly bled by the blood trolls for years. He was almost gone when you arrived. You fought through the blood trolls claiming his shores, sought Bwonsamdi's intercession for a dying loa, and freed the souls trapped around him. Torga died. He just did it on his own terms, with the Horde at his side. Bwonsamdi, for once, was almost respectful. Lashk said nothing. Some losses don't require words."] = "拉斯克帶你來到托加身邊，而你所見的景象，讓周遭的空氣彷彿都碎裂了。這位海龜洛阿古老得難以估量，是那種比帝國活得更久的生物——多年來一直被血食人妖慢慢放血。你抵達時，他已奄奄一息。你殺穿占據他海岸的血食人妖，為這位垂死的洛阿請求伯昂撒姆第出面調停，並解放了困在他周圍的靈魂。托加死了。只是他以自己的方式離去，身旁有部落相伴。伯昂撒姆第難得幾乎表現出了敬意。拉斯克一語不發。有些失去，無需言語。"
L["Last Piece of the Puzzle"] = "最終線索"
L["Lay of the Land"] = "情勢"
L["Lea Stonepaw told of the Claws of Ursoc — weapons that carried the strength of the bear god who had given his life defending Azeroth. You entered the nightmare-touched dens where the Claws had been hidden and fought through the corruption to reclaim them. The weight of Ursoc's sacrifice settled into your hands along with the weapons — a guardian's burden, willingly carried."] = "莉雅‧石爪講述了烏索克之爪——承載著熊神之力的武器，而這位熊神曾為守護艾澤拉斯獻出生命。你進入沾染夢魘的巢穴，那裡藏著烏索克之爪，你殺穿腐化，將它們奪回。烏索克犧牲的重量隨著武器一同落入你的手中——那是守護者的重擔，你心甘情願地扛起。"
L["Lead a covert strike beneath Icecrown Citadel, closer to Frostmourne than any living hand has come."] = "率領一場秘密突襲，潛入冰冠城塞底下，比任何活人都更接近霜之哀傷。"
L["Lead G.E.A.R. through a high-tech campaign against old enemies and reclaim gnomish pride."] = "率領G.E.A.R.展開一場高科技戰役對抗宿敵，重振地精的榮耀。"
L["Lead the allied armies through the streets of Suramar in a desperate push toward the Nighthold."] = "率領盟軍穿越蘇拉瑪爾的街道，孤注一擲地向暗夜堡推進。"
L["Lead the Ebon Blade to the Broken Shore, tame a frost wyrm, and claim the Vilebrood Vanquisher as your mount."] = "率領黯刃騎士團前往破碎海岸，馴服一頭冰霜巨龍，並將邪裔征服者收為坐騎。"
L["Lead the Illidari to the Broken Shore. Defend the Fel Hammer, recruit Lady S'theno, and earn the Slayer's Felbroken Shrieker."] = "率領伊利達瑞前往破碎海岸。保衛魔錘、招募絲瑟諾女士，並贏得殺戮者的魔破尖嘯者。"
L["Lead the united Conclave to Niskara, rescue captured allies, and earn the title of High Priest."] = "率領團結一心的議會前往尼斯卡拉，營救被俘的盟友，並贏得大主教的頭銜。"
