L["Liadrin's Command"] = "莉雅德倫的命令"
L["Lieutenant Sanders"] = "桑德斯中尉"
L["Life Held Hostage"] = "命繫人質"
L["Light Within the Darkness"] = "黑暗中的一絲微光"
L["Light's Wrath"] = "聖光之怒"
L["Lighting Up the Sky"] = "劃亮天空"
L["Lilian Voss"] = "莉莉安‧佛斯"
L["Lilian Voss was raised by the Scarlet Crusade to hate the undead, and then she died, rose, and became one. Trained from childhood to purify the Forsaken, she wakes in Deathknell as the very thing her father taught her to burn.\n\nFollow her from the cellars of the Crusade through Scholomance and the politics of Lordaeron, where vengeance, identity, and belonging keep asking for different answers."] = "莉莉安‧佛斯由血色十字軍撫養長大，被教導要憎恨不死族；後來她死去、復活，自己也成了不死族。她從小受訓去淨化被遺忘者，卻在喪鐘鎮甦醒，成為父親教她要燒死的那種存在。\n\n跟隨她從十字軍的地窖走過通靈學院，再踏入羅德隆的權謀政治——在那裡，復仇、身分認同與歸屬感總是要求著不同的答案。"
L["Lilian's hunt for dark knowledge leads her into the cursed academy of Scholomance. Within its halls she confronts Darkmaster Gandling — but the darkness she wields threatens to consume her entirely. She must destroy the forbidden tomes and end the suffering, or become the very evil she hunts."] = "莉莉安對黑暗知識的追尋，將她帶進了受詛咒的通靈學院。她在學院的大廳中與黑暗院長加丁正面對決——然而她所操控的黑暗，也威脅著要將她徹底吞噬。她必須摧毀禁忌典籍、終結苦難，否則就會淪為她所獵殺的邪惡本身。"
L["Lilian's pursuit of power led her into Scholomance, the cursed academy of necromancy. Through a talking skull she guided you to destroy the Four Tomes of forbidden knowledge and end the suffering within those walls. But when she faced Darkmaster Gandling, the darkness she wielded nearly consumed her. She survived — but the line between hunter and monster grew thinner."] = "莉莉安對力量的追求，將她帶進通靈學院這座受詛咒的死靈法術學院。她透過一顆會說話的頭骨，指引你摧毀四本禁忌知識典籍，終結那些高牆內的苦難。但當她面對黑暗院長加丁時，她所操控的黑暗幾乎將她吞噬。她活了下來——但獵人與怪物之間的界線變得更加模糊。"
L["Lin Applebloom"] = "林‧蘋卉"
L["Lin Tenderpaw"] = "林‧嫩爪"
L["Lina Whitepaw"] = "琳娜‧白爪"
L["Lingering Scars"] = "揮之不去的傷疤"
L["Lion's Heritage"] = "雄獅的傳承"
L["Little Lu"] = "小小盧"
L["Little One Lost"] = "迷路的小孩"
L["Livin' on the Ledge"] = "在岩臺生存"
L["Lo Wanderbrew"] = "小樓‧蕩酒"
L["Loa-Free Diet"] = "別吃那個羅亞"
L["Lockdown"] = "封城"
L["Logistical Matters"] = "後勤工作"
L["Looking for Lukou"] = "尋找盧考"
L["Looking for Something Specific"] = "找個特定的東西"
L["Loot and Plunder!"] = "戰利品和贓物！"
L["Lor'themar Theron"] = "洛索瑪‧塞隆"
L["Loramus, Is That You?"] = "洛拉姆斯，是你嗎？"
L["Lord Chamberlain"] = "宮務大臣"
L["Lord Chamberlain escorts you toward Castle Nathria. Sire Denathrius receives your plea with perfect elegance — and asks you to help restore order first."] = "宮務大臣護送你前往納撒亞城。戴納瑟斯王以無懈可擊的優雅姿態接受你的請求——並要你先協助恢復秩序。"
L["Lord Grayson Shadowbreaker"] = "格雷森·沙東布瑞克公爵"
L["Lord Jorach Ravenholdt"] = "喬拉齊‧拉文霍德領主"
L["Lord Maxwell Tyrosus"] = "麥斯威爾‧泰羅索斯領主"
L["Lord Maxwell Tyrosus calls paladins from every order to the Sanctum of Light beneath Light's Hope Chapel."] = "麥斯威爾‧泰羅索斯領主召集各騎士團的聖騎士，前往聖光之願禮拜堂底下的聖光會堂。"
L["Lord Maxwell Tyrosus issued an urgent summons — the Silver Hand was reforming, and Light's Hope Chapel would be its heart. You descended into the Sanctum of Light, hidden beneath the chapel for centuries, where paladins of every faith gathered. Tyrosus named you champion, and you claimed a weapon of legend. Lady Liadrin pledged the Blood Knights' strength, and the Silver Hand rode again."] = "麥斯威爾‧泰羅索斯領主發出緊急召喚——白銀之手正在重組，而聖光之願禮拜堂將成為它的核心。你深入隱藏在禮拜堂下方數百年的聖光會堂，各種信仰的聖騎士都聚集於此。泰羅索斯封你為勇士，你也奪得了一把傳說武器。莉雅德倫女士承諾貢獻血騎士的力量，白銀之手再度踏上征途。"
L["Lord Maxwell Tyrosus pointed you toward Truthguard — a shield forged by the titans themselves, imbued with the power to protect the righteous and shatter the deceitful. You traveled to the Shrine of the Truthguard and faced the shield's ancient tests. Truthguard weighed nothing in the hands of the pure — and everything in the hands of the unworthy. It chose you."] = "麥斯威爾‧泰羅索斯領主為你指引了真理守護——一面由泰坦親手鍛造的盾牌，蘊含守護正義之士、粉碎欺詐之徒的力量。你前往真理守護聖壇，接受這面盾牌的古老試煉。在純潔者手中，真理守護輕若無物；在不配者手中，它卻重逾千鈞。它選擇了你。"
L["Lord Maxwell Tyrosus spoke the name that every paladin knew — the Ashbringer. The blade that had burned with holy fire in Alexandros Mograine's hands, that had been corrupted and redeemed, that had shattered the Scourge at Light's Hope Chapel. You sought guidance and followed the weapon's trail to its resting place. When you drew the Ashbringer, holy fire erupted along its edge, and the weight of every paladin who had carried it settled onto your shoulders."] = "麥斯威爾‧泰羅索斯領主說出了每位聖騎士都知道的名字——灰燼使者。這把劍曾在亞歷山卓斯‧莫格萊尼手中燃起神聖之火，曾遭腐化又重獲救贖，也曾在聖光之願禮拜堂粉碎天譴軍。你尋求指引，循著這把武器的足跡找到它的安息之地。當你拔出灰燼使者時，聖火沿著劍刃迸發，每一位曾持有它的聖騎士所背負的重量，都落在了你的肩上。"
L["Lord Thorval"] = "索瓦爾領主"
L["Lord Waycrest has vanished and a curse grips the village of Fallhaven. Lucille Waycrest enlists your help to hunt the witches responsible."] = "威奎斯特領主失蹤了，落港村也籠罩在詛咒之中。露西爾‧威奎斯特請求你協助，追獵那些罪魁禍首的女巫。"
L["Lordaeron"] = "羅德隆"
L["Lordaeron has been reclaimed, the penance accepted. But for those who once swore loyalty to the Banshee Queen, a message finds its way back through the dark — one last task, carried by a familiar messenger."] = "羅德隆已被奪回，贖罪也已獲接納。然而對那些曾向女妖之王宣誓效忠的人而言，一則訊息穿越黑暗傳了回來——最後一項任務，由一位熟悉的信使帶來。"
L["Lordaeron is in Forsaken hands again, but old enemies still haunt the forests beyond its walls. The Scarlet Crusade clings to its strongholds, Gilneas has not forgotten, and a former queen's absence leaves difficult questions behind.\n\nLilian Voss has a mission in Silverpine, and she needs someone who knows what it means to be Forsaken: to stand at a graveside, remember, and choose again what the second life is for."] = "羅德隆再度回到被遺忘者手中，但宿敵仍在城牆外的森林中陰魂不散。血色十字軍死守著據點，吉爾尼斯從未忘記過往，而一位前女王的缺席，留下了許多難解的問題。\n\n莉莉安‧佛斯在銀松森林有一項任務，她需要一個明白身為被遺忘者意義的人：站在墓旁，回憶過往，再一次選擇第二次生命的意義。"
L["Lorewalker Cho"] = "博學行者阿洲"
L["Lorewalker Cho did not answer Nazgrim's campaign with orders. He answered with tea, old stones, and the patient insistence that Pandaria had a story before the Horde arrived. You walked a mile in another person's shoes, listened to the forest's dead, peered into the past, and traced the branches of Cho's own family. The lesson was not gentle, but it was necessary: this land remembers what people bring into it. Then the river swallowed you, the hozen found you, and Chief Kah Kah's orders dragged the lesson back into the campaign. You left Cho with more questions than victories, which was probably the point."] = "面對納茲格寧姆的戰役，博學行者阿洲的回應不是命令，而是茶、古老的石碑，以及耐心而堅定的主張：早在部落到來之前，潘達利亞就已經有自己的故事。你設身處地走了一段別人的路，聆聽森林亡者的聲音，窺探過去，並追溯阿洲自己的家族脈絡。這堂課並不溫和，卻是必要的：這片土地會記住人們帶進來的一切。接著河水吞沒了你，猢猻發現了你，卡卡酋長的命令又把這堂課拉回了戰役之中。你離開阿洲時，帶走的問題比勝利還多——而這或許正是重點所在。"
L["Lorewalker Cho's Lesson"] = "博學行者阿洲的教誨"
L["Lorewalker Stonestep"] = "博學行者石步"
L["Lost in Darkness"] = "迷失在黑暗之中"
L["Lost in the Desiccation"] = "迷失於乾枯之地"
L["Lost My Spark"] = "失去火花"
L["Lost Shipment"] = "遺失的「貨物」"
L["Lothraxion"] = "洛斯拉賽恩"
L["Love's Labor"] = "愛情奴隸"
L["Lucille realized that scattered witch hunting would never be enough. A slight detour through the mountains — past yetis and salvaged supplies — led to the ruins of Gol Var, where ancient bones whispered of the Order of Embers. Centuries ago, the Order had been Drustvar's shield against the Drust and their dark magic. Lucille read the histories carved in stone and rune-etched bone, and made her decision: the Order of Embers would rise again. She would lead it, and you would be her blade."] = "露西爾意識到，零星的獵巫行動永遠不夠。你們稍微繞個路穿越山區——途經雪怪與搜刮來的補給——來到戈爾瓦厄遺跡，那裡的遠古骸骨低語著燼火會的往事。數百年前，燼火會曾是佐司瓦抵禦德魯斯及其黑暗魔法的盾牌。露西爾讀完刻在石頭與符文骨頭上的歷史，做出了決定：燼火會將再度崛起。她會領導它，而你將是她的利刃。"
L["Lucille stands accused of witchcraft herself. Marshal Reade demands proof of her innocence through superstitious trials."] = "露西爾自己也被控施行巫術。瑞德元帥要求透過迷信的試煉證明她的清白。"
L["Lucille Waycrest"] = "露西爾‧威奎斯特"
L["Lukou"] = "盧考"
