L["Make contact with nightfallen refugees hiding in the slums of Suramar City, right under Elisande's nose."] = "與躲藏在蘇拉瑪爾城貧民窟中的夜落精靈難民取得聯繫——就在艾莉珊德的眼皮底下。"
L["Make Our Case"] = "我方的證據"
L["Make Them Pay!"] = "叫他們付出代價!"
