L["March on Corlain, the seat of House Waycrest. Forge an arsenal of witchrending weapons and break through the coven's magical barrier."] = "進軍威奎斯特家族的根據地寇連恩。打造一批破巫武器，並突破女巫集會的魔法屏障。"
