L["Master Windstrong"] = "風強大師"
L["Matchmaker"] = "速配達人"
L["Mathias Shaw laid out the strategy in Proudmoore Keep: use the Abyssal Scepter to create a false assault on Nazmir and lure the Horde fleet away from Zuldazar. While Zandalari forces rushed south to repel the distraction, the Alliance fleet would hit the harbor directly. You spent two weeks fighting through Nazmir swamps, disabling Zandalari machinery, and holding the line at the Blood Gate — long enough for the fleet to round the coast.\n\nThen Jaina froze the harbor. The water turned to ice beneath Zandalari hulls. The Alliance sailed straight through. The Battle of Dazar'alor — the most audacious naval assault in a generation — had begun. Lord Admiral Jaina Proudmoore, fighting in her own waters, had brought the war home."] = "麥迪亞斯‧蕭在普勞德摩爾城堡擬定了戰略：利用深淵權杖對納茲米爾發動佯攻，將部落艦隊引離祖達薩。當贊達拉的部隊急忙南下擊退這場佯攻時，聯盟艦隊將直接攻擊港口。你花了兩週時間在納茲米爾的沼澤中奮戰，破壞贊達拉的機械，並在血門堅守防線——一直撐到艦隊繞過海岸。\n\n接著，珍娜冰封了港口。贊達拉船艦底下的海水化為寒冰，聯盟艦隊則長驅直入。達薩亞洛之戰——一個世代以來最大膽的海上突擊——就此展開。海軍上將珍娜‧普勞德摩爾在自己的海域上作戰，把戰火直接燒到了敵人的家門口。"
L["Mathias Shaw, spymaster of SI:7, had been captured and replaced by a dreadlord impostor. You infiltrated the enemy stronghold alongside Taoshi, cutting through guards and wards to reach Shaw's cell. The rescue was harrowing — but when the real Shaw stood free and the impostor was exposed, the conspiracy's days were numbered."] = "SI:7的情報頭子麥迪亞斯‧蕭遭到俘虜，並被一名恐懼魔王冒名頂替。你與陶氏一同潛入敵人的要塞，突破守衛與結界，抵達蕭的牢房。這場救援驚險萬分——但當真正的蕭重獲自由、冒牌貨的真面目被揭穿時，這場陰謀已時日無多。"
L["Mathias Shaw, spymaster of SI:7, has gone missing. A daring rescue mission takes you deep behind enemy lines."] = "SI:7的情報頭子麥迪亞斯‧蕭失蹤了。一場大膽的救援任務，將帶你深入敵後。"
L["Matron Mother Malevolence"] = "懷惡族母"
