L["Maul Gormal"] = "突擊戈爾莫營地"
L["Maw of Souls: Ancient Vrykul Legends"] = "靈魂之喉：古老的維酷傳說"
L["Maw of Souls: Maul of the Dead"] = "靈魂之喉：亡者之槌"
L["Maw of Souls: Message to Helya"] = "靈魂之喉：給黑爾雅的訊息"
