L["Maw of the Damned"] = "遭譴者之顎"
L["Meeting in Moonclaw Vale"] = "在月爪谷會面"
L["Meld Into the Shadows"] = "融入暗影"
L["Merchant Zin"] = "商人辛"
L["Mercy or Misery"] = "慈悲或慘劇"
L["Meryl Felstorm"] = "莫爾‧魔風"
L["Meryl Felstorm appeared with an urgent plea — Kathra'natir, a cunning dreadlord, had broken free of his prison and threatened all of Dalaran. You fought the demon back and descended into the Hall of the Guardian, an ancient sanctum beneath the city. There, Meryl revealed the Tirisgarde — an ancient order of mages sworn to defend Azeroth against the Burning Legion. With a weapon of legend in hand and The Great Akazamzarak's theatrical assistance, you reforged the order and took your place as its champion."] = "莫爾‧魔風帶著緊急的請求現身——狡詐的恐懼魔王卡斯拉納提爾掙脫了囚禁，威脅著整個達拉然。你擊退了這名惡魔，深入城市底下的古老聖所守護者殿堂。在那裡，莫爾揭露了提里斯加德的存在——一個誓言守護艾澤拉斯、對抗燃燒軍團的古老法師修會。手握傳說武器，再加上魔術大師阿卡贊札拉克浮誇的協助，你重建了這個修會，成為它的勇士。"
L["Meryl Felstorm pointed you toward Aluneth — the Greatstaff of the Magna, once wielded by Aegwynn, Guardian of Tirisfal. The staff had been sealed away for good reason: it was sentient, willful, and dangerously powerful. You found it in an arcane vault crackling with unbound energy, and when you grasped it, Aluneth's voice echoed in your mind — condescending, impatient, and undeniably brilliant. You had a weapon. It had opinions."] = "莫爾‧魔風為你指引了艾露奈斯——瑪格納巨杖，曾由提瑞斯法守護者艾格文所持有。這根法杖被封印起來是有原因的：它擁有意識、意志強烈，而且力量強大得危險。你在一座迸發著失控能量的秘法寶庫中找到它，當你握住它時，艾露奈斯的聲音在你腦海中迴盪——高傲、不耐煩，卻又無可否認地才華洋溢。你得到了一件武器。而它有自己的意見。"
L["Meryl Felstorm, an ancient mage, pleads for help against a dreadlord. Together you reforge the Tirisgarde in the Hall of the Guardian."] = "遠古法師莫爾‧魔風請求協助對抗一名恐懼魔王。你們一同在守護者殿堂重建提里斯加德。"
L["Meryl spoke of Ebonchill — the staff of Alodi, the very first Guardian of Tirisfal, sealed within a pocket dimension of frozen time. You breached the dimensional barrier and entered a world where time stood still, ice crystals hanging motionless in the air. At its heart, Ebonchill waited — cold, patient, and ancient beyond measure. When you took it, the pocket dimension shattered, and the staff's frost spread through your veins like a promise."] = "莫爾談到了黯寒——第一位提瑞斯法守護者艾洛迪的法杖，被封印在一個時間凍結的口袋次元中。你突破次元屏障，進入一個時間靜止的世界，冰晶一動也不動地懸浮在空中。在這世界的核心，黯寒靜靜等待——冰冷、耐心，且古老得難以估量。當你取下它時，口袋次元隨之粉碎，法杖的寒霜如同一道承諾般流遍你的血管。"
L["Mia Greymane"] = "米雅‧葛雷邁恩"
