L["Mogu raiders, exhausted farmers, trapped miners, and a starving jade project show what the forest needs before Yu'lon can return."] = "魔古族襲擊者、疲憊不堪的農夫、受困的礦工，以及一座缺乏玉石的雕像工程，揭示了在玉瓏歸來之前，這片森林需要什麼。"
