L["Nadjia the Mistblade"] = "『霧刃』娜迪亞"
L["Naralex"] = "納拉雷克斯"
L["Naralex revealed the location of the Scythe of Elune — an artifact of immense power forged from Elune's staff and the Fang of Goldrinn. You journeyed through cursed lands to claim it, feeling the pull of both the moon's light and the beast within. The Scythe chose you, and with it came the weight of every druid who had wielded it before."] = "納拉雷克斯揭露了伊露恩之鐮的下落——一件以伊露恩的法杖與戈德林之牙鍛造而成、蘊含無窮力量的神器。你穿越受詛咒的土地前去取得它，同時感受到月光與內在野獸的雙重牽引。伊露恩之鐮選擇了你，隨之而來的，是每一位曾揮舞它的德魯伊所背負的重量。"
L["Naralex, the druid who once fell to the Nightmare in the Wailing Caverns, sensed dire growth spreading through the Dream. Together you ventured into nightmare-twisted lands, sampling the corruption to understand its nature. In Malorne's Refuge you found the great stag's sanctuary under siege. You tracked the source of the corruption to its heart and recovered the Idol of the Wilds — an ancient artifact that could turn the tide against the Nightmare."] = "納拉雷克斯——曾在哀嚎洞穴墮入夢魘的德魯伊——察覺到一股可怕的增生正在夢境中蔓延。你們一同深入遭夢魘扭曲的土地，採集腐化樣本以了解其本質。在瑪洛尼避難所，你發現這頭偉大雄鹿的聖所正遭到圍攻。你追蹤腐化的源頭直搗核心，找回了荒野塑像——一件足以扭轉對抗夢魘局勢的遠古神器。"
L["Natalie Seline"] = "娜塔莉‧瑟琳"
L["Nathanos Blightcaller"] = "納薩諾斯‧凋零者"
L["Nathanos Blightcaller and Lilian Voss lead a covert strike into the heart of Tiragarde Sound. While Nathanos secures the mountain outpost, Lilian takes command of the Bridgeport operation — sabotaging Ashvane foundries, planting explosives, and riding through the chaos she created."] = "納薩諾斯‧凋零者與莉莉安‧佛斯率領一場秘密突襲，直搗提拉加德海灣的心臟地帶。納薩諾斯負責拿下山中的前哨，莉莉安則指揮橋梁港的行動——破壞艾胥凡的鑄造廠、安置炸藥，並在自己製造的混亂中策馬穿行。"
L["Nathanos led an expedition to dig up a fallen Kul Tiran war hero for resurrection. As you searched the graveyards of Drustvar, Lilian grew quiet. Unearthing the dead, raising them against their will — it was exactly what had been done to her. She carried out her orders, but the questions in her eyes said everything her lips would not."] = "納薩諾斯率領一支遠征隊，去挖出一位殞落的庫爾提拉斯戰爭英雄，準備讓他復活。當你在佐司瓦的墓地搜尋時，莉莉安變得沉默。挖出死者、違背其意願讓他們復活——這正是她自己曾經的遭遇。她執行了命令，但她眼中的疑問，說盡了她嘴上不願說的一切。"
L["Navigate the treacherous politics of Suramar's noble houses alongside the cunning Ly'leth Lunastre."] = "與狡黠的黎利斯‧路納斯特一同周旋於蘇拉瑪爾貴族世家之間的險惡政治。"
L["Nazgrim"] = "納茲格寧姆"
L["Nazgrim rescues Zin'jun, breaks the Alliance airstrip, and follows the trail to the edge of Cho's lesson."] = "納茲格寧姆救出金浚，摧毀聯盟的飛機跑道，並循線來到阿洲那堂課的門前。"
L["Nazgrim's Command"] = "指揮官納茲格寧姆"
L["Nazmir"] = "納茲米爾"
L["Nazmir is a dying land: ancient, cursed, and crawling with blood trolls whose rituals stain the swamp red. Stranded among loa whose temples have fallen and whose followers have turned to darker powers, you will need help from gods who rarely give anything freely.\n\nForge uneasy bargains, follow the trail through fetid ruins and broken pacts, and learn why the oldest powers in Zandalar still fear what waits beneath the mud."] = "納茲米爾是一片垂死之地：古老、受詛咒，四處爬滿血食人妖，他們的儀式將沼澤染成血紅。你受困於這些神殿傾頹、信徒轉投黑暗力量的洛阿之間，必須向鮮少無償施予的神祇尋求幫助。\n\n締結令人不安的交易，循著惡臭的廢墟與破碎的契約追查線索，並了解為何贊達拉最古老的力量，至今仍畏懼著泥沼底下等待的東西。"
L["Nazmir is swallowed by blood and shadow. Princess Talanji leads the Horde into the swamp to find the loa and stop the blood troll advance."] = "納茲米爾被鮮血與暗影吞噬。塔蘭姬公主率領部落進入沼澤，尋找洛阿並阻止血食人妖的進逼。"
L["Nazmir, the Forbidden Swamp"] = "被遺忘的沼澤，納茲米爾"
L["Nectarbreeze Orchard was not a battlefield until the mogu made it one. Shao the Defiant and Gentle Mother Hanae needed survivors rallied, hardware recovered, and slavers driven off before the orchard became another wound. From there the road bent toward Emperor's Omen and Greenstone Quarry, where the Serpent's Heart had stalled. Foreman Mann had no jade, Hao Mann was trapped, and the miners were running on fear. By freeing farmers, saving workers, and bringing jade back to the statue, you helped the forest rebuild something sacred while the armies outside kept finding reasons to break things."] = "在魔古族把蜜風果園變成戰場之前，那裡從來不是戰場。『目中無人』的邵與溫柔的漢妮媽媽需要你集結倖存者、找回器具、趕走奴隸販子，以免果園成為另一道傷口。道路從那裡轉向帝王之兆與綠石採石場，蟠龍之心的工程在那裡停擺了。工頭蔓恩沒有玉石，郝‧蔓恩受困，礦工們全憑恐懼撐著。藉由解救農夫、拯救工人，並將玉石送回雕像，你幫助這片森林重建了某種神聖之物——而外頭的軍隊，仍不斷找理由破壞一切。"
L["Need More Info"] = "需要更多資訊"
