L["Nimi Brightcastle"] = "妮蜜‧煥堡"
L["No Escape"] = "無路可逃"
L["No Goblin Left Behind"] = "一個哥布林也不能少"
L["No Mercy!"] = "絕不留情!"
L["No Monk Left Behind"] = "一個武僧也不能少"
L["No Plan Survives Contact with the Enemy"] = "攻擊是最好的計畫"
