L["No Sanctuary"] = "無處可逃"
L["Nobundo spoke of Ra-den, the titan keeper who had shaped Azeroth's storms. His weapon — the Fist of Ra-den — lay hidden in a vault sealed since the ordering of the world. You braved the coming storm to claim it, and when lightning struck the weapon in your hands, the power of a titan keeper surged through you."] = "努波頓談起拉登——塑造艾澤拉斯風暴的泰坦守衛者。他的武器拉登之拳，被藏在一座自世界秩序建立以來便封印至今的寶庫中。你冒著即將來臨的風暴前去取得它，當閃電擊中你手中的武器時，泰坦守衛者的力量湧遍你的全身。"
L["Nodd Codejack"] = "諾德‧代碼傑克"
L["Noggenfogger's Reasonable Request"] = "諾格弗格的合理要求"
L["Noressa"] = "諾瑞莎"
L["Not a Bug"] = "不只是蟲子"
L["Not A Toothless Dragon"] = "龍可不好惹"
L["Not everyone who followed the Banshee Queen has made peace with what came after. A message finds its way to the ruins of Lordaeron for those who haven't."] = "並非每個追隨女妖之王的人，都已坦然接受之後發生的一切。一則訊息傳到了羅德隆的廢墟，送給那些仍無法釋懷的人。"
L["Not Fit for This Plane"] = "不該出現在此界域"
L["Not-So-Honorable Combat"] = "不名譽戰鬥"
L["Nothing Like the Classic"] = "經典不敗"
L["Novice Elreth"] = "學徒艾蕾絲"
