L["Nullified"] = "淨化"
L["Oath Breaker"] = "誓約破壞者"
L["Oath of Service"] = "宣誓效忠"
L["Oath of the Windlord"] = "馭風者的誓約"
L["Oculeth Ex Machina"] = "救星歐庫雷斯"
L["Oculeth's Workshop"] = "歐庫雷斯的工坊"
L["Odds and Ends"] = "各種東西"
L["Odyn"] = "歐丁"
L["Odyn and the Valarjar"] = "歐丁與華爾拉亞"
L["Odyn called you to battle, but the Gjallarhorn — the sacred horn that summons the Valarjar to war — had been stolen. Hymdall sent you into Stormheim where you found Svergan Stormcloak, a vrykul king whose honor had been stripped by the thieves. Together you broke his chains, recovered the horn, and tracked a massive worm to the summit of Highmountain. With Svergan's oath sworn and the beast Jorhuttam slain, the Valarjar stood ready for war once more."] = "歐丁召喚你出征，但加拉爾號角——召集華爾拉亞投入戰爭的神聖號角——遭竊了。海姆達爾派你前往斯鐸海姆，你在那裡找到了斯維根‧嘯氅，一位被盜賊剝奪了榮譽的維酷人國王。你們一同打斷他的枷鎖，奪回號角，並追蹤一隻巨大的蠕蟲直到高嶺之巔。斯維根立下誓言、巨獸約爾胡丹遭到斬殺之後，華爾拉亞再次做好了戰爭的準備。"
L["Odyn reaches out to old allies in Ulduar and sends you to deliver a message to Helya in the Maw of Souls. Titan keepers join the fight."] = "歐丁向奧杜亞的老盟友求援，並派你前往靈魂之喉，將訊息帶給海爾亞。泰坦守衛者加入了戰鬥。"
L["Odyn sent you into the Maw of Souls with a defiant message for Helya — the Valarjar would not be broken. In the ancient halls of Ulduar, you rallied the titan keepers to the cause. Dvalen Ironrune, steadfast guardian of the forge, and Thorim, Odyn's own son, pledged themselves to the Valarjar. You retrieved Ymiron's broken blade from the Maw as proof that even the mightiest of Helya's champions could fall."] = "歐丁派你進入靈魂之喉，向海爾亞傳達一則挑釁的訊息——華爾拉亞絕不會屈服。在奧杜亞的古老殿堂中，你號召泰坦守衛者共襄盛舉。熔爐的忠實守護者德瓦倫‧鐵符文，以及歐丁的親生兒子索林姆，都宣誓效忠華爾拉亞。你從靈魂之喉取回依米倫的斷劍，證明即使是海爾亞麾下最強大的勇士也會倒下。"
L["Odyn spoke of Strom'kar, the Warbreaker — a blade forged in the ancient empire of Arathor and wielded by King Thoradin against the Amani trolls. You traveled to the ruins of Stromgarde and fought through the shadows to reclaim the sword from its cursed resting place. The blade hummed with ancient power as you raised it — a weapon worthy of the Battlelord."] = "歐丁談到了「戰爭破壞者」斯壯卡——一把在遠古阿拉索帝國鍛造、由索拉丁國王用來對抗阿曼尼食人妖的利劍。你前往激流堡的廢墟，殺穿重重暗影，從那受詛咒的安息之地奪回了這把劍。當你舉起它時，劍刃因古老的力量而嗡嗡作響——這是一把配得上戰鬥領主的武器。"
L["Odyn summons the greatest warriors to serve under your command. Build your forces and prepare Skyhold for war against the Legion."] = "歐丁召集最偉大的戰士聽你號令。壯大你的部隊，讓擎天堡做好對抗燃燒軍團的準備。"
L["Odyn's Summons"] = "歐丁的召喚"
