L["On Ruby Wings"] = "乘著晶紅之翼"
L["On the Broken Shore, brew a cure for a fallen brewmaster, then follow the trail of Ban-Lu — a legendary celestial tiger."] = "在破碎海岸為一位倒下的釀酒大師釀製解藥，然後追尋班盧的蹤跡——一頭傳說中的天界猛虎。"
L["On the Broken Shore, Lady Liadrin led the Silver Hand's assault. Delas Moonfang's past caught up with her — an ancestor's curse threatened her family. You broke the curse, freed Nerus Moonfang from his torment, and earned another champion for the order. When the Shore was secured, Lord Grayson Shadowbreaker sent you to the Hammer of Dalaran — the legendary forge — where Alard Schmied crafted armor worthy of a Highlord. In the shadows beneath the city, a golden charger waited, and it carried you into the light."] = "在破碎海岸，莉雅德倫女士率領白銀之手發動攻勢。德菈絲‧月牙的過去找上了她——一則祖先的詛咒威脅著她的家族。你破除了詛咒，將奈洛斯‧月牙從折磨中解放，為騎士團再添一位勇士。破碎海岸安定之後，格雷森·沙東布瑞克公爵派你前往傳奇熔爐「達拉然之錘」，艾拉得‧席彌德在那裡打造出配得上大領主的鎧甲。在城市底下的陰影中，一匹金色戰馬靜候著你，載著你邁向光明。"
L["On the Broken Shore, rescue Kanrethad Ebonlocke from imprisonment and earn the Netherlord's Chaotic Wrathsteed."] = "在破碎海岸將坎瑞薩德‧埃伯洛克從囚禁中救出，並贏得虛空領主的混沌怒馬。"
L["On the Broken Shore, the Legion had corrupted wild beasts into felbound monstrosities. Shandris Feathermoon coordinated the assault while Nighthuntress Syrenne led you deep into enemy territory to soothe the wounded creatures and strike at the source of the corruption. When the Broken Shore was secured, you answered a final call — the Night of the Wilds, where a wolfhawk tested your worth as a hunter. It found you worthy, and pledged its loyalty to the Huntmaster."] = "在破碎海岸，燃燒軍團把野獸腐化成受魔能束縛的怪物。珊蒂斯‧羽月統籌攻勢，暗夜女獵手希蕊妮則帶你深入敵境，安撫受傷的生物，並直搗腐化的源頭。破碎海岸安定之後，你回應了最後一道召喚——荒野之夜，一頭狼鷹在那裡考驗你身為獵人的價值。牠認可了你，並宣誓效忠狩獵大師。"
L["On The Road Again"] = "再次上路"
