L["Orgrim's Hammer"] = "奧格林之錘"
L["Orgrim's Hammer is Warchief Garrosh's answer to the Skybreaker — a Horde gunship with a bone to pick. Sky-Reaver Korm Blackscar runs the deck. Sky-Commander Ichman flies the line. Brother Keltan blesses the cannons. The first sortie drops into Ymirheim, where the Scourge mines its saronite. The second swings west to the Broken Front, where a Horde column was hit broadside and left scattered. After that comes the grind: Poke and Prod, Against the Giants, Coprous the Defiled, the goblin Nargle Lashcord and his Fringe Engineer Tezzla. Farther west, past the Valley of Lost Hope, Koltira Deathweaver pries the Desolation Gate open with bent Scourge gear and colder patience. By the time Orgrim's Hammer swings east, the Guardians of Corp'rethar are already bleeding."] = "奧格林之錘是大酋長卡爾洛斯對破天者號的回應——一艘跟敵人有筆帳要算的部落砲艇。空奪者寇姆‧黑疤掌管甲板。天空指揮官伊奇曼負責巡航戰線。凱爾坦修士為大砲祈福。第一次出擊降落在依米海姆，天譴軍在那裡開採薩鋼。第二次轉向西方的破碎前線，一支部落縱隊在那裡遭到側面痛擊，四散潰逃。接下來是一場場苦戰：刺探、抵抗巨人族、污敗的寇普羅斯，還有哥布林納格‧鞭索與他的偏激工程師泰茲菈。再往西越過失落希望谷，寇爾提拉‧亡織者用彎折的天譴軍器械和更冷冽的耐心，撬開了荒寂之門。等到奧格林之錘轉向東方時，寇普雷薩守衛者早已血流不止。"
L["Orgrimmar / Durotar"] = "奧格瑪 / 杜洛塔"
L["Orgrimmar Embassy"] = "駐奧格瑪大使館"
L["Oribos"] = "奧睿博司"
