L["Pandaren heritage lives in stories carried by many voices. Through festival rites, old memories, and shared traditions, you helped weave those voices into a new legacy."] = "熊貓人的傳承存在於眾多聲音傳述的故事中。透過節慶儀式、古老記憶與共同的傳統，你幫助這些聲音交織成一份新的傳承。"
