L["Parqual Fintallas"] = "帕科瓦‧芬塔拉斯"
L["Dorn Plainstalker"] = "多恩·平原行者"
L["Past the Argent line, the Ebon Blade works in cruder tools. Uzo Deathcaller keeps a pen of vrykul prisoners the Crusade cannot know about. Bragi the Mad waits at Jotunheim with a grudge, a list of vargul he wants back, and an increasingly unhinged plan for their recovery. The Bone Witch sells her favors in bones. And at Valhalas, the vrykul hold court for the worthy dead — which means admission, for the right kind of monster, can be earned. Read the bones. Kill the water terror. Find the ancient hero. Win the challenge rounds. Put on their skin. Walk out over their corpses. By the time the hall goes quiet, the Ebon Blade has one last errand — a banshee's revenge, and a Duke who needs his competition eliminated."] = "越過銀白防線之後，黯刃騎士團使用的是更粗暴的手段。烏佐‧喚死者私下關著一欄十字軍不能知道的維酷人囚犯。『瘋狂』布拉吉在卓頓海姆等著，懷著一股怨氣、一份他想要回來的瓦古爾名單，以及一個越來越瘋狂的奪回計畫。骸骨女巫的恩惠得用骨頭來換。而在英靈殿，維酷人為配得上的亡者設宴——這意味著，對合適的怪物而言，入場資格是可以贏來的。解讀骸骨。殺死水中恐魔。尋找遠古英雄。贏得挑戰回合。披上他們的皮。踏著他們的屍體走出去。當大廳歸於寂靜時，黯刃騎士團還有最後一件差事——一位女妖的復仇，以及一位需要剷除競爭對手的公爵。"
L["Patch"] = "派奇"
L["Patch rallied the assault force at Bloodfire Ravine. Talanji stood at the front. The loa — Krag'wa, what remained of Bwonsamdi's power, even the memory of Torga — were with you. The blood trolls had held the Blood Gate as the last barrier between Nazmir and the heart of their god's prison. You blew through their defenses, toppled their totems, and drove a path of fire through their strongest ranks. Grand Ma'da Ateena fell. In the silence after, Titan Keeper Hezrel delivered the final revelation: G'huun still breathed beneath the earth. Nazmir had been reclaimed — but the blood god's prison was cracking. The raid on Uldir was no longer optional."] = "派奇在血火山谷集結突擊部隊。塔蘭姬站在最前線。洛阿們——克拉格瓦、伯昂撒姆第殘存的力量，甚至還有托加的記憶——都與你同在。血食人妖死守血門，那是納茲米爾與他們神祇牢籠核心之間的最後一道屏障。你突破他們的防線，推倒他們的圖騰，在他們最強悍的陣列中殺出一條烈焰之路。大族長艾提娜倒下了。在隨後的寂靜中，泰坦守衛者赫茲羅揭露了最後的真相：古翰仍在地底呼吸。納茲米爾已被奪回——但血神的牢籠正在崩裂。進攻奧迪爾已勢在必行。"
