L["Princess Tess Greymane"] = "泰絲‧葛雷邁恩公主"
L["Princess Tess Greymane guided you through a web of coded messages and hidden vaults to recover the Kingslayers — Garona's legendary daggers, stained with the blood of a king. You infiltrated a Stormwind prison, broke codes, and retrieved the blades from their resting place, returning them to the hands of an assassin who knew their weight better than anyone."] = "泰絲‧葛雷邁恩公主帶你穿越重重密碼訊息與隱密寶庫，尋回弒君者——迦羅娜的傳奇匕首，曾沾染一位國王的鮮血。你潛入暴風城的監獄、破解密碼，從安息之地取回這對匕首，將它們交還到一名比任何人都清楚其分量的刺客手中。"
L["Priorities!"] = "優先事項！"
L["Priscilla Ashvane has been quietly dismantling the Proudmoore Admiralty from within — bribing officials, sabotaging trade, and positioning herself to absorb the family's political legacy while Katherine grieves her son Derek and her estrangement from Jaina. Unraveling the conspiracy takes you across Tiragarde Sound, from Boralus's counting houses to Ashvane prison cells, until the truth lands at Genn Greymane's feet in Boralus Harbor."] = "普莉希拉‧艾胥凡一直暗中從內部瓦解普勞德摩爾海軍府——賄賂官員、破壞貿易，並趁凱瑟琳為兒子德瑞克哀悼、又與珍娜疏遠之際，伺機接收這個家族的政治遺產。揭開這場陰謀的過程將帶你走遍提拉加德海灣，從波拉勒斯的帳房到艾胥凡的牢房，直到真相攤在波拉勒斯港的吉恩‧葛雷邁恩腳下。"
L["Prisoner of Interest"] = "重大囚犯"
L["Problem Salver"] = "問題托盤"
L["Propaganda Takedown"] = "處理文宣"
L["Prophet Velen"] = "預言者費倫"
L["Protocol Recovery"] = "取回協定"
L["Proudmoore's Parley"] = "與普勞德摩爾會談"
L["Prowler Problems"] = "徘徊者問題"
L["Pruning the Garden"] = "修整花園"
L["Purge the Unclean"] = "淨化不潔"
L["Pushing through the farmlands around Deathknell, you clashed with the Scarlet Crusade at their palisade. Inside the fortifications you found Lilian — captured by the zealots she once served. Her captors didn't care that she had been one of them. To the Crusade, she was just another undead abomination to be purged."] = "你在喪鐘鎮周圍的農田一路推進，在柵欄前與血色十字軍交鋒。在防禦工事內，你找到了莉莉安——她被自己曾效忠的狂熱分子俘虜了。俘虜她的人不在乎她曾是他們的一員。對十字軍而言，她只是另一個需要淨化的不死憎惡之物。"
L["Put on vrykul skin, fight through Valhalas's trials, and pay a Bone Witch's debt in blood."] = "披上維酷人的皮，闖過英靈殿的試煉，並以鮮血償還骸骨女巫的債。"
L["Put the Royal Apothecary Society's new weapon through its paces."] = "讓皇家藥劑師協會的新武器接受實戰考驗。"
L["Putting Olakin Back Together Again"] = "將歐拉金拼湊回來"
