L["Recover Felo'melorn, the Flamestrike — the ancient blade of the Sunstrider dynasty, lost in the frozen halls of Icecrown."] = "尋回「烈焰風暴」斐洛梅洛恩——逐日者王朝的遠古之劍，失落在寒冰皇冠的冰封殿堂中。"
L["Recover Light's Wrath, a staff of terrible holy power sealed away in the Nexus Vault because it was too dangerous to wield."] = "尋回聖光之怒，這根蘊含可怕神聖之力的法杖，因過於危險而被封印在奧核寶庫中。"
L["Recover lost tradition, confront painful history, and stand against lingering eredar corruption."] = "找回失落的傳統，直面痛苦的歷史，並對抗揮之不去的埃雷達爾腐化。"
L["Recover Natalie Seline, a priest who delved too deep into the Void, from the shadow realm where she has been lost."] = "從迷失的暗影國度中救回娜塔莉‧瑟琳——一位太過深入虛無的牧師。"
L["Recover Sheilun, the staff of Emperor Shaohao, who shrouded Pandaria in mist for ten thousand years."] = "尋回謝倫——紹昊大帝的法杖，他曾讓潘達利亞籠罩在迷霧中長達一萬年。"
L["Recover the ancient bow of the Windrunner family, lost when Alleria Windrunner vanished beyond the Dark Portal."] = "尋回風行者家族的遠古長弓，它在艾蘭里亞‧風行者消失於黑暗之門彼端時一同失落。"
L["Recover the Claws of Ursoc, the great bear god's weapons, from the nightmares that have claimed them."] = "從奪走烏索克之爪的夢魘手中，尋回這對偉大熊神的武器。"
L["Recover the Maw of the Damned, a vampiric axe that drains the life from its victims to sustain its wielder."] = "尋回遭譴者之顎，一把吸取受害者生命來維繫持有者的吸血戰斧。"
L["Recover the Silver Hand, the holy mace of the original paladins, lost since the founding of the order."] = "尋回白銀之手，這把最初的聖騎士們所使用的神聖戰錘，自騎士團創立以來便已失落。"
L["Recover the Skull of the Man'ari, a demonic focus of immense summoning power used by the eredar lords."] = "尋回曼阿瑞之顱，一件被埃雷達爾領主所用、蘊含強大召喚之力的惡魔法器。"
L["Recover, restore, and reforge an ancient Bronzebeard relic."] = "尋回、修復並重鑄一件古老的銅鬚聖物。"
L["Recovering Remnants"] = "找回古物"
L["Recruit Archmage Kalec and Archmage Modera as champions. Build the Tirisgarde's forces and establish operations."] = "招募大法師卡雷克與大法師莫德菈成為勇士。壯大提里斯加德的部隊，並展開行動。"
L["Recruit the first champions of the Unseen Path and send troops into the field across the Broken Isles."] = "招募無形之徑的第一批勇士，並派遣部隊前往破碎群島各地執行任務。"
L["Recruiting More Troops"] = "招募更多部隊"
