L["Remnants of the Damned"] = "受詛咒的殘餘物"
L["Ren Whitepaw"] = "阿仁‧白爪"
L["Renathal gathered the Harvesters and turned Sinfall's mirrors against Castle Nathria. Light cut across the ramparts, loyalists scattered, and the rebellion surged toward Denathrius. Then the Master stopped pretending. He had not failed to save the Shadowlands from the anima drought — he had helped cause it, hoarding the realm's lifeblood and pouring it into the Maw for the Jailer. Revendreth's gothic theater became something far larger and worse: the first clear proof that the machinery of Death itself had been betrayed. Denathrius retreated into Castle Nathria, and the fight for the Shadowlands changed forever."] = "雷納瑟集結了收割者，讓罪殞城的鏡子轉而對付納撒亞城。光芒劃過城牆，效忠者四散奔逃，叛軍向戴納瑟斯湧去。接著，這位瑞文崔斯之主不再偽裝。他並非沒能讓暗影之境免於心能乾旱——而是他一手促成了乾旱，囤積這個國度的命脈，將其灌入淵喉獻給閻獄之主。瑞文崔斯的哥德式劇場，變成了某種更龐大也更可怕的東西：死亡運轉的機制本身遭到背叛的第一個明確證據。戴納瑟斯退入納撒亞城，暗影之境之戰從此徹底改變。"
L["Renathal's rebellion marches on Castle Nathria. Denathrius reveals the truth: Revendreth's stolen anima is being sent into the Maw."] = "雷納瑟的叛軍進軍納撒亞城。戴納瑟斯揭露了真相：瑞文崔斯遭竊的心能正被送進淵喉。"
L["Rendezvous with the Courier"] = "與信差會合"
L["Rendezvous with the Libation"] = "與獻酒號會合"
L["Rendle"] = "倫德"
L["Rensar Greathoof"] = "蘭薩‧巨蹄"
L["Report from Tian Monastery"] = "來自天僧寺的報告"
L["Repurposing Their Village"] = "淨空村落"
L["Requesting Reinforcements"] = "要求增援"
L["Requires completing all three Kul Tiras zone storylines (Tiragarde Sound, Drustvar, and Stormsong Valley). Speak to Cyrus Crestfall in Boralus to begin. This chapter includes four dungeon quests: Tol Dagor, Shrine of the Storm, Waycrest Manor, and Siege of Boralus."] = "需要完成庫爾提拉斯全部三個地區的故事線（提拉加德海灣、佐司瓦與斯陀頌恩谷地）。在波拉勒斯與塞勒斯‧克瑞斯福交談即可開始。本章節包含四個地城任務：托達戈爾、風暴聖壇、威奎斯特莊園與波拉勒斯圍城戰。"
L["Requires completing the Tiragarde Sound main storyline (\"Trouble in Tiragarde Sound\"). Begin with the Ashvane Trading Company investigation in Boralus."] = "需要完成提拉加德海灣的主線故事（「提拉加德海灣的麻煩」）。從在波拉勒斯調查艾胥凡貿易公司開始。"
L["Rescue a brilliant arcanist trapped by withered nightfallen and secure his knowledge for the growing rebellion."] = "救出一位受困於凋萎者手中的傑出秘法師，為日益壯大的叛軍保住他的知識。"
L["Rescue a captive High Chief and bring a new people into the Horde."] = "救出一名被俘的高階酋長，讓一個新的種族加入部落。"
L["Rescue Koltira Deathweaver from imprisonment and forge deathchargers worthy of the Four Horsemen."] = "拯救寇爾提拉‧亡織者脫離囚禁，並打造配得上四騎士的死亡戰馬。"
L["Rescue monks captured by the vrykul in Stormheim. Recruit Angus Ironfist, Hiro, and Sylara Steelsong as champions."] = "救出在斯鐸海姆被維酷人俘虜的武僧。招募安格斯‧鐵拳、希洛與席拉蕾‧鋼曲成為勇士。"
