L["Return to the Black Temple to confront echoes of the past and secure reinforcements from Illidan's former stronghold."] = "返回黑暗神廟，直面過往的回響，並從伊利丹昔日的要塞取得援軍。"
L["Return to the Chamber of Shadows"] = "返回潛影之廳"
L["Return to the Echo Isles"] = "回到回音群島"
L["Return to the Echo Isles where the Darkspear first made landfall in exile, and listen for loa whose voices have grown quieter since the tribe took its place inside the Horde. The new generation has forgotten more than it realizes.\n\nSeek the loa where they still answer, perform the rites where they are still owed, and remember the Darkspear as a people with roots deeper than any banner."] = "回到回音群島——暗矛食人妖流亡時最初登陸之地——聆聽洛阿的聲音；自從部族在部落中占有一席之地後，那些聲音已日漸微弱。新一代遺忘的東西，比他們自以為的還多。\n\n到洛阿仍會回應之處尋找他們，在仍須獻祭之地舉行儀式，並記住暗矛是一個根源比任何旗幟都更深的民族。"
L["Return to the Firelands"] = "重返火源之界"
L["Return to the Harbor"] = "返回港口"
L["Return to the Surface"] = "重返地表"
L["Revendreth"] = "瑞文崔斯"
L["Revendreth is a gothic realm of sinstones, vampire courts, and ritual penance: the place where prideful souls are meant to be broken open, judged, and remade. Sent to seek anima for the starving Shadowlands, you arrive in a kingdom that is already fraying.\n\nPrince Renathal and the Court of Harvesters are gathering resistance, Sire Denathrius still rules from above, and every misted street carries another rumor about where Revendreth's loyalty truly lies."] = "瑞文崔斯是一個充滿罪石、吸血鬼宮廷與贖罪儀式的哥德式國度：驕傲的靈魂注定要在此被剖開、審判並重塑。你奉命為飢渴的暗影之境尋找心能，抵達的卻是一個早已分崩離析的王國。\n\n雷納瑟王子與收割者廷衛正在集結反抗勢力，戴納瑟斯王依然高高在上統治著，而每一條霧氣瀰漫的街道，都流傳著另一則關於瑞文崔斯真正效忠於誰的傳言。"
L["Revenge for the Vargul"] = "為瓦苟復仇"
L["Revenge, Served Cold"] = "冷酷復仇"
L["Revenge: Served Hot"] = "熱血復仇"
L["Revered"] = "崇敬"
L["Reversal"] = "尋找瑪苟"
L["Revive old rites and prove yourself to the spirit of orcish tradition."] = "復興古老的儀式，向獸人傳統之靈證明你自己。"
L["Reviving Tradition"] = "傳統重現"
L["Rexxar"] = "雷克薩"
L["Ride the Alliance gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "搭乘聯盟砲艇，從依米海姆出發，經過破碎前線，直抵荒寂之門。"
L["Ride the Horde gunship from Ymirheim to the Broken Front to the Desolation Gate."] = "搭乘部落砲艇，從依米海姆出發，經過破碎前線，直抵荒寂之門。"
L["Ride to Wyrmrest Temple and kneel before Alexstrasza, the Life-Binder."] = "前往龍眠神殿，跪在『生命守縛者』雅立史卓莎面前。"
L["Riding the Wavelength: The Bombardment"] = "乘著波長：轟炸"
L["Righting Wrongs"] = "矯正過錯"
L["Riko"] = "瑞可"
L["Rise Up"] = "登高"
L["Rise, Champions"] = "奮起吧，勇士們"
L["Rise, Forsaken"] = "醒來吧，被遺忘者"
L["Rise, Godfrey"] = "起來吧，高佛雷"
L["Rising Shadows"] = "暗影崛起"
L["Rising Troubles"] = "不死災禍"
L["Ritssyn Flamescowl"] = "瑞特辛‧焰慍"
L["Ritssyn Flamescowl appeared in Dalaran with a proposition — the Council of the Black Harvest needed a sixth member, and you had been chosen. The Council operated from Dreadscar Rift, a pocket of the Twisting Nether they had ripped from demonic control and claimed as their own. You proved your worth, claimed an artifact weapon steeped in dark power, and took your seat on the Council. Calydus — a demon bound to serve the warlocks — helped establish the Rift as your base of operations."] = "瑞特辛‧焰慍帶著一項提議出現在達拉然——黑暗收割議會需要第六位成員，而你已雀屏中選。議會以懼痕裂隙為據點，那是他們從惡魔手中奪下、據為己有的一塊扭曲虛空。你證明了自己的價值，奪得一件浸染黑暗力量的神器武器，在議會中坐上了自己的席位。卡萊德斯——一名被束縛來侍奉術士的惡魔——協助你們將裂隙建立為行動基地。"
L["Ritssyn Flamescowl needs a sixth member for the Council of the Black Harvest. You are chosen — but the seat comes with a price."] = "瑞特辛‧焰慍要為黑暗收割議會尋找第六位成員。你被選中了——但這個席位是有代價的。"
L["Ritual Artifacts"] = "儀式文物"
L["Ritual Effects"] = "儀式效果"
L["Ritual Reagents"] = "儀式材料"
L["Ritual Recovery"] = "儀式繼續"
L["Rivett Clutchpop"] = "理弗特‧窩爆"
L["Road Rations"] = "趕路乾糧"
L["Rokhan"] = "洛克漢"
L["Rokhan led you into Gloom Hollow, where the ancient frog loa Krag'wa brooded in the dark. The blood trolls had massacred his followers and desecrated his totems, and Krag'wa was in no mood for diplomacy. You hunted the hunters who had slaughtered his priests, restored his shrines, and prepared the kind of feast that only a frog loa the size of a temple could appreciate. Krag'wa was pleased. He was also terrifying. The agreement was simple enough: he would fight with the Horde against the blood trolls and G'huun. In Gloom Hollow, that counted as a warm welcome."] = "洛克漢帶你進入幽暗谷，遠古的蛙之洛阿克拉格瓦正在黑暗中沉思。血食人妖屠殺了他的信徒、褻瀆了他的圖騰，克拉格瓦可沒有心情談外交。你追獵那些殺害他祭司的獵人，修復他的神壇，並準備了一場只有神殿般巨大的蛙之洛阿才懂得欣賞的盛宴。克拉格瓦很滿意。他也很嚇人。協議再簡單不過：他會與部落並肩對抗血食人妖與古翰。在幽暗谷，這已經算是熱烈歡迎了。"
L["Rotten Old Memories"] = "陳舊的記憶"
L["Ruinous Rituals"] = "招來毀滅的儀式"
L["Ruins of Lordaeron"] = "羅德隆廢墟"
L["Rumor Has It"] = "謠傳"
L["Rune Ruination"] = "毀滅符文"
L["Runic Resistance"] = "符文抵抗"
L["Rush Order"] = "趕工令"
L["Sacred Waters"] = "聖水"
L["Saga of the Shadowblade"] = "影刃傳奇"
L["Salanar the Horseman"] = "『騎士』撒拉納"
L["Salvage Rights"] = "回收物品"
L["Salvation"] = "救贖"
L["Sampling the Nightmare"] = "採集夢魘樣本"
L["Sampling the Source"] = "採集病原體樣本"
