L["Sanctum of Light / Broken Isles"] = "聖光會堂 / 破碎群島"
L["Sanctum of the Sages"] = "賢者聖所"
L["Saronite Mines"] = "薩鋼礦坑"
L["Sassy Hardwrench"] = "賽希‧硬心"
L["Saurfang is gone. Nathanos Blightcaller has been dispatched to find him — and bring him back before he becomes a problem."] = "薩魯法爾不見了。納薩諾斯‧凋零者奉命去找到他——在他成為麻煩之前把他帶回來。"
L["Saurfang leads the charge on the gate to the Lich King's domain."] = "薩魯法爾率軍衝向通往巫妖王領域的大門。"
L["Saurfang leads the Horde up the spiral of Wyrmrest to bargain with the Dragon Queen."] = "薩魯法爾率領部落登上龍眠神殿的螺旋階梯，與龍后談判。"
L["Saurfang the Younger"] = "小薩魯法爾"
L["Saurfang the Younger calls you to the Kor'kron Vanguard. The Taunka are blood-sworn, the Nerubians silenced, and the Forsaken have their weapons. The old Orc himself takes you to Wyrmrest Temple — to kneel, or rather to bargain, before Alexstrasza the Life-Binder. The dragons remember every Horde blade that ever flashed in anger at the Second War. Whether they answer the Warchief's call is another matter."] = "小薩魯法爾召喚你前往柯爾克隆先鋒駐地。坦卡族已立下血誓，奈幽人已被消滅，被遺忘者也拿到了他們的武器。這位老獸人親自帶你前往龍眠神殿——在『生命守縛者』雅立史卓莎面前下跪，或者說，與她談判。巨龍們記得第二次大戰中每一把憤怒揮舞的部落刀刃。他們是否會回應大酋長的呼喚，又是另一回事了。"
L["Saurfang's last act before the gate was a summons sent to every Horde leader still standing. By the time the crowd outside Orgrimmar thinned and the silence settled in, they were already gathering: Baine, Lor'themar, Ji Firepaw, and Lilian Voss, who now spoke for a Forsaken people their former Warchief had used as weapons and discarded. In the middle of it, Lilian stepped away from the main hall to broker a quieter conversation — one that had to happen before anything else could move: Forsaken leadership, face to face with Calia Menethil and Derek Proudmoore. Hidden, necessary, and hers to arrange. Then the full council assembled. The Warchief's throne was empty. Lilian made the case for leaving it that way. No single voice, no single will — a council, the way the Horde had always needed to work but never quite managed. The others listened. Then they agreed."] = "薩魯法爾在城門前的最後一個舉動，是向每一位仍屹立不倒的部落領袖發出召集令。當奧格瑪城外的人群散去、寂靜降臨時，他們已經開始集結：貝恩、洛索瑪、紀‧火爪，以及莉莉安‧佛斯——她如今代表被遺忘者發聲，而這個民族曾被他們的前任大酋長當作武器利用，然後拋棄。在這之間，莉莉安離開主廳，促成了一場較為低調的會談——一場必須先發生、其他事情才能推進的對話：被遺忘者的領導者與卡莉雅‧米奈希爾和德瑞克‧普勞德摩爾面對面。隱密、必要，而且由她一手安排。接著，完整的議會召開了。大酋長的王座空著。莉莉安主張就讓它空著。不再由單一的聲音、單一的意志主宰——而是一個議會，這正是部落一直需要、卻始終未能真正實現的運作方式。其他人聆聽著。然後，他們同意了。"
