L["Scouting Report: The Friend of My Enemy"] = "偵察報告：敵人的朋友"
L["Scouting Reports"] = "偵察報告"
L["Scouting reports painted a grim picture — Legion assassins had infiltrated the Broken Isles, targeting the Unseen Path's agents. You tracked them through Stormheim, rescuing Hudson Crawford from an ambush and calling Beastmaster Hilaire home from the wilds. In Highmountain, you found Rexxar living among the beasts and convinced the legendary hunter to join your cause. With new champions at your side, the Unseen Path's eyes grew sharper."] = "偵察報告描繪出一幅嚴峻的景象——燃燒軍團的刺客已滲透破碎群島，鎖定無形之徑的探員下手。你一路追蹤他們穿越斯鐸海姆，將哈德森‧克勞福從埋伏中救出，並把獸王希萊爾從荒野中召回。在高嶺，你找到了與野獸為伍的雷克薩，說服這位傳奇獵人加入你的陣營。有了新勇士相伴，無形之徑的眼光變得更加銳利。"
L["Scouting reports reveal Legion assassins targeting the Unseen Path. Track them across Stormheim while recruiting Rexxar and Hilaire."] = "偵察報告揭露燃燒軍團的刺客正鎖定無形之徑。在斯鐸海姆追蹤他們，同時招募雷克薩與希萊爾。"
