L["Seek aid from the night elves and blood elves, bridging ten thousand years of division for a common cause."] = "向夜精靈與血精靈尋求援助，為了共同的目標，跨越長達一萬年的分裂。"
L["Seek Fu Zan, a legendary staff carried by monks across the ages, now lost in the wilds."] = "尋找福贊——一根歷代武僧攜帶的傳奇法杖，如今失落在荒野之中。"
L["Seek out a shield forged from a scale of Neltharion himself, hidden deep within the mountains where the earth remembers."] = "尋找一面以奈薩里奧本身的鱗片鍛造的盾牌，它藏在群山深處，大地仍記得的地方。"
L["Seek out Aegira, a vrykul brewmaster in the Halls of Valor, and brew the legendary Storm Brew to empower your forces."] = "尋找英靈殿的維酷人釀酒大師艾綺菈，釀造傳奇的風暴蜜酒來強化你的部隊。"
L["Seek Out the Lorewalker"] = "找尋博學行者"
L["Seek T'uure, a crystal beacon forged by the naaru, whose light has guided the faithful through the darkest ages."] = "尋找圖瑞——那魯鍛造的水晶信標，它的光芒曾引領信徒度過最黑暗的年代。"
L["Seek the Aldrachi Warblades, weapons of a race that defeated a demon lord and chose death over servitude."] = "尋找奧達奇戰刃——這個種族曾擊敗一名惡魔領主，寧死也不願受奴役。"
L["Seek the ancient eagle spear Talonclaw in the peaks of Highmountain, a weapon sacred to the hunters of old."] = "在高嶺的群峰間尋找遠古的鷹之長矛鷹爪，這件武器是古代獵人心中的聖物。"
L["Seek the Fist of Ra-den, a weapon forged by the titan keeper who tamed the storms of Azeroth."] = "尋找拉登之拳，一件由馴服艾澤拉斯風暴的泰坦守衛者所鍛造的武器。"
L["Seek the Scythe of Elune, a weapon of terrible power tied to the worgen curse and the moon goddess herself."] = "尋找伊露恩之鐮，這件蘊含可怕力量的武器，與狼人詛咒及月之女神本身息息相關。"
L["Seek the staff of the Guardian Aegwynn — Aluneth, a weapon of pure arcane power that has a mind of its own."] = "尋找守護者艾格文的法杖——艾露奈斯，一件擁有自我意識、蘊含純粹秘法之力的武器。"
L["Seek the Unsavory"] = "自找麻煩"
L["Seek Truthguard, a titan-forged shield that protects the worthy and strikes down the false."] = "尋找真理守護，一面泰坦鍛造的盾牌，守護值得守護之人，擊倒虛偽之徒。"
L["Seek Ulthalesh, a scythe that reaps souls from the living and binds them in eternal torment."] = "尋找奧薩雷什，一把收割生者靈魂、將其困於永恆折磨的鐮刀。"
