L["Sinfall gave the rebels a foothold, but they still needed their prince. In the ruins of his first rebellion, you found what Denathrius had left behind: cages, broken allies, and Renathal himself, imprisoned as an example. With Theotar, the Accuser, and General Draven at your side, you tore open the prison, stole the key, and pulled Renathal back from Torghast's shadow. The prince returned humbled but unbroken. He had lost a rebellion once. This time, he would not stand alone."] = "罪殞城讓叛軍有了立足之地，但他們仍需要自己的王子。在他第一次叛亂的廢墟中，你發現了戴納瑟斯留下的東西：牢籠、殘破的盟友，以及被囚禁以儆效尤的雷納瑟本人。在希奧塔、控罪者與德瑞文將軍的陪同下，你攻破監獄、偷走鑰匙，將雷納瑟從托迦司的陰影中拉了回來。王子歸來時雖已變得謙卑，卻未曾屈服。他曾經輸掉一場叛亂。這一次，他不會再孤軍奮戰。"
L["Sinstone Delivery"] = "送交罪孽石"
L["Siouxsie the Banshee"] = "『女妖』席厄克希"
L["Sire Denathrius"] = "戴納瑟斯王"
L["Sire Denathrius pointed you at the Accuser, one of the Harvesters standing against him. Lord Chamberlain's hunt was brutal and theatrical: tear through her followers, read the sinstones of her inquisitors, and use those names to drag the guilty into judgment. But the deeper you went, the less clean the story became. The Accuser had punished pride for ages, and she understood what Denathrius's court had become. When her own secret was revealed, it was not simple innocence that saved her — it was the terrible truth that Revendreth's ruler had turned repentance into control."] = "戴納瑟斯王要你對付控罪者——起身反抗他的收割者之一。宮務大臣的獵殺既殘酷又充滿戲劇性：殺穿她的追隨者，解讀她手下審判官的罪石，再利用那些名字把罪人拖去受審。但你越深入，這個故事就越不單純。控罪者懲罰驕傲已有千秋萬世，她明白戴納瑟斯的宮廷變成了什麼樣子。當她自己的秘密被揭露時，拯救她的並非單純的清白——而是一個可怕的真相：瑞文崔斯的統治者把懺悔變成了控制的手段。"
L["Skull of the Man'ari"] = "曼阿瑞之顱"
L["Sky Admiral Rogers"] = "空軍上將羅傑斯"
L["Sky-Reaver Korm Blackscar"] = "空奪者寇姆‧黑疤"
