L["Skylord Omnuron"] = "傲天者歐姆奴隆"
L["Skyseer Ghrent"] = "占天者甘特"
L["Slaves to Saronite"] = "搶救薩鋼礦奴"
L["Slayer's Campaign"] = "斬魔者戰役"
L["Slowing the Spread"] = "減緩蔓延"
L["Slumber No More"] = "不再沉睡"
L["Smarter Than Your Average Trogg"] = "聰明絕頂穴居怪"
