L["Snowfeather"] = "雪羽"
L["Snowfeather, a majestic eagle, arrived in Dalaran bearing an urgent summons. You followed the bird to Trueshot Lodge high in the mountains, where Emmarel Shadewarden revealed the Unseen Path — a secret order of hunters that had watched over Azeroth for generations. You swore the Oath of Service, claimed a weapon of legend, and took your place among their ranks."] = "一隻雄偉的老鷹雪羽飛抵達拉然，帶來緊急召喚。你跟隨這隻鳥來到高山上的神獵廳，艾瑪芮爾‧影衛在那裡揭露了無形之徑——一個世世代代守護著艾澤拉斯的秘密獵人修會。你宣誓效忠，奪得一把傳說武器，在他們的行列中占有一席之地。"
L["So Long, Sister"] = "永別了，女巫"
L["Some Knowledge Shouldn't Be Shared"] = "最好永不流傳的知識"
L["Someone Else's Mess"] = "別人的混亂難題"
L["Something broke inside Lilian Voss. Shadow magic erupted from her hands as she tore through the crusaders with a fury that terrified even the Forsaken. She marched to the tower where her father, High Priest Benedictus Voss, waited — and when he condemned her as a monster, she killed him. Then she vanished, leaving nothing but silence and the smell of burning."] = "莉莉安‧佛斯內心的某樣東西崩潰了。暗影魔法從她手中迸發，她以連被遺忘者都為之膽寒的狂怒殺穿十字軍。她前往父親高階祭司本尼迪塔斯‧佛斯等待的高塔——當他斥責她是怪物時，她殺了他。接著她消失無蹤，只留下一片寂靜與燃燒的氣味。"
L["Something in the Water"] = "水裡有古怪"
L["Something Valuable, Perhaps?"] = "是有價值的東西嗎？"
L["Something's Not Quite Right..."] = "似乎有些不對勁…"
L["Soothing Wounds"] = "緩解傷勢"
L["Soul Beacon"] = "靈魂信標"
L["Soulbound"] = "靈魂之契"
L["Souls for the Death Loa"] = "獻給死亡羅亞的靈魂"
L["South of the Pinnacle, past the rim of the Valley of Echoes, a little Scarlet outpost called Blackwatch keeps quiet company with the Scourge it claims to hate. The Argent Crusade has questions about that. Grimly wants the plague altars in pieces. Father Kamaros, somehow still alive, has a list of his own wounded. Doctor Olakin Sainrith is busy inside the lab cooking something that was never meant to breathe. Overhead, the Flesh Giant Champion walks the ice. Inside Malykriss's foundry, the Runesmiths still pound the Scourge's armor — and one old vrykul skeleton is about to do more work dead than it ever did alive."] = "在頂峰以南、越過回聲山谷的邊緣，一座名為黑色守望的血色小型前哨，與它聲稱憎恨的天譴軍悄然為伍。銀白十字軍對此頗有疑問。格里姆利想把瘟疫祭壇砸個粉碎。不知為何仍活著的卡瑪洛斯神父，手上有一份他自己的傷患名單。奧拉金‧聖瑞斯醫生正忙著在實驗室裡調製某種本不該有呼吸的東西。在高處，血肉巨人勇士在冰原上巡行。在瑪利克里斯的鑄造廠裡，符文鐵匠仍在為天譴軍敲打鎧甲——而一具古老的維酷人骷髏，即將在死後做比生前還多的工作。"
