L["Stand as One"] = "團結一心"
L["Stand on the Pinnacle beside a dying paladin while the world's powers weigh his fate."] = "在頂峰上陪伴一位垂死的聖騎士，世間各方強權正在權衡他的命運。"
L["Stand with Eitrigg, Aggra, and the clans as the Kosh'harg, the great festival of clan and ancestor, is reborn on Azeroth. The Horde has crossed worlds and survived wars, but some rites still need hands to carry them forward.\n\nWalk through Durotar and Nagrand with shamans and young initiates, hear the names of forebears spoken aloud, and remember that orc heritage is more than fang or blade."] = "與伊崔格、阿格拉及各氏族並肩而立，見證氏族與祖先的偉大節慶柯什哈格在艾澤拉斯重生。部落跨越了世界、熬過了戰爭，但有些儀式仍需要有人傳承下去。\n\n與薩滿和年輕的入門者一同走過杜洛塔與納葛蘭，聆聽先祖的名字被高聲唸出，並記住獸人的傳承不僅止於獠牙或刀刃。"
L["Stand with Moira Thaurissan as the Dark Iron clan steps out of Blackrock's shadow and claims its place beside the other dwarven clans. Old pride still smolders in the forges, and old enemies still know the names of the halls beneath the mountain.\n\nWalk through places where fire shaped a people, recover what was scattered, and prove that Dark Iron loyalty is earned in heat, craft, and memory."] = "與茉艾拉‧索瑞森並肩而立，見證黑鐵氏族走出黑石的陰影，在其他矮人氏族之間爭得一席之地。古老的驕傲仍在熔爐中悶燒，宿敵也依然記得山脈底下那些大廳的名字。\n\n走過那些由烈火塑造出一個民族的地方，找回散落各處的事物，並證明黑鐵的忠誠是在熾熱、技藝與記憶中贏得的。"
L["Stand with Tess and the Gilneans to face the Nightbane and reaffirm your people's resolve."] = "與泰絲及吉爾尼斯人並肩對抗夜禍，重申你的人民的決心。"
