L["Stormwind's legacy was tested by old enemies and old mistakes. You followed the trail from the city to Westfall and Northshire, exposed the conspiracy, and helped preserve the honor of the kingdom."] = "暴風城的傳承受到宿敵與舊日錯誤的考驗。你從城內一路追查到西部荒野與北郡，揭穿了陰謀，並協助維護王國的榮譽。"
L["Strange Bedfellows"] = "奇怪的枕邊人"
L["Stranglethorn / Crapopolis"] = "荊棘谷／廢坑市集"
L["Strategic Deployment"] = "戰略佈署"
L["Strength of Icemist"] = "冰霧的力量"
L["Strengthen the Dreamgrove by recruiting champions, training troops, and establishing flight paths through the ancient dreamways."] = "招募勇士、訓練部隊，並開闢穿越遠古夢途的飛行路線，以壯大夢林。"
L["Strom'kar, the Warbreaker"] = "斯壯卡，戰爭破壞者"
L["Strongarm Jarden"] = "打手賈登"
L["Strongarm Tactics"] = "強臂戰略"
L["Stunning View"] = "慘不忍睹"
L["Subject 16"] = "受試者16號"
L["Subtlety had its limits in Nazmir. Patch — a goblin with strong opinions about explosives and personal safety — had a solution for the blood troll barricades that was loud, expensive, and effective. You wrangled his scattered crew, gathered everything they needed, and let them do what goblins do best. The blood troll fortifications that had blocked the advance for weeks turned to rubble in an afternoon. Talanji watched the smoke rise with something close to satisfaction. The path deeper into Nazmir was open."] = "在納茲米爾，低調行事有其極限。派奇——一個對爆裂物和人身安全都有強烈主見的哥布林——為血食人妖的路障想出了一個吵鬧、昂貴又有效的解決方案。你召集了他四散的手下，備齊他們需要的一切，然後讓他們發揮哥布林最擅長的本事。擋住進軍數週之久的血食人妖工事，一個下午就化為瓦礫。塔蘭姬看著濃煙升起，神情近乎滿意。深入納茲米爾的道路已經打開。"
L["Sufficient Motivation"] = "動機充分"
L["Sully \"The Pickle\" McLeary"] = "『醃漬王』蘇利‧麥拉利"
L["Summoner Morn"] = "召喚者摩恩"
L["Summoning the Sisters"] = "召喚姐妹"
L["Sunke Khang"] = "孫齊康"
L["Sunwell Plateau"] = "太陽之井高地"
L["Supply Only the Finest Goons"] = "這裡只有上等打手"
L["Suramar"] = "蘇拉瑪爾"
L["Suramar is an ancient elven city sealed behind a magical barrier for ten thousand years, now opened under the shadow of the Burning Legion. Within the walls, the highborne depend on the arcwine of the Nightwell; outside them, the nightfallen wither without its magic.\n\nAid First Arcanist Thalyssra and her rebellion as they gather allies, infiltrate noble houses, and learn how to challenge a city that has survived by hiding from the world."] = "蘇拉瑪爾是一座遠古的精靈城市，在魔法屏障後封閉了一萬年，如今在燃燒軍團的陰影下重新開啟。城牆之內，上層精靈依賴夜井的秘法酒；城牆之外，夜落精靈因失去它的魔力而逐漸凋萎。\n\n協助首席秘法師薩莉瑟拉與她的叛軍集結盟友、滲透貴族世家，並學會如何挑戰一座靠著與世隔絕而倖存下來的城市。"
L["Survey Says..."] = "調查顯示…"
L["Survey the City"] = "調查城市"
L["Survival Skills"] = "生存技能"
L["Survive the Night"] = "夜晚求生"
L["Svergan Stormcloak"] = "斯維根‧嘯氅"
L["Svergan's Promise"] = "斯維根的約定"
L["Swallowed Whole"] = "囫圇吞「猴」"
L["Swear the blood oath at Agmar's Hammer and dig the Horde's claws into the frozen plain."] = "在阿格瑪之錘立下血誓，讓部落的利爪深深扎進冰凍的平原。"
L["Sweete's Strongbox"] = "史威特的保險箱"
L["Sylvanas found a crack in Icecrown's defenses and sent you in alongside her. The Forge of Souls. The Pit of Saron. And finally the Halls of Reflection, where she came face to face with the memory of the man who murdered her and enslaved her people. She asked Uther the Lightbringer what would become of Arthas when he died. He told her the only way to truly end the Lich King was at the Frozen Throne where he was made. Then he warned her, in the same breath, that her own fate in death would not be kind. She said nothing. She called for the gunship and got everyone out."] = "希瓦娜斯在寒冰皇冠的防禦中找到一道縫隙，派你與她一同潛入。眾魂熔爐。薩倫之淵。最後是倒影大廳——她在那裡與那個殺害她、奴役她子民之人的記憶正面相對。她問『光明使者』烏瑟，阿薩斯死後會變成什麼。他告訴她，要真正終結巫妖王，唯一的方法是在造就他的寒冰王座上。接著，他又同時警告她，她自己死後的命運不會好過。她一語不發。她呼叫砲艇，把所有人都帶了出去。"
L["Sylvanas has found a crack in Icecrown's defenses. She leads a covert strike through three dungeons — the Forge of Souls, the Pit of Saron, and the Halls of Reflection — to reach something she has been waiting years to confront."] = "希瓦娜斯在寒冰皇冠的防禦中找到一道縫隙。她率領一場秘密突襲穿越三座地城——眾魂熔爐、薩倫之淵與倒影大廳——去面對她等待多年的某個存在。"
L["Sylvanas is gone. The Horde's leaders gather to decide what it becomes without her — and Lilian Voss speaks for the Forsaken."] = "希瓦娜斯走了。部落的領袖們齊聚一堂，決定失去她之後的部落將何去何從——而莉莉安‧佛斯代表被遺忘者發言。"
L["Sylvanas is gone. What remains of the Horde gathers to decide what it becomes without her."] = "希瓦娜斯走了。部落殘存的成員齊聚一堂，決定失去她之後的部落將何去何從。"
L["Sylvanas shatters the Helm of Domination and tears open the sky above Icecrown. The leaders of Azeroth follow her into death itself — and find that she left someone behind."] = "希瓦娜斯粉碎了統御之盔，撕裂寒冰皇冠上方的天空。艾澤拉斯的領袖們追隨她進入死亡本身——卻發現她留下了一個人。"
L["Sylvanas went to Icecrown and took the Helm of Domination from Bolvar Fordragon's head. Then she broke it. The veil between the living world and the realm of death split apart where she stood, and she stepped through and left. Bolvar used the shards to open a second rift — he and Jaina, Thrall, Baine, and Anduin went in after her. They landed in the Maw, the prison at the bottom of the Shadowlands, a place no soul had ever escaped from. Sylvanas was already gone deeper in. She had left Anduin behind, locked in a cage in the Tremaculum, to be broken slowly by the Jailer's forces — a message, maybe, or an experiment. Jaina found him. The Jailer's magic had already started working on Baine, poisoning his spirit through a cursed dagger. There was no clean escape: the river of souls, Gorgoa, cut across the only path out, and the Jailer's armies were moving to seal it. The group fought their way through, kept each other standing, and crossed. They came out the other side with Anduin freed and the full shape of the threat finally visible. Sylvanas had not just started a war. She had chosen a side in one that had been running since before Azeroth existed."] = "希瓦娜斯前往寒冰皇冠，從伯瓦爾‧弗塔根頭上取下統御之盔，然後將它粉碎。在她站立之處，生者世界與死亡國度之間的帷幕應聲撕裂，她穿越裂口離去。伯瓦爾用碎片開啟了第二道裂隙——他與珍娜、索爾、貝恩和安杜因隨後追了進去。他們落入淵喉，那座位於暗影之境最底層、從未有靈魂逃脫過的牢獄。希瓦娜斯早已深入更深處。她把安杜因留在後頭，鎖在恐懼殿的牢籠裡，任由閻獄之主的部隊慢慢摧折他的意志——或許是一則訊息，又或許是一場實驗。珍娜找到了他。閻獄之主的魔法已經開始侵蝕貝恩，透過一把受詛咒的匕首毒害他的靈魂。這裡沒有輕鬆的退路：靈魂之河戈爾高亞橫亙在唯一的出路上，而閻獄之主的大軍正前去將它封鎖。眾人一路殺出重圍，彼此扶持，終於渡過河去。他們從另一端脫身，安杜因獲救，威脅的全貌也終於浮現。希瓦娜斯不只是挑起了一場戰爭。她在一場早在艾澤拉斯誕生之前便已展開的戰爭中，選擇了陣營。"
L["Sylvanas Windrunner"] = "希瓦娜斯‧風行者"
L["Sympathizers Among the Shal'dorei"] = "夏多雷內應"
L["Syra Goldendraft"] = "錫拉‧金流"
L["T'uure, Beacon of the Naaru"] = "圖瑞，那魯信標"
L["Tactical Matters"] = "運籌帷幄"
L["Tactical Planning"] = "戰術計畫"
L["Tactician Tinderfell"] = "謀士柴薪"
L["Taelia"] = "泰莉亞"
L["Taelia sent you to Drustvar, where Lord Waycrest had vanished and a dark curse was spreading. In Fallhaven, Cyril White led you through the signs of witchcraft — hexed villagers, twisted familiars, and effigies that pulsed with dark magic. You met Lucille Waycrest, the lord's daughter, who refused to sit idle while her land rotted. Together you hunted the witches through Fallhaven, cracking their curses and burning their effigies. The final effigy crumbled, but the witches' power ran far deeper than one village."] = "泰莉亞派你前往佐司瓦，威奎斯特領主在那裡失蹤了，一股黑暗詛咒正在蔓延。在落港村，希洛‧懷特帶你查看各種巫術的跡象——中了咒術的村民、扭曲的使魔，以及脈動著黑暗魔法的咒像。你遇見了領主的女兒露西爾‧威奎斯特，她不願在家園腐朽時袖手旁觀。你們一同在落港村追獵女巫，破解她們的詛咒，焚毀她們的咒像。最後的咒像崩毀了，但女巫的力量遠遠不只扎根於一座村莊。"
L["Take Me To Your Leader"] = "帶我去見你的領導者"
L["Take part in the Spirit Festival and walk both Tushui and Huojin threads of pandaren heritage."] = "參加靈魂節，走過熊貓人傳承中吐水與火金的兩條道路。"
L["Take the High Road"] = "取道高徑"
L["Takes One to Know One"] = "引薦"
L["Taking a Promenade"] = "漫步在宏園"
L["Taking Charge"] = "接手出擊"
L["Taking Control"] = "掌控局勢"
L["Taking the Blood Gate"] = "佔領血門"
L["Tal-Inara"] = "塔因納拉"
L["Tal-Inara sent you toward Revendreth with a plea for aid: Ardenweald was starving, the Heart of the Forest was weakening, and Sire Denathrius was said to be a master of anima. Revendreth greeted you with teeth behind every smile. Rendle introduced the rules of the realm — sinstones, punishment, service, and the long work of repentance. Lord Chamberlain offered polished courtesy while rebels struck at the roads and Darkhaven buckled under the anima drought. The place looked like a vampire court and spoke like a church of atonement, but something in its foundations was already cracking."] = "塔因納拉派你前往瑞文崔斯求援：森憶之地正陷入飢荒，森林之心日漸衰弱，而據說戴納瑟斯王是一位心能大師。瑞文崔斯迎接你的每一張笑臉背後都藏著利齒。倫德向你介紹這個國度的規矩——罪石、懲罰、服侍，以及漫長的贖罪之路。宮務大臣奉上周到的禮數，叛軍則襲擊道路，暗隱村在心能乾旱下搖搖欲墜。這個地方看起來像吸血鬼的宮廷，說起話來卻像贖罪的教會，但它的根基已經開始崩裂。"
L["Talanji brought you to Nazmir, the oldest and most cursed of the Zandalari lands. The swamp had been swallowed — blood trolls pressed inward from every angle, their offerings feeding something dark and hungry beneath the earth. Rokhan read the signs: to push back the blood tide, you'd need the loa. Ancient, capricious, and rarely willing to be asked. You cut through the blood troll front lines, took in the full scope of the devastation, and prepared to seek out the only powers old enough to matter in Nazmir."] = "塔蘭姬帶你來到納茲米爾，贊達拉所有土地中最古老、也最受詛咒的一片。沼澤已被吞噬——血食人妖從四面八方向內進逼，他們的獻祭正餵養著地底某個黑暗而飢渴的存在。洛克漢解讀了徵兆：要擊退血潮，你需要洛阿的力量。他們古老、反覆無常，而且鮮少願意受人請託。你殺穿血食人妖的前線，親眼目睹了浩劫的全貌，並準備去尋找納茲米爾唯一足夠古老、足以左右局勢的力量。"
L["Talking Skull"] = "說話頭顱"
L["Talon Terror"] = "利爪恐懼"
L["Talon's Call"] = "猛禽的呼喚"
L["Talonclaw"] = "鷹爪"
L["Taming their Beasts"] = "馴服他們的野獸"
L["Taoshi"] = "陶氏"
L["Tapping the Leylines"] = "汲取地脈"
L["Taran Zhu"] = "塔蘭‧祝"
L["Target of Opportunity"] = "預料外的攻擊目標"
L["Tavernkeeper's Fate"] = "旅店老闆的命運"
L["Tea Party"] = "下午茶會"
L["Tech It Up a Notch"] = "科技上層樓"
L["Tech It Up A Notch"] = "科技上層樓"
L["Technical Wizardry"] = "魔法工程"
L["Teddies and Tea"] = "熊熊和茶茶"
L["Telemantic Expanse"] = "傳送術的威力"
L["Temel, the Sin Herald"] = "罪孽使者特梅爾"
L["Temple of the Jade Serpent"] = "玉蛟寺"
L["Temporal Investigations"] = "調查時間魔法"
L["Ten thousand years of division between the elven peoples had to be bridged if Suramar was to be freed. You stood between night elf and blood elf, forging an uneasy alliance from shared purpose. Lady Liadrin and Tyrande Whisperwind each brought their people's strength to the cause, while you cleared the Promenade of Elisande's defenses."] = "若要解放蘇拉瑪爾，就必須彌合精靈民族之間長達一萬年的分裂。你站在夜精靈與血精靈之間，以共同的目標鍛造出一個不甚穩固的同盟。莉雅德倫女士與泰蘭妲‧語風各自為這項大業帶來子民的力量，而你則掃除了長廊上艾莉珊德的防禦。"
L["Teng Applebloom"] = "騰‧蘋卉"
L["Terrace of Ten Thunders"] = "十方雷殿"
L["Testing a Theory"] = "測試理論"
L["Testing Loyalties"] = "忠誠考驗"
L["Thalyssra's Abode"] = "薩莉瑟拉的居所"
L["Thalyssra's Drawers"] = "薩莉瑟拉的抽屜"
L["Thank Your Guide"] = "答謝指引你的靈魂"
L["Thas'dorah, Legacy of the Windrunners"] = "薩斯朵拉，風行者的傳承"
L["Thassarian"] = "薩沙理安"
L["Thassarian came with a personal request — Koltira Deathweaver, his old friend and fellow death knight, had been imprisoned beneath the Undercity by Sylvanas Windrunner. You freed Koltira from his chains, and he pledged himself to your cause. Then came the steeds — Salanar the Horseman forged deathchargers in Neltharion's Lair and the Darkheart Thicket, crafting mounts worthy of the Horsemen from nightmares and shadow."] = "薩沙理安帶來一項私人請求——他的老朋友兼死亡騎士同袍寇爾提拉‧亡織者，被希瓦娜斯‧風行者囚禁在幽暗城底下。你解開寇爾提拉的枷鎖，他也宣誓效忠你的大業。接著是戰馬——『騎士』撒拉納在奈薩里奧巢穴與暗心灌木林打造死亡戰馬，以夢魘與暗影鑄造出配得上騎士們的坐騎。"
L["That Which Haunts the Dead"] = "亡靈之怨"
L["That's Abominable!"] = "有夠討厭!"
L["The Accuser"] = "控罪者"
L["The Accuser sent you to find Prince Renathal, and the trail led to Theotar, the Mad Duke. He was scattered, brilliant, and broken in a way that made perfect sense in Revendreth. His morning was a catastrophe of lost servants, forged warrants, forbidden research, and tea. Beneath the absurdity was the Ember Ward, a district burned by the Light so fiercely that even Venthyr feared its glow. You crossed that desiccated ruin, pieced together Theotar's memories, and secured Sinfall as a rebel refuge. Revendreth's comedy had teeth, but it also had a heart: the rebellion finally had a home."] = "控罪者派你去尋找雷納瑟王子，線索指向「瘋狂公爵」希奧塔。他心神渙散、才華洋溢，而且以一種在瑞文崔斯完全合情合理的方式支離破碎。他的早晨是一場災難：走失的僕人、偽造的令狀、禁忌的研究，還有茶。在這一切荒謬之下是餘燼區，一個被聖光猛烈焚燒過的區域，就連汎希爾都畏懼它的光芒。你穿越那片乾涸的廢墟，拼湊起希奧塔的記憶，並確保罪殞城成為叛軍的避難所。瑞文崔斯的喜劇暗藏利齒，卻也有一顆真心：叛軍終於有了一個家。"
L["The Accuser's Fate"] = "控罪者的命運"
L["The Accuser's Secret"] = "控罪者的秘密"
L["The Accuser's Sinstone"] = "控罪者的罪孽石"
L["The Advisor and the Arcanist"] = "諫言者與秘法師"
L["The Afflictor's Key"] = "加害者的鑰匙"
L["The Aid of the Loa"] = "羅亞的援助"
L["The Aid of the Tides"] = "海潮的協助"
L["The Air Stands Still"] = "空氣也為之凍結"
L["The Alliance and Horde did not discover Pandaria gently. They arrived as wreckage, orders, pursuit, and fire, then tried to make allies before they understood what the land would remember.\n\nThe Jade Forest is the first lesson of Pandaria: every doubt, every grudge, and every easy answer has weight. Follow the campaign from the first landings into a land where war leaves marks deeper than banners in the mud."] = "聯盟與部落發現潘達利亞的方式一點也不溫和。他們挾帶著殘骸、命令、追擊與烈火而來，在還沒弄懂這片土地會記住什麼之前，就試圖結交盟友。\n\n翠玉林是潘達利亞的第一課：每一份疑慮、每一道積怨、每一個輕易的答案，都有其分量。跟隨這場戰役，從最初的登陸深入一片土地，在這裡，戰爭留下的痕跡比插在泥濘中的旗幟更深。"
L["The Alliance finds Taylor, courts the Pearlfin jinyu, and follows Cho's strange methods to Prince Anduin."] = "聯盟找到了泰勒，拉攏珠鰭錦魚人，並循著阿洲奇特的方法找到安杜因王子。"
L["The Alliance fleet came while Dazar'alor was still recovering from everything the Horde had sacrificed to protect it. Jaina Proudmoore led the assault through the sacred pyramid, floor by floor, past every guardian the Zandalari could muster. King Rastakhan, knowing the city could not hold, made a desperate bargain — calling on Bwonsamdi's power directly, burning his own life force to drive the invaders back.\n\nBwonsamdi got his king in the end. Rastakhan fell. But the death loa was there to receive him, and the deal struck in Nazmir had never promised anything more than that — the power to fight, not the guarantee of survival. Talanji watched her father die holding a city that still stood. Bwonsamdi, for his part, was exactly as somber as a loa of death ever gets. The soul of a king is not nothing."] = "聯盟艦隊來襲時，達薩亞洛仍未從部落為保衛它所做的一切犧牲中恢復過來。珍娜‧普勞德摩爾率軍一層一層攻上神聖金字塔，擊敗贊達拉所能召集的每一名守衛。神王拉斯塔哈深知城市守不住，於是做出孤注一擲的交易——直接借用伯昂撒姆第的力量，燃燒自己的生命力來擊退入侵者。\n\n伯昂撒姆第最終還是得到了他的國王。拉斯塔哈倒下了。但死亡洛阿就在那裡迎接他，而在納茲米爾締結的交易從未承諾過更多——只給予戰鬥的力量，而非生存的保證。塔蘭姬眼睜睜看著父親死去，而他守護的城市依然屹立。至於伯昂撒姆第，則擺出了一位死亡洛阿所能表現出的最肅穆模樣。一位國王的靈魂，可不是無足輕重的東西。"
L["The Alliance has come for Lordaeron. Sylvanas holds the walls of the Forsaken capital as Jaina and Anduin lead the siege."] = "聯盟兵臨羅德隆。在珍娜與安杜因率軍圍城之際，希瓦娜斯死守著被遺忘者首都的城牆。"
L["The Alliance strikes at the heart of the Zandalari empire. King Rastakhan calls on Bwonsamdi — and pays the price."] = "聯盟直搗贊達拉帝國的心臟。神王拉斯塔哈向伯昂撒姆第求助——並付出了代價。"
L["The allied armies — nightfallen, blood elves, night elves, and vrykul — marched through the streets of Suramar in a united front. You fought alongside Thalyssra at the vanguard, pushing through Elisande's desperate defenses block by block. The fighting was brutal, but the staging point was secured — the Nighthold was within reach."] = "聯軍——夜落精靈、血精靈、夜精靈與維酷人——同心協力，攻入蘇拉瑪爾的大街小巷。你與薩莉瑟拉一同衝鋒在前，一個街區接著一個街區，突破艾莉珊德垂死掙扎的防線。戰況慘烈，但集結點終於拿下——暗夜堡已近在眼前。"
L["The allied forces breach the Nighthold itself, confronting the source of Elisande's power."] = "聯軍攻破暗夜堡，直搗艾莉珊德的力量根源。"
L["The Anub'ar Nerubians boil up from the Pit of Narjun — spider-warriors of a civilization that should have stayed dead. They strike the Horde's supply lines by night and drag the wounded into the dark by morning. Senior Sergeant Juktok wants them ended at the source. Valnok Windrager is already saddling the wyverns. Agmar will not leave this flank open."] = "阿努巴奈幽蛛魔從納爾瓊之坑蜂擁而出——牠們是早該滅亡的文明所遺留的蜘蛛戰士。牠們趁夜突襲部落的補給線，天一亮，傷患便已被拖進黑暗深處。資深士官丘科多克要從源頭斬草除根。沃爾諾克‧風怒者已經在為雙足飛龍備鞍。阿格瑪絕不會讓這道側翼門戶洞開。"
L["The Anvil-Thane's Designs"] = "鐵砧族長的設計"
L["The Arcan'dor — the ancient tree nurtured in Shal'Aran — began to wither, its roots cracking and leaves curling despite all efforts. Valewalker Farodin led you on a desperate search for fragments of arcane power scattered across Suramar's ruins. In the end, you secured a branch of the Arcan'dor itself, stabilizing the tree and keeping alive the dream of a cure for the nightfallen."] = "在沙亞蘭悉心培育的古樹阿坎多爾開始枯萎；儘管眾人用盡辦法，樹根依舊龜裂，葉片依舊捲曲。谷行者費羅丁帶著你四處搜尋散落在蘇拉瑪爾廢墟中的秘法能量碎片。最後，你取得了阿坎多爾本身的一根枝枒，穩住了古樹的狀況，也讓治癒夜落精靈的希望得以延續。"
L["The Arcan'dor is struggling to survive. Race against time to find what it needs before the tree withers."] = "阿坎多爾奄奄一息。你必須與時間賽跑，在古樹枯萎前找到它所需的東西。"
L["The Arcan'dor needed something that could not be found in Suramar — a seed blessed by the wild magic of Val'sharah. You journeyed with Thalyssra's allies to retrieve it, channeling ley energy through Oculeth's projectors and Valtrois's calculations. The seed took root, and the Arcan'dor bloomed with renewed strength, its fruit offering the first true cure for the nightfallen's dependence on the Nightwell."] = "阿坎多爾需要一樣在蘇拉瑪爾找不到的東西——一顆受維爾薩拉狂野魔法祝福的種子。你與薩莉瑟拉的盟友一同前去取得種子，藉由歐庫雷斯的投射器與瓦爾托伊絲的精密計算引導地脈能量。種子扎根之後，阿坎多爾重新煥發生機、綻放花朵，所結的果實成為第一個真正能治癒夜落精靈對暗夜井依賴的解方。"
L["The Arcane Way"] = "秘法之道"
L["The Arcane Way opened a path back to the Black Temple — Illidan's fortress, now empty and echoing with memories. Belath Dawnblade led you through its halls where the ghosts of the Illidari's past still lingered. A confrontation with the temple's remaining defenses proved that the demon hunters had grown beyond what they once were. New recruits joined from among the temple's guards, and the Fel Hammer's ranks swelled."] = "秘法之道開啟了一條重返黑暗神廟的路——伊利丹的堡壘如今人去樓空，只剩回憶在其中迴盪。貝拉斯‧曦刃帶你穿過神廟的大廳，伊利達瑞往昔的幽魂仍在此徘徊。與神廟殘存守軍的一番交鋒證明，惡魔獵人早已今非昔比。神廟守衛中有人投身成為新兵，魔錘號的陣容隨之壯大。"
L["The Archdruid's Campaign"] = "大德魯伊戰役"
L["The Archmage's Campaign"] = "大法師戰役"
L["The Arcway: Long Buried Knowledge"] = "幽暗地道：埋藏已久的資訊"
L["The Arcway: Opening the Arcway"] = "幽暗地道：開啟幽暗地道"
L["The Argent Vanguard is the last friendly ground at the southern edge of Icecrown. Crusade Commander Entari drills the new arrivals into shape. Father Gustav's engineers run the fleshbeast bombardier; Siegemaster Fezzik's jumpbot waits for one more idiot willing to take the breach. Past the tent line, the ground sours into the Valley of Echoes — and past that, Crusaders' Pinnacle, where Tirion Fordring means to draw a line the Scourge cannot cross."] = "銀白先鋒駐地是寒冰皇冠南緣最後一處友軍據點。十字軍指揮官恩塔利正把新來的人操練成形。賈斯塔夫神父的工程師操作著肉獸轟炸機；攻城大師費茲克的跳躍機器人則在等待下一個願意衝進缺口的傻瓜。越過帳篷區，土地逐漸腐敗，化為回聲山谷——再往前便是十字軍之巔，提里奧‧弗丁打算在那裡畫下一道天譴軍無法跨越的防線。"
L["The Art of Being a Water Terror"] = "身為水駭體的藝術"
L["The Art of Flow"] = "流動的藝術"
L["The Art of War"] = "戰爭的藝術"
L["The Ashbringer"] = "灰燼使者"
L["The Authority of Revendreth"] = "瑞文崔斯管理權"
L["The Banshee Queen"] = "女妖之王"
L["The Battle for Broken Shore"] = "破碎海岸之戰"
L["The Battle For Crusaders' Pinnacle"] = "十字軍之巔保衛戰"
L["The Battle for Lordaeron"] = "羅德隆之戰"
L["The Battle of Bloodfire Ravine"] = "血火山谷之戰"
L["The Battle of Dazar'alor"] = "達薩亞洛之戰"
L["The Battlelord's Campaign"] = "戰鬥領主戰役"
L["The Bees' Knees"] = "蟲蟲腿影"
L["The Best and Brightest"] = "最好與最聰明的"
L["The Big Bad Wolfe"] = "大惡孤狼先生"
L["The Blessing of the Ancestors"] = "先祖祝福"
L["The Blessing of the Clan"] = "氏族祝福"
L["The Blessing of the Land"] = "大地祝福"
L["The Blight Congress"] = "瘟疫集會"
L["The Blood of Demons"] = "惡魔之血"
L["The Bloody Truth"] = "血淋淋的真相"
L["The Bone Witch"] = "骸骨女巫"
L["The Boon of A'dal"] = "阿達歐之恩"
L["The Boon of Alexstrasza"] = "雅立史卓莎之恩"
L["The Boon of Remulos"] = "雷姆洛斯之恩"
L["The Brand of Damnation"] = "詛咒之矛"
L["The Bridgeport Ride"] = "橋梁港巡弋"
L["The Broken Front"] = "破碎前線"
L["The Broken Shore"] = "破碎海岸"
L["The Broken Shore brought an unwelcome ally — Magatha Grimtotem, the elder crone who had murdered Cairne Bloodhoof. She demanded a place in the Earthen Ring in exchange for her considerable power, and the elements themselves seemed to agree. You worked alongside her through gritted teeth, breaking chains and quelling snakes, while Nobundo led the main assault. Firelord Smolderon's offense scorched the Legion's fortifications, and when the calm came after the storm, Consular Celestos summoned you to a gathering of storms — where a tempest given form became your mount, the Farseer's Raging Tempest."] = "破碎海岸之戰帶來了一位不受歡迎的盟友——瑪加薩‧恐怖圖騰，那個殺害凱恩‧血蹄的老巫婆。她以自身強大的力量作為交換，要求在陶土議會中占有一席之地，而就連元素本身似乎也表示同意。你咬緊牙關與她並肩作戰，斬斷鎖鏈、鎮壓群蛇，諾柏多則率領主力發動攻勢。火焰之王斯莫德隆的猛攻燒毀了燃燒軍團的工事；暴風雨過後歸於平靜時，賽勒斯多領事召你前往一場風暴集會——在那裡，一道化為實體的暴風成了你的坐騎：先知的狂怒風暴。"
L["The Broken Shore burned with felfire, and Odyn sent you to lead the Valarjar into the heart of the assault. You recruited new forces, armed them for the battles ahead, and ventured into Helheim itself to recover stolen souls and claim Helya's own horn as a trophy. When Kvaldir raiders answered your call and the last of the missing champions returned, Odyn summoned you for one final trial — the Trial of Rage. You emerged victorious, and a bloodthirsty war wyrm knelt before its new master."] = "破碎海岸陷入一片魔火之中，歐丁派你率領華爾拉亞直搗攻勢核心。你招募新的兵力，為往後的戰鬥武裝他們，並深入黑爾海姆奪回被竊的靈魂，還將海亞的號角當作戰利品帶回。當科瓦迪爾掠奪者響應你的號召，最後一批失蹤的勇士也歸來之後，歐丁召你接受最後的試煉——狂怒試煉。你凱旋而歸，一頭嗜血戰龍在新主人面前俯首稱臣。"
L["The Broken Shore called, and the Ebon Blade answered. Minerva Ravensorrow joined as your newest champion, harnessing power from the very demons you slew. You led an expedition to the Peak of Bones where an army of undead rose at your command, fought alongside Thorim's flame, and defeated the Bonemother. On Daumyr's wings you soared above the battlefield, and when the final ride came, you claimed the Vilebrood Vanquisher — a frost wyrm that knelt before the Deathlord."] = "破碎海岸發出召喚，黯刃騎士團挺身回應。米奈娃‧鴉愁成為你最新的勇士，她能汲取你所斬殺惡魔的力量。你率領遠征軍前往白骨之巔，不死大軍在你的號令下崛起；你與索林姆的烈焰並肩作戰，擊敗了骨母。你乘著丹密爾的雙翼翱翔於戰場上空，而在最後一次出征時，你得到了邪裔征服者——一頭向死亡領主俯首的冰霜巨龍。"
L["The Broken Shore demanded the Dreamgrove's strength. Thisalee Crow, fierce and fearless, joined your cause as the war escalated. Rensar Greathoof channeled the Dreamgrove's power to aid the Legionfall assault, granting you the ability to call upon nature even in the most fel-scarred land. When the battle was won, Thisalee brought word of Aviana under attack — you rushed to defend the mother of flight and earned the Lunarwing form, soaring above the world as only an Archdruid could."] = "破碎海岸之戰需要幻夢之林的力量。隨著戰事升溫，勇猛無畏的黎沙莉‧烏鴉加入了你的行列。蘭薩‧巨蹄引導幻夢之林的力量，支援對抗燃燒軍團的總攻，讓你即使身處遭魔化之力蹂躪最深的土地，也能召喚自然之力。戰事告捷後，黎沙莉帶來艾維娜遭受攻擊的消息——你火速趕去保護這位飛行之母，並因此獲得月翼形態，以唯有大德魯伊才能辦到的方式翱翔於世界之上。"
L["The Broken Shore demanded the Tirisgarde's full power. Aethas Sunreaver, once exiled from Dalaran, returned to lead the mage offensive. You uncovered a nightborne workshop hidden on the Shore, secured its secrets, and armed Dalaran's defenses against a Legion counterattack. When the dust settled, Khadgar entrusted you with one final task — recovering the legendary Discs of Norgannon. From their power, the Archmage's Prismatic Disc was forged — a flying platform that shifted between arcane, fire, and frost as you willed it."] = "破碎海岸之戰需要提里斯法守護者傾盡全力。曾遭達拉然放逐的埃薩‧奪日者歸來，領導法師的攻勢。你在海岸上發現一座隱密的夜裔精靈工坊，取得其中的祕密，並強化達拉然的防禦以抵擋燃燒軍團的反擊。塵埃落定後，卡德加交付你最後一項任務——尋回傳說中的諾甘農之碟。憑藉其力量，大法師的稜彩圓盤就此鍛造成形——這座飛行平台能隨你的心意在秘法、火焰與冰霜之間變換。"
L["The Broken Shore held a prisoner the Council had long sought — Kanrethad Ebonlocke, the warlock who had tried to bind a pit lord and paid the price with his freedom. Shinfel and Jubeka led the search while you culled the Legion cult guarding him and contained the fel crystals keeping him sealed. Kanrethad was freed, scarred but unbroken, and joined as your newest champion. Then came the final rite — Mor'zul Bloodbringer opened a portal to Xoroth, where a wrathsteed of chaotic fire waited. You broke its will and bent it to yours, and the Netherlord's Chaotic Wrathsteed carried you from the flames."] = "破碎海岸囚禁著一名議會尋覓已久的人——坎瑞薩德‧埃伯洛克，這位術士曾試圖束縛一名深淵領主，卻因此付出了自由的代價。馨菲與裘貝卡負責搜索，你則剷除看守他的燃燒軍團教派，並壓制封印他的魔化水晶。坎瑞薩德重獲自由，雖然傷痕累累，意志卻未曾動搖，並成為你最新的勇士。接著是最後的儀式——莫蘇爾·召血者開啟一道通往佐洛斯的傳送門，一匹由混沌之火構成的怒馬正在那裡等候。你擊潰牠的意志，令牠臣服於你，虛空領主的混沌怒馬載著你自烈焰中奔馳而出。"
L["The Broken Shore was a rout. The Horde threw everything at the Legion's landing force and bled for it. Vol'jin took a wound that no healer could close. By the time the retreat was called, he was dying. He summoned Sylvanas, told her the loa had whispered her name, and asked her to lead. She stood there for a moment — the Dark Lady of the Forsaken, who had never wanted anything to do with the Horde's politics — and said yes. She walked out of that room as Warchief. Nobody, including her, fully understood what that meant yet."] = "破碎海岸一役兵敗如山倒。部落傾盡全力攻擊燃燒軍團的登陸部隊，也為此血流成河。沃金身受重傷，沒有任何治療者能讓傷口癒合。等到撤退令下達時，他已命在旦夕。他召來希瓦娜斯，告訴她羅亞低語著她的名字，並請她領導部落。她在原地沉默片刻——這位被遺忘者的黑暗女士，向來不想和部落的政治有任何瓜葛——然後答應了。她走出那個房間時，已是大酋長。包括她自己在內，當時沒有人真正明白這意味著什麼。"
L["The Broken Shore was crawling with demons, and Kor'vas coordinated the Illidari's assault from the Fel Hammer itself. When the Legion counterattacked, you defended the ship in a desperate battle above the battlefield. Lady S'theno, a naga exile who had fought demons for millennia, joined your cause after you restored balance to the Broken Shore's ley lines. When the war was won, a felbat — the Felbroken Shrieker — recognized you as its master, and the Slayer took to the skies."] = "破碎海岸上惡魔橫行，珂娃絲親自在魔錘號上指揮伊利達瑞的攻勢。燃燒軍團發動反擊時，你在戰場上空展開一場殊死戰，守住了這艘戰艦。你恢復破碎海岸地脈的平衡之後，與惡魔奮戰了數千年的納迦流亡者絲瑟諾女士加入了你的行列。戰爭勝利後，一隻魔蝠——魔碎尖嘯者——認你為主，屠殺者從此翱翔天際。"
L["The Bulk of the Guard"] = "大批衛隊"
L["The Burden of Proof"] = "證明之擔"
L["The Call of Battle"] = "戰爭的呼喚"
L["The Call of Icecrown"] = "冰冠城塞的呼喚"
L["The Call to War"] = "號令參戰"
L["The Calm After the Storm"] = "暴風雨後的寧靜"
L["The Campaign Begins"] = "戰役開始"
L["The campaign pushes into the ruins of Gilneas. A traitor needs to be dealt with, and the Gilneas Liberation Front is running out of room to maneuver."] = "戰役推進至吉爾尼斯的廢墟。有個叛徒必須處理，而吉爾尼斯解放陣線的迴旋空間也越來越小。"
L["The Captive Spymaster"] = "被俘虜的間諜大師"
L["The Chain Gun And You"] = "鏈砲與你"
L["The Champion's Return"] = "勇士歸來"
L["The citadel's gates are not for hammering. Sergeant Stackhammer knows it. Sergeant Kregga knows it. The Alliance and Horde sappers have quieter work — crawl into the saronite pits beneath Sindragosa's Fall and set the charges that will shake the foundations from below. Before the pits go up, a voice begins to whisper out of the saronite dark. Whoever he is, he knows a name. He wants it spoken. He wants you to come back when the dust settles and hear the rest of his story at the First Legion Forward Camp."] = "城塞的大門不是靠蠻力就能敲開的。史塔克漢默中士明白這一點，克瑞佳中士也明白。聯盟與部落的工兵有更隱密的工作要做——爬進辛德拉苟莎之殞下方的薩鋼礦坑，安置炸藥，從底下撼動城塞的根基。礦坑還沒炸開，一個聲音便開始從薩鋼的黑暗中低語。不論他是誰，他知道一個名字，並希望有人說出口。他希望你在塵埃落定後回來，到第一軍團前線營地聽他說完剩下的故事。"
L["The clans gathered once more, and old ways found new meaning. Through trials of land, clan, and ancestors, you helped the orcs reclaim identity not as they were, but as they choose to be now."] = "各氏族再度齊聚一堂，古老的傳統有了新的意義。透過土地、氏族與先祖的試煉，你幫助獸人找回自我——不是過去的模樣，而是他們如今選擇成為的樣子。"
L["The Clarion Call"] = "號角響起"
L["The Clessington Will"] = "克雷辛頓的意志"
L["The Codex of Command"] = "命令寶典"
L["The Coming Storm"] = "風暴前夕"
L["The Conclave was united — Light and Shadow standing together for the first time. The final test came on Niskara, a Legion prison world where priests and paladins alike were held captive. With Aponi Brightmane and Lord Maxwell Tyrosus lending their strength, you crossed Legion lines and broke the chains. United as one, the Conclave shattered the demon garrison. Alonsus Faol himself pledged as your champion, and Moira Thaurissan forged your weapon anew. You were named High Priest of Netherlight — a title that carried the weight of every faith you had united."] = "議會終於團結一致——聖光與暗影首度並肩而立。最後的考驗在尼斯卡拉，那是燃燒軍團監獄世界，牧師與聖騎士都被囚禁在此。在阿波尼‧亮鬃與麥斯威爾‧泰羅索斯領主的助力下，你越過燃燒軍團的防線，斬斷了枷鎖。議會團結一心，粉碎了惡魔的駐軍。阿隆索斯‧法奧親自宣誓成為你的勇士，茉艾拉‧索瑞森則為你重鑄武器。你被冠上虛空之光大祭司的稱號——這個頭銜承載著你所團結的每一種信仰的重量。"
L["The Cost of War"] = "戰爭的代價"
L["The Council convened to address Archmage Vargoth's disappearance. Khadgar led you to Vargoth's retreat, where the signs of struggle told a grim story. Following in his footsteps, you traced magical residue across the Broken Isles. Kalec's investigation revealed the truth was worse than anyone feared — Vargoth hadn't simply vanished. Something had taken him, and that something was connected to the dreadlord Kathra'natir."] = "議會召開會議，商討大法師瓦戈斯失蹤一事。卡德加帶你前往瓦戈斯居所，那裡的打鬥痕跡訴說著不祥的經過。你跟隨他的腳步，追蹤遍布破碎群島的魔法殘跡。卡雷克的調查揭露了比任何人所擔憂的都還糟的真相——瓦戈斯並非單純失蹤，而是被某種東西擄走了，而那東西與驚懼領主卡斯拉納提爾有關。"
L["The Council is in Session"] = "議會進行中"
L["The Council needed more power — souls to fuel the Dreadscar Rift's defenses. You retrieved an unclaimed soul from Black Rook Hold, built a soul beacon to gather energy, and recruited Ernest Carlisle — a mad alchemist who turned goat herding into an art form. Shinfel Blightsworn and Kira Iresoul earned their champion marks, and the Council debated who among them was truly worthy of the power they wielded. The Vault of the Wardens provided the answer: power belonged to those who could take it and hold it."] = "議會需要更多力量——需要靈魂來驅動懼痕裂隙的防禦。你從玄鴉堡取回一個無主的靈魂，建造靈魂信標以匯聚能量，並招募了恩尼斯特‧卡萊爾——一個把放牧山羊變成一門藝術的瘋狂鍊金術師。馨菲‧疫誓與琪拉‧怒魂贏得了勇士的地位，議會則爭論著他們之中誰才真正配得上手中的力量。看守者鐵獄給出了答案：力量屬於那些能奪取並守住它的人。"
L["The Council's sixth seat remained contested — and the answer lay with Lulubelle Fizzlebang, a gnome warlock with more ambition than common sense. You found her in Stormheim, coerced a confession from a captured demon, and cleaned up someone else's mess along the way. Lulubelle proved her worth through sheer stubborn brilliance, and the Summoning of the Sisters sealed the pact. With all six members chosen and your weapon forged to its full dark potential, the Council of the Black Harvest was complete. You were named Netherlord."] = "議會的第六個席位仍有爭議——而答案就在露露貝兒‧菲斯巴恩身上，這名地精術士的野心遠大於常識。你在斯鐸海姆找到她，逼一名被俘的惡魔招供，順便替別人收拾了爛攤子。露露貝兒憑著固執到底的過人才華證明了自己的價值，「召喚姊妹」儀式則讓契約正式成立。六名成員全數到齊，你的武器也完全發揮出黑暗的潛能，黑暗收割議會至此成形。你被冠上虛空領主的稱號。"
L["The Crimsonwood was the Drust king's domain — a forest so thick with dark magic that the trees themselves attacked. You saved Master Ashton from the thorns, gathered what you needed from the cursed woods, and went deeper. Inquisitor Cleardawn never flinched as you faced the matrons of the Crimsonwood one by one. At the heart of it all stood Gorak Tul's hall, where the grand rite would have brought the Drust back in full force. You stopped it — barely — and stuck the embers into the heart of his power. Gorak Tul retreated, wounded but not destroyed. Lucille was waiting."] = "緋紅林地是德魯斯之王的領域——這片森林充斥著濃厚的黑暗魔法，連樹木都會主動攻擊。你從荊棘中救出艾希頓大師，在受詛咒的林地裡收集所需之物，然後繼續深入。當你一一面對緋紅林地的女巫主母時，審判官科利爾東始終毫無懼色。這一切的核心是勾拉圖爾的殿堂，那場盛大的儀式原本會讓德魯斯人全面捲土重來。你阻止了它——千鈞一髮——並將餘燼打入他力量的核心。勾拉圖爾負傷撤退，但並未被消滅。露西爾正在等著你。"
L["The Crusaders' Pinnacle"] = "十字軍之巔"
L["The Crux of the Plan"] = "計畫中的關鍵"
L["The Crypt Keeper"] = "墓地管理者"
L["The Culling of Stratholme"] = "斯坦索姆的抉擇"
L["The Curse of Fletcher's Hollow"] = "造箭師谷地的詛咒"
L["The Dark Heart of Nazmir"] = "納茲米爾的黑暗之心"
L["The Dark Iron legacy is forged, not inherited. By proving your worth in brawls, smithing, and service, you helped secure the clan's heritage for a new era."] = "黑鐵的傳承是鍛造出來的，而非繼承而來。你在鬥毆、鍛造與效力中證明了自己的價值，為氏族在新時代守住了傳承。"
L["The Dark Lady Calls"] = "黑暗女王的呼喚"
L["The Darkness Within"] = "內心的黑暗"
L["The Darkspear were pulled toward old fears and dark power, but chose another path. By restoring their ties to Kevo ya Siti, Lukou, and Jani, you helped your people remember who they are and what they stand for."] = "暗矛一度受到古老恐懼與黑暗力量的牽引，最終卻選擇了另一條道路。你修復了他們與凱弗亞西帝、盧考和賈尼之間的連結，幫助你的族人記起自己是誰，以及自己堅守的信念。"
L["The Dawning Light"] = "黎明之光"
L["The Day Hope Died"] = "絕望之日"
L["The Dead and the Damned"] = "亡者與遭譴者"
L["The Deathlord's Campaign"] = "死亡領主戰役"
L["The Defense of Tian Monastery"] = "防衛天僧寺"
L["The Delicate Art of Telemancy"] = "傳送師的精湛技藝"
L["The Demi-God's Return"] = "半神的回歸"
L["The Desolate Council"] = "荒寂議會"
L["The Double Hozen Dare"] = "猴人大挑戰"
L["The draenei's strength comes from memory, faith, and resilience. By sharing burdens old and new, you helped your people move forward without forgetting what they endured."] = "德萊尼的力量來自記憶、信仰與堅韌。你分擔了新舊重擔，幫助族人向前邁進，同時不忘他們所承受的一切。"
L["The Dragonblight Campaign"] = "龍骨荒野戰役"
L["The Dreadblades"] = "驚懼雙刀"
L["The dreadlord has been hiding among your allies all along. The hunt ends on the Broken Shore in a final confrontation."] = "驚懼領主一直潛伏在你的盟友之中。這場獵殺將在破碎海岸的最終對決中畫下句點。"
L["The dreadlord Kathra'natir had been one step ahead all along — and his final move was possessing Meryl Felstorm himself. With the Tirisgarde's founder corrupted from within, Khadgar rallied every resource: a magical affliction cured in the Eye of Azshara, the might of the Tirisgarde focused into a single strike. You stormed the Oculus and faced Kathra'natir in Meryl's body, tearing the demon free without destroying the mage. Meryl stood free, Vargoth was rescued, and your weapon was reforged. The Kirin Tor bestowed upon you the title of Archmage."] = "驚懼領主卡斯拉納提爾始終搶先一步——他的最後一招，竟是附身於莫爾‧魔風本人。提里斯法守護者的創始人遭到由內而外的腐化，卡德加動員了所有資源：在艾薩拉之眼治癒魔法病痛，並將提里斯法守護者的力量凝聚成致命一擊。你攻入奧核之眼，與附身在莫爾體內的卡斯拉納提爾對峙，在不傷及法師的情況下將惡魔硬生生扯出。莫爾重獲自由，瓦戈斯獲救，你的武器也得以重鑄。祈倫托授予你大法師的稱號。"
L["The Dreadlord's Prize"] = "驚懼領主的目標"
L["The Dreamgrove"] = "幻夢之林"
L["The Dreamgrove / Broken Isles"] = "幻夢之林 / 破碎群島"
L["The Dreamgrove needed defenders. Rensar Greathoof tasked you with growing the order's power — recruiting champions to stand at your side and training troops drawn from every corner of Azeroth's wilds. Skylord Omnuron opened new paths through the Dreamway, connecting the Dreamgrove to the wider world. With each branch that grew, the sanctuary's roots dug deeper."] = "幻夢之林需要守護者。蘭薩‧巨蹄交付你壯大教團力量的任務——招募與你並肩作戰的勇士，並訓練來自艾澤拉斯荒野各個角落的部隊。傲天者歐姆奴隆在翡翠夢途中開闢了新的通道，將幻夢之林與更廣闊的世界相連。每長出一根新枝，這座聖地的根便扎得更深。"
L["The Dreamway"] = "翡翠夢途"
L["The Duke"] = "公爵"
L["The Ebon Watcher"] = "黯黑看守者"
L["The Elder's Instruments"] = "長者的指示"
L["The Elements Call..."] = "元素在呼喚…"
L["The Emerald Nightmare"] = "翡翠夢魘"
L["The Emerald Nightmare spreads unchecked. Naralex leads you into the corrupted wilds to find the Idol of the Wilds before the Nightmare claims it."] = "翡翠夢魘肆意蔓延。納拉雷克斯帶你深入遭到腐化的荒野，必須搶在夢魘之前找到荒野塑像。"
L["The Emperor's Gift"] = "皇帝的禮物"
L["The Empyrean Society"] = "天穹學會"
L["The Enemy of My Enemy..."] = "吾敵之敵…"
L["The Eve of Battle"] = "戰鬥前夕"
L["The Eye of Odyn"] = "歐丁之眼"
L["The faction war reaches the Serpent's Heart, shatters the seal, and releases the Sha of Doubt."] = "陣營戰爭蔓延至蟠龍之心，打破了封印，釋放出疑惑之煞。"
L["The Fall of Ga'trul"] = "加楚爾的末日"
L["The Fall of the Sunwell"] = "太陽之井的淪陷"
L["The Fall of Zuldazar"] = "祖達薩的覆滅"
L["The Fangs of Ashamane"] = "亞夏曼之牙"
L["The Fangs of Ashamane — twin daggers blessed by the wild god of the hunt — had been lost in the wilds of Val'sharah. You tracked them through ancient feral grounds, facing guardians left by Ashamane herself. When you grasped the Fangs, the spirit of the great cat surged through you, and the wilds themselves seemed to sharpen around your senses."] = "亞夏曼之牙——一對受狩獵荒神祝福的雙匕首——遺失在維爾薩拉的荒野之中。你穿越古老的野性之地追蹤它們的下落，面對亞夏曼親自留下的守護者。當你握住這對利牙時，巨貓之靈在你體內奔騰，周遭的荒野彷彿也在你的感官中變得更加清晰鮮明。"
L["The Farseer's Campaign"] = "先知戰役"
L["The Fate of Bloodbane"] = "血禍的命運"
L["The Fate of Hodir"] = "霍迪爾的命運"
L["The Fate of Kanrethad"] = "坎瑞薩德的命運"
L["The Fate of Saurfang"] = "紹爾方的命運"
L["The Fate of Sylvanas"] = "希瓦娜斯的命運"
L["The Fearstalker"] = "懼獵者"
L["The Fel Hammer / Broken Isles"] = "魔錘號 / 破碎群島"
L["The Fel Hammer needed to become more than a ship — it needed to become an army. Battlelord Gaardoun helped recruit champions while Kor'vas organized the broken warriors scattered across the Broken Isles. You proved your immortal soul was strong enough to lead, and the Illidari acknowledged you as their commander. The demon hunters were no longer scattered outcasts — they were a blade pointed at the Legion's heart."] = "魔錘號不能只是一艘船——它必須成為一支軍隊。戰鬥領主蓋爾道恩協助招募勇士，珂娃絲則負責整編散落在破碎群島各處的殘兵。你證明了自己不朽的靈魂足以擔當領袖，伊利達瑞也承認你是他們的指揮官。惡魔獵人不再是四散的流亡者——他們是一把直指燃燒軍團心臟的利刃。"
L["The Felsoul Experiments"] = "魔魂堡實驗"
L["The final assault on Grand Ma'da Ateena. The Horde, the loa, and a death god march together into the Blood Gate. G'huun waits beneath."] = "對大族長艾提娜發動最終攻擊。部落、羅亞與一位死亡之神並肩挺進血門。古翰正在下方等待。"
L["The Final Blow!"] = "最後一擊!"
L["The final breach. You entered the Nighthold itself, fighting through the last of Elisande's loyalists to reach the seat of her power. When the Grand Magistrix fell and the Nightwell's corrupting influence was severed, Thalyssra stepped forward to lead her people into a new era. The nightfallen were nightborne once more — free to choose their own fate."] = "最後的突破。你攻入暗夜堡，殺出一條血路，擊潰艾莉珊德最後的死忠部下，直抵她的權力中樞。大魔導師倒下，暗夜井的腐化影響被切斷，薩莉瑟拉挺身而出，帶領她的人民邁向新紀元。夜落精靈再度成為夜裔精靈——終於能自由選擇自己的命運。"
L["The final campaign began with demonic runes appearing across the Broken Isles — the Legion was closing in. You deciphered their meaning in Black Rook Hold, captured a Legion gateway, and stormed Niskara to rescue Hodir, imprisoned by demons since the war began. With every titan keeper free and every rune decoded, Odyn forged your weapon anew and declared you Battlelord of the Valarjar — a title not bestowed in ten thousand years."] = "最後的戰役始於破碎群島各地浮現的惡魔符文——燃燒軍團正步步逼近。你在玄鴉堡解讀出符文的含義，奪下一座燃燒軍團的傳送門，並攻入尼斯卡拉，救出自戰爭爆發以來便遭惡魔囚禁的霍迪爾。所有泰坦守衛者皆已獲釋、每一道符文都已破解，歐丁為你重鑄武器，並宣布你為華爾拉亞的戰鬥領主——這是萬年來未曾授予任何人的頭銜。"
L["The Final Effigy"] = "最後的咒像"
L["The final Horseman must be raised from the most sacred ground in Azeroth. Darion Mograine makes the ultimate sacrifice."] = "最後一位騎士必須從艾澤拉斯最神聖的土地上復生。達利安‧莫格萊尼做出了最終的犧牲。"
L["The final hunt led to the Broken Shore, where a dreadlord had been hiding among your allies in plain sight. With Lilian Voss at your side, you set the trap — false orders, planted evidence, and a trail that led the demon straight into your blade. The Uncrowned had done what armies could not: killed a devil wearing a friend's face."] = "最後的獵殺將你引至破碎海岸，一名驚懼領主一直光明正大地藏身在你的盟友之中。在莉莉安‧佛斯的協助下，你設下了陷阱——假命令、栽贓的證據，以及一條把惡魔直接引向你刀鋒的線索。無冕者完成了軍隊辦不到的事：殺死一個頂著朋友面孔的惡魔。"
L["The Final Shadow"] = "最後一位潛影"
L["The final test. Decipher demonic runes, rescue Hodir from a Legion prison world, and prove yourself worthy of the Battlelord title."] = "最終的考驗。破解惡魔符文，從燃燒軍團監獄世界救出霍迪爾，證明你配得上戰鬥領主的頭銜。"
L["The Firelord's Command"] = "火焰領主的命令"
L["The Firelord's Offense"] = "火焰領主的攻勢"
L["The First Assault"] = "第一波攻勢"
L["The First to Fall"] = "首批烈士"
L["The First Watch"] = "第一個據點"
L["The Firstborn Rises"] = "大將再起"
L["The Fist of Ra-den"] = "拉頓之拳"
L["The Flesh Giant Champion"] = "血肉巨人鬥士"
L["The Flight of the Banshee"] = "女妖的飛行"
L["The Fog of War"] = "戰爭迷霧"
L["The Forest Ward revealed Revendreth at its most predatory. The Fearstalker and his hounds called it penance: let condemned souls glimpse escape, then chase them until pride broke under terror. You learned the ritual, stalked the quarry, and watched the Accuser's doubts harden into rebellion. The hunt was supposed to humble sinners, but it had become sport for nobles who fed on fear. By the time you reached Dredhollow and broke the Hopebreakers, the shape of the war was clear. This was not order against chaos. It was cruelty against the last pieces of Revendreth still trying to remember mercy."] = "森林守區讓你見識到瑞文崔斯最為兇殘的一面。懼獵者與他的獵犬稱之為贖罪：讓受譴的靈魂瞥見逃脫的希望，再一路追捕，直到他們的傲慢在恐懼下崩潰。你學會了這項儀式，追獵獵物，並眼看著指控者的疑慮逐漸化為反叛的決心。這場獵殺原本是為了讓罪人謙卑，如今卻淪為以恐懼為食的貴族的消遣。當你抵達掘息坑、擊垮破望者時，這場戰爭的本質已經十分清楚。這不是秩序與混亂之爭，而是殘酷與瑞文崔斯最後一絲仍試圖記起憐憫的良知之間的對抗。"
L["The Forlorn Soul"] = "棄魂"
L["The Forsaken are marching on Silverpine Forest. Warchief Garrosh Hellscream has heard what Sylvanas is doing to grow their numbers — and he is not pleased."] = "被遺忘者正向銀松森林進軍。大酋長卡爾洛斯‧地獄吼聽說了希瓦娜斯為了擴充兵力所做的事——而他非常不滿。"
L["The Forsaken Blight"] = "被遺忘者荒疫"
L["The Forsaken Blight and You: How Not to Die"] = "被遺忘者荒疫與你:如何不死"
L["The Forsaken Daughter"] = "被遺忘者之女"
L["The Forsaken High Command was busy when Garrosh Hellscream showed up with a grievance. He'd heard what Sylvanas was doing — using the Val'kyr to raise human dead as new Forsaken, growing her forces beyond what the Horde had sanctioned. He told her to stop. She asked him, face to face, what the difference was between her and the Lich King. He didn't have a good answer. The campaign continued."] = "卡爾洛斯‧地獄吼帶著滿腹怨氣現身時，被遺忘者高階指揮所正忙得不可開交。他聽說了希瓦娜斯的所作所為——利用華爾琪將人類的死者復生為新的被遺忘者，讓她的兵力擴張到超出部落允許的程度。他要她住手。她當面反問他，她和巫妖王究竟有什麼不同。他答不出個所以然。戰事仍在繼續。"
L["The Forsaken moved on. Lordaeron was theirs again, and the long war had its accounting. But some loyalties don't dissolve with a verdict. Dori'thur arrived in the ruins of Lordaeron bearing a message — not from a queen, not a command, just acknowledgment. The hunt Sylvanas began in death has no end date. The souls in the Maw number in the countless. She is still there, freeing them one by one. The message asked nothing. It only said: she remembers who stood with her."] = "被遺忘者繼續向前走。羅德隆再度歸他們所有，漫長的戰爭也已有了清算。但有些忠誠不會因一紙判決而消散。多利蘇爾帶著一則訊息來到羅德隆的廢墟——不是來自女王的訊息，也不是命令，只是一份致意。希瓦娜斯在死後展開的獵殺沒有終點。噬淵中的靈魂多得數不清，而她仍在那裡，一個接一個地解放他們。這則訊息什麼也沒要求，只說了一句：她記得誰曾與她並肩而立。"
L["The Forsaken Plague"] = "被遺忘者瘟疫"
L["The Forsaken push into the farmlands of Tirisfal, where the Scarlet Crusade holds a fortified palisade. Someone from Deathknell has gone missing."] = "被遺忘者深入提里斯法的農田，血色十字軍在那裡據守一座防禦工事完備的柵欄營地。喪鐘鎮有人失蹤了。"
L["The Four Tomes"] = "四部巨著"
L["The Fourth Horseman"] = "第四位騎士"
L["The Frozen Halls"] = "冰封大廳"
L["The Frozen Throne"] = "冰封王座"
L["The Fruit of Our Efforts"] = "努力的果實"
L["The Gilneas Liberation Front"] = "吉爾尼斯解放戰線"
L["The Gjallarhorn"] = "加拉爾號角"
L["The Gjallarhorn — the horn that calls the worthy to battle — has been stolen. Hunt down the thieves across Stormheim and reclaim it."] = "加拉爾號角——召喚英勇之士投身戰鬥的號角——遭竊了。在斯鐸海姆各地追捕竊賊，將它奪回。"
L["The Gnome Behind the Trogg"] = "穴居捕蟬，地精在後"
L["The Gondolier"] = "船夫"
L["The Grandmaster's Campaign"] = "宗師戰役"
L["The graveyards of Drustvar hold fallen Kul Tiran war heroes — soldiers too valuable to leave buried. Nathanos leads the expedition to unearth Marshal M. Valentine, while Lilian questions what separates the Horde's methods from the horrors she once suffered at the hands of the Scarlet Crusade."] = "佐司瓦的墓地裡埋葬著陣亡的庫爾提拉斯戰爭英雄——這些士兵太有價值，不能就這樣長眠地下。納薩諾斯率領遠征隊挖出M‧范倫汀元帥，莉莉安則質疑部落的手段，和她當年在血色十字軍手中所受的折磨究竟有何不同。"
L["The Great Akazamzarak"] = "魔術大師阿卡贊札拉克"
L["The Great Banquet"] = "大開筵席"
L["The Great Escape"] = "大逃亡"
L["The Great Stonemother"] = "偉大的石母"
L["The Greatest Duelist"] = "最厲害的鬥劍士"
L["The Grove of Terror"] = "恐懼林地"
L["The Guardians of Corp'rethar"] = "寇普雷薩的守衛者"
L["The Hand of Keletress"] = "凱萊翠絲的魔掌"
L["The Heart of the Dreadscar"] = "懼痕之心"
L["The Hidden City"] = "隱秘之城"
L["The Hidden Need"] = "隱藏的需求"
L["The High Elder"] = "高階長者"
L["The High Overlord"] = "霸王"
L["The High Priest's Campaign"] = "高階牧師戰役"
L["The Highlord's Campaign"] = "大領主戰役"
L["The Hooded Crusader's campaign reached the Scarlet Monastery itself. You retrieved the blessed blades of the Anointed — weapons consecrated to destroy the undead — and drove them into High Inquisitor Whitemane. The irony was not lost on Lilian: the Crusade's holiest weapons, wielded by the dead, against the Crusade's own champion."] = "戴頭罩的十字軍的行動一路推進到血色修道院。你取回受膏者的祝福之刃——這些武器經過聖化，專為消滅不死族而打造——並將它們刺入高階審判官懷特邁恩體內。莉莉安深知其中的諷刺：十字軍最神聖的武器，竟由死者揮舞，用來對付十字軍自己的勇士。"
L["The Hooded Crusader's campaign reaches the Scarlet Monastery. Two blessed blades rest within its halls — consecrated weapons anointed to destroy the undead. High Inquisitor Whitemane commands everything inside."] = "戴頭罩的十字軍的行動推進至血色修道院。兩把受祝福的刀刃就安放在修道院的大廳中——這些聖化過的武器受過膏禮，專為消滅不死族而生。修道院內的一切都由高階審判官懷特邁恩掌控。"
L["The Horde has split in two. Saurfang rallies those who oppose Sylvanas, while loyalists prepare to crush the rebellion."] = "部落分裂成兩派。紹爾方號召反對希瓦娜斯的人，效忠者則準備鎮壓叛亂。"
L["The Horde marched into Ashenvale with speed and purpose. You pushed through Night Elf defenses, secured the roads, and drove toward the coast beneath Teldrassil. The Night Elves fought well but the Horde had the numbers and Sylvanas had a plan. The World Tree loomed at the end of it — massive, ancient, and full of civilians who had not escaped in time. Sylvanas stood at its base with the battle won and the tree in reach. A Night Elf prisoner asked what the people inside had done to deserve this. Sylvanas spoke about hope being the enemy. Then she gave the order. Teldrassil burned. The smoke was visible from Stormwind. Whatever Sylvanas had been building toward, this was no longer a war anyone could call limited."] = "部落迅速而果決地進軍梣谷。你突破夜精靈的防線，控制了道路，一路向泰達希爾下方的海岸挺進。夜精靈奮勇抵抗，但部落兵力占優，希瓦娜斯更是早有盤算。這一切的終點，是巍然聳立的世界之樹——巨大、古老，樹上滿是來不及逃離的平民。希瓦娜斯站在樹下，戰鬥已勝，世界之樹近在咫尺。一名夜精靈俘虜問她，樹上的人們究竟做了什麼，要落得如此下場。希瓦娜斯說，希望才是敵人。接著，她下達了命令。泰達希爾陷入火海，連暴風城都看得見那道濃煙。不論希瓦娜斯一直以來在謀劃什麼，這都已不再是任何人能稱為有限的戰爭。"
L["The Horde needs a tidesage's power over the sea. Lilian and Rexxar track one down in Stormsong Valley — Thomas Zelling, a dying man willing to trade his humanity for a few more years with his family. When the ritual is done, Lilian must watch Zelling's wife recoil from the husband she no longer recognizes. The scene is painfully familiar."] = "部落需要潮汐賢者操控大海的力量。莉莉安與雷克薩在斯陀頌恩谷地找到了一位——湯瑪斯‧澤靈，一個垂死之人，願意用他的人性換取與家人多相處幾年的時間。儀式完成後，莉莉安只能看著澤靈的妻子驚恐地避開這個她再也認不出的丈夫。這一幕熟悉得令人心痛。"
L["The Horde's banner flies over Agmar's Hammer, driven into the permafrost like a spear into a cold chest. Emissary Brighthoof calls for warriors willing to bind themselves to the Warchief's campaign. Overlord Agmar tolerates no softness — the Scourge presses on every side, and a red-eyed gate on the horizon waits to be broken."] = "部落的旗幟在阿格瑪之錘上空飄揚，旗桿深深插入永凍土中，宛如一支長矛刺進冰冷的胸膛。特使亮蹄號召願意投身大酋長戰役的戰士。霸主阿格瑪容不得半點軟弱——天譴軍從四面八方進逼，地平線上一座閃著紅眼的大門正等待被攻破。"
L["The Horde's hozen alliance becomes a proper forward campaign from Grookin Hill."] = "部落與猴人的同盟，在葛魯山丘正式發展成一場前線戰役。"
L["The Horde's war at sea claims a significant prize: Derek Proudmoore, son of the Lord Admiral, goes down with his ship in the waters off Kul Tiras. Hobart Grapplehammer equips you with experimental diving gear as Dread-Admiral Tattersail leads the expedition into the deep. What Sylvanas intends to do with the body is not yet spoken aloud — but the silence on the ship ride home says enough."] = "部落的海上戰爭換來一份重大戰利品：海軍上將之子德瑞克‧普勞德摩爾隨著他的船沉入庫爾提拉斯外海。荷巴爾特‧繫錘為你配備實驗性的潛水裝備，恐衛上將黛特賽爾則率領遠征隊潛入深海。希瓦娜斯打算如何處置這具遺體，目前還沒有人說出口——但返航途中船上的沉默已說明了一切。"
L["The Hunt"] = "獵殺"
L["The Hunter and the Prince"] = "王子與獵手"
L["The Hunter of Heroes"] = "英雄狩獵者"
L["The Hunter's Call"] = "獵人的呼喚"
L["The Hunter's Gaze"] = "獵人的凝視"
L["The Huntmaster's Campaign"] = "狩獵大師戰役"
L["The Idol of the Wilds breathed new life into the Dreamgrove. Archdruid Hamuul Runetotem and the irrepressible Mylune pledged themselves as champions, along with the spirited Brightwing. Together you focused the Dreamgrove's energies into its portal, strengthening the connection between the waking world and the Dream. The Cenarion Circle stood united — and the Nightmare would feel its wrath."] = "荒野塑像為幻夢之林注入了新的生機。大德魯伊哈繆爾‧符文圖騰與活力十足的蜜露恩宣誓成為你的勇士，精神抖擻的亮翼也一同加入。你們齊心將幻夢之林的能量匯聚到傳送門中，強化現實世界與夢境之間的連結。塞納里奧議會團結一致——夢魘將嘗到它的怒火。"
L["The Imposter"] = "假冒者"
L["The Invasion of Niskara"] = "入侵尼斯卡拉"
L["The Iron Fist"] = "鐵拳"
L["The Jade Forest"] = "翠玉林"
L["The Jade Serpent"] = "玉蛟"
L["The Jade Witch"] = "玉巫婆"
L["The Jailer was dead. Sylvanas was whole again — every fragment of her soul restored from where she had given it away. She stood in silence with the full weight of what she had done pressing down on her at last. Then she walked. Down the long road through Oribos, past the faces of the people she had condemned, she came before Tyrande Whisperwind — who had more right to judge her than anyone alive or dead. Tyrande spoke her sentence. Sylvanas accepted it without a word of protest. She would spend eternity freeing the souls she had imprisoned in the Maw, sending them through the veil one by one. Not as punishment. As penance, freely chosen."] = "閻獄之主死了。希瓦娜斯再度完整——她曾經交出去的每一片靈魂碎片都已歸位。她靜靜佇立，終於承受起自己所作所為的全部重量。接著，她邁步前行。她沿著漫長的道路穿過奧睿博司，走過那些曾被她定罪之人的面孔，來到泰蘭妲‧語風面前——無論生者或死者，沒有人比泰蘭妲更有資格審判她。泰蘭妲宣布了判決。希瓦娜斯沒有一句抗辯，默默接受。她將用永恆的時光，解放那些被她囚禁在噬淵中的靈魂，一個接一個地送他們穿越帷幕。這不是懲罰，而是她自願選擇的贖罪。"
L["The Jailer's Defeat"] = "閻獄之主的敗北"
L["The kaldorei endured calamity without abandoning duty. By hunting corruption in Felwood and standing beside the Wardens, you helped preserve the legacy of Elune's people."] = "卡多雷歷經浩劫，卻從未背棄職責。你在費伍德森林獵殺腐化之物，並與守望者並肩作戰，協助守護了伊露恩子民的傳承。"
L["The Keeper's Favor"] = "守護者的援助"
L["The Keys to Success in Freehold"] = "自由港的成功之鑰"
L["The King Rises"] = "國王復甦"
L["The King's Command"] = "國王的命令"
L["The Kingslayers"] = "弒君之刃"
L["The Kor'kron at Wyrmrest"] = "龍眠神殿的柯爾克隆"
L["The Kor'kron Vanguard!"] = "柯爾克隆先鋒駐地!"
L["The Kosh'harg"] = "克許哈格"
L["The Kul Tiran fleet — decades of Proudmoore naval heritage — is scattered and locked behind four keys held by enemies who have taken root across the nation: pirates in Freehold, corrupt wardens in Tol Dagor, drowned tidesages in the Shrine of the Storm, and Drust witches in Waycrest Manor. The keys must be taken by force. At the end, Priscilla Ashvane makes one final move — and Jaina faces her mother in a square in Boralus, in front of the entire fleet, for the first time since Theramore fell."] = "庫爾提拉斯艦隊承載著普勞德摩爾家族數十年的海軍傳統，如今卻四散各地，被四把鑰匙鎖住，而這些鑰匙落入盤據全國各地的敵人手中：自由港的海盜、托達戈爾的腐敗獄卒、風暴聖壇的溺水潮汐賢者，以及威奎斯特莊園的德魯斯女巫。鑰匙只能以武力奪取。最後，普莉希拉‧艾胥凡使出最後一招——而自塞拉摩陷落以來，珍娜首度在波拉勒斯的一座廣場上、當著整支艦隊的面，與她的母親對峙。"
L["The Last Line Of Defense"] = "最後防線"
L["The Last Witch Doctor of Krag'wa"] = "最後的奎格瓦巫醫"
L["The Leaper"] = "跳躍者"
L["The Legion has established a foothold in Azsuna. Lead the Silver Hand to Faronaar and recruit new champions in battle."] = "燃燒軍團已在艾蘇納建立據點。率領白銀之手前往法隆納，在戰鬥中招募新的勇士。"
L["The Legion has landed on the Broken Shore. The Horde answers the call — but this battle will cost far more than anyone expected."] = "燃燒軍團已登陸破碎海岸。部落響應號召——但這場戰役的代價將遠超任何人的預期。"
L["The Legion launches a direct assault on Dalaran through the Violet Hold. Rally the Unseen Path's champions for the final defense."] = "燃燒軍團經由紫羅蘭堡直接進攻達拉然。集結隱匿之徑的勇士，展開最後的防衛戰。"
L["The Legion's grip on Faronaar in Azsuna was tightening. Lord Grayson Shadowbreaker dispatched you to break it. With Vindicator Boros at your side, you cut through demon ranks and destroyed their communication orbs. Justicar Julia Celeste fought with a fury that earned her a place among your champions. The Codex of Command — a Legion tactical manual — was recovered from the battlefield, but its contents were locked behind demonic encryption."] = "燃燒軍團對艾蘇納法隆納的控制日益加緊。格雷森·沙東布瑞克公爵派你前去打破這道封鎖。你在復仇者波羅斯的陪同下殺穿惡魔大軍，摧毀了牠們的通訊寶珠。審判者茱利亞‧莎莉絲蒂奮勇作戰，憑著那股怒火在你的勇士之列中贏得一席之地。你從戰場上尋回命令寶典——一本燃燒軍團的戰術手冊——但其中的內容被惡魔的密碼封鎖著。"
L["The Librarian's Quandary"] = "圖書管理員的困惑"
L["The Lich King commands you to raise the Four Horsemen anew. The first to rise is Nazgrim, the fallen Horde general."] = "巫妖王命令你重新喚起四騎士。第一位復生的是陣亡的部落將軍納茲格寧姆。"
L["The Lich King reveals the location of Apocalypse, a runesword that brings death to everything it touches."] = "巫妖王揭露了天啟的所在——這把符文劍所觸及的一切都將迎來死亡。"
L["The Lich King's reign ends at the Frozen Throne. For Sylvanas, the aftermath is more personal than anyone outside Icecrown will ever know."] = "巫妖王的統治在冰封王座畫下句點。對希瓦娜斯而言，這場戰事的餘波遠比寒冰皇冠以外的任何人所知的更加切身。"
L["The Lich King's voice echoed through Acherus, pointing you toward Apocalypse — a blade of pure death forged in an age of darkness. You followed the trail through Duskwood alongside Revil Kost, hunting the Dark Riders who had stolen the sword. In the depths of Deadwind Pass, you wrested Apocalypse from their skeletal grip. The blade hummed with necrotic power, eager to fulfill the promise of its name."] = "巫妖王的聲音迴盪在亞榭洛之中，指引你找到天啟——一把在黑暗時代鍛造、蘊含純粹死亡之力的劍刃。你與瑞維爾‧寇斯特一同循著線索穿越暮色森林，追捕盜走這把劍的黑暗騎手。在逆風小徑深處，你從他們枯骨般的手中奪回了天啟。劍刃因死靈之力而嗡鳴作響，迫不及待地要實現其名號所預示的末日。"
L["The Light and the Void"] = "光明與虛無"
L["The Light Below"] = "地底之光"
L["The Light's Wrath"] = "聖光之怒"
L["The Lion's Cage"] = "雄獅之籠"
L["The Loa Trials"] = "羅亞試煉"
L["The Long Hunt"] = "漫長的狩獵"
L["The Long Knives"] = "長刀"
L["The Lost Glacier"] = "失落冰川"
L["The Mad Duke"] = "瘋狂公爵"
L["The Maelstrom / Broken Isles"] = "大漩渦 / 破碎群島"
L["The Maelstrom's Air Pillar was failing, and only an elemental lord could restore it. Advisor Sevel tracked the Blessed Blade of the Windseeker — the key to freeing Thunderaan, Prince of Air. You journeyed to Highlord Demitrian, reforged the blade, and climbed to the skies above. There, you recharged the weapon and broke Thunderaan's bonds. The Windlord surged free, his winds howling across the Broken Isles. He swore an oath to the Earthen Ring, and Consular Celestos and Nobundo stood with you as the Air Pillar blazed back to life."] = "大漩渦的風之柱逐漸衰弱，唯有元素領主才能使其恢復。預言者沙費歐追查到逐風者的祝福之刃——這是解放風之王子桑德蘭的關鍵。你前去拜訪大領主德米提恩，重鑄了這把劍刃，並攀上高空。你在那裡為武器重新注能，打破了桑德蘭的枷鎖。風之王衝破束縛，狂風呼嘯著席捲破碎群島。他向陶土議會立下誓言；當風之柱重新煥發光芒時，賽勒斯多領事與諾柏多都站在你的身旁。"
L["The Maelstrom's Air Pillar weakens. Reforge the Blessed Blade of the Windseeker and return Thunderaan to power."] = "大漩渦的風之柱逐漸衰弱。重鑄逐風者的祝福之刃，讓桑德蘭重掌力量。"
L["The March to Nazmir"] = "向納茲米爾進軍"
L["The Marshal's Grave"] = "元帥之墓"
L["The Masks We Wear"] = "面具之下"
L["The Master"] = "主宰"
L["The Master Awaits"] = "謁見主宰"
L["The Master of Lies"] = "謊言之主"
L["The Master of Revendreth"] = "瑞文崔斯的主宰"
L["The Master of Swords"] = "使劍大師"
L["The Master's Plan"] = "教長的計畫"
L["The Mead Master"] = "蜜酒大師"
L["The Mech of Death"] = "死亡機甲"
L["The Might of the Horde"] = "部落的力量"
L["The Might of the Tirisgarde"] = "提里斯護法之力"
L["The Mind of the Enemy"] = "敵人的心靈"
L["The Missing Admiral"] = "失蹤的上將"
L["The Mission"] = "任務"
L["The Monkey King"] = "美猴王"
L["The MOTHERLODE!!"] = "晶喜鎮！"
L["The Murderous Matron"] = "最毒婦人心"
L["The Mysterious Island"] = "神秘島嶼"
L["The Mysterious Paladin"] = "神秘的聖騎士"
