L["The Peak of Serenity falls to the Legion. Rally the surviving monks at the Temple of Five Dawns on the Wandering Isle."] = "寂靜峰被燃燒軍團攻陷。在流浪島的五晨寺集結倖存的武僧。"
L["The Pearlfin Situation"] = "珠鰭困境"
L["The Penitent Hunt"] = "悔罪之狩"
L["The Perfect Opportunity"] = "大好時機"
L["The Pinnacle is won. Its flagstaff flies the white hand of the Argent Crusade above the whole of southern Icecrown. But at the edge of the Fleshwerks below, Crusader Bridenbrad is dying. The plague has him. Father Gustav cannot let a hero end this way. Keeper Remulos, Alexstrasza the Life-Binder, and A'dal — three ancient powers who still remember the Light — each in turn weigh the cost. Whatever answer comes will come in its own time. Meanwhile, gryphon-riders and wyvern-masters circle the Pinnacle, waiting to lift the next wave of soldiers up to the gunships — the Skybreaker and Orgrim's Hammer — hanging over the northern gates."] = "十字軍之巔已經拿下。旗桿上飄揚著銀白十字軍的白手旗幟，俯瞰整個寒冰皇冠南部。但在下方的血肉工廠邊緣，十字軍布理登布萊特已奄奄一息——他染上了瘟疫。賈斯塔夫神父不能讓一位英雄就這樣死去。守衛者雷姆洛斯、『生命守縛者』雅立史卓莎與阿達歐——三位仍銘記聖光的古老存在——輪流權衡其中的代價。無論答案為何，都將在適當的時機到來。與此同時，獅鷲騎士與雙足飛龍馴師在十字軍之巔上空盤旋，準備將下一波士兵送上懸停在北方大門上空的砲艇——破天者號與奧格林之錘。"
L["The Pirate's Bay"] = "海盜灣"
L["The Pit of Saron"] = "薩倫之淵"
L["The Power of Thousands"] = "眾人之力"
L["The Power to Survive"] = "生存之力"
L["The Power Within"] = "隱藏的力量"
L["The Price of Victory"] = "勝利的代價"
L["The Pride of Kul Tiras"] = "庫爾提拉斯之傲"
L["The Pride of the Sin'dorei"] = "辛多雷的驕傲"
L["The Purging Of Scourgeholme"] = "對天譴岸地的淨化"
L["The Raven's Eye"] = "鴉眼"
L["The rebellion emerged from hiding and seized the Waning Crescent district in an act of open defiance. You helped Oculeth triangulate and rescue an imprisoned ally put on public display as a warning, then established the first openly rebel-held territory in Suramar City. The Dusk Lily — the rebellion's symbol — flew for the first time where Elisande's banners once hung."] = "反抗軍從暗處現身，公然起義，占領了弦月區。你協助歐庫雷斯進行三角定位，救出一名被公開示眾、以儆效尤的被囚盟友，接著在蘇拉瑪爾城建立了第一塊由反抗軍公開掌控的領地。反抗軍的象徵——暮色百合——首度飄揚在昔日懸掛艾莉珊德旗幟的地方。"
L["The rebellion grows bolder, establishing a foothold in the Waning Crescent district of Suramar City."] = "反抗軍越發大膽，在蘇拉瑪爾城的弦月區建立了據點。"
L["The Remedy of Lordaeron"] = "羅德隆的解藥"
L["The Restless Dead"] = "死不瞑目"
L["The Return of Twilight"] = "暮光的回歸"
L["The Rider of Blood"] = "血魄騎士"
L["The Rider of Frost"] = "冰霜騎士"
L["The Rider of the Unholy"] = "穢邪騎士"
L["The Rider's Bind"] = "騎兵的約束"
L["The Right Tool For The Job"] = "合適的工具"
L["The Ritual of Tides"] = "海潮儀式"
L["The Road of Pain"] = "苦痛之路"
L["The Road to Corlain"] = "通往寇連恩的路"
L["The Ruined Kingdom"] = "荒廢的王國"
L["The Ruins of Gol Var"] = "戈爾瓦厄廢墟"
L["The Rumpus"] = "格鬥場"
L["The Runesmiths of Malykriss"] = "瑪里庫立斯的符文鐵匠"
L["The Rush'kah"] = "拉許卡"
L["The saronite mines beneath Ymirheim are not just a supply line. They are something older, colder, and hungrier than any ore vein on Azeroth. The metal whispers. Miners chained to the walls hear their names called by voices they once loved. The Argent Crusade has quiet questions about what prolonged exposure does to a living mind. The answers do not make it out of the tunnels."] = "依米海姆底下的薩鋼礦坑不只是一條補給線。它們比艾澤拉斯上任何礦脈都更古老、更寒冷，也更加飢渴。這種金屬會低語。被鎖在礦壁上的礦工，會聽見曾經深愛的人呼喚著他們的名字。銀白十字軍私下想知道，長期接觸會對活人的心智造成什麼影響。但答案從未離開過那些坑道。"
L["The Scarlet Assault"] = "血色突擊"
L["The Scarlet Commander"] = "血色指揮官"
L["The Scarlet Crusade has returned to Silverpine Forest. Lilian Voss needs a champion to go in quietly, earn their trust, and open the way for the Forsaken to strike."] = "血色十字軍重返銀松森林。莉莉安‧佛斯需要一名勇士悄悄潛入，贏得他們的信任，為被遺忘者的攻擊開路。"
L["The Scarlet Halls"] = "血色大廳"
L["The Scarlet Massacre"] = "血色屠殺"
L["The Scarlet Monastery"] = "血色修道院"
L["The Scarlet Onslaught — fanatical remnants of the Crusade — were gathering strength, and Faol saw an opportunity. You infiltrated their ranks disguised as an envoy, walking among zealots who would have burned you alive. Deep inside, you found Mariella — a heretic within their own ranks who had seen through the madness. You liberated her fellow apostates and brought Mariella Ward into the Conclave, her faith tempered by hard truth rather than blind fury."] = "血色突擊軍——十字軍的狂熱殘黨——正在集結力量，而法奧從中看見了機會。你偽裝成使者潛入他們的陣營，行走在那群恨不得將你活活燒死的狂信者之間。在敵陣深處，你找到了瑪莉拉——她是他們之中的異端，早已看穿這場瘋狂。你解救了她的叛教同伴，並帶領瑪莉拉‧瓦德加入議會；她的信仰經由殘酷的真相淬鍊，而非源自盲目的狂怒。"
L["The Scarlet Onslaught has buried itself in the black ice of western Icecrown. The fortress is called the Shadow Vault. High Abbot Landgren commands it now. The Ebon Blade's plan is ugly — wear the Scarlet's own colors, pray nobody looks twice, and open every door from the inside. When the Vault falls, Baron Sliver holds court in its upper halls. Vereth the Cunning sketches the roads out in blood. The Lich King's saronite quarries are pried open. Above the Vault, the flying necropolis of Malykriss still hangs, with four riders of the Bloodbane order riding out the apocalypse in miniature: one of the Unholy, one of Frost, one of Blood, and the name that binds them."] = "血色突擊軍深藏在寒冰皇冠西部的黑冰之中。他們的要塞名為暗影穹殿，如今由高階住持蘭德格倫坐鎮。黯刃騎士團的計畫並不光彩——穿上血色十字軍自己的服色，祈禱沒人多看一眼，再從內部打開每一扇門。暗影穹殿陷落後，史力弗男爵在上層大廳主持事務。奸詐的維瑞希用鮮血畫出對外的道路。巫妖王的薩鋼採石場被撬開。暗影穹殿上空，浮空通靈要塞瑪利克里斯依然懸在那裡，血禍騎士團的四名騎士在其中上演一場縮小版的天啟：一名穢邪、一名冰霜、一名血魄，以及將他們串連在一起的那個名字。"
L["The Scarlet Palisade"] = "血色護欄"
L["The Scarlet Spy"] = "血色間諜"
L["The Scent of Magic"] = "魔法氣息"
L["The School of Roguery"] = "盜賊先修班"
L["The Scourgestone"] = "天譴石"
L["The Scouts Return"] = "探子回報"
L["The Scryer's Dilemma"] = "占卜者的困境"
L["The Scythe of Elune"] = "伊露恩之鐮"
L["The Seal is Broken"] = "封印遭毀"
L["The Seal's Power"] = "封印的能量"
L["The Search for Vargoth"] = "尋找瓦戈斯"
L["The search for Zin'jun began as a rescue and became a campaign. The hozen had stripped him of his gear, the Alliance had dug in at Strongarm Airstrip, and Nazgrim needed every advantage he could improvise. You recovered Zin'jun's belongings, assaulted the airstrip, broke key Alliance officers, and learned that Captain Doren had been consumed by the darkness Taran Zhu warned about. Kiryn and Rivett turned Alliance wreckage into intelligence and acid rain, and Nazgrim sent you to read the shape of the land itself. Lay of the Land was the hinge: the war had carried you this far, but Cho was waiting to show you what the Horde had actually stepped into."] = "尋找金浚的行動原本只是救援，後來卻演變成一場戰役。猴人搶走了他的裝備，聯盟在強臂簡易機場固守陣地，而納茲格寧姆需要他所能想到的一切優勢。你找回了金浚的物品，突襲機場，擊潰聯盟的重要軍官，並得知多倫隊長已被塔蘭‧祝警告過的黑暗吞噬。卡玲與理弗特將聯盟的殘骸變成了情報與酸雨，納茲格寧姆則派你去勘察這片土地的地形。「情勢」是關鍵的轉折點：戰爭將你一路帶到這裡，但阿洲已在等著讓你看清部落究竟踏入了什麼樣的局面。"
L["The Seat of the Triumvirate"] = "三傑議會之座"
L["The second Horseman would be Thoras Trollbane, the warrior-king of Stromgarde who had been murdered by his own son. You traveled to the ruined kingdom where Trollbane's restless spirit lingered, betrayed even in death. Prince Galen, the traitor-son, stood in your way — but regicide was a small price for the Ebon Blade. You cut Galen down and raised his father, and Thoras Trollbane rode once more, his fury undimmed by centuries in the grave."] = "第二位騎士將是索拉斯‧托爾貝恩——激流堡的戰士國王，遭親生兒子殺害。你前往那座殘破的王國，托爾貝恩不得安息的靈魂仍在那裡徘徊，即使死後依然遭到背叛。叛逆之子蓋倫王子擋在你的面前——但對黯刃騎士團而言，弒君不過是微不足道的代價。你斬殺了蓋倫，喚起了他的父親，索拉斯‧托爾貝恩再度策馬奔騰；即使在墳墓中沉睡了數個世紀，他的怒火依然不減。"
L["The Seed of Ages"] = "萬古之種"
L["The Serpent's Heart"] = "蟠龍之心"
L["The Serpent's Heart gave the temple the jade it needed, but Yu'lon could not simply appear on command. Elder Sage Rain-Zhu sent you through the temple's doubts and duties: Wise Mari's scrying, Lorewalker Stonestep's living library, Fei's cloud serpents, and the fireworks that would light the sky for a rebirth. At last Yu'lon emerged, ancient and luminous, and thanked you for helping the forest remember hope. For a moment, it felt like the war might be smaller than the wonder around it."] = "蟠龍之心為神殿提供了所需的玉石，但玉瓏並不會一聲令下就現身。大賢者雨竹讓你經歷神殿的種種疑慮與職責：智者瑪利的占卜、博學行者石步的活圖書館、菲的雲端翔龍，以及將在重生時點亮天空的煙火。玉瓏終於現身，古老而光輝燦爛，感謝你幫助這片森林重拾希望。有那麼一刻，戰爭似乎變得比周遭的奇景還要渺小。"
L["The Setting Sun"] = "下沉的太陽"
L["The Shadow of Death"] = "死亡之影"
L["The Shadow of Gilneas"] = "吉爾尼斯的陰影"
L["The Shadow Vault"] = "暗影穹殿"
L["The Shadowblade's Campaign"] = "影尊戰役"
L["The Shadows Reveal"] = "暗影顯現"
L["The Shardmaidens"] = "裂片林精"
L["The Silkwood Road"] = "絲林之路"
L["The Silver Hand"] = "白銀之手"
L["The Silver Hand marshaled for war. You led the assault on Niskara — a demon world where Aponi Brightmane was held captive. Through waves of demons you fought, Aponi's libram serving as a beacon. When you found her, she was wounded but unbroken. Together with Delas Moonfang — who chose to become a paladin that day — you shattered the Legion's forces on Niskara. The mind of the enemy lay open, and the Silver Hand's unity was forged in fire."] = "白銀之手整軍備戰。你率軍進攻尼斯卡拉——一個囚禁著阿波尼‧亮鬃的惡魔世界。你在一波波的惡魔中奮戰前進，阿波尼的聖契如燈塔般為你指引方向。當你找到她時，她雖然負傷，卻依然堅毅不屈。你與德菈絲‧月牙——她在那天選擇成為聖騎士——一同擊潰了燃燒軍團在尼斯卡拉的部隊。敵人的心靈就此敞開，白銀之手的團結也在烈火中淬鍊成形。"
L["The Sin'dorei remember through ritual, grief, and endurance. You carried the Sunwell's flame through Ghostlands and Quel'Danas, stood witness to the fall of legends, and helped preserve the memory that still defines your people."] = "辛多雷透過儀式、哀悼與堅忍銘記過往。你帶著太陽之井的聖火穿越鬼魂之地與奎爾達納斯，見證傳奇的殞落，並協助保存了至今仍定義著你族人的記憶。"
L["The Sinstone"] = "罪孽石"
L["The Sixth"] = "第六位成員"
L["The Skies Above"] = "天外天"
L["The Skybreaker"] = "破天者號"
L["The Skyfire reaches Pandaria hunting for Admiral Taylor and Prince Anduin, but the Alliance lands in the middle of a Horde war zone."] = "天火號抵達潘達利亞，搜尋泰勒上將與安杜因王子的下落，但聯盟卻降落在部落的戰區正中央。"
L["The Slayer's Campaign"] = "斬魔者戰役"
L["The Solution Solution"] = "溶劑就是好計"
L["The Speaker Awaits"] = "發言者在等候"
L["The Spirit of the Hunter"] = "獵人之靈"
L["The Spirit of Thunder Ridge"] = "雷霆山之靈"
L["The spirits called, and you answered. By walking between worlds and standing with Baine and the spiritwalkers, you helped the Shu'halo restore harmony and honor their ancestors."] = "靈魂發出召喚，你挺身回應。你穿梭於兩個世界之間，與貝恩及靈行者並肩而立，幫助修哈洛恢復和諧，並向他們的先祖致敬。"
L["The Spiritwalkers"] = "靈行者"
L["The Splintered Path"] = "殘破之路"
L["The Sprites' Plight"] = "妖精之難"
L["The Stone That Started A Revolution"] = "革命的基石"
L["The Stoneborn"] = "石源魔"
L["The Stormwind Extraction"] = "暴風城撤離"
L["The Strength of the Storm"] = "風暴之力"
L["The Strike on Boralus"] = "突襲波拉勒斯"
L["The Strongarm Airstrip"] = "強臂簡易機場"
L["The Stuff of Dreams"] = "幻夢沃土"
L["The Sum is Greater than the Parts"] = "聚沙成塔"
L["The Sunken Graveyard"] = "海底墓地"
L["The Sunken Vault"] = "沉沒的遺址"
L["The Sword of Kings"] = "王者之劍"
L["The Tale of Ban-Lu"] = "班盧的故事"
L["The Temple of the Jade Serpent"] = "玉蛟寺"
L["The third Horseman would be the most controversial — High Inquisitor Whitemane of the Scarlet Crusade, a zealot who had burned the undead with holy fire for years. You led the assault on the Scarlet Monastery, cutting through fanatical defenders in a massacre that painted the halls red. When Whitemane fell, you raised her — and the woman who had sworn to destroy every death knight opened her eyes as one. The irony was not lost on anyone."] = "第三位騎士最具爭議——血色十字軍的高階審判官懷特邁恩，這名狂信者多年來以神聖之火焚燒不死族。你率軍進攻血色修道院，殺穿狂熱的守軍，這場屠殺將大廳染成一片血紅。懷特邁恩倒下後，你喚起了她——這個曾誓言消滅所有死亡騎士的女人，再度睜開雙眼時，自己也成了死亡騎士。這其中的諷刺，所有人都心知肚明。"
L["The Threads that Stick"] = "黏黏的線"
L["The Three Sisters"] = "女巫三姊妹"
L["The time for subtlety had passed. You helped Oculeth build war machines, gathered supplies with Valtrois, trained civilian volunteers into a fighting force, and armed the rebellion with weapons taken from the Legion itself. When the trial by demonfire proved the rebels could hold their own, there was nothing left to do but march."] = "暗中行事的時候已經過去了。你協助歐庫雷斯打造戰爭機械，與瓦爾托伊絲一同蒐集物資，將平民志願者訓練成一支戰鬥部隊，並用從燃燒軍團手中奪來的武器武裝反抗軍。當惡魔之火的試煉證明反抗軍能夠獨當一面，剩下的就只有進軍了。"
L["The time had come to strike at the Nightmare's heart. Keeper Remulos guided you through a rift into the Dream's darkest depths, where you relived the War of the Ancients — watching Archimonde the Defiler lay waste to the world ten thousand years ago. In that crucible of memory and shadow, you reached Malorne himself. The great white stag stirred, rose, and returned to the waking world. With the demi-god reborn and your weapon forged anew, the Cenarion Circle had become a force even the Legion feared."] = "直搗夢魘核心的時刻到了。守衛者雷姆洛斯引領你穿過一道裂隙，進入夢境最黑暗的深處，你在那裡重溫了上古之戰——親眼目睹污染者阿克蒙德在一萬年前蹂躪世界。在那記憶與陰影交織的熔爐中，你找到了瑪洛尼本尊。這頭巨大的白色雄鹿甦醒、起身，回到了現實世界。半神重生，你的武器也再度重鑄，塞納里奧議會已成為連燃燒軍團都畏懼的力量。"
L["The Tirisgarde needed power, and power came in the form of legends. Archmage Kalec — the blue dragon who once guarded the Sunwell — and Archmage Modera of the Council of Six both pledged their strength. Archmage Omniara trained troops while Archmage Melis provided the technical wizardry to keep the Hall of the Guardian running. The Tirisgarde was no longer a relic of history — it was a force."] = "提里斯法守護者需要力量，而這份力量以傳奇人物的形式降臨。曾守護太陽之井的藍龍大法師卡雷克，以及六人議會的大法師莫德菈，都承諾貢獻自己的力量。大法師歐妮雅拉負責訓練部隊，大法師梅莉絲則提供精湛的技術魔法，維持守護者殿堂的運作。提里斯法守護者不再是歷史的遺物——而是一股不容小覷的力量。"
L["The Tirisgarde Reborn"] = "提里斯護法的重生"
L["The titans built Uldir to study the Old Gods — to understand the corruption before they tried to cure it. What they created instead was G'huun: a proto-god of blood and shadow, born in a lab, every safeguard bypassed. Sealed in stasis for millennia, fed by the blood trolls until he was strong enough to break containment himself. Uldir was not a dungeon. It was a prison that had started to answer back.\n\nYou fought through the facility's corrupted wards — past G'huun's lieutenants, through the experiments that had gone wrong in the age before trolls had language — and reached the heart of the prison. G'huun fell. The blood god's thousand-year campaign to break free ended in the same titan vault it began in. Nazmir would take generations to recover. The trolls who had given their lives feeding G'huun would never be fully redeemed. But the earth was quiet again, and the seal held."] = "泰坦建造奧迪爾，是為了研究上古之神——在嘗試治癒腐化之前，先了解它。然而他們創造出來的卻是古翰：一個由鮮血與暗影構成的原始神祇，誕生於實驗室中，突破了每一道防護措施。他被封印在停滯力場中數千年，靠著血食人妖的餵養，直到強大到足以自行衝破封鎖。奧迪爾不是地城，而是一座開始反撲的監牢。\n\n你殺穿設施中遭到腐化的防護結界——越過古翰的副官，穿過那些在食人妖尚未擁有語言的年代便已失控的實驗——抵達了監牢的核心。古翰倒下了。這位血之神千年來的脫困圖謀，最終在它起始的同一座泰坦寶庫中畫下句點。納茲米爾需要好幾代的時間才能復原。那些獻出生命餵養古翰的食人妖，永遠無法完全得到救贖。但大地再度歸於平靜，封印依然穩固。"
L["The Tome of Blighted Implements"] = "荒蕪武器秘典"
L["The Touch of an Aspect"] = "守護巨龍之觸"
L["The trail leads to Azsuna, where a leyworm infestation masks something far more dangerous. Hemet Nesingwary lends his expertise."] = "線索指向艾蘇納，那裡肆虐的地脈蟲背後隱藏著更危險的東西。赫米特‧奈辛瓦里將助你一臂之力。"
L["The trail leads to Crusader's Run and the tower of High Priest Benedictus Voss. A daughter has come a long way to find her father — and what he says to her will determine everything."] = "線索指向十字軍小徑，以及高階祭司本尼迪塔斯‧佛斯的高塔。一個女兒千里迢迢前來尋找她的父親——而他對她說的話將決定一切。"
L["The Trial of Ban-Lu"] = "班盧的試煉"
L["The Trial of Rage"] = "怒氣試煉"
L["The Truth of the Grave"] = "墳墓的真相"
L["The Twilight Master"] = "暮光教長"
L["The Underrot"] = "幽腐深窟"
L["The Underrot: Sealing G'huun's Corruption"] = "幽腐深窟：封印古翰之腐化"
L["The Undersea Ledge"] = "海中斷崖"
L["The Unkillable"] = "不死之身"
L["The Unseen Blade"] = "無形之刃"
L["The Unseen Path"] = "隱獵團"
L["The unthinkable happened — the Peak of Serenity, the monks' sacred mountain, fell to a Legion assault. As smoke rose from the ruins, you gathered the survivors and led them to the Temple of Five Dawns on the Wandering Isle. There, Fearsome Jang named you Grandmaster of the order, and you claimed an artifact weapon to carry into the war ahead. Iron-Body Ponshu began organizing the scattered monks into a fighting force."] = "難以想像的事發生了——武僧的聖山寂靜峰在燃燒軍團的攻擊下淪陷。廢墟中濃煙升起之際，你集結倖存者，帶領他們前往流浪島的五晨寺。在那裡，『威震八方』老章任命你為武僧團的宗師，你也取得一把神器武器，準備帶著它投入眼前的戰爭。鐵胴彭舒開始將四散的武僧整編成一支戰鬥部隊。"
L["The Val'kyr raise new Forsaken in the crypt of Deathknell. One of them is Lilian Voss — daughter of the Scarlet Crusade's High Priest, raised as the very thing she was trained to destroy."] = "華爾琪在喪鐘鎮的墓穴中喚起新的被遺忘者。其中一人是莉莉安‧佛斯——血色十字軍高階祭司的女兒，如今卻復生為她自小被訓練去消滅的存在。"
L["The Valewalker's Burden"] = "谷行者的負擔"
L["The Valley of Echoes is a bowl of old Scourge work. Plague altars cough smoke into the wind; restless dead pace the rim by moonlight. Father Gustav wants scourgestones. The Ebon Watcher wants the altars cold. The Argent Crusade wants the road cleared north — to the Pinnacle, where Tirion Fordring has already set his banner. When the banner flies, the whole rim of Icecrown hears it, and the gunships in the northern sky start warming their engines."] = "回聲山谷是一處遍布天譴軍舊日傑作的盆地。瘟疫祭壇朝風中噴吐濃煙；不得安息的亡者在月光下沿著谷緣徘徊。賈斯塔夫神父想要天譴石。黯黑看守者要讓祭壇徹底熄滅。銀白十字軍則要打通向北的道路——直抵十字軍之巔，提里奧‧弗丁已在那裡插上了他的旗幟。旗幟飄揚之時，整個寒冰皇冠邊緣都聽得見，北方天空中的砲艇也開始暖機。"
L["The Vanguard's wreckage proved Anduin had survived, but it also pulled the Alliance into the Pearlfin jinyu's crisis. Taylor and Bold Karasshi had been captured by the Slingtail hozen, and the only way forward was through the pits. You freed prisoners, recovered waterspeaker relics, broke Kung Din's hold, and helped the Pearlfin decide whether the Alliance deserved their trust. SI:7's reports then made the bargain real: the Horde had armed the hozen, so Taylor trained the jinyu to fight back. When the trail finally led to Cho, the search changed shape. Tea, stories, and a strange brew opened the way to Anduin, who was already choosing curiosity over command."] = "先鋒號的殘骸證明安杜因還活著，卻也讓聯盟捲入了珠鰭錦魚人的危機。泰勒與英勇的卡爾勒什被甩尾猴人抓走了，唯一的出路就是穿過那些坑洞。你解救了俘虜，尋回水語者的遺物，打破鋼釘的控制，並協助珠鰭錦魚人判斷聯盟是否值得信任。軍情七處的報告隨後讓這筆交易成了定局：部落武裝了猴人，因此泰勒訓練錦魚人奮起反擊。當線索終於指向周時，這場搜尋也變了樣。茶、故事和一杯奇特的酒，為你開啟了通往安杜因的道路——而他早已選擇了好奇心，而非指揮權。"
L["The Vanishing Lord"] = "消失的領主"
L["The Vault of the Tirisgarde"] = "提里斯護法寶庫"
L["The Vile Hold"] = "邪鄙堡"
L["The Village of Glenbrook"] = "谷溪村"
L["The Vindicator's Plea"] = "復仇者的請求"
L["The Violet Citadel, Dalaran"] = "紫羅蘭城塞（達拉然）"
L["The VIP List"] = "VIP名單"
L["The voice in the dark has a name now — Matthias Lehner. He claims to know the Lich King better than any living thing should. His memories run like a buried river through the Frozen Wastes. He leads you to a dragon's corpse. To a hunter and a prince. To the knowledge that cannot be unknown. Whether he can be trusted is a judgement you will make when the road ends — at the foot of the citadel, where Tirion Fordring lifts the Ashbringer and calls for one more charge."] = "黑暗中的聲音如今有了名字——米希阿斯‧薩爾奈。他聲稱自己對巫妖王的了解，超出任何活人應有的程度。他的記憶如同一條地下暗河，流貫冰凍荒原。他帶你找到一具巨龍的屍骸，找到一名獵人與一位王子，找到一旦知曉便再也無法遺忘的真相。他是否值得信任，要等到旅途的終點再由你判斷——就在城塞腳下，提里奧‧弗丁將在那裡高舉灰燼使者，號召最後一次衝鋒。"
L["The Wakening"] = "甦醒"
L["The Wanderer's Companion"] = "漫行者之伴"
L["The Wanderers"] = "漫遊者"
L["The Waning Crescent"] = "弦月旅店"
L["The war at sea gave the Horde what blades on land could not: Derek Proudmoore, heir to Kul Tiras, dead at the bottom of the ocean. Hobart Grapplehammer put you in a diving suit and you went down. The ocean floor was littered with the wreckage of the battle — dog tags, sunken ships, the bones of sailors on both sides. You found Derek and hauled him up. No one said what Sylvanas would do with him. No one had to."] = "海上的戰爭為部落帶來了陸上刀劍無法取得的東西：庫爾提拉斯的繼承人德瑞克‧普勞德摩爾，已葬身海底。荷巴爾特‧繫錘讓你穿上潛水服，你就這麼潛了下去。海床上散落著戰鬥的殘骸——兵籍牌、沉船，以及雙方水手的骸骨。你找到德瑞克，把他拖了上來。沒有人說希瓦娜斯打算如何處置他。也不必有人說。"
L["The war ended. Sylvanas was gone. And Lilian Voss led the Forsaken home.\n\nThey came back to ruins — streets flooded with Blight, Undercity dark and broken. Calia Menethil walked beside her, daughter of the last king of Lordaeron, and between the two of them they held the Forsaken together through all of it: the plague work, the dead to bury, the city to reclaim room by room. At the end they formed the Desolate Council — Lilian, Calia, Velonara, Belmont, Faranell — not a Dark Lady, not a warchief. A council. Their own.\n\nLilian Voss, who had spent her whole life as something to be used and discarded, had become the person her people followed home."] = "戰爭結束了。希瓦娜斯走了。而莉莉安‧佛斯帶領被遺忘者回家。\n\n迎接他們的是一片廢墟——街道被荒疫淹沒，幽暗城漆黑殘破。卡莉雅‧米奈希爾走在她身旁，她是羅德隆末代國王的女兒，兩人攜手讓被遺忘者撐過了這一切：清除瘟疫、埋葬亡者，一間接一間地收復城市。最後，她們成立了荒寂議會——莉莉安、卡莉雅、薇洛娜拉、貝爾蒙特、法拉奈爾——不是黑暗女士，也不是大酋長，而是一個議會。屬於他們自己的議會。\n\n莉莉安‧佛斯這一生都被當成可以利用、用完即丟的東西，如今卻成了帶領族人回家的人。"
L["The War for Silverpine"] = "銀松森林之戰"
L["The war in the Shadowlands is over. Sylvanas stands before those she has wronged — and must face what comes next."] = "暗影之境的戰爭已經結束。希瓦娜斯站在那些曾被她虧待的人面前——必須面對接下來的一切。"
L["The war moves to the Broken Shore. Aethas Sunreaver leads the Tirisgarde's assault, and you earn the Archmage's Prismatic Disc."] = "戰火延燒至破碎海岸。埃薩‧奪日者率領提里斯法守護者發動攻勢，你也將贏得大法師的稜彩圓盤。"
L["The war moves to the Broken Shore. Contend with Magatha Grimtotem, secure Smolderon's flame, and earn a mount of living storm."] = "戰火延燒至破碎海岸。與瑪加薩‧恐怖圖騰周旋，取得斯莫德隆的火焰，並贏得一匹由活生生的風暴化成的坐騎。"
L["The war moves to the Broken Shore. Lead the Unseen Path against the Legion's corrupted beasts and earn the trust of a loyal wolfhawk."] = "戰火延燒至破碎海岸。率領隱匿之徑對抗燃燒軍團腐化的野獸，並贏得一隻忠誠狼鷹的信任。"
L["The war moves to the Broken Shore. Rally the Valarjar for a final push, brave the depths of Helheim, and earn your war wyrm."] = "戰火延燒至破碎海岸。集結華爾拉亞發動最後的攻勢，勇闖黑爾海姆深處，並贏得屬於你的戰龍。"
L["The War of the Ancients"] = "先祖之戰"
L["The War of Thorns"] = "荊棘之戰"
L["The war reaches the Broken Shore. Break a family curse, then forge the Highlord's Golden Charger at the Hammer of Dalaran."] = "戰火延燒至破碎海岸。破除一道家族詛咒，然後在達拉然之錘打造大領主的金色戰馬。"
L["The war reaches the Broken Shore. Defend the wilds, recruit Thisalee Crow, and earn the Archdruid's Lunarwing flight form."] = "戰火延燒至破碎海岸。守護荒野，招募黎沙莉‧烏鴉，並贏得大德魯伊的月翼飛行形態。"
L["The War Within"] = "地心之戰"
L["The Warchief Cometh"] = "大酋長駕到"
L["The Warchief sets her sights on Darkshore. What unfolds there will make the Fourth War impossible to contain."] = "大酋長將目光投向黑海岸。那裡即將發生的事，將使第四次大戰一發不可收拾。"
L["The Warchief's Fleet"] = "大酋長的艦隊"
L["The Warsong at the Wrathgate"] = "憤怒之門的戰歌"
L["The Warswords of the Valarjar called to you — twin blades said to contain the fury of a hundred battles. Odyn sent you to Stormheim to hunt the hero-slayer who had stolen them. Through storm and fire, you tracked the thief to their lair and pried the swords from their grip. The runes along the blades blazed to life in your hands, as if they had been waiting."] = "華爾拉亞戰劍在召喚你——傳說這對雙劍蘊含著百場戰役的怒火。歐丁派你前往斯鐸海姆，追捕盜走雙劍的屠英者。你穿越風暴與烈火，一路追蹤竊賊到其巢穴，從對方手中奪回了雙劍。劍身上的符文在你手中熊熊亮起，彷彿早已在等待著你。"
L["The Way Back Home"] = "回家的路"
L["The Way of the Tiger"] = "白虎之道"
L["The Waycrest Daughter"] = "威奎斯特家的女兒"
L["The Wayward Crone"] = "難以捉摸的老婦人"
L["The Wayward Dead"] = "固執的亡靈"
L["The White Pawn"] = "白棋"
L["The Will of the Naaru"] = "那魯的意志"
L["The Winter Queen needs anima, and Revendreth is supposed to be the realm that knows how to harvest it. Your request begins in Darkhaven, where every sin has a stone."] = "凜冬女王需要心能，而瑞文崔斯理應是最懂得如何收集心能的國度。你的請求從暗隱村開始，在那裡，每一樁罪孽都有一塊對應的石頭。"
L["The witch hunt turned on Lucille herself — Marshal Everit Reade accused the Waycrest daughter of sorcery. In a land gripped by paranoid suspicion, even nobility was not above the trials. You gathered proof of Lucille's innocence through the marshal's superstitious tests: walking through the woods that watched, enduring ambush, and passing the trial by superstition. A pungent alchemical solution revealed the true witches hiding in plain sight. The burden of proof was met, but the experience left its mark — in Drustvar, trust was a luxury no one could afford."] = "獵巫行動的矛頭轉向了露西爾本人——埃弗雷‧瑞德元帥指控這位威奎斯特家的女兒施行巫術。在這片被多疑猜忌籠罩的土地上，就連貴族也無法免於審判。你通過元帥那些迷信的考驗，為露西爾蒐集清白的證據：穿越那片會窺視人的林地、承受伏擊，並通過迷信的試煉。一劑氣味刺鼻的鍊金藥水，讓光明正大藏身眾人之中的真正女巫現出原形。「證明之擔」總算完成，但這段經歷留下了烙印——在佐司瓦，信任是任何人都負擔不起的奢侈品。"
L["The Witchwood of Drustvar"] = "佐司瓦的巫覡之林"
L["The Woods Have Eyes"] = "隔木有眼"
L["The World is Not Enough"] = "縱橫天下"
L["The Wrathgate"] = "憤怒之門"
L["The Wrathsteed of Xoroth"] = "克索諾斯憤怒戰馬"
L["The Zealot Rises"] = "狂熱者復甦"
L["The zone ends where its warning began: inside the Temple of the Jade Serpent. The sha has seeped into wisdom, memory, discipline, and flame. Wise Mari, Lorewalker Stonestep, Liu Flameheart, and the temple's defenders are all trapped in doubt's reflection. By cleansing the temple and defeating the Sha of Doubt, you do what the armies outside could not: stop feeding the darkness long enough to face it. The Jade Forest is not untouched anymore. It is wounded, changed, and still alive."] = "這片區域的故事，在當初發出警告的地方畫下句點：玉蛟寺之內。煞已滲入智慧、記憶、紀律與火焰之中。智者瑪利、博學行者石步、劉‧焰心與神殿的守衛者，全都困在疑惑的倒影裡。你淨化了神殿、擊敗疑惑之煞，完成了外頭的軍隊辦不到的事：停止餵養黑暗，並撐得夠久去直視它。翠玉林已不再是未受侵擾的淨土。它負了傷、改變了，卻依然活著。"
L["Theotar"] = "希奧塔"
L["Theotar, the Mad Duke, may know where Prince Renathal is. His ruined tea party leads through the Light-scarred Ember Ward and back to Sinfall."] = "瘋狂公爵希奧塔或許知道雷納瑟王子的下落。他那場毀於一旦的茶會，將你引向遭聖光灼傷的餘燼區，再回到罪殞城。"
L["Theotar's Mission"] = "希奧塔的任務"
L["Therazane"] = "瑟拉贊恩"
L["Therazane the Stonemother sent a tremor through the Maelstrom — a cry for help. Deepholm, the elemental plane of earth, was being consumed by the Twilight's Hammer once more. You descended into the stone realm and found Therazane besieged, her domain crumbling. Together you destroyed the cult's forces, unmasked their master's plan, and unleashed the elements against them. Therazane promised the earth's strength to the Earthen Ring, and Muln Earthfury pledged himself as your champion."] = "石母瑟拉贊恩在大漩渦中引發一陣震動——那是求救的呼喊。大地元素位面地深之源，再度遭到暮光之錘吞噬。你深入這片岩石之境，發現瑟拉贊恩正遭圍攻，她的領域逐漸崩塌。你們聯手摧毀了教團的部隊，揭穿其首腦的陰謀，並釋放元素之力反擊他們。瑟拉贊恩承諾將大地之力借予陶土議會，穆倫‧地怒也宣誓成為你的勇士。"
L["There is Another"] = "還有另一位"
L["There Is No Plan \"B\""] = "替代方案？才沒有這種東西咧"
L["Theryn"] = "瑟倫"
L["They Move Against Us"] = "違逆我們的行動"
L["They Will Know Fear"] = "讓他們體悟恐懼"
L["They Won't Know What Hit Them"] = "他們連自己怎麼死的都不知道"
L["They're So Thorny!"] = "他們刺真多!"
L["Things Gaardoun Needs"] = "蓋爾道恩需要的東西"
L["Thinly Veiled Threats"] = "明目張膽的威脅"
L["This Ain't Mine"] = "這不是地雷"
L["This Is Retribution"] = "此即懲戒"
L["This is the Hour of the Forsaken"] = "被遺忘者的時刻"
L["This Land is Ours"] = "捍衛家園"
L["This Time, Leave a Trail"] = "這次，留下蹤跡"
L["This Was Home"] = "歸鄉"
L["Thisalee Crow"] = "黎沙莉‧烏鴉"
L["Thomas Zelling"] = "湯瑪斯‧澤靈"
L["Thomas Zelling was a dying tidesage who traded his humanity for undeath, desperate for a few more years with his family. You and Lilian performed the ritual that raised him — and then watched his wife recoil in horror from the husband she no longer recognized. Lilian stood in silence as the scene played out, seeing her own story reflected in Zelling's shattered face. To be Forsaken, she finally understood, was not just a curse of the body."] = "湯瑪斯‧澤靈是一名垂死的潮汐賢者，為了能與家人多相處幾年，不惜拿人性換取不死之身。你和莉莉安舉行儀式讓他復生——然後眼看著他的妻子驚恐地避開這個她再也認不出的丈夫。莉莉安默默看著這一幕，在澤靈破碎的面容上看見了自己的故事。她終於明白，成為被遺忘者，不只是肉體上的詛咒。"
L["Thorim"] = "索林姆"
L["Those Scrying Eyes"] = "占卜之眼"
L["Thousands of Years Ago..."] = "好幾千年前…"
L["Thrall"] = "索爾"
L["Thrall calls you to the Maelstrom, where the Earthen Ring fights to keep the world from tearing apart."] = "索爾召你前往大漩渦，陶土議會正在那裡奮戰，避免世界分崩離析。"
L["Thrall could no longer hear the elements. The Doomhammer — Orgrim's weapon, carried through the First and Second Wars — had gone silent in his hands. He passed it to you, and the moment your fingers closed around the haft, thunder split the sky. The elements had chosen a new wielder. The Doomhammer was yours."] = "索爾再也聽不見元素的聲音。毀滅之錘——奧格林的武器，曾歷經第一次與第二次大戰——在他手中陷入沉寂。他將它交給了你，就在你的手指握住錘柄的那一刻，雷霆劃破天際。元素選擇了新的持有者。毀滅之錘從此屬於你。"
L["Thrall passes the Doomhammer to you — the weapon of Orgrim Doomhammer, carried through two wars and across worlds."] = "索爾將毀滅之錘交給了你——這是奧格林‧末日錘的武器，曾歷經兩場大戰，橫跨數個世界。"
L["Thrall's summons brought you to the edge of the Maelstrom — the wound in the world where Deathwing had nearly torn Azeroth asunder. The Earthen Ring was losing the fight to hold it together. Farseer Nobundo stood at the eye of the storm, channeling what remained of the ring's power. You claimed an artifact weapon attuned to the elements, and Stormcaller Mylra and Duke Hydraxis pledged themselves as your first champions. The elements were restless — and they were listening."] = "索爾的召喚將你帶到大漩渦邊緣——這是死亡之翼險些將艾澤拉斯撕裂時留下的世界傷口。陶土議會為了穩住它而苦戰，卻逐漸落居下風。先知諾柏多佇立於風暴之眼，引導議會僅存的力量。你取得一把與元素共鳴的神器武器，風暴召喚者米爾拉與海達克西斯公爵也宣誓成為你的首批勇士。元素躁動不安——而它們正在傾聽。"
L["Three Horsemen rode, but the fourth seat remained empty. The Lich King demanded a champion of unmatched power — and the only candidate lay buried beneath Light's Hope Chapel itself. You stormed the most sacred ground on Azeroth, battling paladins and holy guardians, only for the assault to fail against the Chapel's consecrated power. In the end, it was Darion Mograine who knelt and gave himself — dying so he could rise as the Fourth Horseman. With your weapon forged anew and all four riders assembled, you were named Deathlord of the Ebon Blade."] = "三位騎士已然出征，但第四個席位依舊空懸。巫妖王要求一位力量無可匹敵的勇士——而唯一的人選就埋葬在聖光之願禮拜堂底下。你攻入艾澤拉斯最神聖的土地，與聖騎士和神聖守護者交戰，卻在禮拜堂的聖化之力面前功敗垂成。最終，是達利安‧莫格萊尼跪下獻出了自己——以死亡換取作為第四位騎士重生。你的武器再度重鑄，四位騎士全員到齊，你被冠上黯刃騎士團死亡領主的稱號。"
L["Throne of the Tides"] = "海潮王座"
L["Thros, the Blighted Lands"] = "瑟洛斯，荒疫之原"
L["Through Ly'leth Lunastre's connections, you obtained a magical disguise and walked the gilded streets of Suramar City as one of the Nightborne elite. Behind the masks and pleasantries, you made first contact with sympathizers among the nobility — those who whispered against Elisande but dared not act alone."] = "透過黎利斯‧路納斯特的人脈，你取得了魔法偽裝，以夜裔精靈菁英的身分走在蘇拉瑪爾城金碧輝煌的街道上。在面具與客套話的背後，你首度接觸到貴族中的同情者——他們私下對艾莉珊德頗有微詞，卻不敢單獨行動。"
L["Through the Emerald Dreamway, you discover the Dreamgrove: a sanctuary of nature hidden in Val'sharah. The Legion's war is spreading into places that should have been beyond its reach.\n\nAs Archdruid of the Cenarion Circle, heal the wounds of the Nightmare, gather ancient allies, and call on powers older than any mortal battlefield."] = "你經由翡翠夢途發現了幻夢之林：一座隱藏在維爾薩拉的自然聖地。燃燒軍團的戰火正蔓延到原本不該觸及的地方。\n\n身為塞納里奧議會的大德魯伊，你要治癒夢魘造成的創傷，召集古老的盟友，並喚起比任何凡人戰場都更古老的力量。"
L["Through the Eye"] = "透過另一隻眼"
L["Through the Old Roads"] = "穿過古道"
L["Through the Shattered Sky"] = "穿越破碎天空"
L["Through trogg-infested ruins, ancient records, and the heat of the forge, you helped restore a lost legacy and carry the mountain king's heritage into the present."] = "穿越穴居人肆虐的遺跡、翻閱古老的紀錄、承受熔爐的高溫，你協助恢復了失落的傳承，並將山丘之王的遺產延續至今。"
L["Throwing SI:7 Off the Trail"] = "誤導軍情七處"
L["Thunder Bluff / Mulgore / Stonetalon"] = "雷霆崖／莫高雷／石爪山脈"
L["Thunderaan"] = "桑德蘭"
L["Thurgaden's Designs"] = "瑟加頓的設計圖"
L["Thus Begins the War"] = "戰爭揭幕"
L["Tian Monastery"] = "天僧寺"
L["Tian Monastery is under siege. Fight alongside Taran Zhu and The Monkey King to drive back the Legion and rebuild the order."] = "天僧寺遭到圍攻。與塔蘭‧祝和美猴王並肩作戰，擊退燃燒軍團，重建武僧團。"
L["Tian Monastery offered a different kind of strength. You entered as a guest, sat at the banquet, then trained under masters who cared as much about patience as power. You made a weapon with Groundskeeper Wu, learned precision from Instructor Xann, faced sparring partners who turned humility into bruises, and endured the Rumpus without mistaking chaos for victory. Flying Colors was more than a graduation. It was Pandaria quietly asking whether you could be taught."] = "天僧寺提供了另一種力量。你以客人的身分進入寺中，入席參加宴會，接著在師父們的指導下修練——他們重視耐心不亞於力量。你和園丁老吳一起打造武器，向講師老詹學習精準，面對那些把謙卑化為瘀青的對練夥伴，並熬過了「大騷動」，沒有把混亂誤認為勝利。「火樹銀花」不只是一場結業儀式，更是潘達利亞在靜靜地問你：你是否受教。"
L["Tickets, Please?"] = "請出示票券？"
L["Tide of Virmen"] = "潮水般的兔妖"
L["Tidesage Teachings"] = "浪潮賢者的教誨"
L["Time Flies When Yer Havin' Rum!"] = "喝蘭姆酒的快樂時光總是過得特別快！"
L["Time for Answers"] = "揭曉之時"
L["Time is of the Essence"] = "時間寶貴"
L["Time to Hide"] = "快躲起來"
L["Time Yet Remains"] = "尚有時間"
L["Tiragarde Sound was rotting at its foundations. Priscilla Ashvane and the Ashvane Trading Company had corrupted the Admiralty's supply lines, bribed its officers, and turned institutional loyalty into a private racket — all while Katherine Proudmoore remained in the dark, managing the public appearances of a nation that was quietly being hollowed out beneath her. You dismantled the operation piece by piece, surfacing the evidence until the case against Ashvane was undeniable. Katherine met with Genn Greymane in Boralus Harbor. She still had not spoken to Jaina."] = "提拉加德海灣從根基開始腐爛。普莉希拉‧艾胥凡與艾胥凡貿易公司腐蝕了海軍部的補給線，賄賂軍官，把體制內的忠誠變成了私人的斂財勾當——而凱瑟琳‧普勞德摩爾卻始終被蒙在鼓裡，忙著維持這個國家的表面形象，渾然不知國家正在她腳下悄悄被掏空。你一步步瓦解了這整個組織，讓證據浮出檯面，直到艾胥凡的罪證確鑿、無可抵賴。凱瑟琳在波拉勒斯港與吉恩‧葛雷邁恩會面。她仍未與珍娜說過話。"
L["Tirion's Gambit"] = "提里奧的決斷"
L["Tirion's Help"] = "提里奧的協助"
L["Tirisfal Glades / Kul Tiras / Lordaeron"] = "提里斯法林地 / 庫爾提拉斯 / 羅德隆"
L["Tirisfal Glades / Silverpine Forest"] = "提里斯法林地 / 銀松森林"
L["Titan Keeper Hezrel"] = "泰坦守衛者赫茲羅"
L["Titan Keeper Hezrel had been running containment protocols in Nazmir longer than any troll civilization had existed. His facility was damaged, his routines degraded, and the thing he was containing was actively working to get out. G'huun — a failed titan experiment, a blood god born in a lab and deemed too dangerous to destroy — had been sealed beneath Nazmir since before the trolls arrived. You helped Hezrel repair his systems, purified the corrupted earth, cleared the undead and void creatures that had crept into the facility, and restored the containment. For now. What had already escaped, and the blood trolls' true purpose — feeding G'huun until he broke free on his own terms — was only becoming clear."] = "泰坦守衛者赫茲羅在納茲米爾執行收容協定的時間，比任何食人妖文明存在的歷史都還要久。他的設施受損，例行程序也逐漸失靈，而他所收容的東西正積極設法逃脫。古翰——一場失敗的泰坦實驗，一個誕生於實驗室、被認為危險到無法摧毀的血之神——早在食人妖到來之前就已被封印在納茲米爾底下。你協助赫茲羅修復系統，淨化遭到腐化的土地，清除潛入設施的不死生物與虛無生物，並恢復了收容狀態。至少暫時如此。至於有什麼東西已經逃脫，以及血食人妖的真正目的——餵養古翰，直到他能按照自己的意願破封而出——這些才剛逐漸明朗。"
L["Titanstrike"] = "泰坦之擊"
L["To Be Forsaken"] = "成為被遺忘者"
L["To Bridge Earth and Sky"] = "橋接天地"
L["To Dai-Lo Farmstead"] = "前往戴洛農莊"
L["To Darkhaven"] = "前往暗隱村"
L["To Falconhurst!"] = "前往獵鷹林！"
L["To Faronaar"] = "前往法隆納"
L["To Fel and Back"] = "魔化歸來"
L["To Felblaze Ingress"] = "前往魔炎入口"
L["To Fordragon Hold!"] = "前往弗塔根堡!"
L["To Gloom Hollow"] = "前往幽暗谷。"
L["To Kill a Loa"] = "殺死羅亞"
L["To Morning Breeze"] = "前往晨風村"
L["To Northshire"] = "前往北郡"
L["To See Clearly"] = "雙目清晰"
L["To Tame the Beast"] = "馴服野獸"
L["To the Broken Shore"] = "前往破碎海岸"
L["To the Deeps"] = "邁向深淵"
L["To The Dreamgrove"] = "前往幻夢之林"
L["To the Other Side"] = "穿越障礙"
L["To the Sepulcher"] = "前往瑟伯切爾"
L["To the Summit!"] = "前往山巔！"
L["Tol Dagor: The Fourth Key"] = "托達戈爾：第四把鑰匙"
L["Tomb of Sargeras"] = "薩格拉斯之墓"
L["Tooki Tooki"] = "兔積‧兔積"
L["Torastrasza"] = "托菈史卓莎"
L["Torga, ancient sea turtle loa of Nazmir, is dying. The blood trolls have bled him for decades. You arrive too late to save him — but not too late to release him."] = "納茲米爾古老的海龜羅亞托加奄奄一息。血食人妖已吸取他的血長達數十年。你來得太遲，救不了他——但還來得及讓他解脫。"
L["Torga, the Turtle Loa"] = "烏龜羅亞，托加"
L["Torga's Eternal Return"] = "托加的永恆回歸"
L["Torghast, Tower of the Damned"] = "『譴罪之塔』托迦司"
L["Total Ohmage: The Valley of Lost Hope!"] = "電力全開：失落希望之谷！"
L["Totemic Restoration"] = "以圖騰恢復神力"
L["Touching Ground"] = "著地"
L["Toya"] = "托亞"
L["Track down the Fangs of Ashamane, twin daggers imbued with the spirit of the wild god of feral druids."] = "追查亞夏曼之牙的下落，這對雙匕首蘊含著野性德魯伊所崇拜的荒野之神的靈魂。"
L["Track down the legendary assassination daggers once wielded by Garona Halforcen, hidden away after the fall of a king."] = "追查迦羅娜‧半血曾經使用的傳奇刺殺匕首，它們在一位國王殞落後便被藏了起來。"
L["Track down Titanstrike, a legendary rifle forged by the titan keeper Mimiron, lost in the wilds of Ulduar."] = "追查泰坦之擊的下落，這把傳奇步槍由泰坦守衛者彌米倫打造，遺失在奧杜亞的荒野之中。"
L["Tracking a Killer"] = "循線緝凶"
L["Tracking the Enemy"] = "追蹤敵人"
L["Tracking Tidesages"] = "追蹤浪潮賢者"
L["Tracking Tipoff"] = "暗地追蹤"
L["Trail of Echoes"] = "秘法的殘影"
L["Traitor!"] = "叛徒！"
L["Traitors In Our Midst"] = "我們之中的叛徒"
L["Translation: Danger!"] = "翻譯內容：危險！"
L["Trapped!"] = "受困！"
L["Traumatized Nectarbreeze Farmer"] = "受創的蜜風果農"
L["Travel back to the hour that broke a prince — and make sure history unfolds as it always has."] = "回到讓一位王子崩潰的那一刻——確保歷史一如既往地發展。"
L["Travel from the Exodar to Bloodmyst Isle and onward to the broken sky of Outland, retracing the long flight of a people who have lost more worlds than most have ever known. The past is not distant for the draenei; it is written into every refuge.\n\nStand on ground still marked by betrayal, ask what faith can carry through grief, and help forge a future worthy of draenei endurance."] = "從艾克索達前往血謎島，再前進至外域破碎的天空之下，重溫一個民族漫長的流亡之路——他們失去的世界，比大多數人所知道的還要多。對德萊尼而言，過去並不遙遠；它就刻在每一處避難所之中。\n\n站在仍留有背叛痕跡的土地上，探問信仰能否撐過悲痛，並協助打造一個無愧於德萊尼堅毅精神的未來。"
L["Trial by Demonfire"] = "魔火試煉"
L["Trial by Superstition"] = "迷信審判"
L["Trolling Them"] = "大鬧營地"
L["Troops in the Field"] = "戰地部隊"
L["Trueshot Lodge / Broken Isles"] = "神獵廳 / 破碎群島"
L["Truthguard"] = "真理守護者"
L["Tubbins"] = "塔賓斯"
L["Tubbins's Tea"] = "塔賓斯的茶"
L["Turtle Power"] = "海龜之力"
L["Turtle Powered"] = "烏龜之力"
L["Twinblades of the Deceiver"] = "欺詐者雙刃"
L["Twinspire Keep"] = "雙石要塞"
L["Tyrande Whisperwind"] = "泰蘭妲‧語風"
L["Tyrande's Command"] = "泰蘭妲的命令"
L["Tzu the Ironbelly"] = "『鐵肚皮』祖"
L["Uldaman"] = "奧達曼"
L["Uldir — Blood From Stone"] = "奧迪爾——石中之血"
L["Ulduar's Oath"] = "奧杜亞的誓言"
L["Ulthalesh, the Deadwind Harvester"] = "烏薩雷許，逆風收割者"
L["Unbearable Light"] = "見光死"
L["Unbeleyvable"] = "扭轉地脈"
L["Unbound"] = "鬆綁"
L["Unbridled Power"] = "不受控制的力量"
L["Under Cover of Darkness"] = "黑暗籠罩之下"
L["Under False Colors"] = "掛羊頭賣狗肉"
L["Under Lock and Keys"] = "鎖頭與鑰匙"
L["Under Ly'leth Lunastre's guidance, you plunged into the viper pit of Nightborne politics — buying votes, silencing rivals, and navigating a web of alliances that shifted with every whispered rumor. Through cunning and carefully applied force, Ly'leth secured her position among the nobility and opened the path to the Arcway, an ancient tunnel network running beneath the city."] = "在黎利斯‧路納斯特的指引下，你一頭栽進夜裔精靈政治的蛇窟——收買選票、讓對手噤聲，並在隨著每一則耳語謠言而變動的同盟網絡中周旋。憑藉狡詐與恰到好處的武力，黎利斯鞏固了她在貴族間的地位，也打通了前往秘法迴廊的道路——那是一座在城市底下延伸的古老隧道網絡。"
L["Undercover Sista"] = "臥底姊妹"
L["Undying Totems"] = "不死圖騰"
L["Unexpected Guests"] = "不速之客"
L["Unexpected Visitors"] = "出乎意料的訪客"
L["Unfair Trade"] = "不公平的交易"
L["United As One"] = "團結一心"
L["Unleash Hell"] = "獄火降臨"
L["Unleashing the Elements"] = "釋放元素"
L["Unliving Summons"] = "無生召喚"
L["Unlocking History"] = "解密歷史"
L["Unlocks after defeating N'Zoth. Speak with Valeera Sanguinar in Zuldazar to begin."] = "擊敗恩若司後解鎖。與祖達薩的瓦麗拉‧桑古納爾交談以開始。"
L["Unnatural Consequences"] = "非自然的後果"
L["Unreliable Allies"] = "不可靠的盟友"
L["Unseen Protection"] = "隱形防護"
L["Unto Dust Thou Shalt Return"] = "汝當歸於塵土"
L["Unwelcome Undead"] = "不受歡迎的不死生物"
L["Upward and Onward"] = "邁向成功"
L["Urgent Summons"] = "緊急召喚"
L["Uther the Lightbringer"] = "『光明使者』烏瑟"
L["Vaelen Has Returned"] = "維倫回來了"
L["Val'zuun"] = "瓦爾祖"
L["Valarjar Warsinger"] = "華爾拉亞頌戰者"
L["Valeera Sanguinar"] = "瓦麗拉‧桑古納爾"
L["Valeera Sanguinar led you on a hunt for the Raven's Eye, an ancient vrykul artifact capable of piercing any disguise. Your search took you through the Maw of Souls and into the haunted depths of Black Rook Hold, where you retrieved the artifact and deciphered a letter that revealed the true scope of the enemy's infiltration."] = "瓦麗拉‧桑古納爾帶你尋找鴉眼——一件能看穿任何偽裝的古老維酷人神器。你的搜尋穿過靈魂之喉，深入玄鴉堡鬧鬼的深處，在那裡取回了神器，並破譯一封信，揭露了敵人滲透的真正規模。"
L["Valeera Sanguinar tracked a pair of shadow-forged blades to a demonic vault hidden between worlds. You fought through the Twisting Nether itself, confronting the demon Val'zuun who guarded the Fangs of the Devourer. The blades pulsed with hunger as you claimed them — weapons that devoured souls and grew stronger with every kill."] = "瓦麗拉‧桑古納爾追查到一對暗影鍛造的刀刃，它們藏在世界夾縫間的一座惡魔寶庫中。你殺入扭曲虛空，與守護吞噬者之牙的惡魔瓦爾祖正面交鋒。當你取得這對刀刃時，它們因飢渴而脈動——這是會吞噬靈魂、每殺一人便更加強大的武器。"
L["Valewalker Farodin"] = "谷行者費羅丁"
L["Valley of Echoes"] = "回聲山谷"
L["Valley of Spirits, Orgrimmar"] = "精神谷（奧格瑪）"
L["Valnok Windrager"] = "沃爾諾克‧風怒者"
L["Vandalizing Jotunheim"] = "燃燒吧，卓頓海姆!"
L["Vanessa VanCleef"] = "凡妮莎‧范克里夫"
L["Vassandra Stormclaw"] = "維珊卓拉‧風爪"
