L["Walk north through the ruin of Scourgeholme and onto the high plateau of Crusaders' Pinnacle."] = "向北穿越天譴岸地的廢墟，登上十字軍之巔的高原。"
L["Walk of Faith"] = "與信仰同行"
L["Walk the long road that turned Prince Arthas Menethil into the Lich King, and the longer road taken by those who march north to face him. It begins in Stratholme, where a prince makes an unforgivable choice in the name of salvation.\n\nBetween that memory and Icecrown lie the dragon-haunted plains of Dragonblight, the howling reach of Northrend, and a campaign waged in the long shadow of Frostmourne."] = "走過那條讓阿薩斯‧米奈希爾王子成為巫妖王的漫長道路，以及那些北上與他對抗之人所走過、更加漫長的道路。一切始於斯坦索姆，一位王子在那裡以救贖之名，做出了不可饒恕的抉擇。\n\n在那段記憶與寒冰皇冠之間，橫亙著巨龍出沒的龍骨荒野平原、寒風呼嘯的北裂境，以及一場籠罩在霜之哀傷漫長陰影下的戰役。"
L["Walk the saronite tunnels below Ymirheim and test what the whispers can do to a soldier's mind."] = "走進依米海姆底下的薩鋼坑道，測試那些低語會對士兵的心智造成什麼影響。"
L["Walk with Lor'themar through the memory of Quel'Thalas and what the Sin'dorei lost when Arthas marched on Silvermoon. The grief is older than many kingdoms, and the silence the Scourge left behind still has weight.\n\nStand where names are remembered, face old wounds with care, and honor the heritage of a people whose line endured even when the kingdom nearly did not."] = "與洛索瑪一同走過奎爾薩拉斯的記憶，重溫阿薩斯進軍銀月城時辛多雷所失去的一切。這份悲痛比許多王國的歷史還要古老，天譴軍留下的沉默至今依然沉重。\n\n站在銘記著逝者名字的地方，謹慎地面對舊日的傷痕，並向這個民族的傳承致敬——即使王國幾近覆滅，他們的血脈依然延續。"
L["Wandering Isle / Broken Isles"] = "流浪島／破碎群島"
L["Waning Refuge"] = "無力庇護"
L["War with the Horde"] = "與部落開戰"
L["War'zuul the Provoker"] = "『尋釁者』瓦祖爾"
L["Warbringer Davos Rioht"] = "戰爭使者戴沃斯‧里歐特"
L["Warchief of the Horde"] = "部落的大酋長"
L["Wardens' Wrath"] = "看守者之怒"
