L["Waycrest Manor: Draining the Heartsbane"] = "威奎斯特莊園：汲取禍心"
L["Waycrest Manor: The Fallen Mother"] = "威奎斯特莊園：墮落的母親"
L["We Meet at Light's Hope"] = "在聖光之願會師"
L["We Must be Prepared!"] = "我們必須做好準備！"
L["We Need Weapons"] = "我們需要武器"
L["We Ride!"] = "出發！"
L["We'll Meet Again"] = "後會有期"
L["Weapons o' the Dark Iron"] = "黑鐵武器"
L["Weapons of Legend"] = "傳說中的武器"
L["Welcome to Dawn's Blossom"] = "歡迎來到晨綻"
L["Welcome to Revendreth"] = "歡迎來到瑞文崔斯"
L["Welcome Wagons"] = "歡迎車隊"
L["What Comes After"] = "塵埃落定之後"
L["What Is Going On Here?"] = "這裡到底出了什麼事？"
L["What Is Worth Fighting For"] = "值得奮戰的理由"
L["What Remains of Marshal M. Valentine"] = "莫‧瓦倫泰元帥的遺骸"
L["What Rots Beneath"] = "底下朽壞的東西"
L["What Tomorrow Brings"] = "明天的希望"
L["What Winstone Suggests"] = "溫斯頓的「建議」"
L["What You May Regret"] = "悔不當初"
L["What's in a Name Name?"] = "名名是什麼?"
L["What's Mined Is Yours"] = "挖到就是你的"
L["What's the Cache?"] = "箱子裡有什麼？"
L["What's Their Problem?"] = "他們是哪根筋不對？"
L["Whatever Will Be"] = "不計後果"
L["When a Plan Comes Together"] = "計畫成形"
L["When Smoochums was found in the woods, Abby was gone. In her place: a register listing every Glenbrook villager — most names struck through. Jonathan Hayes had his heart removed for a ritual. Samuel Hawthorne lay dead in the trees. Mary Hayes had turned witch and killed her own husband. Only Annie Warren survived, barely, imprisoned in a cave.\n\nAbby came back. She led you to a circle of candles with Smoochums — the cat, now sacrificed — at the center. She poured the tea. She said there was one more guest to meet. Then she ran, and the Conjured Horror arrived in her place."] = "在樹林裡找到親親時，艾比已經不見了。取而代之的是一本名冊，上面列著格倫布魯克的每一位村民——大多數名字都被劃掉了。強納森‧海耶斯的心臟在一場儀式中被取出。山繆‧霍桑陳屍在樹林間。瑪麗‧海耶斯變成了女巫，殺害了自己的丈夫。只有安妮‧華倫勉強活了下來，被囚禁在一處洞穴中。\n\n艾比回來了。她帶你來到一圈蠟燭前，中央是親親——那隻貓，如今已成了祭品。她倒好了茶，說還有一位客人要見。接著她拔腿就跑，取而代之出現的是召喚恐獸。"
L["When Spirits Whisper"] = "當靈魂低語之時"
L["When Spiritwalker Ussoh's vision revealed Baine's imminent execution, Lor'themar gathered a small band of rebels — Thrall, Saurfang, and others. You infiltrated Orgrimmar's depths, fought through Sylvanas's forces, and rescued Baine from his cell. Jaina Proudmoore, of all people, helped you escape. The Horde was fracturing, and this was just the beginning."] = "靈行者烏守的幻象揭示貝恩即將被處決，洛索瑪於是召集了一小群反抗者——索爾、薩魯法爾等人。你潛入奧格瑪深處，殺穿希瓦娜斯的部隊，從牢房中救出了貝恩。出乎所有人意料，協助你們脫逃的竟是珍娜‧普勞德摩爾。部落正在分裂，而這只是開始。"
L["When the gate went quiet and Sylvanas left, Lilian Voss was already in the room. Baine, Lor'themar, Ji Firepaw — all the leaders who had waited out the war with their doubts held close — and the question nobody wanted to be first to say: what do they do about the Warchief's throne? Before the full council assembled, Lilian stepped away from the main hall to arrange a quieter meeting — Forsaken leadership, Calia Menethil, and Derek Proudmoore. Hidden, necessary, and entirely hers to broker. Then she came back into the room and made the case for leaving the throne empty. No single voice. A council, where every people kept their own weight and no one leader could burn the world on a private conviction. She had spent years being used by the powerful as a tool. She knew exactly what concentrated authority looked like from the receiving end. The others listened. They agreed. It was the first time Lilian Voss had spoken in a room full of power and been heard."] = "當那道門歸於沉寂、希瓦娜斯離去時，莉莉安‧佛斯已經身在那個房間裡。貝恩、洛索瑪、紀‧火爪——所有在戰爭中將疑慮深藏心底、默默撐到最後的領袖都在場——還有那個沒人想第一個說出口的問題：大酋長的王座該如何處置？在全體議會召開之前，莉莉安離開主廳，安排了一場更低調的會面——被遺忘者的領導層、卡莉雅‧米奈希爾，以及德瑞克‧普勞德摩爾。這場會面隱密、必要，而且完全由她一手促成。接著，她回到房間，力主讓王座空懸。不再由單一的聲音發號施令，而是成立一個議會，讓每個種族都保有自己的分量，任何領袖都無法憑一己的信念焚毀世界。她多年來一直被掌權者當作工具利用，比誰都清楚身為集權之下的承受者是什麼滋味。其他人聆聽著，也表示同意。這是莉莉安‧佛斯第一次在滿是權勢者的房間裡發言，並被人聽見。"
L["When the Peak of Serenity falls to the Legion, the monks rally at the Temple of Five Dawns on the Wandering Isle. Their order bends, breathes, and returns to its center.\n\nAs Grandmaster, defend sacred training grounds, recruit legendary warriors, and seek the old brews and older lessons that turn discipline into strength."] = "寂靜峰被燃燒軍團攻陷後，武僧們在流浪島的五晨寺重新集結。他們的武僧團彎而不折，調息吐納，重新回歸自身的中心。\n\n身為宗師，你要守護神聖的修練場，招募傳奇戰士，並尋找古老的佳釀與更古老的教誨，將紀律化為力量。"
L["When There's a Will, There's a Way"] = "有志者事竟成"
L["Where Are They Coming From?"] = "他們打哪來的?"
L["Where Dragons Fell"] = "龍殞之地"
L["Where In the World is Mathias?"] = "馬迪亞斯在哪裡？"
L["Where is Prince Renathal?"] = "雷納瑟王子在哪裡？"
L["Where the Hammer Falls"] = "落錘之處"
L["Whispers in the Void"] = "虛無中的低語"
L["Wicked Wikkets"] = "邪惡的怪怪人"
L["Will of the Valarjar"] = "華爾拉亞的意志"
L["Will to Survive"] = "求生意志"
L["Win back the Anvil-Thane's designs and reforge Dark Iron pride through craft and grit."] = "奪回鐵砧領主的設計圖，以技藝與毅力重鑄黑鐵的榮耀。"
L["Wings of the Red Flight"] = "紅龍軍團之翼"
L["Wintergarde Keep clings to the broken edge of the Dragonblight, pinned between Naxxramas overhead and the plaguebearers boiling up from the Carrion Fields. Duke August Foehammer holds what he can. The 7th Legion bleeds for every mile of frozen ground. High Commander Wyrmbane has orders from Highlord Bolvar Fordragon — push east, past the dragonshrines, toward a black gate in a black mountain."] = "溫特加德要塞緊攀在龍骨荒野殘破的邊緣，夾在頭頂上的納克薩瑪斯與從腐屍原野湧出的瘟疫散播者之間。奧古斯特‧敵錘公爵竭力守住所能守住的一切。第七軍團為了每一哩冰凍的土地流血犧牲。高階指揮官龍禍接獲大領主伯瓦爾‧弗塔根的命令——向東推進，越過巨龍聖壇，直指一座黑色山脈中的黑色大門。"
L["Wise Mari"] = "智者瑪利"
L["Witch Doctor Kejabu"] = "巫醫科加布"
L["Witch Doctor Kejabu had a plan that required a certain willingness to look like the enemy. Disguised as blood trolls, you slipped into Zalamar, one of the blood cult's most fortified settlements. Inside you found something worse than blood trolls: Hir'eek, the bat loa, had turned. Corrupted by G'huun's influence, the loa now fed on his own people, demanding sacrifice. A corrupted loa was more dangerous than no loa at all. You poisoned the blood troll's brood, stripped away their rituals, and faced Hir'eek at the heart of his lair. The bat loa fell. It was not a victory to celebrate."] = "巫醫科加布的計畫，需要你願意把自己扮成敵人的模樣。你偽裝成血食人妖，潛入血之教團防禦最嚴密的據點之一——札拉瑪。你在裡面發現了比血食人妖更糟的東西：蝙蝠羅亞希爾雷克已經變節。受到古翰的影響而腐化，這位羅亞如今以自己的子民為食，要求獻祭。一個遭腐化的羅亞，比沒有羅亞還要危險。你毒殺了血食人妖豢養的幼獸，破壞他們的儀式，並在希爾雷克巢穴的核心與他對決。蝙蝠羅亞倒下了。但這並不是值得慶祝的勝利。"
L["Witch Doctor Tzadah"] = "巫醫札妲"
L["Witch Hunt"] = "獵巫"
L["Witchrending"] = "剋制女巫"
L["With Air and Earth secured, Fire remained. You entered the Firelands — still scarred from Ragnaros' fall — and found a new Firelord reigning: Smolderon, younger and more calculating than his predecessor. Baron Scaldius served as intermediary while you proved yourself in trials of flame. The Brand of Damnation burned your skin as a mark of passage, and Smolderon's allegiance was won — grudgingly, but bound by elemental law. Rehgar Earthfury joined your champions, and your weapon was reforged with the power of all three elemental lords."] = "風與土已經穩固，只剩下火。你進入火源之界——那裡仍留著拉格納羅斯殞落的傷痕——發現一位新的火焰之王正在統治：斯莫德隆，他比前任更年輕，也更工於心計。斯卡迪奧男爵居中斡旋，你則在烈焰試煉中證明自己。「詛咒之矛」在你的皮膚上烙下通行的印記，你也贏得了斯莫德隆的效忠——雖然心不甘情不願，卻受到元素法則的約束。雷加‧地怒加入了你的勇士行列，你的武器也憑藉三位元素領主的力量得以重鑄。"
L["With clever engineering and fearless aerial operations, you dismantled a trogg-backed threat, defeated Sparkspanner, and proved Gnomeregan's ingenuity is stronger than ever."] = "憑藉巧妙的工程技術與無畏的空中行動，你瓦解了穴居人撐腰的威脅，擊敗火花扳手，證明了諾姆瑞根的創造力比以往更加強大。"
L["With Lordaeron newly reclaimed, old enemies resurfaced. The Scarlet Crusade established a foothold in Silverpine Forest, determined to purge the Forsaken from their ancestral lands. Under Lilian Voss's guidance, you gathered alchemical weapons, donned a stolen disguise, slipped into the enemy’s ranks, and opened the way for the Forsaken to strike back in force. When the dust settled, you stood as a proven champion — Forsaken by death, but not by purpose."] = "羅德隆才剛收復，宿敵便再度浮上檯面。血色十字軍在銀松森林建立據點，決心將被遺忘者從他們祖先的土地上清除殆盡。在莉莉安‧佛斯的指引下，你蒐集鍊金武器，換上偷來的偽裝，潛入敵軍陣營，為被遺忘者的全力反擊開路。塵埃落定後，你已是一位證明了自身價值的勇士——死亡讓你被遺忘，但你從未遺忘自己的使命。"
L["With Niskara shattered, the Silver Hand stood triumphant. Arator the Redeemer — son of Turalyon and Alleria — joined your order, his half-elven heritage bridging every divide. Then came Lothraxion, a nathrezim infused with the Light itself — living proof that even demons could be redeemed. Lord Maxwell Tyrosus forged your weapon anew and bestowed the title of Highlord upon you — the first since the Lich King destroyed the original Silver Hand. A light in the darkness, brighter than ever."] = "尼斯卡拉被擊潰，白銀之手大獲全勝。救贖者阿拉特——圖拉揚與艾蘭里亞之子——加入了你的騎士團，他的半精靈血統跨越了所有隔閡。接著到來的是洛斯拉賽恩，一位被聖光灌注的納斯雷茲姆——他是連惡魔也能被救贖的活生生證明。麥斯威爾‧泰羅索斯領主為你重鑄武器，並授予你大領主的頭銜——這是自巫妖王摧毀最初的白銀之手以來的第一人。闇境明燈，比以往更加耀眼。"
L["With Prince in Tow"] = "拖著王子走"
L["With Sinfall secured, the rebellion moves to rescue Prince Renathal from the ruins of his failed uprising."] = "罪殞城已經穩固，反抗軍隨即行動，要從起義失敗後的廢墟中救出雷納瑟王子。"
L["With Sylvanas defeated and the war over, Lilian Voss and Calia Menethil lead the Forsaken back to Lordaeron. The city is choked with Blight, the halls of Undercity dark and half-collapsed. Together they fight to reclaim it — cleansing what can be saved, burying what cannot — and at the end, form the Desolate Council: a governing body the Forsaken chose for themselves."] = "希瓦娜斯戰敗，戰爭結束，莉莉安‧佛斯與卡莉雅‧米奈希爾帶領被遺忘者重返羅德隆。城市被荒疫籠罩，幽暗城的大廳漆黑一片、半數坍塌。她們攜手奮戰，收復家園——淨化尚能挽救的，埋葬無法挽回的——最後成立了荒寂議會：一個由被遺忘者自己選擇的統治機構。"
L["With the Idol recovered, recruit Hamuul and Mylune as champions and power the Dreamgrove's portal to prepare for the final battle."] = "塑像已經尋回，招募哈繆爾與蜜露恩成為勇士，並為幻夢之林的傳送門注入能量，為最終決戰做好準備。"
L["With the Serpent's Heart restored, you travel to Yu'lon's temple and help the sages prepare for her rebirth."] = "蟠龍之心已經修復，你前往玉瓏的神殿，協助賢者們為她的重生做好準備。"
L["With the south secured, Marshal Reade led the march on Corlain — the ancestral seat of House Waycrest, now a fortress of the Heartsbane Coven. The first watch was grim: the town was sealed behind a magical barrier that killed anything that touched it. Inquisitor Notley scouted the approach while you gathered precious metals and crafted an improvised arsenal of witchrending weapons. Lucille herself struck the final blow against the barrier, shattering it with the Order's combined power. The road to Waycrest Manor was open."] = "南方已經穩固，瑞德元帥率軍進攻寇連恩——這裡是威奎斯特家族的祖居，如今已成為禍心巫會的要塞。第一個據點的情況十分嚴峻：整座城鎮被一道魔法屏障封鎖，任何碰觸它的東西都會喪命。審判官諾特利負責偵察進路，你則蒐集貴金屬，臨時打造出一批破巫武器。露西爾親自對屏障施以最後一擊，以餘燼騎士團的合力將其粉碎。通往威奎斯特莊園的道路就此敞開。"
L["With the Unseen Path established, you set about building its strength. Loren Stormhoof was the first to answer the call, pledging as champion. Tactician Tinderfell organized scouts and soldiers, dispatching them across the Broken Isles to gather intelligence and hold the line while you prepared for the greater battles ahead."] = "隱匿之徑成立後，你開始壯大它的力量。洛倫‧風暴之蹄第一個響應號召，宣誓成為勇士。謀士柴薪組織偵察兵與士兵，派遣他們前往破碎群島各地蒐集情報、堅守防線，而你則為往後更大的戰役做準備。"
L["Word came of monks captured by the vrykul in Stormheim. Angus Ironfist, a massive Pandaren brawler, led you into the frozen north where your brothers and sisters were being held. You quelled the tide of enemies, rebuilt the shattered defenses brick by brick, and freed every last monk. Hiro — a humble fighter who became a hero that day — and Sylara Steelsong joined your growing roster of champions. No monk would be left behind."] = "消息傳來，有武僧在斯鐸海姆遭維酷人俘虜。身材魁梧的熊貓人格鬥家安格斯‧鐵拳，帶你前往冰天雪地的北方，你的師兄弟姊妹就被囚禁在那裡。你遏止了蜂擁而來的敵人，一磚一瓦地重建殘破的防禦工事，並救出了每一位武僧。希羅——一位在那天成為英雄的謙遜鬥士——與席拉蕾‧鋼曲加入了你日益壯大的勇士陣容。絕不丟下任何一位武僧。"
L["Word on the Winds"] = "風之語"
L["Worthy of the Title"] = "襯托威名"
L["Wounds Beyond Flesh"] = "非實質的傷口"
L["Wrath and Justice"] = "正義怒火"
L["Wrath of the Lich King"] = "巫妖王之怒"
L["Writing on the Wall"] = "牆上的記述"
L["Written in Stone"] = "石中秘文"
L["Wyrmrest Temple, Dragonblight"] = "龍眠神殿（龍骨荒野）"
L["Xal'atath, Blade of the Black Empire"] = "夏拉薩斯，黑色帝國之刃"
L["Xiao"] = "曉"
L["Xiao, the Eater"] = "貪吃的曉"
L["Yalia Sagewhisper"] = "雅里亞‧賢語者"
L["Years later, Lilian served the Horde on the shores of Kul Tiras. While Nathanos Blightcaller secured a mountain outpost, Lilian led you through Bridgeport — sabotaging foundries, planting explosives, and riding through the flames of your own making. She was efficient, ruthless, and completely in her element. The girl who once trembled in Deathknell was gone."] = "多年後，莉莉安在庫爾提拉斯的海岸為部落效力。納薩諾斯‧凋零者負責攻占一座山區前哨，莉莉安則帶著你穿越橋梁港——破壞鑄造廠、安置炸藥，並策馬穿越你們親手點燃的烈焰。她效率十足、冷酷無情，完全如魚得水。那個曾在喪鐘鎮瑟瑟發抖的女孩已經不在了。"
L["Years passed before Lilian surfaced again — this time as a hooded figure lurking inside the Scarlet Halls. She hired you to slaughter your way through the Crusade's ranks and steal their membership records. Every name on that list was a target. Lilian Voss was no longer running from the Crusade — she was hunting them down, one by one."] = "多年之後，莉莉安才再度現身——這一次，她是潛伏在血色大廳中的一名戴兜帽的神祕人物。她僱用你殺穿十字軍的陣營，偷走他們的成員名冊。名冊上的每一個名字都是目標。莉莉安‧佛斯不再逃避十字軍——她正在一個接一個地獵殺他們。"
L["Yeti to Rumble"] = "大戰雪人"
L["You answered Khadgar's call and journeyed into the ancient city of Suramar, finding it sealed behind a shimmering barrier of arcane power. Beyond the wall, you discovered First Arcanist Thalyssra — once a leader of the Nightborne, now exiled and starving for mana. Together you claimed the ruins of Shal'Aran as a hidden refuge, a fragile spark of rebellion in the shadow of the Grand Magistrix."] = "你響應卡德加的召喚，前往古城蘇拉瑪爾，卻發現它被一道閃爍的秘法屏障封鎖。在屏障之外，你找到了首席秘法師薩莉瑟拉——她曾是夜裔精靈的領袖之一，如今遭到放逐，渴求著魔力。你們一同將沙亞蘭的廢墟作為隱密的避難所，在大魔導師的陰影下點燃一絲脆弱的反抗星火。"
L["You built The Uncrowned from a whisper into a force, recruiting legendary rogues like Vanessa VanCleef and Garona Halforcen as champions. From the Chamber of Shadows beneath Dalaran, you established a network of operatives across the Broken Isles and ensured the order's school of roguery could train the next generation of shadows."] = "你讓無冕者從一句耳語成長為一股勢力，招募了凡妮莎‧范克里夫與迦羅娜‧半血等傳奇盜賊作為勇士。你從達拉然地底的潛影之廳出發，在破碎群島各地建立起特務網絡，並確保組織的盜賊學院能培育出下一代的暗影。"
L["You Can't Take the Sky from Me"] = "別想奪走我的天空"
L["You infiltrated the arcwine vineyards that kept Suramar's populace docile and dependent on Elisande's generosity. Working with Vintner Iltheux and the defiant Margaux, you sabotaged the production, poisoned the supply, and struck at the very system of control the Grand Magistrix had built. When Margaux fell to the Duskwatch's retribution, you ensured her sacrifice was not in vain — the rebellion now had its own supply of arcwine and the loyalty of those she inspired."] = "你潛入秘法酒葡萄園——正是這些秘法酒讓蘇拉瑪爾的民眾溫順聽話，依賴艾莉珊德的恩賜。你與葡萄酒商勒修斯和不屈的瑪苟合作，破壞生產、在供應中下毒，直擊大魔導師所建立的控制體系。當瑪苟遭到暮衛軍的報復而倒下時，你確保她的犧牲沒有白費——反抗軍如今擁有自己的秘法酒來源，以及那些受她感召之人的忠誠。"
L["You located Chief Telemancer Oculeth in his ruined workshop, surrounded by the wreckage of his life's work. Together you restored fragments of the ancient telemancy network, reactivating portals that would allow the rebels to move unseen across Suramar. The old telemancer's genius may have dulled with hunger, but his loyalty to Thalyssra never wavered."] = "你在殘破的工坊中找到了首席傳送師歐庫雷斯，他身邊盡是畢生心血的殘骸。你們一同修復了古老傳送網絡的片段，重新啟動傳送門，讓反抗軍能神不知鬼不覺地穿梭蘇拉瑪爾各地。這位年邁傳送師的天賦或許因飢餓而變得遲鈍，但他對薩莉瑟拉的忠誠從未動搖。"
L["You opened your eyes in the crypt of Deathknell, raised by the Val'kyr as one of the Forsaken. Among the newly risen was a young woman trembling with rage — Lilian Voss, daughter of the Scarlet Crusade's High Priest. While you accepted your new existence, she could not. She fled into the darkness, refusing to believe what she had become."] = "你在喪鐘鎮的墓穴中睜開雙眼，被華爾琪喚起，成為被遺忘者的一員。在新復生的人當中，有一名因憤怒而顫抖的年輕女子——莉莉安‧佛斯，血色十字軍高階祭司的女兒。你接受了自己的新存在，她卻無法接受。她逃入黑暗之中，拒絕相信自己變成了什麼。"
L["You slipped into the Waning Crescent, a forgotten slum where nightfallen refugees huddled in the shadows of Suramar City. Working alongside Silgryn, you established supply lines, freed imprisoned allies, and built a network of safe houses right beneath the Duskwatch's nose. What began as a handful of desperate exiles became the backbone of an underground resistance."] = "你潛入了弦月區——這片被遺忘的貧民窟裡，夜落精靈難民蜷縮在蘇拉瑪爾城的陰影之中。你與西爾格林並肩合作，建立補給線、解救遭囚禁的盟友，更在暮衛的眼皮底下佈下一張安全屋網絡。起初只是一小群走投無路的流亡者，最後竟成了地下反抗軍的中堅力量。"
L["You ventured into the ley line tunnels beneath Suramar, fighting corrupted creatures to restore the flow of ancient mana to Shal'Aran. The cavern hummed back to life as power surged through its crystalline conduits, giving the nightfallen refugees a lifeline against the withering that threatened to consume them all."] = "你深入蘇拉瑪爾地底的地脈隧道，與腐化的生物交戰，讓遠古魔力重新流向沙亞蘭。隨著力量湧過水晶導管，洞窟再度嗡鳴復甦，為夜落精靈難民帶來一線生機，得以抵禦那幾乎要將所有人吞噬的凋萎。"
L["You're Either With Us Or..."] = "不是朋友就是…"
L["Your Attention, Please"] = "照過來!"
L["Your Training Starts Now"] = "訓練正式展開"
L["Yu'lon's rebirth did not end the war. It only made the cost clearer. The Alliance returned to Pearlfin Village; the Horde returned to Grookin Hill. Both sides prepared their local allies for the next blow, and Cho called for help with the last piece of an ancient puzzle. Then the seal broke. The Serpent's Heart cracked under the weight of fear, anger, and suspicion. Jade became weapon and prison, friends were scattered in the fallout, and the Sha of Doubt rose from the ruin. The Jade Forest's lesson had become impossible to ignore: the enemy was not only across the battlefield."] = "玉龍的重生並未結束戰爭，只讓代價更加清晰。聯盟回到珠鰭村，部落回到葛魯山丘。雙方都在為下一波攻擊整備當地的盟友，周則請求協助尋回一道遠古謎題的最後一塊。接著，封印破裂了。蟠龍之心在恐懼、憤怒與猜疑的重壓下崩裂。玉石化為武器與牢籠，朋友在餘波中四散，疑惑之煞自廢墟中升起。翠玉林的教訓已無法忽視：敵人不只在戰場的另一端。"
L["Zabra Hexx"] = "薩布拉‧海克斯"
