L["For the Alliance, the Scarlet Crusade first looked like a distant Lordaeron problem: troubling enough for Brother Crowley to send word to Brother Anton, and troubling enough for Anton to send you onward. Raleigh the Devout understood what the red tabards meant. The Monastery was not merely a garrison. It was the heart of a militant faith losing its way."] = "對聯盟而言，血色十字軍起初看似只是遠在羅德隆的麻煩：棘手到足以讓克羅雷修士捎信給安東修士，也棘手到讓安東把你派往更遠的地方。虔誠的萊雷恩明白那些紅色戰袍代表著什麼。修道院不只是一座駐軍據點，而是一個正逐漸迷失方向的好戰信仰的核心。"
