L["After the first foothold in Zereth Mortis was secured, Uther arrived in Haven with news from Oribos: Sylvanas had awakened. Her soul had been split since Frostmourne killed her, and the restored fragment forced her to face the Banshee Queen's atrocities as her own. In the vision Uther shared, the Ranger-General saw Teldrassil burn, rejected the comfort of pretending those crimes belonged to someone else, and chose to wake. The campaign then turned back to Zereth Mortis. Elder Ara led you through a pilgrimage to repair the ancient translocator to the Sepulcher. At the end, Sylvanas stood with Uther, Jaina, and Bolvar before the raid entrance. She knew Anduin was the key, and Uther convinced Jaina to let Sylvanas help free him."] = "在澤瑞斯莫提斯站穩第一個據點後，烏瑟帶著來自奧睿博司的消息抵達避風港：希瓦娜斯甦醒了。自從霜之哀傷殺死她之後，她的靈魂便一分為二，而歸還的碎片迫使她承認，女妖之王的暴行皆出自她自己之手。在烏瑟分享的幻象中，這位遊俠將軍目睹泰達希爾燃燒，拒絕假裝那些罪行屬於別人以求慰藉，並選擇醒來。戰役接著回到澤瑞斯莫提斯。亞拉長老帶領你踏上朝聖之旅，修復通往聖塚的遠古傳送器。最後，希瓦娜斯與烏瑟、珍娜和柏瓦爾一同站在團隊副本入口前。她知道安杜因是關鍵，而烏瑟說服珍娜讓希瓦娜斯協助解救他。"
L["Aggressive Excavation"] = "強行挖掘"
L["Anduin has been rescued, but the Jailer still commands Domination. Bolvar and the Primus seek a way to turn the broken helm into a weapon of free will."] = "安杜因已獲救，但閻獄之主仍掌控著統御之力。柏瓦爾與統御者正設法將破碎的頭盔化為自由意志的武器。"
L["After Anduin was freed, the way forward was still blocked by the Jailer's Domination magic. Bolvar, Darion, Anduin, and Sylvanas all carried scars from the helm, the blade, or the will behind them. Their memories became part of the answer. In Bastion, Sylvanas faced the wound of what she had done and named the truth plainly: there was no absolution waiting inside a shard of memory, only the choice to keep resisting. The Primus reforged the Helm of Domination into the Crown of Wills, a symbol not of command, but of defiance. With it, Zovaal could finally be faced."] = "安杜因獲救後，前路仍被閻獄之主的統御魔法阻擋。柏瓦爾、達瑞安、安杜因與希瓦娜斯身上，都留著那頂頭盔、那把劍，或其背後意志所造成的傷痕。他們的記憶成了答案的一部分。在昇靈堡，希瓦娜斯直面自己所犯下的罪孽，並坦白說出真相：記憶碎片中沒有等待她的赦免，只有繼續抗爭的選擇。統御者將統御之盔重鑄為意志之冠——它象徵的不是號令，而是反抗。有了它，終於能與佐瓦爾正面對決。"
L["A Gathering of Covenants"] = "誓盟雲集"
L["Anduin steals the Archon's sigil, and Sylvanas moves on Ardenweald. Tyrande finally catches her in the Heart of the Forest."] = "安杜因奪走大執政官的印記，希瓦娜斯轉而進軍亞登曠野。泰蘭妲終於在森林之心追上了她。"
L["Before the assault on the Sanctum, Bolvar saw fragments of what was happening inside Torghast. The Jailer forged Kingsmourne, a mourneblade shaped around Anduin's own weapon and a soul crystal. Sylvanas brought the blade to Anduin and demanded he join their cause willingly or be made to serve. Anduin saw the wound she was trying to hide: she kept offering him the choice Arthas had stolen from her. Blizzard later removed or auto-completed much of this Torghast questline for catch-up characters, but the vision is the emotional bridge into Chains of Domination."] = "在進攻聖所之前，柏瓦爾看見了托迦司內部情景的片段。閻獄之主鍛造了王之哀傷——一把以安杜因自身的武器與一顆靈魂水晶為基礎打造的哀傷之劍。希瓦娜斯將這把劍交給安杜因，要求他心甘情願加入他們，否則就被迫效命。安杜因看穿了她試圖隱藏的傷口：她一再給他的選擇，正是阿薩斯當年從她手中奪走的。暴雪後來為追趕進度的角色移除或自動完成了這段托迦司任務線的大部分內容，但這段幻象是通往「統御之鍊」的情感橋梁。"
L["Begins after your covenant campaign reaches The Search for Baine. Later characters may be offered a skip to Korthia; skipping completes this chapter."] = "在你的盟約戰役進行到「尋找貝恩」後開始。後期角色可能會獲得直接跳到科西亞的選項；選擇跳過將直接完成本章。"
L["Bolvar's visions reveal the Jailer's next weapon: Anduin, bound to a mourneblade. Sylvanas still tries to call it a choice."] = "柏瓦爾的幻象揭露了閻獄之主的下一把武器：被哀傷之劍束縛的安杜因。希瓦娜斯仍試圖稱之為一種選擇。"
L["Can't Turn Our Backs"] = "不能坐視不管"
L["Chains of Domination"] = "統御之鍊"
L["Complete Zereth Mortis campaign chapter 3, Forming an Understanding. This becomes available from Uther in Haven after The Way Forward."] = "完成澤瑞斯莫提斯戰役第3章「建立共識」。完成「前進之路」後，可於避風港向烏瑟接取。"
L["Crown of Wills"] = "意志之冠"
