L["News from Oribos"] = "來自奧睿博司的消息"
L["One Half of the Equation"] = "等式的一半"
L["Oppress and Destroy"] = "壓制並摧毀"
L["Our Last Option"] = "走投無路的選擇"
L["Pluck from the Vines"] = "藤蔓摘採"
L["Reclaiming Provis Esper"] = "奪回魂靈供應區"
L["Report to Oribos"] = "前往奧睿博司回報"
L["Remnants of the First Ones"] = "首創者的殘片"
L["Root of the Problem"] = "問題的根源"
L["Keeper's Respite, Korthia"] = "守衛者歇息地（科西亞）"
L["Sanctum of Domination"] = "統御聖所"
L["Shattered Legacies"] = "破碎的傳承"
L["Domination's Grasp"] = "統御之握"
L["Sepulcher of the First Ones"] = "首創者聖塚"
L["Storming the Sanctum"] = "猛攻聖所"
L["The assault on the Sanctum of Domination carried the covenants into the Jailer's seat of power. Sylvanas waited at the top of Torghast, fighting across shattered chains and the edge of the Maw while the Jailer dragged Oribos toward his prison. When Zovaal spoke of remaking reality so all would serve, Sylvanas finally heard Arthas in his words. She turned on him. The Jailer answered by returning the soul fragment Frostmourne had torn from her at Silvermoon, then left her unconscious at the mercy of those she had betrayed. She was defeated, but not judged. Not yet."] = "進攻統御聖所，讓各盟約直搗閻獄之主的權力核心。希瓦娜斯在托迦司頂端等候，在破碎的鎖鍊與淵喉邊緣間奮戰，同時閻獄之主正將奧睿博司拖向他的牢獄。當佐瓦爾說起要重塑現實、讓萬物皆為其效命時，希瓦娜斯終於在他的話語中聽見了阿薩斯的聲音。她倒戈相向。閻獄之主的回應，是歸還霜之哀傷當年在銀月城從她身上撕裂的靈魂碎片，接著將昏迷的她留給那些曾被她背叛的人處置。她被擊敗了，卻尚未受審。還沒有。"
L["The covenants assault the Jailer's fortress in Torghast. At the summit waits Sylvanas, and the battle ends with the choice that makes News from Oribos possible."] = "各盟約進攻閻獄之主位於托迦司的堡壘。希瓦娜斯在頂端等候，而這場戰鬥以一個抉擇告終——正是這個抉擇，讓「來自奧睿博司的消息」得以發生。"
L["The path through the Sepulcher reaches Anduin at last. Freeing him from Kingsmourne sets the stage for the Crown of Wills."] = "穿越聖塚的道路終於通往安杜因。將他從王之哀傷中解放，為意志之冠鋪好了路。"
L["Within the Sepulcher, the heroes found Anduin still bound to the Jailer's will. The fight was not only to defeat him, but to reach the part of him still resisting. In the end, Anduin found the strength to help shatter Kingsmourne from within. Sylvanas's warning had been true: saving Anduin was the key to opposing Zovaal's design."] = "在聖塚之中，英雄們發現安杜因仍受閻獄之主的意志束縛。這場戰鬥不只是要打敗他，更是要觸及他心中仍在抵抗的那一部分。最終，安杜因找到了力量，從內部協助粉碎王之哀傷。希瓦娜斯的警告是對的：拯救安杜因，正是對抗佐瓦爾計畫的關鍵。"
L["Take Charge"] = "控制能量"
L["Testing One Two"] = "牛刀小試"
L["The Broken Crown"] = "破碎王冠"
L["The Battle of Ardenweald"] = "亞登曠野之戰"
L["The Crown of Wills"] = "意志之冠"
L["The First Move"] = "第一步棋"
L["The Heart of Ardenweald"] = "亞登曠野之心"
L["The Jailer's next move began in Bastion. Anduin, dominated through Kingsmourne, struck down the Archon and took her sigil while Sylvanas watched the plan unfold. Bolvar gathered the covenants in Oribos, and the war rushed to Ardenweald before the Winter Queen's sigil could be taken next. There, beneath the Heart of the Forest, Tyrande Whisperwind caught Sylvanas at last. Elune's wrath burned through her, but the Night Warrior's power faded before the killing blow. Sylvanas escaped, and the covenants turned toward Korthia and the Sanctum of Domination."] = "閻獄之主的下一步始於昇靈堡。透過王之哀傷受到統御的安杜因擊倒了大執政官並奪走她的印記，希瓦娜斯則在一旁看著計畫展開。柏瓦爾在奧睿博司集結各盟約，戰火隨即延燒至亞登曠野，要搶在凜冬女王的印記被奪走之前。在那裡的森林之心下方，泰蘭妲‧語風終於逮住了希瓦娜斯。伊露恩的怒火在她身上灼燒，但夜戰士的力量在致命一擊前消退了。希瓦娜斯逃脫，各盟約隨後轉向科西亞與統御聖所。"
L["The Not-Scientific Method"] = "不科學的方法"
L["The Pilgrim's Journey"] = "朝聖之旅"
L["The Pilgrimage Ends"] = "朝聖之旅結束"
L["The Primus"] = "統御者"
L["Torghast Visions"] = "托迦司幻象"
L["Two Paths to Tread"] = "兩條道路"
L["Unchecked Growth"] = "失控的增生"
L["Uther appears in Haven with news from Oribos. Sylvanas has awakened, but reaching the Sepulcher means earning the Enlightened's help first."] = "烏瑟帶著來自奧睿博司的消息出現在避風港。希瓦娜斯已經甦醒，但要抵達聖塚，必須先贏得開悟者的協助。"
L["What Makes Us Strong"] = "我們之所以強大的原因"
L["What We Overcome"] = "我們克服的困難"
L["What We Wish to Forget"] = "我們想要遺忘的傷痛"
L["Where the Memory Resides"] = "記憶所在之處"
L["Where There's a Pilgrim, There's a Way"] = "有朝聖者的地方，就有道路"
L["Voices of the Eternal"] = "永恆者之聲"
L["overlook behind Pilgrim's Grace"] = "朝聖者之恩後方的瞭望臺"
L["A Cage for Alleria"] = "給艾蘭里亞的籠子"
L["A vision of Quel'Thalas in shadow sends Arator looking for the Windrunners. His search reaches the Maw, where Sylvanas is still freeing the souls she condemned."] = "一幅奎爾薩拉斯籠罩於暗影中的幻象，讓阿拉特開始尋找風行者家族。他的追尋一路來到淵喉，希瓦娜斯仍在那裡解放她曾經判入此地的靈魂。"
L["A Void Test of Wills"] = "虛無的意志考驗"
L["Alleria Windrunner"] = "艾蘭里亞‧風行者"
L["Arator"] = "阿拉特"
L["Be careful with the Threads of Fate choice from Fatescribe Roh-Tahl in Oribos. Choosing Threads of Fate skips the Shadowlands leveling campaign and marks Revendreth's main story quests complete, so use the replay storyline option if you want to play this chapter."] = "在奧睿博司向述命者羅塔爾做出「命運之線」選擇時務必小心。選擇命運之線會跳過暗影之境的升級戰役，並將瑞文崔斯的主線任務標記為已完成；若想遊玩本章，請使用重玩故事線的選項。"
L["Blessings Be Upon You"] = "祝福你"
L["Bringer of the Void"] = "虛無使者"
L["Chaos Control"] = "混沌管理"
L["Determination"] = "決心"
L["Distant Echoes"] = "遙遠的回音"
L["Do You Have a Spare?"] = "你有多的籠子嗎？"
L["Excising the Incursion"] = "剷除入侵者"
L["Here Goes Something"] = "一試便知"
L["In Her Shadow"] = "在她的陰影中"
L["Mad Space"] = "瘋狂空間"
