L["Off to Tazavesh"] = "前往塔札維許"
L["Off to Tazavesh, Again"] = "再次前往塔札維許"
L["outside the Dornogal bank"] = "多恩諾加銀行外"
L["Preludes and Preparations"] = "前期準備"
L["Repent of the Highborne"] = "高等精靈的懺悔"
L["Repossession is Nine-Tenths of the Law"] = "先搶先贏"
L["Returning to Life"] = "重返生命"
L["Silver Hand Squire"] = "白銀之手侍從"
L["Tag, You're It"] = "捉到你了"
L["The Eleventh Hour"] = "最後一刻"
L["The Final Hazard"] = "最後的危險"
L["The Long Vigil"] = "漫長的守望"
L["The Parent Trap"] = "親情陷阱"
L["The Warning"] = "警告"
L["Those As Well"] = "舉手之勞"
L["To Cleanse Shadow's Stain"] = "淨化暗影的汙點"
L["Ve'nari"] = "維娜里"
L["Vereesa Windrunner"] = "凡蕾莎‧風行者"
L["Vereesa's Tale"] = "凡蕾莎的故事"
L["What Might Come"] = "可能的結果"
L["Where in K'aresh is Alleria Windrunner?"] = "艾蘭里亞‧風行者究竟身在何方？"
L["Your trainer sends you to Moonglade for lessons that cannot be taught in a city. The Cenarion Circle has work for young druids who are ready to listen to spirits, heal sick beasts, and follow the call of distant waters."] = "你的訓練師派你前往月光林地，學習那些在城市裡學不到的課程。塞納里奧議會有工作要交給年輕的德魯伊——那些準備好聆聽先靈、治療病弱野獸，並追隨遠方水域呼喚的人。"
L["Speak with Duthorian Rall and take up the Tome of Valor. A paladin's lessons are not only prayers; they ask for aid given, judgment shown, and materials gathered with care.\n\nFollow the order's tests from early duty to the rites reserved for those who have carried the Light long enough to be trusted with more."] = "與達索瑞恩·拉爾交談，接下勇氣之書。聖騎士的課程不只是禱告；它要求你伸出援手、展現公正的判斷，並用心蒐集材料。\n\n追隨騎士團的試煉，從最初的職責一路走向那些專為長久承載聖光、值得託付更多重任之人而保留的儀式。"
L["Master Mathias Shaw and Shenthul do not teach by lecture. They send rogues into guarded places, locked boxes, and situations where an antidote matters as much as a blade.\n\nBegin with your faction's poison work, then follow the hints that lead beyond city trainers into a wider trade of signals and reputation."] = "馬迪亞斯‧肖爾大師與申蘇爾從不靠講課授業。他們會把盜賊派進戒備森嚴的地方、帶到上鎖的箱子前，或丟進解毒劑與刀刃同樣重要的處境之中。\n\n從你所屬陣營的毒藥工作開始，再循著線索走出城市訓練師的範圍，踏入一門關乎暗號與聲望、更為廣闊的行當。"
L["Your first totem begins with a call, not a command. The elements answer through trials, offerings, and long walks between trainers, spirits, and hidden shrines.\n\nFollow earth, fire, water, and air as each power is earned in turn. Later, the same lessons point toward a deeper test of balance."] = "你的第一個圖騰始於一聲呼喚，而非一道命令。元素會透過試煉、供品，以及在訓練師、先靈與隱密神龕之間的長途跋涉來回應你。\n\n依序追隨大地、火焰、水與空氣，逐一贏得每一種力量。之後，同樣的課程將引領你迎向一場更深層的平衡試煉。"
L["Warlock trainers do not offer power freely. They give names, errands, and circles, then ask whether you can bind what answers.\n\nBegin with the first summons and follow the darker lessons through demons, tomes, mounts, and bargains that always ask for more than coin."] = "術士訓練師從不白白給予力量。他們給你名字、差事與法陣，然後問你能否束縛那些回應召喚之物。\n\n從最初的召喚開始，追隨那些更黑暗的課程，穿越惡魔、典籍、坐騎，以及總是索求比金幣更多代價的交易。"
L["Your warrior trainer has a practical lesson first: learn to stand, endure, and fight with discipline. After that, older tests wait beyond the starting grounds.\n\nSeek the instructors who send warriors to brawls, islands, charms, and a windwatcher's summons. The reward is a weapon, but the road is the real trial."] = "你的戰士訓練師要先教你實用的一課：學會站穩、忍耐，並以紀律戰鬥。之後，更古老的試煉正在新手區之外等著你。\n\n去找那些會把戰士派去參加鬥毆、前往島嶼、尋找護符，或回應觀風者召喚的教官。獎勵是一把武器，但這段旅程本身才是真正的試煉。"
L["Apothecary Johaan has work in Brill, and it is not the sort of work the living would approve of. The Forsaken need samples, records, and willing hands if they are to learn what can still kill the dead.\n\nBegin with the Royal Apothecary Society's errands in Tirisfal and follow the plague work into Silverpine and Hillsbrad. Each vial answers one question and raises another."] = "藥劑師喬漢在布瑞爾有工作要交代，而且不是活人會認同的那種。若被遺忘者想知道還有什麼能殺死亡者，他們需要樣本、紀錄，以及願意出力的人手。\n\n從提里斯法的皇家藥劑師協會差事開始，追隨瘟疫研究深入銀松森林與希爾斯布萊德。每一瓶藥劑解答一個問題，也帶出另一個問題。"
L["North of Brill, the Agamand Mills still carry the family name. Coleman Farthing wants proof of what happened there, Deathguard Dillinger wants the dead cleared out, and Magistrate Sevren has heard enough about the family crypt to be concerned.\n\nSearch the old estate, bring back what the Forsaken ask for, and see why Tirisfal's dead rarely stay where they are put."] = "在布瑞爾北方，阿加曼德磨坊仍冠著這個家族的姓氏。庫勒曼·法席恩想要證據，查明那裡究竟發生了什麼；亡靈衛兵迪林格爾想把亡者清掃乾淨；執政官塞弗倫則對家族墓穴耳聞已多，不禁心生憂慮。\n\n搜索這片古老的莊園，帶回被遺忘者要的東西，看看為何提里斯法的亡者很少安分地待在原地。"
L["Auberdine's watchers have seen trouble near the Tower of Althalaxx. Speak with Balthule Shadowstrike and learn what the Cult of the Dark Strand is doing on the northern coast.\n\nWhat begins as a report from Darkshore pulls you toward Ashenvale, where parchments, gems, and old corruption point to a threat still gathering strength."] = "奧伯丁的守望者察覺奧薩拉克斯之塔附近出了狀況。與巴蘇爾‧影擊交談，查明黑暗之環教派在北方海岸有何圖謀。\n\n起初只是來自黑海岸的一份報告，卻將你引向梣谷——在那裡，羊皮紙、寶石與古老的腐化，都指向一股仍在積聚力量的威脅。"
L["The Sepulcher needs help holding Silverpine Forest. Worgen stalk the roads, Dalaran mages keep their own counsel at Ambermill, and rumors from Shadowfang Keep have not grown quieter.\n\nTake the Forsaken orders one by one and learn why the forest still refuses to be claimed."] = "瑟伯切爾需要人手協助守住銀松森林。狼人在道路上遊蕩，達拉然的法師在安伯米爾自行其是，而影牙城堡傳出的流言也從未平息。\n\n逐一接下被遺忘者的命令，了解這片森林為何至今仍不肯臣服。"
L["High Executor Darthalia has work for anyone willing to serve Tarren Mill. The humans of Hillsbrad still farm, trade, and guard the roads as if the Forsaken claim means nothing.\n\nReport for orders and carry the campaign from the fields to the mines and beyond. Darthalia will tell you who must fall next."] = "高階執行官達薩利亞要找任何願意為塔倫米爾效力的人。希爾斯布萊德的人類依然耕作、交易、守衛道路，彷彿被遺忘者的主權宣告毫無意義。\n\n前去報到領取命令，將戰事從田野推進到礦坑，乃至更遠的地方。達薩利亞會告訴你下一個該倒下的是誰。"
L["Marlene Redpath asks you to find her niece Pamela in Darrowshire. In the ruins, a lonely child is still waiting for family and trying to remember where her doll has gone.\n\nBegin with Pamela's small request and follow the Redpath family through old grief, missing records, and the question of what really happened on Darrowshire's last night."] = "瑪萊恩‧雷德帕斯請你到達隆郡尋找她的姪女帕米拉。在廢墟中，一個孤單的孩子仍在等待家人，努力回想她的娃娃去了哪裡。\n\n從帕米拉的小小請求開始，追隨雷德帕斯一家穿越往日的悲痛、遺失的紀錄，以及達隆郡最後一夜究竟發生了什麼的謎團。"
L["Deputy Willem has a simple problem near Northshire: thieves in red masks have stolen from the abbey's vineyards. In Elwynn and Westfall, the same masks keep turning up in places they should not.\n\nHelp the local marshals and the People's Militia follow the Defias trail. What begins as bandit work soon asks who is organizing it, and why."] = "維里副隊長在北郡附近遇上一個簡單的麻煩：戴著紅面具的盜賊偷走了修道院葡萄園的東西。在艾爾文與西部荒野，同樣的面具接連出現在不該出現的地方。\n\n協助當地的治安官與人民軍追查迪菲亞的蹤跡。起初只是對付盜匪，很快就得追問：是誰在背後組織這一切，又是為了什麼。"
L["Darkshire keeps its lanterns lit because the woods do not. Commander Althea Ebonlocke needs help with the Night Watch, and every road out of town seems to carry another rumor, corpse, or warning.\n\nTake up the town's work and follow Duskwood's troubles as the locals give them to you: graves, worgen, missing people, and names spoken carefully after dark."] = "森林一片漆黑，所以夜色鎮的燈火從不熄滅。指揮官奧爾希雅‧埃伯洛克需要人手協助守夜人，而每一條出城的道路似乎都會帶來另一則傳聞、另一具屍體，或另一個警告。\n\n接下鎮上的差事，跟著當地人的委託追查暮色森林的種種麻煩：墳墓、狼人、失蹤者，以及入夜後被人小心說出口的名字。"
L["At the edge of the Blasted Lands, a fallen hero still waits for orders that never came. His regiment is gone, and the demons beyond Nethergarde have had years to make use of what was left behind.\n\nListen to the dead man's account and follow the scattered trail of soldiers, relics, and old command. The road is long because the failure was not simple."] = "在詛咒之地的邊緣，一位殞落的英雄仍在等待永遠不會到來的命令。他的部隊已不復存在，而守望堡外的惡魔多年來早已利用了那些遺留下來的東西。\n\n聆聽這位亡者的陳述，循著散落各地的士兵、遺物與舊日指揮的線索前進。這段路之所以漫長，是因為那場失敗並不單純。"
L["Marshal Dughan has posted a bounty at Westbrook Garrison. A Riverpaw brute named Hogger is prowling the woods, and Stormwind wants proof that the roads are safer.\n\nTake the warrant, follow the ridge southwest, and see why the locals speak his name with more concern than a single gnoll should earn."] = "治安官杜漢在西泉要塞張貼了懸賞令。一個名叫霍格的河爪豺狼人暴徒正在林間出沒，暴風城需要證據證明道路變得更安全了。\n\n接下這張通緝令，沿著山脊往西南走，看看為何當地人提起他的名字時，那份憂慮遠超過一隻豺狼人應得的程度。"
L["Under the broken Thandol Span, a dwarf's remains lie where few travelers think to look. Among them is a letter that never reached the woman waiting in Ironforge.\n\nCarry Sully Balloo's words home and let Sara Balloo decide what should be done with them. Some duties begin after the battle is already over."] = "在殘破的薩多爾大橋下，一具矮人遺骸躺在少有旅人會留意的地方。遺物之中有一封信，始終沒能送到在鐵爐堡等候的那名女子手中。\n\n將蘇利‧巴魯的話語帶回家，讓薩拉‧巴魯決定該如何處置。有些責任，在戰鬥結束之後才真正開始。"
L["At the Crossroads, Mankrik is looking for his wife. He last saw her on the Gold Road, and the Barrens offers little comfort to anyone searching through quillboar territory.\n\nTake his question with you into the heat and dust. What you find, if you find anything, belongs first to the husband still waiting."] = "在十字路口，曼寇里克正在尋找他的妻子。他最後一次見到她是在黃金之路上，而對任何在野豬人領地中搜尋的人來說，貧瘠之地都難以給人慰藉。\n\n帶著他的疑問走進熱浪與塵土之中。無論你找到什麼——如果真能找到——都應該先交給那位仍在等待的丈夫。"
L["Feathermoon Stronghold expected a courier from Thalanaar. He never arrived, and the coast of Feralas has a way of swallowing small boats and easy answers.\n\nSearch the wreckage, carry back what proof you can, and follow the signs inland if the sea is not the whole story."] = "羽月要塞原本等著一名從薩蘭納爾來的信使。他始終沒有抵達，而菲拉斯的海岸向來會吞沒小船，也吞沒輕易的答案。\n\n搜索殘骸，盡可能帶回證據；若大海並非故事的全貌，就循著跡象深入內陸。"
L["Thomas has been asked to find an adventurer for Bishop DeLavey in Stormwind Keep. The bishop will not speak of the matter openly, only that discretion matters and the kingdom may have need of you.\n\nBegin in Stormwind and follow a quiet trail of favors, contacts, and rumors. What starts as a missing man soon points beyond a simple disappearance."] = "湯瑪斯奉命為暴風要塞的德拉維主教找一位冒險者。主教不願公開談論此事，只說行事務必低調，而王國或許需要你的協助。\n\n從暴風城出發，循著一條由人情、聯絡人與傳聞交織而成的隱密線索前進。起初只是一名男子失蹤，很快就顯示事情遠不只是單純的失蹤。"
L["In the Burning Steppes, Helendis Riverhorn has orders for the Alliance against black dragonkin gathering near Morgan's Vigil. In Kargath, Warlord Goretooth has a command for the Horde that points into Blackrock Spire.\n\nTake the first report and follow your faction's chain of summons, proofs, and dangerous names. The amulet at the end of the road is not given to anyone who has only heard rumors of dragons."] = "在燃燒平原，赫林迪斯‧河角為聯盟下達命令，對付在摩根的崗哨附近集結的黑龍族。在卡加斯，督軍高圖斯則為部落下令，矛頭直指黑石塔。\n\n接下第一份報告，循著你所屬陣營的一連串召喚、證明與危險名號前進。旅途盡頭的護符，不會交給只聽過巨龍傳聞的人。"
L["In Blackrock Depths, rumors about Princess Moira Bronzebeard have become too serious for Ironforge to ignore. The Dark Irons say one thing, the kingdom fears another, and no one outside the mountain has the full truth.\n\nEnter the depths on your faction's orders and find out what became of the princess. Rescue may not be as simple as it sounds."] = "在黑石深淵，關於茉艾拉‧銅鬚公主的傳聞已嚴重到鐵爐堡無法再置之不理。黑鐵矮人說的是一回事，王國擔心的又是另一回事，而山外沒有人知道全部的真相。\n\n奉你所屬陣營之命深入深淵，查明公主究竟遭遇了什麼。營救或許不像聽起來那麼簡單。"
L["Raene Wolfrunner sends you west from Astranaar to look for Teronis, who went searching for answers to the furbolg attacks and did not return.\n\nFollow his trail through Ashenvale's moonwells, ruins, and old magic. If the forest is being changed, Raene wants to know how, and who is helping it spread."] = "萊恩‧狼行者派你從阿斯特蘭納向西出發，尋找特羅尼斯——他為了查明熊怪襲擊的真相而離開，從此一去不返。\n\n循著他的足跡穿越梣谷的月井、遺跡與古老魔法。若森林正在被改變，萊恩想知道是如何改變的，又是誰在助長它的蔓延。"
L["At Grom'gol, Nimboya asks after Yenniku, youngest son of the Darkspear chief. The Bloodscalp trolls may know where he was taken, but Stranglethorn rarely gives up a captive cleanly.\n\nPress the jungle tribes for answers, listen when older spirits are called, and keep following the trail even when it turns toward magic no troll should take lightly."] = "在格羅姆高，尼姆布亞打聽著耶尼庫的下落——他是暗矛酋長的幼子。血頂食人妖或許知道他被帶往何處，但荊棘谷很少乾脆地放走俘虜。\n\n逼問叢林部族以取得答案，在古老的靈魂被召喚時仔細聆聽；即使線索轉向任何食人妖都不該輕忽的魔法，也要繼續追查下去。"
L["The Scarlet Crusade claims to defend Lordaeron from the undead, but its soldiers do not always wait to ask who is innocent. In Tirisfal, Southshore, and the Plaguelands, people have reasons to send you against the red tabard.\n\nFollow the Crusade's trail through farms, prisons, monasteries, and northern keeps. Each order you uncover makes their righteousness harder to trust."] = "血色十字軍自稱保衛羅德隆、對抗不死族，但他們的士兵往往不會先問清楚誰是無辜的。在提里斯法、南海鎮與瘟疫之地，人們都有理由派你去對付那些身穿紅色戰袍的人。\n\n循著十字軍的蹤跡穿越農場、監牢、修道院與北方的要塞。你揭露的每一道命令，都讓他們的正義更加難以令人信服。"
L["A battered raft in Un'Goro holds a few odd belongings: a compass, a map, a key, and a photograph. No one stands nearby to explain them. Only the crater, the wreckage, and the sense that someone lost more than supplies.\n\nFollow the clues from Marshal's Refuge and help piece together what happened to their owner. The trail is strange, old-fashioned, and not eager to explain itself."] = "安戈洛的一艘破舊木筏上留著幾件古怪的物品：一個羅盤、一張地圖、一把鑰匙和一張照片。附近沒有人能解釋它們的來歷。只有環形山、殘骸，以及一種感覺——有人失去的不只是補給。\n\n從馬紹爾營地開始循著線索，協助拼湊出物主的遭遇。這條線索古怪、老派，而且不急著解釋自己。"
L["A small scroll waits aboard a Bloodsail ship south of Booty Bay. It bears no proper patron, only a riddle and enough direction to make you wonder what was hidden.\n\nTake Cortello's words seriously and follow the clues wherever they send you. The treasure is not marked for anyone who wants a straight road."] = "在藏寶海灣南方的一艘血帆海盜船上，有一卷小小的卷軸等著你。上頭沒有正式的委託人，只有一則謎語，以及剛好足以讓你好奇藏了什麼的指引。\n\n認真看待寇特羅的話語，無論線索將你帶往何方，都跟著走下去。這份寶藏不屬於想走直路的人。"
L["Abercrombie's requests sounded lonely before they sounded dangerous. Hair, juice, blossoms, ribs, and a stolen crate became Stitches on the road, and Darkshire learned what the hermit had been making."] = "亞伯克隆比的請求起初聽來寂寞，後來才顯得危險。頭髮、果汁、花朵、肋骨，以及一箱偷來的貨物，最後化作路上的縫合怪，夜色鎮這才明白那名隱士一直在造些什麼。"
L["Aid Gryan Stoutmantle in Westfall and seek Wiley the Black's note in Lakeshire."] = "協助西部荒野的格里安·斯托曼，並前往湖畔鎮尋找黑衣威利的字條。"
L["Alliance priests carry word of Scarlet activity from Stormwind to Desolace, Southshore, and finally the Monastery."] = "聯盟的牧師將血色十字軍活動的消息從暴風城一路傳到淒涼之地、南海鎮，最後抵達修道院。"
L["Answer Archmage Xylem's request in Azshara and study the magic left by Warlord Krellian."] = "回應大法師克希雷姆在艾薩拉的請求，研究軍閥克雷利安留下的魔法。"
L["Answer your trainer's summons, draw a voidwalker into the circle, and bind it to your will."] = "回應訓練師的召喚，將虛無行者引入法陣，使其聽命於你。"
L["Apothecary Johaan began with blood, scales, and venom gathered from the creatures near Brill. In the tavern cellar, a captured mountaineer became the first proof that the new plague could be more than theory."] = "藥劑師喬漢從布瑞爾附近的生物身上採集鮮血、鱗片與毒液著手。在旅店地窖裡，一名被俘的山地巡邏兵成了第一個證據，證明新瘟疫不只是理論。"
L["At Fire Plume Ridge, the strange tools finally proved their worth. The Silver Totem stripped Blazerunner's shield, the sword found its purpose, and the Golden Flame was carried back to Marshal's Refuge. Linken's memory was still imperfect, but the road had given him a shape to follow: hero, blade, flame, and a companion brave enough to see it done."] = "在火羽山，那些奇特的工具終於證明了價值。銀色圖騰剝除了烈焰行者的護盾，長劍找到了它的使命，金色火焰也被帶回了馬紹爾營地。林克的記憶仍不完整，但這段旅程為他勾勒出一條可依循的輪廓：英雄、劍刃、火焰，以及一位勇敢到足以陪他走完全程的同伴。"
L["At the Deepwater Tavern, follow the man who listens too closely and make Tapoke Jahn tell what he knows."] = "在深水旅店跟蹤那個偷聽得太仔細的男人，逼塔伯克‧賈恩說出他所知道的事。"
L["At the Scarab Wall, Anachronos shows the old war and names the broken road a scepter bearer must follow."] = "在甲蟲之牆，阿納克洛斯展示了昔日的戰爭，並指出節杖持有者必須踏上的殘破之路。"
L["Azuregos sends you to Narain Soothfancy, whose ledger runs through goggles, chops, ransom notes, Draconic pages, and the sea."] = "艾索雷苟斯派你去找納里安‧柔想，他的帳本裡記著護目鏡、肉排、勒贖信、龍語書頁，還有大海。"
L["Baristolth sends you to Anachronos and then to Blackwing Lair. Broodlord Lashlayer's head begins the work of earning Nozdormu's trust."] = "巴瑞斯托斯派你去找阿納克洛斯，再前往黑翼之巢。龍領主勒西雷爾的首級，是贏得諾茲多姆信任的第一步。"
L["Before Tirion Fordring's search for his son, Hearthglen already stood as a military problem. Kirsta Deepshadow wanted the Scarlet Crusade measured in practical terms: medics, hunters, magi, knights, named officers, and the strength of the town itself. The reconnaissance made one thing clear. Hearthglen was not a remnant. It was an army still drilling under red banners."] = "在提里奧‧弗丁尋找兒子之前，壁爐谷早已是個軍事難題。科爾斯塔‧迪普沙東要以實際的標準評估血色十字軍：醫護兵、獵人、法師、騎士、有名有姓的軍官，以及城鎮本身的實力。偵察結果清楚表明了一件事：壁爐谷並非殘部，而是一支仍在紅色旗幟下操練的軍隊。"
L["Begin in the Burning Steppes with Helendis Riverhorn and carry the black dragon reports between Lakeshire, Stormwind, and Morgan's Vigil."] = "在燃燒平原與赫林迪斯‧河角會面，並將黑龍的報告往返傳遞於湖畔鎮、暴風城與摩根的崗哨之間。"
L["Begin Lord Grayson Shadowbreaker's rite and prepare yourself for the charger's judgment."] = "展開格雷森·沙東布瑞克公爵的儀式，準備迎接戰馬的審判。"
L["Begin Mor'zul Bloodbringer's work, gather the ritual tools, and prepare the road to Xoroth."] = "展開莫蘇爾·召血者交付的任務，蒐集儀式器具，為前往索羅斯之路做好準備。"
L["Begin Nimboya's search by pressing the Bloodscalp trolls for any sign of Yenniku."] = "向血頂食人妖施壓，探查耶尼庫的任何蹤跡，展開尼姆布亞的搜尋。"
L["Begin with the red masks near Northshire and follow the same bandit sign through Elwynn."] = "從北郡附近的紅面具著手，循著同樣的盜匪標記穿越艾爾文。"
L["Bodley was frightened, talkative, and deeply entangled in Lord Valthalak's fate. Through him, the armor work became a matter of flame, reputation, and a shattered amulet."] = "布德利驚恐、多話，與瓦薩拉克領主的命運糾葛極深。透過他，護甲的升級工作變成了一件關乎火焰、聲望與一枚碎裂護符的事。"
L["Break the Stones of Binding and seek the last names left to the Fallen Hero: Corporal Thund Splithoof and Lieutenant Kirith."] = "摧毀束縛之石，尋找殞落的英雄僅存的最後兩個名字：桑德‧裂蹄下士與基利斯中尉。"
L["Bring a Dungeon Set 1 bracer to Deliana or Mokvar and accept the first upgrade work."] = "將一件地城套裝1的護腕交給德莉娜或莫克瓦，接下第一項升級任務。"
L["Bring General Drakkisath's blood to Rexxar and complete the Drakefire Amulet."] = "將達基薩斯將軍之血交給雷克薩，完成龍火護符。"
L["Bring proof of the elements to the temple trial and show that the four powers can be held together."] = "將元素的證明帶到神殿試煉，證明你能同時駕馭這四種力量。"
L["Bring Raschal's knife to Quintis Jonespyre and let the blade show what ordinary searching could not."] = "將拉沙爾的小刀交給奎恩提斯‧炎癮，讓刀刃揭示一般搜尋無法發現的事物。"
L["Bring the Ancient Petrified Leaf to Felwood and hear what the ancients require of a hunter."] = "將遠古石化葉片帶到費伍德森林，聆聽古樹對獵人的要求。"
L["Bring the dead leaders to the cauldron and answer the price they demand before they speak."] = "將死去的首領帶到大鍋前，在他們開口之前，付出他們所要求的代價。"
L["By the time you reached Brill, the Scarlet Crusade was no rumor. Deathguard Simmer's stolen pumpkins became Apothecary Johaan's experiment, and a captured Scarlet Zealot learned how the Royal Apothecary Society meant to answer holy certainty. Outside town, Executor Zygand sent you into the Scarlet camps again and again until their officers broke. Brill's campaign was not only defense. It was the Forsaken answer taking shape."] = "等你抵達布瑞爾時，血色十字軍已不再只是傳聞。亡靈守衛希米爾被偷走的南瓜成了藥劑師喬漢的實驗材料，一名被俘的血色狂熱者則親身領教了皇家藥劑師協會打算如何回應那份神聖的篤定。在城外，執行官塞加德一次又一次派你突襲血色營地，直到他們的軍官潰敗。布瑞爾的戰役不只是防禦，更是被遺忘者的反擊逐漸成形。"
L["Carlin and Chromie needed names made into relics: Horgus, Marduk, Davil, Joseph, and the marauders who joined the slaughter. Each recovered piece brought the last battle closer to being answered."] = "卡林與克羅米需要將一個個名字化為遺物：霍古斯、馬杜克、達維爾、約瑟夫，以及參與屠殺的掠奪者。每找回一件，那最後一戰就離得到回應更近一步。"
L["Carry Balthule's warning to Delgren and follow the Dark Strand's trail through Ashenvale."] = "將巴蘇爾的警告帶給德爾格倫，循著黑暗之環的蹤跡穿越梣谷。"
L["Carry Duthorian Rall's lesson to Westfall and prove that valor protects those who cannot stand alone."] = "將達索瑞恩·拉爾的教誨帶到西部荒野，證明英勇能守護那些無法獨自挺立的人。"
L["Carry the Azsharite to Galvan the Ancient so Felbane can be forged for the Blasted Lands."] = "將艾薩萊特水晶交給『長者』加爾文，好為詛咒之地鍛造出邪能剋星。"
L["Carry the Silver Totem into Linken's final trial and see whether the old adventure can be finished."] = "帶著銀色圖騰迎接林克的最終試煉，看看這段舊日冒險能否畫下句點。"
L["Carry VanCleef's letter to Baros Alexston and follow the matter into the Stockade."] = "將范克里夫的信交給巴洛斯‧艾力克斯頓，並追查此事直至暴風城監獄。"
L["Carry waters between distant places and learn why this totem asks for patience."] = "在遙遠的地點之間運送水，了解這個圖騰為何需要耐心。"
L["Commander Gor'shak's message pulls the Horde into Blackrock Depths, where Moira's captivity may shape more than one kingdom."] = "指揮官哥沙克的訊息將部落引入黑石深淵，在那裡，茉艾拉遭囚一事所牽動的或許不只一個王國。"
L["Complete your first warrior trial and learn the stance that keeps you standing when blows fall."] = "完成你的第一項戰士試煉，學會在攻擊落下時讓你屹立不搖的姿態。"
L["Dalar Dawnweaver asks you to thin the Moonrage worgen and recover signs of Arugal's magic."] = "達拉爾‧織曦者請你削減月怒狼人的數量，並找回阿魯高魔法的痕跡。"
L["Dalar Dawnweaver wanted proof that Arugal's curse still stained Silverpine. You hunted Moonrage worgen, recovered the Remedy of Arugal, and struck down those most touched by the mage's work."] = "達拉爾‧織曦者想要證據，證明阿魯高的詛咒仍玷污著銀松森林。你獵殺月怒狼人，找回了阿魯高的藥劑，並擊倒了那些受這名法師之術影響最深的人。"
L["Darkshire's first need was simple: more blades for the Night Watch. You answered Althea's call at Raven Hill and helped hold a town Stormwind could not easily protect."] = "夜色鎮最初的需求很簡單：守夜人需要更多戰力。你在烏鴉嶺回應了奧爾希雅的召喚，協助守住一座暴風城難以保護的城鎮。"
L["Darthalia's first orders were plain: strike the farms, kill those who worked them, and leave the town afraid. Tarren Mill's campaign had begun."] = "達薩利亞最初的命令直截了當：襲擊農場，殺死在那裡工作的人，讓整座城鎮陷入恐懼。塔倫米爾的戰役就此展開。"
L["Deathknell's newly risen are not alone. Strike the Scarlet converts and take the courier's message before it leaves the valley."] = "喪鐘鎮不只有新甦醒的亡者。擊殺血色十字軍的皈依者，在信使離開山谷之前奪下他的訊息。"
L["Delgren sent you after the cult's soul gems and writings from Ordil'Aran to Fire Scar Shrine and Satyrnaar. Each recovered piece loosened the hold of the power behind Althalaxx."] = "德爾格倫派你從奧迪拉蘭一路追到火痕神殿與薩提納爾，找回教派的靈魂寶石與文稿。每找回一件，奧薩拉克斯背後那股力量的掌控便鬆動一分。"
L["Dun Garok stood as the last hard point in Darthalia's campaign. When its mountaineers, priests, riflemen, and Captain Ironhill were dead, her commendation could be carried to Varimathras."] = "丹加洛克是達薩利亞戰役中最後一處堅固據點。當那裡的山地巡邏兵、牧師、火槍手與達倫‧鐵山上尉全數陣亡後，她的嘉獎令便能呈交給瓦里瑪薩斯。"
L["Emberstrife demands the skulls of four dragons: Scryer, Somnus, Chronalis, and Axtroz."] = "艾博斯塔夫要求四頭龍的頭骨：占卜者、索姆努斯、克魯納里斯與埃克托茲。"
L["Emberstrife's tests scattered the Horde across Azeroth. Scryer waited in Winterspring, Somnus haunted Swamp of Sorrows, Chronalis guarded the Caverns of Time, and Axtroz patrolled the road to Grim Batol. Each skull was trophy, key, and proof of strength. By the time the fourth dragon fell, Emberstrife's amulet was ready for the last transformation."] = "艾博斯塔夫的試煉讓部落奔走於艾澤拉斯各地。占卜者在冬泉谷等候，索姆努斯盤踞在悲傷沼澤，克魯納里斯守護著時光之穴，埃克托茲則在通往格瑞姆巴托的路上巡邏。每一顆頭骨都是戰利品、鑰匙，也是力量的證明。當第四頭龍倒下時，艾博斯塔夫的護符已準備好迎接最後一次蛻變。"
L["Enter Dire Maul and recover the knowledge Lorekeeper Lydros keeps in the Athenaeum."] = "進入厄運之槌，取回博學者萊德羅斯保存在智慧之殿中的知識。"
L["Enter Shadowfang Keep for the missing deathstalkers, the Book of Ur, and the mage who rules above the forest."] = "進入影牙城堡，尋找失蹤的死亡潛行者、烏爾之書，以及那位高踞森林之上的法師。"
L["Enter the Deadmines beneath Moonbrook and confront the Brotherhood at the heart of its hideout."] = "進入月溪鎮下方的死亡礦坑，在兄弟會藏身處的核心與他們正面對決。"
L["Enter the Monastery's graveyard and library for prisoners, forbidden books, and the records the Crusade keeps locked away."] = "進入修道院的墓地與圖書館，尋找囚犯、禁書，以及十字軍深鎖的紀錄。"
L["Follow the last sign into the hive and learn whether Raschal's errand can still be answered."] = "循著最後的跡象深入蟲巢，看看拉沙爾的任務是否還能有個交代。"
L["Eris Havenfire's trial tested mercy under pressure. You kept the fallen moving, held shadow at bay, and earned Benediction through discipline and compassion."] = "艾瑞斯·哈文法的試煉考驗你在壓力下的慈悲。你護送受難者持續前行，將暗影擋在外頭，並以紀律與憐憫贏得了祈福。"
L["Escort Marshal Windsor back to Stormwind and stand with him when his proof is finally heard."] = "護送溫德索爾元帥返回暴風城，在他的證據終於被聽取時站在他身旁。"
L["Falrin Treeshaper's vendetta turned Dire Maul's library into your next post. The creatures he named were hunted, the enchantment was made, and a challenge was prepared for Blackrock Depths."] = "法琳·樹形者的復仇讓厄運之槌的圖書館成了你的下一個據點。你獵殺了他點名的生物，完成了附魔，並為黑石深淵準備好一場挑戰。"
L["Felwood gave the search older magic. Eridan Bluewind understood the silver heart Linken had been trying to make and sent you into Winterspring's old forests before Aquementas rose in Un'Goro. The elemental's power became a silver totem, the key to stripping away the final guardian's protection. The errand had strange humor about it, but the ritual was real."] = "費伍德森林為這場搜尋帶來了更古老的魔法。艾瑞丹‧藍風明白林克一直想打造的銀色之心是什麼，並派你前往冬泉谷的古老森林，之後亞奎門塔斯才在安戈洛現身。這個元素的力量化為一枚銀色圖騰，成為剝除最後守護者防護的關鍵。這趟差事雖帶著幾分古怪的幽默，儀式卻是貨真價實的。"
L["Find Balthule Shadowstrike near the Tower of Althalaxx and learn what gathers on Darkshore's northern coast."] = "在奧薩拉克斯之塔附近找到巴蘇爾‧影擊，查明黑海岸北方海岸正在聚集什麼。"
L["Find Bodley near Blackrock Spire and learn why Lord Valthalak's amulet matters."] = "在黑石塔附近找到布德利，了解瓦薩拉克領主的護符為何重要。"
L["Find Pamela Redpath in Darrowshire and help gather the pieces of the doll she has lost."] = "在達隆郡找到帕米拉‧雷德帕斯，協助她找回遺失娃娃的碎片。"
L["Find Ravenholdt Manor and present yourself to the rogues who keep their own company in the hills."] = "找到拉文霍德莊園，向那些隱居山中、自成一派的盜賊表明身分。"
L["Find Rexxar and follow the trials he sets before the amulet can be completed."] = "找到雷克薩，完成他設下的試煉，護符才能完成。"
L["Fire asked for risk, offering, and obedience to the rite. When the brazier answered, the flame became a servant at your side."] = "火焰要求冒險、供品，以及對儀式的服從。當火盆回應時，火焰便成了你身旁的僕從。"
L["Follow Madame Eva's cards through old records, locked chests, and the trail of Stalvan Mistmantle."] = "循著伊娃夫人的卡牌，追查舊紀錄、上鎖的箱子，以及斯塔文·密斯特曼托的蹤跡。"
L["Follow Pamela's family trail to Marlene, Carlin, and Chromie, who seeks the Annals of Darrowshire."] = "循著帕米拉的家族線索找到瑪萊恩、卡林，以及正在尋找達隆郡編年史的克羅米。"
L["Follow Shael'dryn's guidance through old Ashenvale magic and the work left unfinished by Teronis."] = "跟隨夏爾德琳的指引，探索梣谷的古老魔法，以及特羅尼斯未竟的工作。"
L["Follow Sven's grief, Jitters' journal, and the shadow that hangs over Raven Hill."] = "追尋斯溫的悲痛、吉特斯的日誌，以及籠罩烏鴉嶺的陰影。"
L["Follow the call of fire through offerings, reagents, and the flame that waits in Durotar."] = "追隨火焰的呼喚，準備供品與施法材料，找到在杜洛塔等候的火焰。"
L["Follow the Circle's instructions, gather what is needed for a cure, and cleanse the sick beasts you find."] = "依照議會的指示，蒐集治療所需的材料，淨化你遇到的病弱野獸。"
L["Follow the Devourer of Souls chain and prepare the binding of a subtler demon."] = "完成噬魂者任務線，準備束縛一隻更難以捉摸的惡魔。"
L["Trust the musty scroll's final verse and search where Cortello chose to hide his prize."] = "相信那卷霉舊卷軸的最後一段詩句，在寇特羅選擇藏匿寶物的地方搜尋。"
L["Follow Thelwater, Baros, Shaw, and Trias as the Defias trail returns to Stormwind."] = "隨著迪菲亞的蹤跡回到暴風城，追隨塞爾沃特、巴洛斯、肖爾與崔亞斯的腳步。"
L["Follow Watcher Backus to Addle's Stead and bring the Defias docket back to Trias."] = "跟隨守夜人巴庫斯前往腐草農場，將迪菲亞的案卷帶回給崔亞斯。"
L["Follow your faction's rogue trainer into guarded ground, locked boxes, and the antidote work needed for poisons."] = "跟隨你所屬陣營的盜賊訓練師，深入戒備森嚴之地、打開上鎖的箱子，並完成製作毒藥所需的解毒劑工作。"
L["From Stonard or Nethergarde, the road ended at the same ghost. The Fallen Hero told what waited beyond the swamp: Razelikh's servants took his fallen regiment, denied them rest, and bound them to stones of demonic power. His regret became an order of its own. If his soldiers could not live, they could still be set free."] = "無論從斯通納德還是守望堡出發，這條路都止於同一個鬼魂。殞落的英雄說出了沼澤彼端的遭遇：拉瑟里克的僕從帶走了他陣亡的部隊，不讓他們安息，並將他們束縛在蘊含惡魔力量的石頭上。他的悔恨化為一道屬於自己的命令。若他的士兵無法活下來，至少還能讓他們重獲自由。"
L["Gather ectoplasm, a power source, and goblin parts so Mux can finish his device."] = "蒐集靈質、能源與哥布林零件，讓莫克斯完成他的裝置。"
L["Gather Johaan's ingredients around Brill and bring the mixture to the prisoner in the Gallows' End Tavern."] = "在布瑞爾周圍蒐集喬漢需要的材料，並將調好的藥劑送給恐懼之末旅店裡的囚犯。"
L["Gather Jordan Stilwell's materials from distant dangers and help forge Verigan's Fist."] = "從遠方的險地蒐集喬丹·斯迪威爾需要的材料，協助鍛造維里甘之拳。"
L["Gather singing crystals and the Mind's Eye so Kin'weelay can make a Soul Gem for Yenniku."] = "蒐集歌唱水晶與心靈之眼，讓肯維雷為耶尼庫製作一顆靈魂寶石。"
L["Gather the final materials and ready the Brazier of Invocation for Upper Blackrock Spire."] = "蒐集最後的材料，為黑石塔上層備妥祈願火盆。"
L["Go north of Brill to the Agamand Mills, clear the dead, and recover what remains of the family."] = "前往布瑞爾北方的阿加曼德磨坊，清除亡者，並找回這個家族的遺留之物。"
L["Go to Tabetha in Dustwallow Marsh, recover the knowledge she needs, and prepare a wand of your chosen school."] = "前往塵泥沼澤找塔貝薩，取回她需要的知識，並準備一根屬於你所選學派的魔杖。"
L["Gryan Stoutmantle suspected that Westfall's troubles reached beyond scattered bandits. Wiley's note confirmed allies, machinery, hidden routes, and the old grievance of the Stonemasons."] = "格里安·斯托曼懷疑西部荒野的麻煩不只是零星的盜匪。威利的字條證實了盟友、機械、隱密路線，以及石匠公會的舊日怨恨。"
L["Hear Ragged John's tale, find Marshal Windsor in Blackrock Depths, and recover the proof taken from him."] = "聽狼狽不堪的約翰講述他的故事，在黑石深淵找到溫德索爾元帥，並取回他被奪走的證據。"
L["Hear the old tale of Thaurissan, then enter Blackrock Depths to learn what the mountain is hiding."] = "聽聽索瑞森的古老故事，然後進入黑石深淵，查明這座山脈隱藏著什麼。"
L["Help Calor and Carevin hunt the worgen moving through Brightwood Grove and the Rotting Orchard."] = "協助卡洛爾與卡瑞文獵殺出沒於亮木樹林與腐爛果園的狼人。"
L["Help Lydon finish the Elixir of Agony and find a way to deliver it to the captured farmers upstairs."] = "協助林度恩完成苦楚藥劑，並設法將它送給樓上被俘的農夫。"
L["Help Tyrion prepare the spybot and learn what quiet meeting it was built to uncover."] = "協助泰里恩準備間諜機器人，查明它是為了揭露哪場祕密會面而打造的。"
L["High Executor Hadrec's missing deathstalkers, Bel'dugur's forbidden book, and Dalar's demand all led into Shadowfang Keep. Arugal fell there, and the Sepulcher received the proof it required."] = "高階執行官哈德瑞克失蹤的死亡潛行者、貝杜格的禁書，以及達拉爾的要求，全都指向影牙城堡。阿魯高在那裡殞落，瑟伯切爾也得到了所需的證據。"
L["Hillsbrad's strength lay in its smithy, leaders, registry, and mine. Darthalia sent you against each in turn, breaking the town by removing the people and records that held it together."] = "希爾斯布萊德的力量來自鐵匠鋪、領導者、登記簿與礦坑。達薩利亞派你逐一出擊，除掉維繫這座城鎮的人與紀錄，就此將它擊垮。"
L["If the Eye of Divinity comes into your possession, seek Eris Havenfire in the Eastern Plaguelands. She has a trial that asks for more than quick hands and bright prayers.\n\nStand between panic and shadow, save who you can, and learn whether your faith holds when every mistake has a cost."] = "若你獲得了神性之眼，就前往東瘟疫之地尋找艾瑞斯·哈文法。她的試煉所要求的，不只是靈巧的雙手與虔誠的禱告。\n\n擋在恐慌與暗影之間，盡你所能拯救更多人，看看當每個錯誤都要付出代價時，你的信仰是否依然堅定。"
L["In Brill, the Forsaken answer the Crusade with prisoners, poison, and attacks against the camps west of town."] = "在布瑞爾，被遺忘者以囚犯、毒藥，以及對城西營地的攻擊來回應十字軍。"
L["In Kargath, take Warlord Goretooth's orders into Blackrock Spire and bring Rend Blackhand's command to Thrall."] = "在卡加斯接下督軍高圖斯的命令，深入黑石塔，並將雷德·黑手的命令帶給索爾。"
L["In Silithus, the Bronze Dragonflight does not hand trust to strangers. Before anyone can challenge what waits behind Ahn'Qiraj's gates, someone must prove they are more than another mortal asking for legends.\n\nBegin with the Brood of Nozdormu and follow the old scepter's trail through dragonflights, hidden lairs, bargains, and errands that sound impossible until someone does them."] = "在希利蘇斯，青銅龍軍團不會輕易信任陌生人。在任何人能挑戰安其拉大門後的存在之前，必須有人證明自己不只是又一個追逐傳說的凡人。\n\n從諾茲多姆的子嗣開始，循著古老節杖的蹤跡，穿越各大龍族軍團、隱密巢穴、交易，以及那些在有人真正完成之前都聽似不可能的差事。"
L["In Stratholme, search the Scarlet Bastion for the archive and the truth hidden behind its holy face."] = "在斯坦索姆搜索血色堡壘，找出檔案庫，以及隱藏在其神聖外表背後的真相。"
L["In Theramore, find Private Hendel near Sentry Point and bring him in alive if you can."] = "在塞拉摩的警戒崗哨附近找到士兵亨德爾，可能的話將他活著帶回。"
L["Join Commander Althea's Night Watch and begin clearing the dead around Raven Hill."] = "加入指揮官奧爾希雅的守夜人，開始清除烏鴉嶺周圍的亡者。"
L["King Magni sends the letter on to Grand Mason Marblesten, who needs Alterac Granite before Sully's memorial can stand."] = "麥格尼國王將信轉交給大石匠瑪布勒斯坦，他需要奧特蘭克花崗岩，才能為蘇利建起紀念碑。"
L["Kirsta Deepshadow sends you into the Scarlet lines around Hearthglen to kill their specialists and scout the fortress."] = "科爾斯塔‧迪普沙東派你深入壁爐谷周圍的血色防線，擊殺其中的各類專才並偵察要塞。"
L["Krellian's magic broke apart in curious ways, and Xylem knew what to make of it. The result was odd, useful, and unmistakably a mage's lesson."] = "克雷利安的魔法以奇特的方式崩解，而克希雷姆知道該如何利用。成果古怪又實用，毫無疑問是一堂法師的課。"
L["Latronicus sends you to Ginro Hearthkindle, who needs the Feralas coast searched for Raschal's missing boat."] = "拉托尼庫斯派你去找基恩諾‧燃爐，他需要有人搜索菲拉斯海岸，找出拉沙爾失蹤的船。"
L["Linken's memory did not return like a clean answer. It came through strange errands, ghostly meetings, and a sword that changed in flashes of light. Donova, Gaeriyan, and the grave outside Gadgetzan turned the lost gnome's fragments into a rite of recovery. By the time the sword was reforged, Linken still did not fully understand himself, but the road was opening before him again."] = "林克的記憶並沒有像一個乾淨俐落的答案那樣回來。它是透過奇怪的差事、與鬼魂的會面，以及一把在閃光中不斷變化的劍逐漸浮現的。多諾瓦、加里楊，以及加基森外的那座墳墓，將這位失憶地精的記憶碎片化為一場找回自我的儀式。當長劍重鑄之時，林克仍未完全了解自己，但前方的道路再次為他敞開。"
L["Lorekeeper Lydros entrusted you with a spell every company of adventurers comes to value. Power is not always flame and frost; sometimes it is preparation."] = "博學者萊德羅斯將一道每支冒險隊伍都會珍視的法術託付給你。力量並不總是烈焰與冰霜；有時，力量是事前的準備。"
L["Lydon's work in Tarren Mill turned research into local experiment. Tongues, ichor, and mountain lion blood became elixirs, and the tests on Umpi and Stanley showed how cruelly effective they could be."] = "林度恩在塔倫米爾的工作，將研究化為實地實驗。舌頭、膿液與山獅之血被製成藥劑，而在烏比與史丹利身上的測試，顯示了它們的效果有多麼殘酷。"
L["Magistrate Sevren knew the trouble went below the mills. In the family crypt you found older dead, wailing ancestors, and Captain Dargol's skull, ending the matter one grave at a time."] = "執政官塞弗倫知道問題遠在磨坊之下。你在家族墓穴中發現了更古老的亡者、哀號的先祖，以及達戈爾上尉的頭骨，一座墳接著一座墳，終結了這件事。"
L["Mankrik survived a quillboar attack on the Gold Road, but Olgra did not return. Search the road south of the Crossroads for his wife."] = "曼寇里克在黃金之路上的野豬人襲擊中倖存，但歐格拉沒有回來。搜索十字路口以南的道路，尋找他的妻子。"
L["Mankrik's request was painfully plain: find his wife. The Barrens offered little direction and less mercy, only a long road south of the Crossroads and quillboar waiting in the dust. When Olgra was found, the search became grief. Mankrik had asked for hope and received a body. What followed was the only answer his pain could bear: Bristleback tusks, brought back one by one."] = "曼寇里克的請求單純得令人心痛：找到他的妻子。貧瘠之地幾乎指不出方向，更談不上仁慈，只有十字路口以南的漫長道路，以及在塵土中等待的野豬人。當歐格拉被找到時，搜尋化為了悲痛。曼寇里克求的是希望，得到的卻是一具遺體。接下來的，是他的痛苦唯一能承受的答案：鬃背野豬人的獠牙，一根根被帶回來。"
L["March on Dun Garok and bring Darthalia the victory she needs for her sealed commendation."] = "進軍丹加洛克，為達薩利亞贏得她密封嘉獎令所需的勝利。"
L["Marlene's request led you to Pamela Redpath, alone among the ruins and still asking after her doll. Returning the pieces brought comfort, and also the first hard truth of Darrowshire."] = "瑪萊恩的請求將你引向帕米拉‧雷德帕斯——她獨自待在廢墟之中，仍在詢問她的娃娃。找回碎片帶來了慰藉，也帶來了達隆郡的第一個殘酷真相。"
L["Meet Falrin Treeshaper in Dire Maul and gather what he needs for the next challenge."] = "在厄運之槌與法琳·樹形者會面，蒐集他下一場挑戰所需之物。"
L["Menethil Harbor made the conspiracy plain. Mikhail noticed a listener by the tavern door, and Tapoke \"Slim\" Jahn tried to run before the questions reached him. When he broke, the case changed completely. The Defias had not taken a mere diplomat. They had taken Stormwind's king, and Slim had helped place Hendel aboard the king's ship. Mikhail could only send you to Theramore before the trail disappeared into military silence."] = "米奈希爾港讓這場陰謀昭然若揭。米克哈爾注意到旅店門口有個偷聽的人，而『瘦子』塔伯克‧賈恩想在被盤問之前溜走。當他終於招供，整起案件徹底變了樣。迪菲亞綁走的不只是一名外交官，而是暴風城的國王，瘦子還幫忙把亨德爾安插上了國王的船。米克哈爾只能在線索消失於軍方的沉默之前，派你前往塞拉摩。"
L["Moira's disappearance led backward to old Thaurissan and the War of the Three Hammers. Ironforge's old wound led straight into Blackrock Depths, where Kharan Mighthammer's prison cell held the news Magni did not want to hear. Moira was in the heart of the Dark Iron kingdom, and the rescue he wanted was already tangled in questions of love, control, succession, and inherited hatred."] = "茉艾拉的失蹤，將線索回溯到古老的索瑞森與三錘之戰。鐵爐堡的舊傷直接通往黑石深淵，在那裡，卡蘭·巨錘的牢房中藏著麥格尼不願聽見的消息。茉艾拉身處黑鐵王國的核心，而他想要的營救，早已與愛情、控制、王位繼承與世代仇恨等問題糾纏不清。"
L["Mor'zul and Gorzeeki sent you through blood, stardust, Jaedenar, and Scholomance. In Dire Maul the rite opened, and the dreadsteed came through bound to your command."] = "莫蘇爾與戈瑟奇帶你走過鮮血、星塵、加德納爾與通靈學院。儀式在厄運之槌開啟，恐懼戰馬穿越而來，聽命於你。"
L["Morgan Ladimore's grave led to a sorrow Darkshire had tried to bury. You ended Mor'Ladim's wandering and brought Sarah Ladimore the truth of her father."] = "摩根·拉迪莫爾的墳墓，牽出一段夜色鎮試圖埋葬的悲傷。你終結了摩拉迪姆的遊蕩，並將她父親的真相告訴了莎拉·拉迪莫爾。"
L["Move from fields to town records, workers, leaders, and the mine that keeps Hillsbrad supplied."] = "從田野轉向城鎮紀錄、工人、領導者，以及為希爾斯布萊德提供補給的礦坑。"
L["Mux Manascrambler's device required ghostly residue, strange power, and parts only a goblin would trust. Once complete, it pointed the armor work toward matters no smith could see unaided."] = "莫克斯·施法者的裝置需要鬼魂殘渣、奇異的能源，以及只有哥布林才信得過的零件。一旦完成，它便將護甲的升級工作引向任何鐵匠都無法憑肉眼看見的領域。"
L["Pamela's family was scattered by grief: Marlene near Andorhal, Jessica far away, and Carlin at Light's Hope. Chromie gave their sorrow a shape by asking for the Annals of Darrowshire."] = "帕米拉的家人因悲傷而離散：瑪萊恩住在安多哈爾附近，潔西卡遠在他方，卡林則在聖光之願禮拜堂。克羅米請你尋找達隆郡編年史，讓他們的哀傷有了具體的形狀。"
L["Push into the Armory and Cathedral, where the Crusade's champions guard the heart of the Monastery."] = "攻入軍械庫與大教堂，十字軍的勇士們正守護著修道院的核心。"
L["Ravenholdt opened a door beyond ordinary city training. There were signals to learn, reputations to mind, and thieves who knew the craft by its older rules."] = "拉文霍德打開了一扇超越一般城市訓練的大門。這裡有要學的暗號、需留心的聲望，還有依循更古老規矩行事的盜賊。"
L["Read the scroll found aboard the Bloodsail ship and follow only the clue Cortello left behind."] = "閱讀在血帆海盜船上找到的卷軸，只追隨寇特羅留下的線索。"
L["Read the wanted poster outside Westbrook Garrison and hunt Hogger, the Riverpaw gnoll terrorizing southwestern Elwynn."] = "閱讀西泉要塞外的通緝告示，獵殺霍格——在艾爾文森林西南部肆虐的河爪豺狼人。"
L["Read the weathered grave north of Raven Hill and learn why Mor'Ladim still walks."] = "查看烏鴉嶺北方那座飽經風霜的墓碑，了解摩拉迪姆為何仍在遊蕩。"
L["Recover the amulet pieces and components Bodley names from the old dungeons of Azeroth."] = "從艾澤拉斯古老的地城中，找回布德利指名的護符碎片與材料。"
L["Recover the relics and skulls tied to Darrowshire's old defenders, villains, and marauders."] = "找回與達隆郡昔日守衛者、惡徒和掠奪者相關的遺物與頭骨。"
L["Recover the waterlogged letter beneath the Thandol Span and carry its last words home."] = "取回薩多爾大橋下那封浸水的信，將信中最後的話語帶回家。"
L["Renferrel and Faranell carried the work beyond Brill. Berard's journal, Pyrewood's danger, and the samples from Lake Lordamere gave the apothecaries older knowledge to add to their new recipe."] = "倫費瑞爾與法蘭奈爾將研究帶出了布瑞爾。貝拉德的日誌、焚木村的危機，以及洛丹米爾湖的樣本，為藥劑師們的新配方增添了更古老的知識。"
L["Report to Apothecary Lydon in Hillsbrad and gather what he needs for his next field trials."] = "向希爾斯布萊德的藥劑師林度恩報到，蒐集他下一次實地試驗所需的材料。"
L["Report to High Executor Darthalia and carry her first orders against the farms of Hillsbrad."] = "向高階執行官達薩利亞報到，執行她針對希爾斯布萊德農場的第一道命令。"
L["Return to Darrowshire with Chromie's relic bundle and stand with the town in its final battle."] = "帶著克羅米的遺物包裹回到達隆郡，與這座城鎮並肩迎接最後一戰。"
L["Return to Deliana or Mokvar for the final exchange and complete the armor upgrade."] = "回到德莉娜或莫克瓦那裡進行最後的交換，完成護甲升級。"
L["Return to the tower with Balthule's command and face Athrikus Narassin at the summit."] = "帶著巴蘇爾的命令回到塔中，在塔頂面對埃瑟里克斯‧納拉辛。"
L["Return to Westfall, watch the Brotherhood's movements, and let the trail show where it leads."] = "回到西部荒野，監視兄弟會的動向，看看線索將引向何方。"
L["Return to your trainer and receive the last totem needed to complete the circle of elements."] = "回到你的訓練師身邊，領取完成元素之環所需的最後一個圖騰。"
L["Return with the lost command, or answer Nethergarde's summons, and hear what Razelikh did to the soldiers who crossed into the Blasted Lands."] = "帶著遺失的命令歸來，或回應守望堡的召喚，聽聽拉瑟里克對那些踏入詛咒之地的士兵做了什麼。"
L["Run Abercrombie's errands near Raven Hill and learn what the old hermit means to build."] = "在烏鴉嶺附近為亞伯克隆比跑腿，查明這位老隱士打算造些什麼。"
L["Search for Teronis near Lake Falathim and return with whatever remains of his work."] = "在法拉希姆湖附近尋找特羅尼斯，帶回他所留下的任何工作成果。"
L["Search the Woodpaw camps for Raschal's missing packs and any sign of where his errand went next."] = "搜索木爪豺狼人的營地，尋找拉沙爾遺失的背包，以及他的任務下一步去向的任何跡象。"
L["Search the wrecked raft in Un'Goro and bring the small pack to Linken at Marshal's Refuge."] = "搜索安戈洛那艘失事的木筏，將小背包交給馬紹爾營地的林克。"
L["Follow the next names in Linken's tale and prepare the totem he will need."] = "追尋林克故事中出現的下一批名字，準備他需要的圖騰。"
L["Seek Haleh in Winterspring and bring her General Drakkisath's blood to make the Drakefire Amulet."] = "前往冬泉谷尋找哈爾琳，將達基薩斯將軍之血交給她，以製作龍火護符。"
L["Seek Loramus Thalipedes in Azshara. The demon hunter knows how Razelikh is warded, but he needs a name torn from the deep."] = "前往艾薩拉尋找洛拉姆斯‧薩里比迪斯。這位惡魔獵人知道拉瑟里克受到何種結界保護，但他需要一個從深處奪來的名字。"
L["Seek Strahad Farsan, assemble the Tome of the Cabal, and prepare the felhunter binding."] = "尋找斯坦哈德·法爾杉，拼湊出陰謀之書，準備束縛惡魔獵犬。"
L["Seek the earth's sapta, speak with its manifestation, and return with your first totem."] = "尋找大地的薩普塔，與大地的化身交談，帶著你的第一個圖騰歸來。"
L["Seek the halves of the pendant across lake and sea so the form of the sea lion may be taught."] = "在湖泊與大海之間尋找墜飾的兩半，好讓你學會海獅形態。"
L["Seek the Islander, gather the charms, and answer Bath'rah's summons for the whirlwind weapon."] = "尋找島民，蒐集護符，並回應巴斯拉的召喚以取得旋風武器。"
L["Sentinel Elissa's missing scout was alive, but Balthule's report was grave. Warlocks held the tower, their parchments spoke of the Dark Strand, and the warning had to reach Ashenvale."] = "哨兵伊莉莎失蹤的斥候還活著，但巴蘇爾的回報卻令人憂心。術士佔據了高塔，他們的羊皮紙提到黑暗之環，這個警告必須送到梣谷。"
L["Shaw's report gave Gryan a name, but the messenger gave him movement. The Defias Traitor then led you through Moonbrook to the hidden entrance beneath the ruined town."] = "肖爾的報告給了格里安一個名字，信使則讓事情有了進展。接著，迪菲亞叛徒帶你穿過月溪鎮，來到這座廢墟城鎮底下的隱密入口。"
L["Speak with the proper trainer and bind the felsteed that will carry you on darker roads."] = "與相應的訓練師交談，束縛那匹將載你踏上更黑暗道路的地獄戰馬。"
L["Sven's murdered family and Jitters' fear showed that Raven Hill was being worked by a darker hand. With Morbent's Bane prepared, you ended the necromancer beyond the graves."] = "斯溫遇害的家人與吉特斯的恐懼，顯示有一隻更黑暗的手在操弄烏鴉嶺。備妥莫本特剋星後，你在墓地彼端終結了那名死靈法師。"
L["Tabetha's work asked for texts, materials, and a measure of field sense. When the ritual was complete, your studies had a proper focus in hand."] = "塔貝薩的工作需要典籍、材料，以及些許實地經驗。儀式完成後，你的研究終於有了一件稱手的法器。"
L["Take Coleman's concern to Magistrate Sevren and descend into the crypt beneath the mills."] = "將庫勒曼的擔憂轉告執政官塞弗倫，然後深入磨坊下方的墓穴。"
L["Take Johaan's work to Silverpine, recover Berard's research, and bring Faranell the samples he requires."] = "將喬漢的研究帶到銀松森林，找回貝拉德的研究資料，並將法蘭奈爾需要的樣本交給他。"
L["Take the soggy clue at its word and look for the next scrap where the riddle says it waits."] = "照著那條濕透線索的字面意思，到謎語所說的地方尋找下一張紙片。"
L["The Agamand Mills still bore the family name, though the family itself had joined Tirisfal's dead. You brought Coleman Farthing the remains he asked for and helped clear the grounds for Brill."] = "阿加曼德磨坊仍冠著這個家族的姓氏，儘管家族成員早已加入了提里斯法的亡者行列。你為庫勒曼·法席恩帶回了他要的遺骸，並協助為布瑞爾清理這片土地。"
L["The amulet hunt sent you after pieces, components, and summoned echoes in dangerous places. Each recovery brought Lord Valthalak's broken pride closer to being called forth."] = "尋找護符的過程讓你在危險之地追尋碎片、材料與被召喚的殘影。每一次尋回，都讓瓦薩拉克領主破碎的傲氣更接近被召喚出來。"
L["The Ancient Petrified Leaf proved to be a summons. The ancients named the demons, and by hunting them alone you earned the right to carry Rhok'delar."] = "遠古石化葉片原來是一道召喚。古樹點名了那些惡魔，而你獨自獵殺牠們，贏得了持有洛克迪拉爾的資格。"
L["The Armory and Cathedral were the Crusade's creed made flesh. Houndmaster Loksey guarded the Library with trained violence. Herod turned recruits into zealots through spectacle and blood. In the Cathedral, Scarlet Commander Mograine and High Inquisitor Whitemane embodied the order's shining lie: holy words wrapped around endless war. Whether sent by Varimathras or Raleigh, you cut through the Monastery's saints and executioners alike."] = "軍械庫與大教堂是十字軍信條的具體化身。馴犬者洛克希以訓練有素的暴力守衛圖書館。赫洛德透過血腥的表演將新兵變成狂熱者。在大教堂中，血色十字軍指揮官莫格萊尼與高階審判官懷特邁恩體現了這個組織光鮮的謊言：以神聖話語包裝的無盡戰爭。無論是受瓦里瑪薩斯還是萊雷恩派遣，你都斬穿了修道院裡的聖徒與劊子手。"
L["The Azsharite was raw possibility: crystal from a dangerous coast, named by a demon hunter, and meant for a foe normal steel could not touch. Galvan the Ancient gave that possibility form. Felbane was not an heirloom or a trophy. It was a blade for one brutal task: wound Razelikh's protected servants, gather the shattered amulet, and open the way to the demon himself."] = "艾薩萊特水晶是未經雕琢的可能性：來自危險海岸的水晶，由一位惡魔獵人點名，專為一般鋼鐵傷不了的敵人而備。『長者』加爾文賦予了這份可能性形體。邪能剋星不是傳家寶，也不是戰利品，而是一把為殘酷任務而生的劍：傷及拉瑟里克受保護的僕從，收集破碎的護符，並打開通往這個惡魔本身的道路。"
L["The blue shard hid grave purpose beneath impossible errands. Azuregos sent you to Narain, and Narain's ledger demanded Molten Core goggles, a great chimaerok meal, a stolen book, a ransom drop, pages from dragons, the fires of Onyxia and Ragnaros, and Neptulon's wrath off Azshara's coast. Strange as it was, each step pulled the shard closer to the scepter."] = "藍色碎片在不可能的差事之下，藏著嚴肅的目的。艾索雷苟斯派你去找納里安，而納里安的帳本要求熔火之心的護目鏡、一頓豐盛的奇美隆大餐、一本被偷的書、一次贖金交付、巨龍的書頁、奧妮克希亞與拉格納羅斯之火，以及艾薩拉海岸外的奈普圖隆之怒。儘管古怪，每一步都讓碎片更接近節杖。"
L["The call of air was brief, but it completed what the earlier trials began. Earth, fire, water, and air now stood with you."] = "空氣的呼喚雖然短暫，卻完成了先前試煉所開啟的一切。大地、火焰、水與空氣，如今都與你同在。"
L["The call of water sent you farther than the earlier trials. Through Barrens dust and distant roads, you learned the patience the element required."] = "水的呼喚讓你走得比先前的試煉更遠。穿越貧瘠之地的塵土與遙遠的道路，你學會了這個元素所要求的耐心。"
L["The charger's trial demanded sacrifice, craft, and courage in haunted places. At the end, the spirit answered the Light and came to your side."] = "戰馬的試煉要求犧牲、技藝，以及在鬧鬼之地展現的勇氣。最後，那個靈魂回應了聖光，來到你的身旁。"
L["The Circle sent you from lesson to remedy. You found the source of the sickness, gathered the cure, and restored creatures that had been left to suffer."] = "議會讓你從課程走向療法。你找到了疾病的源頭，蒐集了解藥，讓那些被棄於苦難中的生物恢復健康。"
L["The Dalaran wizards at Ambermill were moving supplies and waking old ley-work beneath Silverpine. Shadow Priest Allister and Dalar Dawnweaver followed the evidence until Archmage Ataeric stood exposed."] = "安伯米爾的達拉然法師正在運送補給，並喚醒銀松森林地底古老的地脈裝置。暗影牧師奧利斯特與達拉爾‧織曦者循著證據追查，直到大法師阿泰瑞克的真面目被揭穿。"
L["The dead of Darrowshire rose to fight again. You held the line, faced the corrupted Joseph Redpath, and gave Pamela the peace of knowing her father had come home."] = "達隆郡的亡者再度起身作戰。你守住了防線，面對已遭腐化的約瑟夫‧雷德帕斯，讓帕米拉得以安心——她的父親終於回家了。"
L["The Deadmines were mine, factory, shipyard, and fortress. At the heart of it all stood Edwin VanCleef, whose death ended Westfall's immediate crisis and left one final letter behind."] = "死亡礦坑既是礦場，也是工廠、造船廠與堡壘。在這一切的核心，站著艾德溫‧范克里夫，他的死終結了西部荒野迫在眉睫的危機，也留下了最後一封信。"
L["The device revealed Anthion Harmon, a ghost bound by his sister's danger. You entered Stratholme, reached Ysida in time, and returned to the brother who had waited outside its gates."] = "裝置揭露了安希恩·哈莫——一個因妹妹身陷危險而受束縛的鬼魂。你進入斯坦索姆，及時趕到亞希達身邊，再回到那位在城門外等候的哥哥身旁。"
L["The Elixir of Agony passed from blossom to composite, from Faranell's decay to Lydon's final activation. With Dun Garok stout as the vessel, the inn itself became the last test."] = "苦楚藥劑從花朵到複合物，從法蘭奈爾的腐化劑到林度恩的最終活化，一步步成形。以丹加洛克黑啤酒作為載體，旅店本身成了最後的試驗場。"
L["The Fallen Hero speaks of a regiment lost waiting for orders. Begin in Stonard and search the southern swamps for the command that never reached him."] = "殞落的英雄訴說著一支在等待命令中迷失的部隊。從斯通納德出發，在南方沼澤中搜尋那道從未送到他手中的命令。"
L["The Fallen Hero's grief began with obedience. He led his soldiers toward the Blasted Lands and waited for orders that never came. Dispatch Commander Ruag remembered the lost message, Bengor remembered the ambush, and the Swamp Talker still held the Warchief's command. The truth was bitter: the regiment had been told to withdraw. The order never reached them."] = "殞落的英雄的悲痛始於服從。他率領士兵前往詛咒之地，等待著永遠不會到來的命令。分隊指揮官盧爾格記得那封遺失的訊息，本戈爾記得那場伏擊，而沼澤語者仍持有大酋長的命令。真相令人痛心：部隊早已被下令撤退，但命令從未送達。"
L["The felsteed was not purchased like an ordinary mount. It was called, bound, and made to bear the one who mastered the ritual."] = "地獄戰馬不像一般坐騎那樣能用錢買到。牠是被召喚、被束縛，並被迫載負那位掌握儀式之人的。"
L["The fight moved from ghostly remorse to demon-hunter craft. Loramus Thalipedes understood Razelikh's ward, but knowledge had to be earned. Lord Arkkoroc gave up the beast's name only after Hetaera's heads were brought from the Bay of Storms, and Loramus used the blood to name the enemy properly. The demon's protections were no longer a mystery. Felbane had to be made."] = "這場戰鬥從鬼魂的悔恨轉向惡魔獵人的技藝。洛拉姆斯‧薩里比迪斯了解拉瑟里克的結界，但知識必須靠自己贏得。直到從風暴海灣帶回赫泰拉的頭顱，亞考羅克領主才說出那頭野獸的名字，洛拉姆斯則用那份鮮血正確地喚出敵人的名號。惡魔的防護不再是謎。邪能剋星必須鍛造出來。"
L["The final clue led to the great falls on the Hinterlands coast. Under the water, after pirates, mud, and raptors, Cortello's chest waited with a reward fit for a traveler."] = "最後的線索指向辛特蘭海岸的大瀑布。在水面之下，歷經海盜、泥濘與迅猛龍之後，寇特羅的寶箱帶著一份適合旅人的獎賞等在那裡。"
L["The final proof came from General Drakkisath himself. His blood completed the amulet's power, and Rexxar turned the long road of commands, disguises, skulls, and trials into a single key. The Horde had its answer to Onyxia: strength tested across the world and deep inside Blackrock Spire."] = "最後的證明來自達基薩斯將軍本人。他的鮮血使護符的力量臻於完整，雷克薩則將這條由命令、偽裝、頭骨與試煉組成的漫長道路化為一把鑰匙。部落終於有了對付奧妮克希亞的答案：一股在世界各地，以及黑石塔深處經過考驗的力量。"
L["The first binding taught the warlock's bargain clearly. A creature of the void answered, resisted, and was made to serve."] = "第一次束縛清楚地教會了你術士的交易法則。一個虛空生物回應了召喚，抵抗過，最終被迫效命。"
L["The first Defias were thieves in the vineyards and bandits on the roads. By the time Morgan the Collector's ring reached Marshal Dughan, the red masks looked less like chance and more like organization."] = "最早的迪菲亞是葡萄園裡的小偷與道路上的強盜。等到收貨人摩根的戒指送到治安官杜漢手中時，那些紅面具看起來已不像巧合，而更像是有組織的行動。"
L["The first exchange began with a worn class bracer and a simple test of readiness. Deliana or Mokvar made the first improvement and sent you onward to Gadgetzan."] = "第一次交換始於一件磨損的職業護腕，以及一場簡單的準備測試。德莉娜或莫克瓦完成了第一次強化，並派你前往加基森。"
L["The first scroll waited in the hold of a Bloodsail ship with no one to explain it. Its verse led you beneath a bridge in the Swamp of Sorrows, where the next clue lay in the mud."] = "第一張卷軸在血帆海盜船的貨艙裡等待，沒有任何人能解釋它。詩句將你引向悲傷沼澤的一座橋下，下一條線索就埋在泥濘之中。"
L["The first signs of Onyxia's reach came from the Burning Steppes, where Helendis Riverhorn watched black dragonkin gathering strength. Magistrate Solomon treated the threat as a kingdom matter, Bolvar Fordragon weighed it from Stormwind Keep, and Marshal Maxwell became the Alliance's field anchor. The question was no longer whether dragons were moving. It was who in Stormwind had allowed the threat to spread."] = "奧妮克希亞勢力擴張的最初跡象出現在燃燒平原，赫林迪斯‧河角在那裡注視著黑龍族逐漸壯大。所羅門鎮長將此威脅視為王國大事，柏瓦爾‧弗塔根在暴風要塞審慎衡量，麥斯威爾元帥則成了聯盟在前線的支柱。問題已不再是巨龍是否有所行動，而是暴風城裡有誰放任這股威脅蔓延。"
L["The Graveyard and Library showed the Crusade's order from the inside. Vorrel Sengutz lay tortured by Interrogator Vishas. Scholars wanted books the Crusade had locked away. Horde agents wanted the Compendium of the Fallen, and Parqual Fintallas wanted the book the Crusade used to teach itself how to fight the dead. Alliance scholars wanted the Mythology of the Titans. Every shelf and cell told the same truth: the Scarlet Crusade did not only kill enemies. It controlled what its followers were allowed to know."] = "墓地與圖書館從內部揭示了十字軍的秩序。沃瑞爾‧森古斯遭審問者韋沙斯拷問。學者們想要十字軍深鎖的書籍。部落的特工想要墮落者綱要，帕科瓦‧芬塔拉斯則想要十字軍用來自學如何對抗亡者的那本書。聯盟的學者想要泰坦神話。每一座書架、每一間牢房都訴說著同一個真相：血色十字軍不只殺戮敵人，還控制著追隨者能知道些什麼。"
L["The green shard was not won by simple killing. Eranikus had fallen into nightmare, and Remulos needed the corruption named before it could be answered. The defense of Moonglade became a rite before all who came to stand there: shades pouring from the Dream, Remulos holding the line, and Tyrande's grace turning a dragon's rage toward redemption."] = "綠色碎片不是單靠殺戮就能贏得的。艾瑞尼克斯已墜入夢魘，而雷姆洛斯必須先指出腐化的本質，才能加以應對。月光林地的防衛戰成了所有前來守護者共同見證的儀式：幽影從夢境中傾瀉而出，雷姆洛斯堅守防線，而泰蘭妲的恩典讓一頭巨龍的怒火轉向救贖。"
L["The Horde's road to Onyxia began with Blackrock command papers and the old wound of the Blackhand name. Warlord Goretooth demanded proof from Lower Blackrock Spire, Eitrigg weighed the report in Orgrimmar, and Thrall sent you to kill Warchief Rend Blackhand. Rend's death was a declaration that the Horde would not bow to a false warchief propped up by dragons."] = "部落通往奧妮克希亞之路，始於黑石氏族的命令文件與黑手之名的舊日傷痕。督軍高圖斯要求從黑石塔下層取得證明，伊崔格在奧格瑪審閱報告，索爾則派你去擊殺大酋長雷德·黑手。雷德之死是一份宣言：部落絕不會向一個靠巨龍撐腰的偽大酋長低頭。"
L["The Islander tested your mettle, Bath'rah named the charms, and Cyclonian answered the call. When the storm was defeated, the weapon was yours."] = "島民考驗你的膽識，巴斯拉說出護符的名稱，塞克隆尼亞則回應了召喚。當風暴被擊敗時，這把武器就屬於你了。"
L["The last climb belonged to the dead as much as the living. Grol the Destroyer, Archmage Allistarj, and Lady Sevine each held a piece of Razelikh's power, and Felbane made them mortal enough to fall. The united ward opened the Rise of the Defiler. There, above the ruined land that had swallowed a Horde regiment, Razelikh finally answered for the souls he chained. The Fallen Hero could not undo his failure, but he saw the demon broken and his soldiers released."] = "最後的攀登，既屬於生者，也屬於亡者。毀滅者古羅爾、大法師艾利斯塔爾吉與希雯女士各自掌握著拉瑟里克的一部分力量，而邪能剋星讓他們不再刀槍不入，終能倒下。合而為一的結界開啟了污染者高地。在那裡，在這片吞噬了一支部落部隊的荒蕪大地之上，拉瑟里克終於為他所禁錮的靈魂付出代價。殞落的英雄無法挽回他的失敗，但他親眼看見惡魔被擊潰，他的士兵也獲得了解脫。"
L["The last preparations made the brazier ready. After ghosts, goblins, gladiators, and dungeon shades, the path narrowed to the chamber where Valthalak could answer."] = "最後的準備讓火盆就緒。歷經鬼魂、哥布林、角鬥士與地城幽影之後，道路收束到一間密室，瓦薩拉克將在那裡回應。"
L["The last step was not to kill Yenniku, but to reach him. At the Ruins of Aboraz, beside Zanzil's servants and the haunted Crystal Shore, the Soul Gem turned violence into rescue. Yenniku's soul was pulled free of Zanzil's control and carried back to Nimboya. The work that had begun with trophies and cauldron smoke ended as a Darkspear promise: the tribe would remember the one who brought the chief's son home."] = "最後一步不是殺死耶尼庫，而是觸及他。在阿博拉茲廢墟，在贊吉爾的僕從與鬧鬼的水晶海岸旁，靈魂寶石將暴力化為救援。耶尼庫的靈魂從贊吉爾的控制中被拉出，帶回給尼姆布亞。這段以戰利品與大鍋煙霧開始的工作，最終以暗矛的承諾作結：部族將永遠記得那位帶酋長之子回家的人。"
L["The notice at Westbrook Garrison named a gnoll and a claw. Forest's Edge taught the rest. Hogger stood among the Riverpaw with enough strength to make a simple bounty feel like a hard lesson in the wilds beyond Elwynn's roads. When Marshal Dughan received the claw, the border toward Westfall felt less like open countryside and more like a warning."] = "西泉要塞的告示寫著一隻豺狼人與一隻爪子。其餘的，林邊空地都教會了你。霍格身處河爪豺狼人之中，強大到足以讓一份簡單的懸賞，變成艾爾文道路之外荒野中的一堂嚴酷課程。當治安官杜漢收下那隻爪子時，通往西部荒野的邊境感覺不再像是開闊的鄉間，而更像是一道警告。"
L["The Plaguelands proved the Crusade had become more than a monastery. Scarlet banners flew over towers and towns, Stratholme's living quarter hid the Fordring family painting, and Hearthglen stood as a fortress of certainty. Tirion Fordring, exiled and alone, still believed his son could be saved from it. Forgotten memories, lost honor, and the painting became weapons against fanatic teaching. Disguised as Scarlet, you reached Taelan and watched him remember who he was before the Crusade taught him whom to hate."] = "瘟疫之地證明了十字軍早已不只是一座修道院。血色旗幟飄揚在高塔與城鎮之上，斯坦索姆的生者區藏著弗丁家族的畫像，壁爐谷則是一座堅信不疑的堡壘。遭到放逐、孤身一人的提里奧‧弗丁，仍相信他的兒子能被救出。遺忘的記憶、失落的榮譽，以及那幅畫像，都成了對抗狂熱教義的武器。你偽裝成血色十字軍的一員，找到了泰蘭，看著他想起在十字軍教他該仇恨誰之前，自己原本是誰。"
L["The raft in Un'Goro held a compass, a curled map, a lion-headed key, and a photograph of a gnome in green. Linken knew the belongings, but memory would not come with them. The crater had left him with fragments of an errand, a blade without its tale, and the sense that someone had once entrusted him with more than he could remember."] = "安戈洛的木筏上有一個羅盤、一張捲起的地圖、一把獅頭鑰匙，以及一張身穿綠衣的地精照片。林克認得這些物品，但記憶並未隨之而來。環形山只留給他一段差事的片段、一把沒有故事的劍，以及一種感覺：曾有人託付給他的，遠比他記得的更多。"
L["The records, letters, and keepsakes led from Duskwood to Stormwind, Elwynn, Westfall, and back again. At Mistmantle Manor, Stalvan's legend ended with his ring in Madame Eva's hands."] = "紀錄、信件與紀念品引你從暮色森林前往暴風城、艾爾文、西部荒野，然後再回來。在密斯特曼托莊園，斯塔文的傳說隨著他的戒指交到伊娃夫人手中而落幕。"
L["The red shard was the bluntest path and perhaps the cruelest. Vaelastrasz, already broken by Nefarian, could only point toward the master of Blackwing Lair and set a clock running. The shard was taken from Nefarian under pressure, a raid victory folded into the long duty of the scepter."] = "紅色碎片是最直接，或許也是最殘酷的一條路。早已被奈法利安摧殘的瓦拉斯塔茲，只能指向黑翼之巢的主人，並啟動倒數計時。碎片是在時限壓力下從奈法利安手中奪得的——一場團隊副本的勝利，就此融入節杖漫長的使命之中。"
L["The red tear outside Ahn'Qiraj was memory made visible. Anachronos let the past speak: the night elves, dragons, and qiraji locked in a war old enough to feel mythic. The scepter had broken across dragonflights and tragedies. To open the gates, the champion would have to follow those wounds into the Emerald Dream, Blackwing Lair, and Azshara's blue-dragon riddles."] = "安其拉外的紅色裂痕是被具象化的記憶。阿納克洛斯讓過去開口：夜精靈、巨龍與其拉蟲人陷入一場古老得近乎神話的戰爭。節杖在龍族軍團與悲劇之間碎裂。若要開啟大門，勇士必須循著那些傷痕深入翡翠夢境、黑翼之巢，以及艾薩拉的藍龍謎題。"
L["The second clue turned the riddle into a journey across the sea. In Dustwallow, among Bloodfen raptors, another scrap waited for anyone stubborn enough to keep reading."] = "第二條線索讓謎題成了一趟跨海之旅。在塵泥沼澤的血沼迅猛龍之間，另一張紙片正等著任何夠固執、願意繼續讀下去的人。"
L["The Stockade did not end the matter. Thelwater's visitor, Baros' warning, Shaw's caution, and Trias' quiet knowledge all pointed toward a dangerous friend of the Brotherhood inside Stormwind."] = "暴風城監獄並未讓事情就此結束。塞爾沃特的訪客、巴洛斯的警告、肖爾的謹慎，以及崔亞斯不動聲色的情報，全都指向暴風城內一位與兄弟會往來的危險人物。"
L["The succubus trial warned that not every danger arrives with brute force. You gathered what was required and bound temptation to command."] = "魅魔的試煉警告你，並非所有危險都伴隨蠻力而來。你蒐集了所需之物，將誘惑束縛於你的號令之下。"
L["The Sunken Temple trial asked you to carry the elements as one calling. When the proofs were gathered, your mastery had been tested in full."] = "沉沒的神廟試煉要求你將諸元素視為同一個使命來承載。當證明蒐集齊全時，你的掌控力已受到完整的考驗。"
L["The Tome of the Cabal led through old contacts and dangerous errands. When the binding was done, the felhunter's hunger became your weapon against magic."] = "陰謀之書引領你走過舊日的聯絡人與危險的差事。束縛完成後，惡魔獵犬的飢渴便成了你對抗魔法的武器。"
L["The Tome of Valor led you to Daphne Stilwell and a hard lesson in service. Valor was not spoken over you; it was proven on a dangerous road."] = "勇氣之書引領你找到達芙妮·斯迪威爾，上了一堂關於服務的艱難課程。英勇不是別人為你宣告的，而是在一條危險的路上證明出來的。"
L["The trail began beneath the broken Thandol Span, beside a dwarf pinned in the riverbed. Sully Balloo's letter was not a weapon, a map, or a royal order. It was a husband's goodbye, written before war turned private love into public loss. Sara Balloo received the letter in Ironforge and asked for only one thing more: that her king know what had been given in his name."] = "線索始於殘破的薩多爾大橋下，一名被困在河床上的矮人身旁。蘇利‧巴魯的信既不是武器、地圖，也不是王室命令。那是一位丈夫的道別，寫於戰爭將私人的愛化為公眾的失去之前。薩拉‧巴魯在鐵爐堡收到了這封信，只再提出一個請求：讓她的國王知道，以他之名所付出的是什麼。"
L["The water trial carried you beyond the safety of your trainer. When the pendant was made whole, the sea lion form answered, and deeper waters opened to you."] = "水之試煉帶你走出訓練師的庇護。當墜飾重歸完整時，海獅形態回應了你，更深的水域也為你敞開。"
L["The Woodpaw trail looked at first like scavenging. Then you found Raschal's backpacks pinned to a tree, still bearing Feathermoon insignia. One parcel could be delivered to Thalanaar, a small duty completed in the middle of the search. The other evidence mattered more: a note about strange insect creatures south of the gnoll camps. Raschal had not merely been attacked. He had chosen to investigate a threat under Feralas."] = "木爪豺狼人的蹤跡起初看似只是在搜刮。接著你發現拉沙爾的背包被釘在一棵樹上，仍帶著羽月的徽記。其中一個包裹可以送到薩蘭納爾，在搜尋途中完成了一項小小的職責。另一件證據則更為重要：一張字條，提到豺狼人營地南方有奇怪的昆蟲生物。拉沙爾不只是遭到襲擊。他是選擇了去調查菲拉斯地底的一股威脅。"
L["The worgen were another fear in the dark, hunting through grove and orchard. Calor tested you against them until Master Carevin accepted that you could help keep their teeth from Darkshire."] = "狼人是黑暗中的另一種恐懼，在樹林與果園間獵食。卡洛爾讓你與牠們交手接受考驗，直到卡瑞文大師認可你能協助讓夜色鎮免於牠們的利牙。"
L["The Writhing Deep made the whole case larger. Raschal was alive, sealed inside an alien pod by the Zukk'ash, and his report confirmed that Feralas was facing something more dangerous than a local hive. Shandris Feathermoon sent the warning to Darnassus, where Gracina Spiritmight named the threat: silithid. What began as a missing courier ended as an early warning about the insect menace waiting beneath Azeroth's southern deserts."] = "痛苦深淵讓整起事件的規模擴大了。拉沙爾還活著，被祖卡什封在一個異形莢囊中，而他的報告證實，菲拉斯面對的是比當地蟲巢更危險的東西。珊蒂斯‧羽月將警告送往達納蘇斯，格拉希娜‧靈風在那裡說出了威脅的名字：異種蠍。一起信使失蹤案，最後成了對潛伏在艾澤拉斯南方沙漠之下的蟲族威脅的早期警告。"
L["Theldren's challengers waited in the Ring of Law, where words meant little. You survived the arena, and Anthion had what he needed for the next pieces."] = "瑟爾德倫的挑戰者們在法律之環等候，在那裡言語毫無意義。你在競技場中存活下來，安希恩也得到了下一批碎片所需之物。"
L["Theramore brought the mystery into the open without solving it. Commander Samaul sent you to Sentry Point, Archmage Tervosh guided you to Private Hendel, and Hendel's guard post became the last fight of the trail. When Hendel yielded, Jaina Proudmoore appeared to take charge of the prisoner and thank you quietly for services that could not be publicly named. You had exposed the kidnapping of King Varian Wrynn, but the larger wound remained open: the king was still missing, and someone powerful enough to use the Defias had not yet shown their face."] = "塞拉摩讓謎團浮上檯面，卻沒有揭開它。指揮官薩莫爾派你前往警戒崗哨，大法師特沃許引導你找到士兵亨德爾，而亨德爾的哨站成了這條線索的最後一戰。當亨德爾投降時，珍娜‧普勞德摩爾現身接管了囚犯，並低調地感謝你那些無法公開表揚的貢獻。你揭發了瓦里安‧烏瑞恩國王遭綁架一事，但更大的傷口仍未癒合：國王依舊下落不明，而那個有能力利用迪菲亞的強大幕後之人，至今尚未露面。"
L["Thomas sends you quietly to Bishop DeLavey in Stormwind Keep, where a missing envoy has become a private matter."] = "湯瑪斯悄悄地派你前往暴風要塞找德拉維主教，一名使節的失蹤在那裡已成了私下處理的事。"
L["Tirion Fordring asks for aid in a personal matter that leads through Stratholme and Scarlet-held country."] = "提里奧‧弗丁為一件私事請求協助，這件事將帶你穿越斯坦索姆與血色十字軍掌控的土地。"
L["Travel to Moonglade, hear the Great Bear Spirit, and return ready for the trial of body and heart."] = "前往月光林地，聆聽巨熊之靈的教誨，歸來時做好準備，迎接身與心的試煉。"
L["Trias sends you into Old Town after Dashel Stonefist, whose answers pull the matter beyond Stormwind."] = "崔亞斯派你到舊城區追查達舍爾‧石拳，而他的答案將事情引向暴風城之外。"
L["Turn from worgen to Dalaran, gathering crates, pendants, and rune-work around Ambermill."] = "將目標從狼人轉向達拉然，在安伯米爾周圍蒐集箱子、墜飾與符文裝置。"
L["Turn stolen Scarlet orders against Tyr's Hand and use Nathanos' disguise to walk inside their ranks."] = "利用偷來的血色命令對付提爾之手，並借助納薩諾斯的偽裝混入他們的隊伍。"
L["Tyrion's disguise and spybot drew Lord Gregor Lescovar and Marzon the Silent Blade into the open. Their deaths carried the truth back through Trias, Baros, and the king's court."] = "泰里恩的偽裝與間諜機器人，引出了格里高‧萊斯科瓦領主與『沉默之刃』馬爾松。他們的死讓真相經由崔亞斯、巴洛斯，傳回了國王的朝廷。"
L["Use Dartol's Rod to reach Krolg and turn against Ran Bloodtooth's corrupted furbolg."] = "使用達托爾之杖接近庫羅格，並轉而對抗蘭恩‧血牙麾下已遭腐化的熊怪。"
L["Use Mux's device near Stratholme, then race the city to save Ysida Harmon from the baron."] = "在斯坦索姆附近使用莫克斯的裝置，然後在城中與時間賽跑，從男爵手中救出亞希達·哈莫。"
L["Carry Kin'weelay's Soul Gem into the jungle and look for the moment to free Yenniku."] = "帶著肯維雷的靈魂寶石深入叢林，尋找解救耶尼庫的時機。"
L["Use the taming rod on the beasts your trainer names, then return to learn how to keep a companion."] = "對訓練師指定的野獸使用馴獸棒，然後回去學習如何與夥伴相處。"
L["Follow Linken's memory through strange visions and help his sword remember what he cannot."] = "循著林克的記憶穿越奇異的幻象，協助他的劍記起他記不得的事。"
L["Vaelastrasz gives little time for ceremony. The red shard must be claimed before the chance is lost."] = "瓦拉斯塔茲沒有給你多少客套的時間。必須在機會消失之前奪得紅色碎片。"
L["VanCleef's letter reached Baros Alexston, who remembered the Stonemasons better than most. His concern led to Warden Thelwater, Bazil Thredd, and the riot within the Stockade."] = "范克里夫的信送到了巴洛斯‧艾力克斯頓手中，他比大多數人都更記得石匠公會的事。他的憂慮牽出了典獄官塞爾沃特、巴基爾·斯瑞德，以及暴風城監獄內的暴動。"
L["When the shards were whole, the matter no longer belonged to one champion. The Might of Kalimdor waited on the war effort, the armies at the wall, and all who had prepared for the gates to open. The gong turned a repaired scepter into history: Ahn'Qiraj opened, and the war beyond the Scarab Wall began."] = "當碎片重歸完整，這件事便不再只屬於一位勇士。卡林多之力仰賴著戰爭物資的籌備、城牆前的大軍，以及所有為大門開啟做好準備的人。銅鑼聲讓修復的節杖成為歷史：安其拉大門開啟，甲蟲之牆彼端的戰爭就此展開。"
L["When your hunter trainer turns from weapons to trust, learn how to tame and train a beast. Later, if an ancient leaf ever finds its way into your hands, answer the stranger calling from Felwood."] = "當你的獵人訓練師從武器轉而談到信任時，學習如何馴服並訓練野獸。之後，若有一片遠古的葉子落入你的手中，就去回應那位從費伍德森林呼喚你的陌生人。"
L["When your old dungeon armor has seen enough battle, Deliana or Mokvar will offer work that sounds simple enough: bring the right pieces, prove you are ready, and keep following instructions.\n\nThe errands soon reach far beyond a single set of bracers. Expect old dungeons, stranger patrons, expensive favors, and a brazier whose purpose is not explained all at once."] = "當你那套舊地城護甲已身經百戰，德莉娜或莫克瓦會提供一份聽來夠簡單的工作：帶來正確的部件，證明你已準備就緒，並持續遵照指示行事。\n\n這些差事很快就會遠遠超出一副護腕的範圍。準備好面對古老的地城、更古怪的委託人、代價高昂的人情，以及一座用途不會一次說清的火盆。"
L["Win Theldren's challenge in Blackrock Depths so Anthion can continue the armor work."] = "在黑石深淵贏得瑟爾德倫的挑戰，讓安希恩能繼續護甲的工作。"
L["With Athrikus Narassin weakened, Balthule sent you back into Althalaxx. You climbed past the warlocks of the Dark Strand and ended their master where he had gathered them."] = "埃瑟里克斯‧納拉辛被削弱後，巴蘇爾派你重返奧薩拉克斯。你一路攀爬，越過黑暗之環的術士，在他們的首領聚集眾人之處將其終結。"
L["With Felbane in hand, follow the last names the Fallen Hero gives you and prepare for the demon's reckoning."] = "手握邪能剋星，循著殞落的英雄告訴你的最後幾個名字前進，為惡魔的清算做好準備。"
L["With Onyxia exposed, the Alliance still needed a way into her lair. Bolvar sent you to Haleh, hidden in Winterspring, and Haleh named the final price: the blood of General Drakkisath from Upper Blackrock Spire. The black dragonflight's own champion became the material for the Drakefire Amulet. The court conspiracy was over. The assault on Onyxia could begin."] = "奧妮克希亞的真面目被揭穿後，聯盟仍需要一個進入她巢穴的方法。柏瓦爾派你去找隱居冬泉谷的哈爾琳，而哈爾琳說出了最後的代價：黑石塔上層達基薩斯將軍的鮮血。黑龍軍團自己的勇士，成了龍火護符的材料。宮廷陰謀已經結束，進攻奧妮克希亞的行動終於可以展開。"
L["With the Eye of Divinity in hand, seek Eris Havenfire and protect the spirits entrusted to you."] = "手持神性之眼，前去尋找艾瑞斯·哈文法，並保護託付給你的靈魂。"
L["With the three shards restored, take up the Scepter of the Shifting Sands and return to the Scarab Gong."] = "三塊碎片修復後，拿起流沙節杖，回到甲蟲之鑼。"
L["You answered the call to Moonglade and learned from the Great Bear Spirit. When the final trial was done, the strength of the bear was yours to call upon in battle."] = "你回應了前往月光林地的召喚，向巨熊之靈學習。當最後的試煉完成時，熊的力量便任你在戰鬥中召喚。"
L["You approached the wild as a hunter must: with patience, caution, and respect. When the final beast yielded, you were no longer meant to travel alone."] = "你以獵人應有的方式接近荒野：耐心、謹慎與尊重。當最後一隻野獸屈服時，你便注定不再獨自旅行。"
L["You carried ore, gems, and other hard-won materials back to Jordan Stilwell. Verigan's Fist was not granted by ceremony alone; it was made through effort."] = "你把礦石、寶石和其他得來不易的材料帶回給喬丹·斯迪威爾。維里甘之拳並非單憑一場儀式就能授予，而是靠努力打造出來的。"
L["You carried the sapta, listened to the earth, and proved steady enough to bear its totem. The first element had answered."] = "你帶著神符，聆聽大地之聲，證明自己沉穩得足以承載它的圖騰。第一個元素已經回應了你。"
L["You returned to the one who started the work with a full trail behind you: rescues, bargains, spirits, and old dungeons. The final pieces made the upgraded set a record of where you had been."] = "你回到當初交付這項工作的人身邊，身後留下了一長串足跡：救援、交易、靈魂，還有古老的地城。最後幾件物品，讓這套升級後的裝備成了你一路走來的紀錄。"
L["Your first warrior lesson was not about striking harder. You learned to take the blow, hold your ground, and live long enough to answer."] = "你的第一堂戰士課，學的不是如何出手更重。你學會的是承受打擊、堅守陣地，並活得夠久，才能還以顏色。"
L["Your mage trainer sends you to Tabetha in Dustwallow Marsh, where practical magic begins with travel, errands, and materials that will not gather themselves.\n\nFollow the lessons that turn study into tools: a wand, a strange polymorph, and food enough for hungry companions."] = "你的法師訓練師派你前往塵泥沼澤找塔貝薩。在那裡，實用的魔法始於長途跋涉、跑腿差事，以及不會自己湊齊的材料。\n\n跟隨這些課程，將所學化為工具：一根魔杖、一個奇特的變形術，以及足夠餵飽飢餓同伴的食物。"
L["Your poison training taught the trade plainly: enter unseen, open what is locked, and survive the danger you mean to wield."] = "毒藥訓練直截了當地教會你這門手藝：潛入時不被察覺、打開上鎖之物，並在你想駕馭的危險中活下來。"
