L["Breaking the Stones of Binding turned battle into mercy. One by one, the servants of Razelikh, Grol, Allistarj, and Sevine lost their anchors, and the dead soldiers were released from a fate worse than death. Corporal Thund Splithoof appeared long enough to honor the work and leave a token behind. Then one name remained: Lieutenant Kirith. Finding him in the Serpent's Coil revealed the next truth. Razelikh could not be reached until his protections were understood."] = "摧毀束縛之石，讓戰鬥化為了慈悲。拉瑟利克的僕從格羅爾、艾利斯塔吉和瑟薇恩一一失去了依附，陣亡的士兵也從比死亡更悲慘的命運中解脫。桑德‧裂蹄下士短暫現身，向這份功績致意，並留下一件信物。接著只剩下一個名字：基利斯中尉。在盤蛇谷找到他之後，下一個真相浮出水面：在弄清拉瑟利克的防護之前，根本無法接近他。"
