L["Castle Nathria fell, but Revendreth was not finished with its former ruler. In the Sanguine Depths, General Draven found Z'rali, the naaru whose Light had wounded the realm and whose mercy might yet help contain its sins. Then Remornia, Denathrius's living blade, became the prison that would hold him. The rebellion did not simply execute its master. It chose the harsher, stranger work Revendreth was built for: to bind arrogance, preserve what could still be redeemed, and let time do what vengeance could not."] = "納撒亞城陷落了，但瑞文崔斯與它的前任統治者之間還沒了結。在血紅深淵中，德瑞文將軍找到了那魯茲拉利——它的聖光曾經重創這片國度，而它的慈悲或許仍能幫忙遏止此地的罪孽。隨後，德納修斯的活體之刃雷莫尼亞，成了關押他的牢籠。叛軍並未就此處決他們的主人，而是選擇了瑞文崔斯生來就要承擔的工作，一項更嚴苛、也更奇特的任務：束縛傲慢，保全仍可救贖之物，讓時間去完成復仇無法做到的事。"
L["Castle Nathria's Aftermath"] = "納撒亞城的餘波"
