L["Dashel Stonefist was exactly the sort of contact Trias expected: violent, useful, and unwilling to talk until persuaded. Once subdued, he admitted that his part had ended when the first plan failed. The backup plan involved someone from Menethil Harbor, a man called Slim. Trias knew enough to send you across the sea before the trail went cold."] = "達舍爾‧石拳正是提亞斯預料中的那種人：粗暴、有用，而且不吃點苦頭就不肯開口。被制伏後，他承認第一個計畫失敗時，他的任務就結束了。備用計畫牽涉到米奈希爾港的某個人，一個叫斯林的男人。提亞斯很清楚，必須趕在線索斷掉之前送你渡海。"
L["Dashel's Lead"] = "達舍爾的線索"
