L["Dead Man's Plea"] = "逝者的請求"
L["Death did not make the Bloodscalp leaders cooperative. Nezzliok wanted trophy skulls stolen from the Skullsplitters. Gan'zulah wanted Ana'thek's broken armor and a tally of Skullsplitter hunters, headhunters, and berserkers. The spirits were not redeemed by the cauldron. They were bribed, threatened, and indulged until they finally gave up the truth: Yenniku had not died with the Bloodscalps. Zanzil the Outcast had taken him."] = "死亡並沒有讓血頂部族的首領變得合作。內茲里奧克想要從碎顱部族手中奪來的戰利品顱骨。甘祖拉要的是阿納塞克的破損護甲，外加一份碎顱獵手、獵頭者與狂戰士的擊殺數。大鍋並沒有讓這些靈魂得到救贖。他們被賄賂、被威脅、被縱容，直到終於吐露真相：延尼庫並沒有和血頂部族一起死去，而是被流放者贊吉爾帶走了。"
