L["Deathguard Samsa"] = "亡靈守衛沙穆薩"
L["Deathknell taught the Forsaken their first lesson about Lordaeron's living survivors: the Scarlet Crusade did not see people, only infection. Executor Arren sent you against Scarlet converts and their courier, then read the stolen intelligence and understood the warning. The Crusade was watching Deathknell, counting the dead, and preparing for war."] = "喪鐘鎮讓被遺忘者上了第一課，認清羅德隆那些活著的倖存者是什麼樣子：在血色十字軍眼中沒有人，只有感染。執行官阿倫派你對付血色十字軍的新信徒和他們的信差，接著讀了奪來的情報，明白了其中的警訊：十字軍正在監視喪鐘鎮、清點死者，並準備開戰。"
