L["Duskwood supplied the first hard evidence. Watcher Backus remembered Defias agents gathering around Addle's Stead, and the small farmhouse held the proof: a docket official enough to worry even a veteran watchman. Backus sent it back to Trias, and Trias saw the shape of the next lead in one familiar word: Fist."] = "暮色森林提供了第一份確鑿的證據。守夜人巴庫斯記得迪菲亞的特務曾在腐草農場一帶聚集，而那間小農舍裡正藏著證據：一份正式到足以讓老練守衛都憂心的文件。巴庫斯將它送回給提亞斯，而提亞斯從一個熟悉的字眼中看出了下一條線索的輪廓：「拳」。"
