L["Ginro's next idea was strange even by night elf standards: give the knife to Quintis Jonespyre and let psychometry do what ordinary tracking could not. Quintis saw Raschal taking two large leather backpacks inland, worrying over Woodpaw gnolls, and failing to notice water elementals forming behind him. The knife did not solve the mystery, but it gave the search a direction and a new fear: Raschal had found something worse than gnolls."] = "基恩諾的下一個主意，就連以夜精靈的標準來看都很古怪：把刀子交給奎恩提斯‧炎癮，讓物體感應術做到一般追蹤辦不到的事。奎恩提斯看見拉沙爾帶著兩個大皮背包往內陸走去，一路擔心著木爪豺狼人，卻沒注意到身後正逐漸成形的水元素。這把刀並未解開謎團，卻為搜索指出了方向，也帶來了新的恐懼：拉沙爾遇上了比豺狼人更可怕的東西。"
