L["Jaina and Anduin brought the Alliance's hammer down on Lordaeron. The Horde fought from the walls, but the siege was overwhelming. When the gates could no longer hold, Sylvanas triggered the plague systems beneath the city — releasing the Blight on her own capital rather than let the Alliance take it. Soldiers on both sides choked and died. The Undercity was lost, left poisoned and empty behind her. The Forsaken had no home left. Again."] = "珍娜與安杜因率領聯盟大軍重擊羅德隆。部落在城牆上奮戰，但攻城的力量勢不可擋。當城門再也守不住時，希瓦娜斯啟動了城市底下的瘟疫裝置——寧可在自己的首都釋放凋零瘟疫，也不讓聯盟奪下它。雙方的士兵都窒息而死。幽暗城就此失守，只留下一座遭到毒害的空城。被遺忘者再度無家可歸。"
