L["Magni could not answer Sara's grief with victory, so he answered with remembrance. Grand Mason Marblesten took the commission seriously, sending you into the Darrow Hill cave for Alterac Granite worthy of the memorial. When the stone was cut and the work was done, the tribute no longer belonged only to Sully Balloo. It stood for every soldier whose death had been reduced to orders, borders, and reports until someone stopped long enough to read the letter."] = "麥格尼無法以勝利回應莎拉的悲痛，於是他選擇以紀念來回應。大石匠瑪布勒斯坦認真看待這份委託，派你進入達隆山的洞穴，尋找配得上這座紀念碑的奧特蘭克花崗岩。當石材切割完成、工程竣工時，這份悼念已不只屬於蘇利‧巴魯。它代表著每一位士兵——他們的死亡曾被簡化成命令、邊界與報告，直到有人願意停下腳步，讀完那封信。"
L["Magni orders a rescue, but Blackrock Depths may make it more complicated than an ordinary fight."] = "麥格尼下令展開救援，但黑石深淵可能會讓這件事比一場普通的戰鬥更加棘手。"
