L["Marshal Windsor's return turned suspicion into spectacle. At the gates of Stormwind, he gathered himself for one last duty and marched through the city toward the keep. The guards, nobles, and courtiers saw what the dragon had hidden from them: Lady Katrana Prestor was no noble advisor. She was Onyxia, broodmother of the black dragonflight. Windsor died exposing her, but his sacrifice broke the illusion around Bolvar and gave the Alliance a clear enemy at last."] = "溫德索爾元帥的歸來，讓懷疑化為一場眾目睽睽的揭露。在暴風城門前，他打起精神履行最後的職責，穿過整座城市朝要塞進發。衛兵、貴族與朝臣終於看清了巨龍向他們隱瞞的真相：卡特拉娜‧普瑞斯托女士根本不是什麼高貴的顧問，她是奧妮克希亞，黑龍軍團的龍后。溫德索爾在揭穿她的過程中犧牲，但他的犧牲打破了籠罩伯瓦爾的幻術，也終於讓聯盟看清了敵人。"
