L["Nathanos Blightcaller understood the Scarlet Crusade as an enemy of logistics as much as faith. The Crimson Courier carried command papers through the Plaguelands. Varimathras wanted them read. Nathanos wanted them used. With a rotten apple and a Scarlet disguise, you walked into Tyr's Hand as if you belonged there, then returned with enough truth to send Demetria and her escort to their deaths on the road."] = "納薩諾斯‧凋零者明白，血色十字軍不只靠信仰作戰，也靠後勤運作。紅衣信差帶著指揮文件穿越瘟疫之地。瓦里瑪薩斯想讀懂它們，納薩諾斯則想善加利用。靠著一顆爛蘋果和一身血色十字軍的偽裝，你大搖大擺地走進提爾之手，彷彿你本來就屬於那裡，回來時帶著足夠的情報，讓德米提雅和她的護衛在路上送了命。"
L["Nathanos' Ruse"] = "納薩諾斯的計謀"
