L["Nezzliok's answer made the rescue feel almost impossible. Zanzil controlled Yenniku body and soul, and ordinary weapons could not solve that. Kin'weelay found one thin chance in the legends of Stranglethorn: the Mind's Eye. Pulsing blue shards from Crystalvein Mine prepared the ritual, and Mai'Zoth's ogres guarded the Eye itself inside the Mosh'Ogg mound. With both in hand, Kin'weelay could reshape the magic into a Soul Gem."] = "內茲里奧克的回答，讓這場救援顯得近乎不可能。贊吉爾完全控制了延尼庫的身體與靈魂，這不是尋常武器能解決的問題。肯維雷在荊棘谷的傳說中找到一線希望：心靈之眼。來自水晶礦坑、脈動著藍光的碎片為儀式做好了準備，而心靈之眼本身則由莫什奧格巨魔山裡麥索斯的食人魔看守。兩者到手之後，肯維雷就能將魔法重塑成一顆靈魂寶石。"
L["Night Run, Ashenvale"] = "夜道谷（梣谷）"
L["Night Web Venom"] = "夜網毒液"
L["Nighthaven, Moonglade"] = "永夜港（月光林地）"
L["Nimboya"] = "尼姆布亞"
L["Nimboya's search began with a fear no Darkspear wanted confirmed. Yenniku, the chief's youngest son, had vanished after being given to the Gurubashi, and the Bloodscalp tribe looked like the only trail left. Tusks proved you could hunt them. Shrunken heads proved Yenniku was not among their trophies. Finally, Gan'zulah and Nezzliok had to die so their heads could be forced to answer from the cauldron at Grom'gol."] = "尼姆布亞的搜尋，始於一個沒有任何暗矛食人妖願意證實的恐懼。酋長的麼子延尼庫被送給古拉巴什後就失蹤了，而血頂部族看來是僅存的線索。獠牙證明瞭你有能力獵殺他們，縮頭則證明延尼庫並不在他們的戰利品之中。最後，甘祖拉和內茲里奧克必須一死，好讓他們的頭顱在格羅姆高的大鍋中被迫開口。"
