L["Raene Wolfrunner feared for Teronis, and Ashenvale answered with a corpse. The murlocs near Lake Falathim had killed him, but his journal survived, along with the trail to a glowing gem. Returning both to Astranaar changed the task. Teronis had died looking for a way to slow the furbolg attacks, and Raene asked you to carry that hope forward."] = "萊恩‧狼行者擔心泰羅尼斯的安危，而梣谷給出的答案是一具屍體。他死於法拉希姆湖附近的魚人之手，但他的日記留了下來，還有一條通往一顆發光寶石的線索。把這兩樣東西帶回阿斯特蘭納後，任務的性質變了。泰羅尼斯是在尋找減緩熊怪攻勢的方法時喪命的，而萊恩請你接下這份希望，繼續走下去。"
L["Raene's Cleansing"] = "萊恩的淨化"
L["Rage of Blood"] = "血之狂暴"
L["Ragged John gave the conspiracy a name and a survivor: Marshal Reginald Windsor. Finding Windsor in Blackrock Depths did not bring immediate victory. He had lost hope, and the proof had been torn away from him. A crumpled note and a shred of evidence changed that. Windsor remembered his duty, gathered the missing information, and prepared for the impossible part: walking out of Blackrock Depths alive."] = "狼狽不堪的約翰為這場陰謀揭露了一個名字和一位倖存者：雷吉納德‧溫德索爾元帥。在黑石深淵找到溫德索爾，並未立刻帶來勝利。他已經失去希望，證據也被人奪走。一張皺巴巴的紙條和一點殘存的證據改變了這一切。溫德索爾記起了自己的職責，蒐集了遺失的情報，並準備面對最不可能的部分：活著走出黑石深淵。"
L["Ragged John's Tale"] = "狼狽不堪的約翰的故事"
