L["Shael'dryn knew what Teronis had been chasing: Dartol's Rod, broken into pieces and hidden across Ashenvale's corrupted places. The iron shaft lay behind a key carried by twisted treants near Felwood. The iron pommel had passed through Dor'danil's dead and into the slime. When the rod was remade, a hidden shrine gave it power again. By then, Teronis' errand had become something stranger: not a weapon, but a way to speak across the line between the uncorrupted and the lost."] = "夏爾德琳知道泰羅尼斯一直在追尋什麼：達托爾之杖。它被拆成數段，藏在梣谷各處遭到腐化的地方。鐵製杖身被鎖了起來，鑰匙由費伍德森林附近扭曲的樹人持有。鐵製柄頭則輾轉經過多丹尼爾的亡者之手，最後落入了軟泥怪體內。手杖重鑄之後，一座隱密的神殿讓它重獲力量。此時，泰羅尼斯的任務已變成更奇特的東西：不是一件武器，而是一種跨越界線、讓未受腐化者與迷失者彼此對話的方法。"
