L["Sylvanas Windrunner was a Ranger-General, then a corpse, then a queen the Horde was never fully prepared for. Slain by Arthas at the gates of Silvermoon and raised as the first of his banshees, she clawed her way back to herself and built an undead kingdom from the ruins of Lordaeron.\n\nFollow her from Icecrown and Silverpine into wars that test leadership, vengeance, survival, freedom, and the question of what remains when a Windrunner can no longer run from what she has done."] = "希瓦娜斯‧風行者曾是遊俠將軍，後來成了一具屍體，最後又成為部落從未真正準備好接納的女王。她在銀月城門前被阿薩斯殺害，並被復生為他麾下的第一個女妖。她奮力奪回了自我，在羅德隆的廢墟上建立起一個不死王國。\n\n跟隨她從寒冰皇冠與銀松森林出發，投入一場場考驗領導、復仇、生存與自由的戰爭，並面對一個問題：當一位風行者再也逃不開自己的所作所為時，她還剩下什麼？"
