L["The bronze dragonflight did not greet mortals as allies. Baristolth's trial led to Anachronos, then back through Blackwing Lair and into the Silithus hives. The Head of Broodlord Lashlayer proved strength; the carapace fragments proved endurance. Before the scepter could be repaired, a champion first had to become someone the Brood of Nozdormu would even address."] = "青銅龍軍團並不把凡人當成盟友來迎接。巴里斯托斯的試煉引你找到阿納克洛斯，接著又讓你重返黑翼之巢，再深入希利蘇斯的蟲巢。龍族領主勒西雷爾的頭顱證明了力量，甲殼碎片則證明了毅力。在修復權杖之前，勇士得先成為諾茲多姆的子嗣願意正眼相待的人。"
