L["The Horde path entered the same crisis through a different door: a commander in chains, a prisoner with information, and Thrall reading the politics beneath the dungeon walls. Freeing Moira was not mercy alone. It was strategy. If a Dark Iron child could inherit Ironforge, then Blackrock Depths was not only a prison. It was a future capital waiting in the dark."] = "部落的路線從另一扇門走進了同一場危機：一位身陷鎖鏈的指揮官、一名掌握情報的囚犯，還有洞察地城高牆之下政治局勢的索爾。解救茉艾拉不只是出於仁慈，更是一種策略。如果一個流著黑鐵血脈的孩子能繼承鐵爐堡，那麼黑石深淵就不只是一座監牢，而是一座在黑暗中等待的未來首都。"
L["the house north of Raven Hill Cemetery"] = "烏鴉嶺墓地北方的房子"
L["The Hunter's Path"] = "獵人之道"
L["the Imperial Seat, Blackrock Depths"] = "帝王寶座，黑石深淵"
L["The Instigator's Enchantment"] = "教唆者的附魔"
L["The investigation began with resignation. Latronicus had already declared Raschal missing in action, and Ginro Hearthkindle had spent a week searching Feralas for nothing but gnoll teeth and disappointment. The wrecked row boat on the Forgotten Coast changed that. It was shredded almost in two, marked with Feathermoon's crest, and hiding one small clue in the mud: Raschal's knife."] = "調查是在一片無奈中展開的。拉托尼庫斯早已宣告拉沙爾在任務中失蹤，而基恩諾‧燃爐在菲拉斯搜尋了一個星期，除了豺狼人的牙齒和失望之外一無所獲。被遺忘的海岸上那艘失事的划艇改變了這一切。它幾乎被撕成兩半，上面印著羽月的徽記，泥巴裡還藏著一條小小的線索：拉沙爾的刀子。"
L["The investigation began with secrecy, not ceremony. Thomas found you near the Cathedral and sent you to Bishop DeLavey, who admitted that a diplomat sent to meet Jaina Proudmoore had disappeared. DeLavey suspected the Defias but could not prove it, so he pulled in people outside the usual channels: Jorgen by the Valley of Heroes, then Elling Trias above the cheese shop. The case had already moved from church business to spy work."] = "這場調查始於保密，而非儀式。湯瑪斯在大教堂附近找到你，派你去見德拉維主教。主教坦承，一位奉派前去會見珍娜‧普勞德摩爾的外交官失蹤了。德拉維懷疑是迪菲亞所為，卻苦無證據，於是他找來體制之外的人手：先是英雄谷旁的喬貞，接著是乳酪店樓上的伊林‧提亞斯。這起案子早已從教會事務變成了諜報工作。"
L["The Islander"] = "島民"
