L["The order sounded simple because grief needed it to be simple: kill Thaurissan, spare Moira, bring the princess home. Blackrock Depths answered with something crueler. When the emperor fell, Moira did not thank her rescuers. She mourned her husband, named her unborn child heir to Ironforge, and sent Magni a future he could not command away."] = "這道命令聽起來很簡單，因為悲痛需要它簡單：殺死索瑞森，饒過茉艾拉，把公主帶回家。黑石深淵卻給出了更殘酷的答案。大帝倒下時，茉艾拉並沒有感謝前來救她的人。她為丈夫哀悼，宣布腹中未出世的孩子為鐵爐堡的繼承人，並給麥格尼送去了一個他無法以命令抹去的未來。"
