L["The rod transformed more than your shape. It let you approach Krolg, an uncorrupted furbolg who still carried grief and anger for what had happened to his people. Krolg blamed the night elves, but he also knew Ran Bloodtooth had become a threat no one could ignore. Killing Ran and his guards did not cleanse Ashenvale, but it proved Teronis had not died for nothing. Raene kept the skull and the rod as proof that the forest could still be defended."] = "這根手杖改變的不只是你的外形。它讓你得以接近庫羅格——一位未受腐化的熊怪，仍為族人的遭遇懷抱著悲痛與憤怒。庫羅格怪罪夜精靈，但他也知道，蘭恩‧血牙已經成了無人能忽視的威脅。殺死蘭恩和他的護衛並沒有淨化梣谷，卻證明了泰羅尼斯沒有白白犧牲。萊恩留下了那顆頭骨和手杖，作為這片森林仍能守護的證明。"
