L["the Ruins of Aboraz, along the Crystal Shore"] = "水晶海岸沿岸的阿博拉茲廢墟"
L["the Scarab Wall, Silithus"] = "甲蟲之牆（希利蘇斯）"
L["The Scarlet Bastion in Stratholme did not only guard soldiers and sermons. Its archive held the evidence Duke Nicholas Zverenhoff wanted burned, and Balnazzar's fall showed the deeper rot under the Crusade's purity. The order's zeal was not merely human cruelty. Something worse had been wearing it like a vestment."] = "斯坦索姆的血色堡壘守護的不只是士兵與佈道。它的檔案室裡藏著尼古拉斯‧瑟倫霍夫公爵想燒毀的證據，而巴納札爾的敗亡，揭露了十字軍純潔表象下更深的腐敗。這個教團的狂熱不只是人類的殘酷。有個更可怕的東西，一直像披著聖袍般披著它。"
