L["The trail through Midnight returned to Windrunner Spire, the family home that still held the sisters' wounds in its stone. The halls were not only abandoned; they were haunted by memory, loyalty, resentment, and grief. For Sylvanas's story, the dungeon is context rather than command: a place where the Windrunner name still aches, and where the past keeps answering long after everyone tried to leave it behind."] = "在《至暗之夜》中，這條線索重新回到了風行者塔——這座家族故居的石牆裡，仍留著姊妹們的傷痕。這些廳堂不只是荒廢了，還被回憶、忠誠、怨恨與悲傷所縈繞。對希瓦娜斯的故事而言，這座地城是背景，而非必經之路：在這裡，風行者之名依然隱隱作痛，而即使所有人都試圖將過去拋在身後，它仍不斷給出回應。"
