L["The way into the Sepulcher opened, and the covenants carried the fight into the machinery of creation. With the Crown of Wills reforged and Anduin freed, the final battle moved deeper into the Sepulcher, where Zovaal tried to remake reality through the First Ones' design. He failed. The Jailer fell, and the Shadowlands war finally ended. Only then could Sylvanas be brought before those she had wronged."] = "通往聖塚的道路開啟，誓盟將戰火帶進了創世的機關之中。意志之冠重鑄完成，安杜因也重獲自由，最後的決戰更深入聖塚內部，佐瓦爾企圖藉由首創者的設計重塑現實。他失敗了。閻獄之主倒下，暗影之境的戰爭終於結束。直到這時，希瓦娜斯才能被帶到那些曾被她傷害的人面前。"
