L["Thrall knew Onyxia's threat reached beyond Blackrock Mountain, so he sent you to Rexxar. The champion of the Horde carried old knowledge and a hard road: find Myranda, wear an illusion, gather dragon eyes in Upper Blackrock Spire, and use that disguise to reach Emberstrife. Where the Alliance exposed a dragon in court, the Horde had to deceive a dragon servant into opening the next gate."] = "索爾知道奧妮克希亞的威脅遠不止於黑石山，於是派你去找雷克薩。這位部落的勇士帶來古老的知識，也指出一條艱難的路：找到米蘭達、披上幻象、在黑石塔上層收集龍眼，再利用這身偽裝接近艾博斯塔夫。聯盟是在朝堂上揭穿了一頭巨龍，部落則必須欺騙一名巨龍的僕從，讓牠打開下一道大門。"
