L["Vereesa's visions showed Silvermoon under a shadowed sun, and Arator went looking for the family legacy that might answer it. Alleria was still hunting Xal'atath, and Sylvanas remained in the Maw, freeing the souls she had condemned. So Arator followed the trail no one else wanted to walk: through Ve'nari's gate and into the realm of the damned. The Devouring Host followed him there, and together he and Sylvanas cut them out of the Tremaculum. Arator asked her to come home. Sylvanas refused. Her duty was still among the dead, but she gave him the answer he needed: Silvermoon did need a Windrunner, and he could be one."] = "凡蕾莎的幻象顯示銀月城籠罩在一輪暗影之日下，阿拉特於是出發尋找或許能回應這一切的家族傳承。艾蘭里亞仍在追獵薩拉塔斯，而希瓦娜斯依然留在淵喉，解放那些曾被她定罪的靈魂。因此，阿拉特踏上了一條沒人願意走的路：穿過維娜里的大門，進入罪魂的國度。吞噬大軍也追著他來到那裡，他與希瓦娜斯聯手將它們逐出了崔馬庫倫。阿拉特請她回家，希瓦娜斯拒絕了。她的職責依然在亡者之間，但她給了他所需要的答案：銀月城確實需要一位風行者，而他可以成為那個人。"
