L["Whirlwind Weapon"] = "旋風武器"
L["Wildeyes"] = "戈瑟奇·邪眼"
L["Windrunner Spire"] = "風行者塔"
L["Windrunner Spire opens its haunted halls in Midnight. This is not required for Sylvanas's penance, but it is a sharp look back at the Windrunner family home and the grief left behind by Alleria, Sylvanas, and Vereesa."] = "風行者塔將在《至暗之夜》中敞開它鬼影幢幢的廳堂。這並非希瓦娜斯贖罪之路的必經之地，卻是一次深刻的回望，帶你重返風行者家族的故居，以及艾蘭里亞、希瓦娜斯與凡蕾莎所留下的悲傷。"
L["Windrunner Spire, Eversong Woods"] = "風行者塔（永歌森林）"
L["Windrunner Spire: Haunting Melodies"] = "風行者塔：駭人旋律"
L["Winter Queen"] = "凜冬女王"
L["Wintergarde Keep, Dragonblight"] = "溫特加德要塞（龍骨荒野）"
L["Witch Doctor Zentimo"] = "巫醫贊提莫"
L["Worgen in the Woods"] = "森林裡的狼人"
L["Worn Parchments"] = "破舊的羊皮紙"
L["Wrath of the Lich King — Midnight"] = "巫妖王之怒 — 至暗之夜"
L["Wreckage"] = "殘骸"
L["Wrecked Row Boat"] = "擱淺的小船"
L["Wu Shen"] = "武神"
L["Wu Shen, Stormwind, then Fray Island, The Barrens"] = "吳申，暴風城，接著前往勇士島，貧瘠之地"
L["Xorothian Stardust"] = "克索諾斯星塵"
L["Yaw Sharpmane"] = "雅文·刺鬃"
L["Yaw Sharpmane, Mulgore"] = "亞烏‧銳鬃，莫高雷"
L["Yiska"] = "伊絲卡"
L["You Are Rakh'likh, Demon"] = "惡魔拉瑟萊克"
L["You fought through the Ruins of Gilneas — sabotage, ambushes, a cat-and-mouse hunt through a shattered city — and cornered Godfrey, the man who had betrayed everyone at least once. Sylvanas raised him without ceremony. Then came the final push: Lorna Crowley was captured and brought before her. Sylvanas offered terms. The Gilneas Liberation Front could keep fighting and watch everything turn to dust, or stand aside. It was not a bluff. It was cold, precise, and entirely in character."] = "你一路殺穿吉爾尼斯廢墟——破壞行動、伏擊，還有在殘破城市中展開的貓捉老鼠——最後將高佛萊逼入絕境，這個人至少背叛過每個人一次。希瓦娜斯毫不客套地將他復生。接著是最後的攻勢：羅娜‧克羅雷被俘，帶到了她面前。希瓦娜斯開出了條件：吉爾尼斯解放戰線可以繼續作戰，眼睜睜看著一切化為塵土，或者退到一旁。這不是虛張聲勢。冷酷、精準，完全是她的作風。"
L["Ysida Harmon"] = "亞希達·哈莫"
L["Yvette Farthing"] = "伊維特·法席恩"
L["Zanzil's Hold"] = "贊吉爾的掌控"
L["Zekhan"] = "澤坎"
L["Zombie Juice"] = "僵屍"
L["Zukk'ash Pod"] = "祖卡什蟲繭"
L["A Few Handfuls of Oats"] = "幾把燕麥"
L["Gather oats from the farms of Westfall and bring them back to Verna Furlbrow for Old Blanchy."] = "從西部荒野的農場收集燕麥，帶回給弗娜·法布隆餵老馬布蘭契。"
L["Jansen Stead, Westfall"] = "詹森農場，西部荒野"
L["Old Blanchy"] = "老馬布蘭契"
L["Poor Old Blanchy"] = "可憐的老布蘭契"
L["The Furlbrows had fled their farm with little more than a broken wagon and a hungry old horse. Eight handfuls of oats were not much against the trouble in Westfall, but for Blanchy and the people still trying to leave, it was enough to make the road feel possible again."] = "法布隆夫婦逃離農場時，身邊幾乎只剩一輛壞掉的馬車和一匹飢餓的老馬。面對西部荒野的種種困境，八把燕麥實在算不了什麼，但對布蘭契和那些仍在設法離開的人來說，這已足以讓前方的路再次顯得走得下去。"
L["Verna Furlbrow"] = "弗娜·法布隆"
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Their old horse, Blanchy, has carried more than her share already.\n\nGather what oats you can from the nearby farms. It is a small kindness, but on a hard road even that can matter."] = "弗娜·法布隆和她的丈夫匆忙離開了農場，馬車卻在通往西部荒野的路上壞了。他們的老馬布蘭契早已扛下了超出牠本分的重擔。\n\n從附近的農場盡可能收集燕麥。這只是小小的善意，但在艱難的路上，即使如此也很重要。"
L["Defias camps around Elwynn Forest"] = "艾爾文森林各處的迪菲亞營地"
L["Farmer Furlbrow"] = "農夫法布隆"
L["Furlbrow's Deed"] = "法布隆的地契"
L["Recover the Furlbrows' watch from the pumpkin farm, return any stolen deed you find, and gather oats for Old Blanchy."] = "從南瓜農場找回法布隆夫婦的懷錶，歸還你找到的任何被竊地契，並為老馬布蘭契收集燕麥。"
L["The Forgotten Heirloom"] = "遺失的傳家之寶"
L["The Furlbrows had fled their farm with a broken wagon, a hungry old horse, and too little room for memory. The pocket watch was only a small thing, but it carried a wedding day and a home they might never see again. The oats were just as small, yet for Old Blanchy and the people still trying to leave Westfall, they made the road feel possible again."] = "法布隆夫婦逃離農場時，只帶著一輛壞掉的馬車、一匹飢餓的老馬，幾乎容不下任何回憶。那只懷錶雖然只是個小東西，卻承載著他們的婚禮之日，以及一個他們也許再也見不到的家。燕麥同樣微不足道，但對老馬布蘭契和那些仍在設法離開西部荒野的人來說，它們讓前方的路再次顯得走得下去。"
L["Verna Furlbrow and her husband left their farm in a hurry, only for their wagon to break near the road into Westfall. Behind them are thieves in the fields, a farmhouse they may never see again, and a few keepsakes left in the rush.\n\nRecover what the Furlbrows could not carry, then gather oats for Blanchy. It is a small kindness on the edge of a larger ruin."] = "弗娜·法布隆和她的丈夫匆忙離開了農場，馬車卻在通往西部荒野的路上壞了。他們身後是田野間的盜賊、一座也許再也見不到的農舍，以及在倉皇中遺落的幾件紀念品。\n\n找回法布隆夫婦帶不走的東西，再為布蘭契收集燕麥。在一場更大的浩劫邊緣，這只是一份小小的善意。"
L["What They Left Behind"] = "他們留下的東西"
L["Westfall"] = "西部荒野"
L["Apothecary Faustin"] = "藥劑師法奧斯丁"
L["Beggar's Haunt"] = "乞丐鬼屋"
L["Beggar's Haunt, Duskwood"] = "乞丐鬼屋（暮色森林）"
L["Deathstalker Zraedus"] = "亡靈哨兵萊度斯"
L["Deepstrider Giants"] = "深行者巨人"
L["Duskwood / Swamp of Sorrows / Desolace"] = "暮色森林 / 悲傷沼澤 / 淒涼之地"
L["eastern Swamp of Sorrows"] = "悲傷沼澤東部"
L["Faustin's Serum"] = "法奧斯丁的血清"
L["Infiltrator Marksen"] = "間諜瑪克森"
L["Meet the Forsaken agents hidden in Duskwood and help prepare a truth serum for Stonard's prisoner."] = "與藏身於暮色森林的被遺忘者特務會面，協助為斯通納德的囚犯調製吐真劑。"
L["Mire Lord"] = "泥沼之王"
L["Misty Valley, Swamp of Sorrows"] = "迷霧谷（悲傷沼澤）"
L["North of the road into Deadwind Pass, two Forsaken agents keep a quiet post at Beggar's Haunt. A human infiltrator has seen too much, and Stonard's orcs have taken him alive before the matter could be settled.\n\nWork with Deathstalker Zraedus and Apothecary Faustin on a serum meant to draw out the truth. They are very particular about whose truth reaches the Horde."] = "在通往逆風小徑的道路北側，兩名被遺忘者特務在乞丐鬼屋悄悄駐守。一名人類滲透者看到了太多不該看的事，而在事情了結之前，斯通納德的獸人就已將他生擒。\n\n與亡靈哨兵萊度斯和藥劑師法奧斯丁合作，調製一種能逼出真相的血清。至於誰的真相能傳到部落耳中，他們可是非常講究。"
L["Nothing But The Truth"] = "真言藥水"
L["Shadow Panthers"] = "暗影黑豹"
L["Stonard's Prisoner"] = "斯通納德的囚犯"
L["The Truth Serum"] = "吐真劑"
L["the coast near Ethel Rethor, Desolace"] = "伊瑟雷索附近的海岸，淒涼之地"
L["Zraedus and Faustin called it help for their orcish allies, but every errand served the same purpose: keep the captive in Stonard from saying too much. The serum needed panther hearts, rare fungus, and a giant's tumor before Faustin could finish it. By the time Marksen drank the disguised brew, the truth was already losing its chance to be heard."] = "萊度斯和法奧斯丁聲稱這是在協助他們的獸人盟友，但每一項差事都只為了同一個目的：不讓斯通納德的俘虜說出太多。法奧斯丁要完成血清，得先湊齊黑豹的心臟、稀有的真菌，以及巨人的腫瘤。等到馬克森喝下那瓶偽裝過的藥劑時，真相早已失去被聽見的機會。"
L["Zraedus's Request"] = "萊度斯的請求"
L["The Shady Rest Inn"] = "樹蔭旅店"
L["On the road between Dustwallow Marsh and the Barrens, the Shady Rest Inn is nothing but ash, hoofprints, a scorched shield, and a guard badge that should not be there.\n\nFollow the clues before faction blame buries the truth. What begins as a burned waystation becomes an investigation through evidence that may have been left to tell too simple a story."] = "在塵泥沼澤與貧瘠之地之間的路上，樹蔭旅店只剩下灰燼、蹄印、一面燒焦的盾牌，以及一枚不該出現在那裡的衛兵徽章。\n\n趕在陣營間的互相指責埋沒真相之前，追查這些線索。一座被燒毀的驛站就此引出一場調查，而這些證據或許是有人刻意留下，好讓故事顯得太過簡單。"
L["Dustwallow Marsh"] = "塵泥沼澤"
L["World of Warcraft"] = "World of Warcraft"
L["Suspicious Hoofprints"] = "可疑的蹄印"
L["Hoofprints"] = "蹄印"
L["the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "樹蔭旅店廢墟，塵泥沼澤"
L["Foothold Citadel, Theramore Isle"] = "塞拉摩堡壘（塞拉摩島）"
L["Lost Point, Dustwallow Marsh"] = "廢棄哨塔（塵泥沼澤）"
L["North Point Tower, Dustwallow Marsh"] = "北點哨塔（塵泥沼澤）"
L["the Theramore blacksmith, Dustwallow Marsh"] = "塞拉摩的鐵匠，塵泥沼澤"
L["Brackenwall Village, Dustwallow Marsh"] = "蕨牆村（塵泥沼澤）"
L["Theramore Isle, Dustwallow Marsh"] = "塞拉摩島（塵泥沼澤）"
L["outside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "樹蔭旅店廢墟外，塵泥沼澤"
L["Tabetha's Farm, Dustwallow Marsh"] = "塔貝薩的農場（塵泥沼澤）"
L["inside the ruins of the Shady Rest Inn, Dustwallow Marsh"] = "樹蔭旅店廢墟內，塵泥沼澤"
L["The Ruins"] = "廢墟"
L["Captain Garran Vimes sends you to the burned inn, where the first clues point in several uncomfortable directions."] = "蓋蘭·維米斯隊長派你前往被燒毀的旅店，而最初的線索指向了好幾個令人不安的方向。"
L["The ruins did not offer a clean answer. Hoofprints marked the ash outside the inn, a blackened shield suggested a tauren hand, and a Theramore badge tied the scene to Lieutenant Paval Reethe. Even Smiling Jim's grief only sharpened the question: who wanted everyone looking at the wrong enemy?"] = "廢墟並沒有給出明確的答案。旅店外的灰燼上留著蹄印，一面燒黑的盾牌暗示著牛頭人的手筆，而一枚塞拉摩徽章則將現場與帕瓦爾·雷瑟上尉連在一起。就連微笑吉姆的悲痛，也只讓問題變得更加尖銳：到底是誰想讓所有人把矛頭指向錯誤的敵人？"
L["Inspecting the Ruins"] = "勘查廢墟"
L["Captain Garran Vimes"] = "蓋蘭·維米斯隊長"
L["They Call Him Smiling Jim"] = "微笑的吉姆"
L["Guard Byron"] = "衛兵拜倫"
L["The Black Shield"] = "黑色盾牌"
L["Follow the scorched shield from the ruined fireplace back through Theramore's smiths."] = "從廢墟壁爐中的燒焦盾牌著手，循線追查到塞拉摩的鐵匠。"
L["The black shield looked like the simplest clue, and so it became the most dangerous one. Caz Twosprocket could tell it was not made in Theramore, and the size suggested a tauren bearer, but certainty stayed out of reach. The clue was real, yet it still felt planted to push anger toward the Horde."] = "黑色盾牌看似最簡單的線索，也因此成了最危險的一條。卡茲·雙鏈看得出它並非塞拉摩所造，而盾牌的尺寸暗示持有者是牛頭人，但真正的定論依然遙不可及。這條線索是真的，卻仍像是有人刻意栽贓，要把怒火引向部落。"
L["Black Shield"] = "黑色盾牌"
L["The Black Shield: Caz Twosprocket"] = "黑色盾牌：卡茲·雙鏈"
L["The Black Shield: Vimes' Report"] = "黑色盾牌：維米斯的報告"
L["Caz Twosprocket"] = "卡茲·雙鏈"
L["Paval Reethe"] = "帕瓦爾·雷瑟"
L["Trace the Theramore Guard badge to Paval Reethe and the deserters at Lost Point."] = "循著塞拉摩衛兵徽章，追查到帕瓦爾·雷瑟和廢棄哨塔的逃兵。"
L["The guard badge led away from the inn and into Theramore's own troubles. Paval Reethe had deserted, and Balos Jacken's men at Lost Point had little love left for their old command. Reethe looked guilty enough to be useful, but not guilty enough to be the answer."] = "衛兵徽章將線索引離旅店，帶進了塞拉摩自身的麻煩之中。帕瓦爾·雷瑟已經叛逃，而巴魯斯·加科因在廢棄哨塔的手下，對他們的舊上司早已沒剩多少好感。雷瑟看起來夠可疑，足以拿來利用，卻還不足以成為真正的答案。"
L["Lieutenant Paval Reethe"] = "帕瓦爾·雷瑟上尉"
L["Theramore Guard Badge"] = "塞拉摩衛兵徽章"
L["Lieutenant Paval Reethe: Records"] = "帕瓦爾·雷瑟上尉：紀錄"
L["Daelin's Men"] = "戴林的下屬"
L["Adjutant Tesoran"] = "泰索蘭副官"
L["The Deserters"] = "背叛者"
L["The Deserters: Lost Point"] = "背叛者：廢棄哨塔"
L["The Deserters: Balos' Account"] = "背叛者：巴魯斯的證詞"
L["Balos Jacken"] = "巴魯斯·加科因"
L["The Hidden Hand"] = "幕後黑手"
L["The evidence carries you north to one more camp, then south to Tabetha for a clearer look at the hand behind the fire."] = "證據先帶你北上前往另一座營地，再南下去找塔貝薩，看清縱火案背後的那隻黑手。"
L["The missing piece was not a deserter or a city guard, but a Grimtotem move meant to poison Theramore and the Horde against each other. Captain Darill's evidence exposed Blackhoof Village as part of the plot, while Tabetha pointed to Direhorn Post as the real source of the attack. When the camp burned, the Shady Rest finally had an answer."] = "缺少的那塊拼圖既不是逃兵，也不是城衛，而是恐怖圖騰的一步棋，意在挑撥塞拉摩與部落反目成仇。達利爾上尉的證據揭露了黑蹄村也是陰謀的一環，而塔貝薩則指出恐角崗哨才是這次襲擊的真正源頭。當那座營地陷入火海，樹蔭旅店終於有了答案。"
L["A Grim Connection"] = "恐怖的關聯"
L["Confirming the Suspicion"] = "證實懷疑"
L["Captain Darill"] = "達利爾上尉"
L["Arms of the Grimtotems"] = "恐怖圖騰的武器"
L["Tabetha's Assistance"] = "塔貝薩的協助"
L["Raze Direhorn Post!"] = "夷平恐角崗哨！"
L["Justice for the Hyals"] = "為海亞爾一家討回公道"
L["Peace at Last"] = "終得安息"
L["Krog has orders to investigate the burned inn, but the real clues are waiting in the ash."] = "克羅格奉命調查被燒毀的旅店，但真正的線索正埋在灰燼之中。"
L["The ruins were not merely Alliance grief. Hoofprints, a scorched shield, and a Theramore badge could all be read as accusations, and Krog wanted the Horde's answers before Theramore wrote the story for everyone. The evidence pointed at tauren ironwork and Paval Reethe, but neither trail felt complete."] = "這片廢墟不只是聯盟的傷痛。蹄印、燒焦的盾牌和塞拉摩徽章，都可能被解讀成指控，而克羅格想在塞拉摩替所有人定下說法之前，先找到部落自己的答案。證據指向牛頭人的鐵器和帕瓦爾·雷瑟，但兩條線索都不完整。"
L["Krog"] = "克羅格"
L["Carry the blackened shield through Brackenwall and Thunder Bluff until Mosarn can place the craft."] = "帶著燒黑的盾牌輾轉於蕨牆村與雷霆崖，直到莫薩恩辨認出它的工藝來歷。"
L["The shield should have settled the matter, but it only made the case stranger. Krog, Do'gol, and Mosarn could follow the iron's story, yet the shield alone did not prove who set the fire. It was a clue with enough truth to be useful and enough ambiguity to start a war."] = "這面盾牌本該讓事情水落石出，卻只讓案情變得更加離奇。克羅格、杜高爾和莫薩恩能追溯這塊鐵的來歷，但光憑盾牌，無法證明是誰放的火。這條線索的真實程度足以派上用場，模糊之處卻也足以引發一場戰爭。"
L["The Black Shield: Do'gol"] = "黑色盾牌：杜高爾"
L["The Black Shield: Do'gol's Findings"] = "黑色盾牌：杜高爾的發現"
L["Do'gol"] = "杜高爾"
L["The Black Shield: Return to Krog"] = "黑色盾牌：回到克羅格身邊"
L["The Black Shield: Mosarn"] = "黑色盾牌：莫薩恩"
L["Track Paval Reethe with Ogron's help and see why the badge was left behind."] = "在奧格隆的協助下追蹤帕瓦爾·雷瑟，查明那枚徽章為何會被留下。"
L["Paval Reethe was real, cornered, and dangerous, but the speed of his death made him look less like the murderer and more like a man someone needed silenced. The badge at the inn had not solved the case. It had revealed how badly someone wanted a convenient suspect."] = "帕瓦爾·雷瑟確有其人，被逼入絕境，也確實危險，但他死得如此之快，讓他看起來不像兇手，反倒更像是有人急著滅口的對象。旅店裡的徽章並沒有破案，反而揭露了某人有多麼想要一個方便的嫌犯。"
L["Questioning Reethe"] = "盤問雷瑟"
L["Ogron"] = "奧格隆"
L["Mosarn's new lead brings the investigation back to Krog, then south to Tabetha for a clearer look at the hand behind the fire."] = "莫薩恩的新線索將調查帶回克羅格身邊，再南下去找塔貝薩，看清縱火案背後的那隻黑手。"
L["Mosarn's memory reopened the case and pulled the scattered clues into one line: the Grimtotem had used the inn to inflame Theramore and the Horde. Krog's evidence and Tabetha's certainty led to Direhorn Post. Burning it down did not restore the Shady Rest, but it stopped the lie from doing more work."] = "莫薩恩的回憶讓案子重新展開，也將零散的線索串成一條線：恐怖圖騰利用這間旅店，煽動塞拉摩與部落之間的怒火。克羅格的證據和塔貝薩的篤定，將你引向恐角崗哨。燒毀那裡並沒有讓樹蔭旅店恢復原貌，卻阻止了這個謊言繼續作祟。"
L["Return to Krog"] = "回到克羅格身邊"
L["Mosarn"] = "莫薩恩"
L["More than Coincidence"] = "不只是巧合"
L["The Grimtotem Plot"] = "恐怖圖騰的陰謀"
L["Seek Out Tabetha"] = "尋找塔貝薩"
L["Justice Dispensed"] = "正義得以伸張"
L["The Hakkari Trail"] = "哈卡萊之路"
L["At Steamwheedle Port, Yeh'kinya asks for help with old troll spirits and older tablets. The work sounds archaeological at first, but the names on the tablets are not harmless history.\n\nFollow the trail from Feralas and Zul'Farrak to Jintha'Alor, the Temple of Atal'Hakkar, Blackrock Spire, and finally Yojamba Isle. What begins as a favor for a lone troll becomes a warning about the Soulflayer's return."] = "在熱砂港，葉基亞請你協助處理古老的食人妖靈魂，以及更加古老的石板。這份工作起初聽來像是考古，但石板上的名字可不是無害的歷史。\n\n循著線索從菲拉斯和祖爾法拉克前往辛薩羅、阿塔哈卡神廟、黑石塔，最後抵達尤亞姆巴島。起初只是幫一個孤身食人妖的小忙，最後卻成了一則關於奪魂者歸來的警告。"
L["Tanaris / Feralas / Zul'Farrak / The Hinterlands / Sunken Temple / Blackrock Spire / Stranglethorn Vale"] = "塔納利斯 / 菲拉斯 / 祖爾法拉克 / 辛特蘭 / 沉沒的神廟 / 黑石塔 / 荊棘谷"
L["Zul'Farrak"] = "祖爾法拉克"
L["Screecher Spirits"] = "尖嘯者的靈魂"
L["Yeh'kinya"] = "葉基亞"
L["Steamwheedle Port, Tanaris"] = "熱砂港（塔納利斯）"
L["Zul'Farrak, near Gahz'rilla's pool"] = "祖爾法拉克，加茲瑞拉的水池附近"
L["the summit cave at Jintha'Alor, The Hinterlands"] = "辛薩羅山頂的洞穴，辛特蘭"
L["the Sanctum of the Fallen God, Temple of Atal'Hakkar"] = "墮落之神的聖所，阿塔哈卡神廟"
L["Zul'Mashar, Eastern Plaguelands"] = "祖瑪沙爾（東瘟疫之地）"
L["Lower Blackrock Spire"] = "黑石塔下層"
L["Yojamba Isle, Stranglethorn Vale"] = "尤亞姆巴島（荊棘谷）"
L["Yeh'kinya sends you into Feralas to question the spirits of Vale Screechers."] = "葉基亞派你前往菲拉斯，向谷地尖嘯者的靈魂問話。"
L["The first clue was not written on stone. Yeh'kinya's bramble drew memories from dead screechers in Feralas, and those spirits pointed toward an old troll prophecy. The errand had opened a door into Hakkari history."] = "第一條線索並非刻在石頭上。葉基亞的荊棘從菲拉斯死去的尖嘯者身上汲取記憶，而那些靈魂指向了一則古老的食人妖預言。這趟差事為你打開了一扇通往哈卡萊歷史的大門。"
L["The Prophecy of Mosh'aru"] = "摩沙魯的預言"
L["Recover the first two Mosh'aru tablets from Zul'Farrak, then seek the ancient egg hidden in Jintha'Alor."] = "從祖爾法拉克取回前兩塊莫沙魯石板，接著前往辛薩羅尋找藏在那裡的遠古之卵。"
L["Zul'Farrak held the first tablets: one with Theka the Martyr, one near Hydromancer Velratha and the sacred pool. Their prophecy named an ancient egg, a relic from the age of troll empires. At Jintha'Alor, the egg waited behind the amphitheater at the top of the city, guarded by the kind of history that still had teeth."] = "祖爾法拉克藏著最初的石板：一塊在殉教者塞卡身上，另一塊則在水占師維蕾薩和聖池附近。石板上的預言提到一顆遠古之卵，那是食人妖帝國時代的遺物。在辛薩羅，這顆卵就藏在城市頂端的圓形劇場後方，守護它的是一段至今仍然獠牙畢露的歷史。"
L["The Ancient Egg"] = "遠古之卵"
L["The God Hakkar"] = "神靈哈卡"
L["Carry the egg into the Temple of Atal'Hakkar and bind the avatar's essence inside it."] = "將卵帶進阿塔哈卡神廟，把化身的精華封印在其中。"
L["The temple in the Swamp of Sorrows gave the prophecy its true weight. The egg was not merely a container for old magic; it was a vessel for Hakkar's essence. In the Sanctum of the Fallen God, the avatar rose, fell, and left behind power Yeh'kinya had asked you to gather."] = "悲傷沼澤中的神廟讓這則預言顯露出真正的分量。這顆卵不只是盛裝古老魔法的容器，更是承載哈卡精華的器皿。在墮落之神的聖所裡，化身甦醒、倒下，並留下了葉基亞要你收集的力量。"
L["The Final Tablets"] = "最後的石板"
L["Prospector Ironboot reveals the missing tablets and sends you to Eastern Plaguelands and Lower Blackrock Spire."] = "勘查員詹斯·鐵靴揭露了遺失的石板，並派你前往東瘟疫之地和黑石塔下層。"
L["Prospector Ironboot saw the lie in the work Yeh'kinya had given you. There were six tablets, not two, and the rest changed the meaning of the prophecy. Zul'Mashar held the third and fourth; Lower Blackrock Spire held the final pair. Piece by piece, the tablets stopped sounding like a way to contain Hakkar and started sounding like a way to bring him back."] = "勘查員詹斯·鐵靴看穿了葉基亞交給你的差事中的謊言。石板共有六塊，而不是兩塊，其餘的石板徹底改變了預言的含義。第三和第四塊在祖瑪沙爾，最後兩塊則在黑石塔下層。隨著石板一塊塊湊齊，它們聽起來不再像是封印哈卡的方法，反倒像是讓他歸來的方法。"
L["The Lost Tablets of Mosh'aru"] = "失落的摩沙魯石板"
L["Prospector Ironboot"] = "勘查員詹斯·鐵靴"
L["The Hand of Rastakhan"] = "拉斯塔哈之手"
L["Confront Yeh'kinya, then carry Ironboot's warning to Molthor on Yojamba Isle."] = "面對葉基亞，然後將鐵靴的警告帶給尤亞姆巴島上的莫托爾。"
L["Yeh'kinya had not been preserving the world from Hakkar. He had sped the Soulflayer's return. The truth turned a long dungeon trail into a Zandalar summons, and Molthor received the warning on Yojamba Isle. The fight had moved beyond tablets and temples. Zul'Gurub was waiting."] = "葉基亞並不是在保護世界免受哈卡之害，而是在加速奪魂者的歸來。真相讓這條漫長的地城之路，化為一道來自贊達拉的召集令，莫托爾也在尤亞姆巴島上收到了警告。戰鬥已不再侷限於石板與神廟。祖爾格拉布正等著你。"
L["Confront Yeh'kinya"] = "面對葉基亞"
L["Maraudon"] = "瑪拉頓"
L["The crystal caverns beneath Desolace are holy ground, burial ground, and wound all at once. Satyrs, centaur spirits, corrupted plants, and an earth princess all pull at the same buried story.\n\nEnter Maraudon from the orange and purple passages, recover the Scepter of Celebras, and follow the descent to Princess Theradras and the remains of Zaetar."] = "淒涼之地底下的水晶洞穴，既是聖地，也是墓地，更是一道傷口。薩特、半人馬的靈魂、遭到腐化的植物，以及一位大地公主，全都牽扯著同一段埋藏地底的故事。\n\n從橘色與紫色通道進入瑪拉頓，取回瑟萊布拉斯權杖，再一路深入，直抵瑟萊德絲公主與札爾塔的遺骸所在。"
L["Desolace / Maraudon / Moonglade"] = "淒涼之地 / 瑪拉頓 / 月光林地"
L["The Pariah's Instructions"] = "賤民的指引"
L["Centaur Pariah"] = "半人馬賤民"
L["southern Desolace"] = "淒涼之地南部"
L["southern Desolace, near the Valley of Spears"] = "淒涼之地南部，長矛谷附近"
L["Kormek's Hut, Desolace"] = "考米克小屋（淒涼之地）"
L["Shadowprey Village, Desolace"] = "葬影村（淒涼之地）"
L["the orange crystal passage, Maraudon"] = "橘色水晶通道，瑪拉頓"
L["south of Shadowprey Village, Desolace"] = "葬影村南方，淒涼之地"
L["Earth Song Falls, Maraudon"] = "地歌瀑布，瑪拉頓"
L["The Pariah and the Prophet"] = "賤民與先知"
L["Follow the Centaur Pariah's instructions and heed Willow's request for Maraudon's carved crystals."] = "依照半人馬賤民的指示行事，並答應薇蘿的請求，收集瑪拉頓的雕刻水晶。"
L["Before the inner caverns, Maraudon offered two warnings. The Centaur Pariah named the khans and the Nameless Prophet, a path through the centaur dead. Willow, far less trustworthy, wanted Theradric carvings from the same twisted place. Both errands made the caverns feel older than Desolace's current wars."] = "在深入內部洞穴之前，瑪拉頓先給了你兩個警告。半人馬賤民說出了諸位可汗與無名先知的名字，那是一條穿越半人馬亡者的道路。遠不如他可信的薇蘿，則想要同一個扭曲之地出產的瑟萊德雕刻。這兩項差事都讓人感覺，這些洞穴比淒涼之地眼下的戰爭還要古老。"
L["Twisted Evils"] = "扭曲的邪惡"
L["Willow"] = "維洛"
L["Vyle Corruption"] = "邪惡腐化"
L["Cleanse Vylestem vines in the orange caverns and gather shadowshards from the purple side."] = "淨化橘色洞穴中的邪莖藤蔓，並在紫色那一側收集暗影碎片。"
L["Vyletongue's corruption was not only demonic; it had soaked into Maraudon's plants and crystals. Talendria or Vark sent you to fill a vial at the orange pool and draw the poison out plant by plant. The shadowshards outside the purple passage told the same story in stone: the caverns were sick, and the sickness had useful fragments for people outside."] = "維利塔恩帶來的腐化不只是惡魔之力，更已滲入瑪拉頓的植物與水晶之中。塔琳德莉亞或瓦克派你到橘色水池裝滿一瓶水，再一株一株地把毒素逼出來。紫色通道外的暗影碎片，則在石頭上訴說著同樣的故事：這些洞穴病了，而這場病還留下了一些對外人有用的碎片。"
L["Vyletongue Corruption"] = "維利塔恩的污染"
L["Talendria"] = "塔琳德莉亞"
L["Vark Battlescar"] = "瓦克·戰痕"
L["Shadowshard Fragments"] = "暗影殘片"
L["Theramore, Dustwallow Marsh"] = "塞拉摩，塵泥沼澤"
L["Uthel'nay"] = "尤塞爾奈"
L["The Scepter of Celebras"] = "塞雷布拉斯節杖"
L["Recover the Celebrian rod and diamond, free Celebras, and restore the scepter."] = "取回瑟萊布里安之杖與鑽石，解放瑟萊布拉斯，並修復權杖。"
L["Cavindra's plea gave the dungeon its heart. Noxxion held the rod, Lord Vyletongue held the diamond, and Celebras himself wandered under corruption. Once the keeper was defeated and redeemed, the two pieces could become a scepter again, not only a shortcut through Maraudon but a sign that some part of the place could still be restored."] = "凱雯德拉的懇求，賦予了這座地城真正的核心。諾克賽恩持有法杖，維利塔恩領主持有鑽石，而瑟萊布拉斯本人則在腐化中徘徊。當這位守護者被擊敗並得到救贖後，兩件碎片便能重新合為一柄權杖。它不只是穿越瑪拉頓的捷徑，更象徵著這個地方仍有一部分能夠復原。"
L["Legends of Maraudon"] = "瑪拉頓的傳說"
L["Cavindra"] = "凱雯德拉"
L["Celebras the Redeemed"] = "贖罪的塞雷布拉斯"
L["Corruption of Earth and Seed"] = "大地的污染"
L["Slay Princess Theradras, learn what became of Zaetar, and carry the Seed of Life to Remulos."] = "擊殺瑟萊德絲公主，查明札爾塔的下落，並將生命之種帶給雷姆洛斯。"
L["At the bottom of Maraudon, Princess Theradras guarded both destruction and grief. Zaetar's remains had fed the place into strange life, and his spirit asked for something gentler than vengeance: a seed carried to his brother in Moonglade. The dungeon ended not with a clean victory over the centaur's origin, but with proof that Zaetar had become part of the land."] = "在瑪拉頓的最深處，瑟萊德絲公主守護著毀滅，也守護著悲傷。札爾塔的遺骸滋養了這片土地，催生出奇異的生命，而他的靈魂所求的並非復仇，而是更溫柔的事：將一顆種子帶給他在月光林地的兄弟。這座地城的結局並非戰勝半人馬起源的乾脆勝利，而是證明了札爾塔已化為這片土地的一部分。"
L["Keeper Marandis"] = "守護者瑪蘭迪斯"
L["Selendra"] = "瑟琳德拉"
L["Seed of Life"] = "生命之種"
L["Zaetar's Spirit"] = "札爾塔的靈魂"
L["Scarlet Monastery Library, Tirisfal Glades"] = "血色修道院圖書館，提里斯法林地"
L["Retrieve %s from %s and return to %s in %s."] = "取回%s（來源：%s），然後交給%s（位於%s）。"
L["the Monastery in Tirisfal Glades"] = "提里斯法林地的修道院"
L["Going, Going, Guano!"] = "蝙蝠的糞便"
L["Caer Darrow's ruined school is locked behind more than a door. The Scourge has made Scholomance a place of experiments, ghosts, noble inheritance, and old betrayals that refuse to stay buried.\n\nForge the Skeleton Key, then follow the stories waiting inside: Eva Sarkhoff's revenge, Kirtonos, Ras Frostwhisper's lost humanity, and the Barov family's poisoned fortune."] = "凱爾達隆那座殘破的學院，鎖住它的不只是一道門。天譴軍將通靈學院變成了一個充斥著實驗、鬼魂、貴族遺產，以及不肯被埋葬的古老背叛之地。\n\n打造骷髏鑰匙，然後追尋在學院中等待著你的故事：艾瓦·薩克霍夫的復仇、基爾圖諾斯、萊斯·霜語失落的人性，以及巴羅夫家族那筆被下了毒的財富。"
L["Western Plaguelands / Tanaris / Un'Goro Crater / Scholomance"] = "西瘟疫之地 / 塔納利斯 / 安戈洛環形山 / 通靈學院"
L["the ruins of Andorhal, Western Plaguelands"] = "安多哈爾廢墟，西瘟疫之地"
L["Doctor Theolen Krastinov's room, Scholomance"] = "瑟爾林‧卡斯迪諾夫醫生的房間，通靈學院"
L["the Chamber of Summoning, Scholomance"] = "召喚之廳，通靈學院"
L["near the Bulwark, Tirisfal Glades"] = "亡靈壁壘附近，提里斯法林地"
L["The Skeleton Key"] = "骷髏鑰匙"
L["After proving yourself in the Plaguelands, forge the Skeleton Key that opens Scholomance."] = "在瘟疫之地證明自己的實力後，打造能開啟通靈學院的骷髏鑰匙。"
L["Scholomance was not simply entered. Arbington or Dithers sent you through bones from Andorhal, a costly goblin mold in Gadgetzan, a forging at Fire Plume Ridge, and Araj's scarab in the ruined city. The finished Skeleton Key turned Caer Darrow's locked academy from a rumor into a place you could finally confront."] = "通靈學院可不是說進就能進的。阿賓頓或迪瑟斯讓你一路收集安多哈爾的骨頭、在加基森取得昂貴的哥布林模具、在火羽山進行鍛造，再到廢墟之城奪取阿拉基的聖甲蟲。完成的骷髏鑰匙，讓凱爾達隆那座深鎖的學院從傳聞變成了一個你終於能夠直面的地方。"
L["Skeletal Fragments"] = "骸骨碎片"
L["Alchemist Arbington"] = "化學家阿爾比頓"
L["Apothecary Dithers"] = "藥劑師迪瑟斯"
L["Mold Rhymes With..."] = "昂貴的模具"
L["Fire Plume Forged"] = "火羽山"
L["Krinkle Goodsteel"] = "克林科·古德斯迪爾"
L["Araj's Scarab"] = "阿拉基的聖甲蟲"
L["The Key to Scholomance"] = "通靈學院的鑰匙"
L["The Sarkhoffs"] = "薩克霍夫一家"
L["Eva Sarkhoff asks you to punish Krastinov, recover his bag, and summon Kirtonos."] = "艾瓦·薩克霍夫要你懲罰卡斯迪諾夫、取回他的袋子，並召喚基爾圖諾斯。"
L["Eva Sarkhoff's grief had been waiting outside the school. Doctor Theolen Krastinov had butchered her family, and Jandice Barov guarded the next proof. When the Blood of Innocents called Kirtonos to the balcony, Scholomance answered with one of its own monsters, and Eva's vengeance finally had form."] = "艾瓦·薩克霍夫的悲痛一直在學院外等待著。瑟爾林·卡斯迪諾夫教授殘殺了她的家人，而詹迪斯‧巴羅夫守著下一份證據。當無辜者之血將基爾圖諾斯召喚到陽台上時，通靈學院派出了它自己的一頭怪物來回應，艾瓦的復仇終於有了具體的形貌。"
L["Doctor Theolen Krastinov, the Butcher"] = "瑟爾林·卡斯迪諾夫教授"
L["Eva Sarkhoff"] = "艾瓦·薩克霍夫"
L["Krastinov's Bag of Horrors"] = "卡斯迪諾夫的恐懼之袋"
L["Kirtonos the Herald"] = "傳令官基爾圖諾斯"
L["Ras Frostwhisper"] = "萊斯·霜語"
L["Learn who Ras Frostwhisper was, restore the memory of his death, and face the lich in Scholomance."] = "了解萊斯·霜語的過去，重現他死亡時的記憶，並在通靈學院面對這名巫妖。"
L["Ras Frostwhisper was not born a lich. Magistrate Marduke and Artist Renfray helped recover the human truth beneath the monster: a keepsake, a memory at Menethil's Gift, and a ritual strong enough to pull Ras back toward mortality. In Scholomance, the keepsake made him vulnerable. Killing him ended a lich and returned a human head to Caer Darrow."] = "萊斯·霜語並非生來就是巫妖。馬杜克鎮長和畫家瑞弗蕾協助找回了這頭怪物底下屬於人類的真相：一件紀念品、一段在米奈希爾的禮物留下的記憶，以及一場強大到足以將萊斯拉回凡人之身的儀式。在通靈學院裡，這件紀念品讓他變得脆弱。殺死他不僅終結了一名巫妖，也將一顆人類的頭顱帶回了凱爾達隆。"
L["The Human, Ras Frostwhisper"] = "萊斯·霜語"
L["Magistrate Marduke"] = "馬杜克鎮長"
L["The Dying, Ras Frostwhisper"] = "亡靈萊斯·霜語"
L["Menethil's Gift"] = "米奈希爾的禮物"
L["Soulbound Keepsake"] = "禁錮靈魂的遺物"
L["The Lich, Ras Frostwhisper"] = "巫妖萊斯·霜語"
L["Barov Family Fortune"] = "巴羅夫家族的寶藏"
L["Recover the Barov deeds from Scholomance, then choose which heir becomes the last Barov."] = "從通靈學院取回巴羅夫家族的地契，然後選擇哪位繼承人將成為最後的巴羅夫。"
L["The Barov fortune was scattered through Scholomance in deeds to Brill, Tarren Mill, Southshore, and Caer Darrow. Alexi and Weldon each claimed the inheritance and each wanted the other dead. When the papers were recovered, the family matter became murder by proxy, and one brother's claim ended at the other's feet."] = "巴羅夫家族的財富，以布瑞爾、塔倫米爾、南海鎮和凱爾達隆的地契形式，散落在通靈學院各處。阿萊克斯與維爾頓各自宣稱擁有繼承權，也都巴不得對方去死。文件取回之後，這樁家務事就成了一場借刀殺人，其中一位兄弟的繼承權，最終斷送在另一人的腳下。"
L["Weldon Barov"] = "維爾頓·巴羅夫"
L["Alexi Barov"] = "阿萊克斯·巴羅夫"
L["The Last Barov"] = "巴羅夫的繼承人"
L["Near Ashenvale's northern border, the Howling Vale is full of wolf-men that should not be there. Sentinel Melyria Frostshadow believes the Tome of Mel'Thandris may explain why.\n\nFollow Velinde Starsong's trail from Ashenvale to Darnassus, Ratchet, Booty Bay, and Duskwood. The scythe's story is not tidy, but it is one of Classic's clearest windows into the first mysteries of the worgen."] = "在梣谷北方邊境附近，狼嚎谷裡滿是不該出現在那裡的狼人。哨兵梅麗瑞亞·霜影相信，《梅爾薩蘭迪斯之書》或許能解釋原因。\n\n循著維琳德·星歌的足跡，從梣谷前往達納蘇斯、棘齒城、藏寶海灣與暮色森林。這把鐮刀的故事並不完整，卻是經典版中最能清楚窺見狼人最初謎團的窗口之一。"
L["Ashenvale / Darnassus / The Barrens / Stranglethorn Vale / Duskwood"] = "梣谷 / 達納蘇斯 / 貧瘠之地 / 荊棘谷 / 暮色森林"
L["The Howling Vale"] = "狼嚎谷"
L["Sentinel Melyria Frostshadow"] = "哨兵梅麗瑞亞·霜影"
L["Forest Song, Ashenvale"] = "林歌神殿（梣谷）"
L["the Howling Vale, Ashenvale"] = "狼嚎谷（梣谷）"
L["the Warrior's Terrace, Darnassus"] = "戰士區，達納蘇斯"
L["the Sentinels' bunkhouse, Darnassus"] = "哨兵宿舍，達納蘇斯"
L["Ratchet, The Barrens"] = "棘齒城（貧瘠之地）"
L["Booty Bay, Stranglethorn Vale"] = "藏寶海灣（荊棘谷）"
L["Darkshire Town Hall, Duskwood"] = "夜色鎮市政廳，暮色森林"
L["Roland's Doom, Duskwood"] = "羅蘭之墓（暮色森林）"
L["Study the Tome of Mel'Thandris and learn why worgen have appeared near the Felwood border."] = "研讀《梅爾薩蘭迪斯之書》，查明狼人為何會出現在費伍德森林邊境附近。"
L["The Tome of Mel'Thandris did not give a plain report. It showed Velinde Starsong praying for help against demons and receiving the Scythe of Elune in answer. The worgen in the Howling Vale were no local accident. They were tied to a night elf priestess, a weapon, and a call that had gone wrong."] = "《梅爾薩蘭迪斯之書》並沒有給出直白的記述。書中描繪了維琳德·星歌祈求援助以對抗惡魔，而她得到的回應就是伊露恩之鐮。狼嚎谷的狼人並非當地的意外，而是與一位夜精靈女祭司、一件武器，以及一次出了差錯的召喚緊緊相連。"
L["Velinde Starsong"] = "維琳德·星歌"
L["Carry Melyria's concern to Darnassus and search Velinde's stored effects."] = "將梅麗瑞亞的憂慮帶到達納蘇斯，並搜查維琳德存放的遺物。"
L["Darnassus remembered Velinde as a trusted priestess, not a villain. Thyn'tel Bladeweaver opened her stored belongings, and the journal inside changed the search from a military report into a missing-person trail. Velinde had used the scythe, lost control of the worgen, and disappeared while seeking help far from Ashenvale."] = "在達納蘇斯，人們記得的維琳德是一位值得信賴的女祭司，而非惡人。塞恩提爾·刃紋打開了她存放的物品，裡頭的日記讓這次搜查從軍事報告變成了尋找失蹤者的線索。維琳德曾使用那把鐮刀，卻失去了對狼人的控制，並在遠離梣谷尋求援助時下落不明。"
L["Velinde's Effects"] = "維琳德的日記"
L["Thyn'tel Bladeweaver"] = "塞恩提爾·刃紋"
L["Across the Sea"] = "渡海而去"
L["Follow Velinde's travel records from Ratchet to Booty Bay and onto the roads north."] = "循著維琳德的旅行紀錄，從棘齒城前往藏寶海灣，再踏上北方的道路。"
L["Velinde's journal sent the trail across the world instead of deeper into Ashenvale. Ratchet remembered her passage to Booty Bay, and Booty Bay's caravan records pointed north toward Duskwood. The scythe had crossed continents, leaving only ship ledgers, goblin memory, and a road through dangerous country."] = "維琳德的日記讓線索橫跨世界，而非更深入梣谷。棘齒城的人記得她搭船前往藏寶海灣，而藏寶海灣的商隊紀錄則指向北方的暮色森林。那把鐮刀跨越了大陸，只留下船運帳本、哥布林的記憶，以及一條穿越險地的道路。"
L["The Barrens Port"] = "貧瘠之地的港口"
L["Passage to Booty Bay"] = "藏寶海灣的航道"
L["Wharfmaster Dizzywig"] = "碼頭管理員迪茲維格"
L["The Caravan Road"] = "商隊通路"
L["Caravaneer Ruzzgot"] = "旅行者拉茲戈特"
L["The Carevin Family"] = "卡爾文家族"
L["Ask Darkshire's records and the Carevin family what they know about worgen in Duskwood."] = "查閱夜色鎮的紀錄，並詢問卡爾文家族對暮色森林的狼人知道些什麼。"
L["Darkshire had no clean record of Velinde, but it had worgen. Clerk Daltry pointed to Jonathan Carevin, whose family made a business of hunting the forest's monsters. Carevin's suspicion gave way to a practical bargain: if the trail led into Roland's Doom, then any answer found there should be shared with Darkshire."] = "夜色鎮沒有關於維琳德的明確紀錄，卻有狼人。書記員達爾塔指點你去找喬納森·卡爾文，他的家族以獵殺森林中的怪物為業。卡爾文起初心存疑慮，後來談成了一筆務實的交易：如果線索通往羅蘭之墓，那麼在那裡找到的任何答案，都必須與夜色鎮分享。"
L["Jonathan Carevin"] = "喬納森·卡爾文"
L["Answered Questions"] = "回覆珊蒂斯"
L["Return to Darnassus with what the Duskwood cave revealed about Velinde and the scythe."] = "帶著暮色森林洞穴中揭露的維琳德與鐮刀之事，返回達納蘇斯。"
L["Roland's Doom gave no triumphant recovery, only signs of what the scythe had unleashed and where Velinde's trail had broken. Thyn'tel accepted the report with gratitude and unease. The worgen could be contained for now, but the Scythe of Elune remained out of night elf hands, waiting for another chapter."] = "羅蘭之墓並沒有帶來凱旋般的尋回，只留下鐮刀所釋放之物的痕跡，以及維琳德的蹤跡在何處中斷。塞恩提爾帶著感激與不安接受了這份報告。狼人暫時可以得到控制，但伊露恩之鐮仍不在夜精靈手中，等待著下一個篇章。"
L["Travel to Darkshore and speak with Zidormi outside Lor'danel to view the time before the burning of Teldrassil."] = "前往黑海岸，與洛丹諾外的希朵米交談，即可檢視泰達希爾焚毀之前的時期。"
L["Play or replay this scenario from Archivist Sylvia in Orgrimmar's Valley of Wisdom. If you still have the original quest, begin with High Overlord Saurfang in Grommash Hold."] = "向奧格瑪智慧谷的文獻管理員希薇亞開啟此事件，即可遊玩或重玩。如果你仍保有原始任務，請從葛羅瑪許堡的薩魯法爾霸王開始。"
L["Complete Stay of Execution, then follow the path you chose: loyalists continue with Nathanos Blightcaller in Grommash Hold, while rebels continue with Lor'themar Theron at the Dranosh'ar Blockade outside Orgrimmar."] = "完成「阻止行刑」後，依你選擇的路線繼續：效忠派前往葛羅瑪許堡找納薩諾斯‧凋零者，叛亂派則前往奧格瑪外的德拉諾沙封鎖線找洛索瑪‧塞隆。"
L["Speak with Highlord Bolvar Fordragon in the Ring of Fates, Oribos, and follow the Torghast campaign until the Anduin and Kingsmourne vision. If Bolvar no longer offers the chain, the game has already moved this character past it."] = "與命運之環（奧睿博司）的大領主伯瓦爾‧弗塔根交談，並跟隨托迦司的戰役任務，直到出現安杜因與王之哀傷的幻象。如果伯瓦爾不再提供這系列任務，代表遊戲已讓此角色跳過了這段劇情。"
L["Secrets of Uldaman"] = "奧達曼的秘密"
L["The Badlands dig site is more than a ruin full of troggs and Dark Iron dwarves. Uldaman holds titan records, old dwarven fears, and relics that both factions are willing to chase through the dust.\n\nFollow Hammertoe's warning, the Shattered Necklace, and the Platinum Discs to uncover what the Titans left beneath the stone."] = "荒蕪之地的挖掘場，可不只是一座擠滿穴居人與黑鐵矮人的廢墟。奧達曼藏著泰坦的紀錄、矮人古老的恐懼，以及兩大陣營都願意在塵土中追逐的遺物。\n\n循著鐵趾的警告、破碎的項鏈與白金圓盤，揭開泰坦留在岩石之下的秘密。"
L["Badlands / Ironforge / Orgrimmar / Thunder Bluff / Uldaman"] = "荒蕪之地 / 鐵爐堡 / 奧格瑪 / 雷霆崖 / 奧達曼"
L["A Sign of Hope"] = "一線希望"
L["Crumpled Map"] = "弄皺的地圖"
L["Hammertoe's Digsite, Badlands"] = "鐵趾挖掘場（荒蕪之地）"
L["the outer Uldaman caves, Badlands"] = "奧達曼外圍洞穴，荒蕪之地"
L["Angor Fortress, Badlands"] = "苦痛堡壘（荒蕪之地）"
L["Galgann Firehammer's chamber, Uldaman"] = "加加恩‧火錘的房間，奧達曼"
L["the Mystic Ward, Ironforge"] = "秘法區（鐵爐堡）"
L["Droffers and Son Salvage, Orgrimmar"] = "德洛佛父子回收站，奧格瑪"
L["near Revelosh's chamber, Uldaman"] = "魯維羅什的房間附近，奧達曼"
L["the treasure chamber beyond Archaedas, Uldaman"] = "阿扎達斯後方的寶藏室，奧達曼"
L["the Vault, Ironforge"] = "金庫，鐵爐堡"
L["Hammertoe's Warning"] = "鐵趾的警告"
L["Find Hammertoe Grez, stop the Shadowforge search, and recover the titan-inscribed Tablet of Will."] = "找到鐵趾格雷茲，阻止暗爐的搜索行動，並取回刻有泰坦銘文的意志石板。"
L["A crumpled map turned a dig-site rumor into a rescue. Hammertoe Grez had been taken into Uldaman because he knew too much about titan relics and Dark Iron plans. His amulet reached Ironforge, Belgrum sent you against Ambassador Infernus, and the Tablet of Will was recovered before the Shadowforge could turn titan knowledge into stronger golems."] = "一張皺巴巴的地圖，讓挖掘場的傳聞變成了一場救援。鐵趾格雷茲被抓進奧達曼，因為他對泰坦遺物和黑鐵矮人的計畫知道得太多。他的護符被送到了鐵爐堡，貝爾格魯姆派你去對付因弗納斯大使，並趕在暗爐將泰坦知識用來打造更強大的魔像之前，奪回了意志石板。"
L["Prospector Ryedol"] = "勘察員雷杜爾"
L["Amulet of Secrets"] = "鐵趾的護符"
L["Hammertoe Grez"] = "鐵趾格雷茲"
L["Prospect of Faith"] = "鐵趾的遺願"
L["Passing Word of a Threat"] = "亡者的警告"
L["Historian Karnik"] = "史學家卡尼克"
L["An Ambassador of Evil"] = "邪惡的使者"
L["The Lost Tablets of Will"] = "意志石板"
L["The Shattered Necklace"] = "破碎的項鏈"
L["Trace the broken necklace through Uldaman's gems, journals, and power source."] = "透過奧達曼的寶石、日誌與能量源，追查那條斷裂項鏈的來龍去脈。"
L["The shattered necklace made Uldaman personal in two different ways. Alliance characters traced Talvash's old work and restored the piece through gems and Archaedas' power source. Horde characters followed Droffers and Son Salvage into a bargain with Jarkal Mossmeld. Either way, the dungeon became a puzzle of ruby, sapphire, topaz, and a construct's heart."] = "破碎的項鏈以兩種不同的方式，讓奧達曼與你切身相關。聯盟角色追溯塔瓦斯昔日的研究，並藉由寶石和阿扎達斯的能量源修復了項鏈。部落角色則跟著德洛佛父子回收站的線索，與加卡爾談成一筆交易。無論是哪一邊，這座地城都成了一道由紅寶石、藍寶石、黃玉，以及一顆構造體之心組成的謎題。"
L["Shattered Necklace"] = "破碎的項鏈"
L["Lore for a Price"] = "昂貴的知識"
L["Talvash del Kissel"] = "塔瓦斯德·基瑟爾"
L["Back to Uldaman"] = "回到奧達曼"
L["Find the Gems"] = "尋找寶石"
L["Restoring the Necklace"] = "修復項鏈"
L["Necklace Recovery"] = "搜尋項鏈"
L["Dran Droffers"] = "德蘭·杜佛斯"
L["Necklace Recovery, Take 2"] = "搜尋項鏈，再來一次"
L["Translating the Journal"] = "翻譯日記"
L["Remains of a Paladin"] = "聖騎士的遺體"
L["Jarkal Mossmeld"] = "加卡爾"
L["Find the Gems and Power Source"] = "尋找寶貝"
L["Deliver the Gems"] = "運送寶石"
L["Necklace Recovery, Take 3"] = "項鏈任務的終結"
L["The Platinum Discs"] = "白金圓盤"
L["Defeat Archaedas, consult the stone watcher, and carry the miniature discs to your faction's scholar."] = "擊敗阿扎達斯，請教石之守望者，並將微型圓盤帶給你所屬陣營的學者。"
L["Behind Archaedas, the Discs of Norgannon spoke with the calm weight of titan memory. They named the Creators, the Earthen, and the deep history beneath dwarven stone. The portable discs went from Uldaman to Ironforge or Thunder Bluff, where scholars understood that the find was not only treasure. It was origin."] = "在阿扎達斯身後，諾甘農圓盤以泰坦記憶那份沉靜的分量開口。它們提到了造物者、土靈，以及矮人岩石底下深藏的歷史。可攜式圓盤從奧達曼被送往鐵爐堡或雷霆崖，學者們在那裡明白，這項發現不只是寶藏，而是起源。"
L["Discs of Norgannon"] = "諾甘農圓盤"
L["High Explorer Magellas"] = "資深探險家麥格拉斯"
L["Mourning Rise"] = "悼念高地"
L["The Stonevault"] = "石庫"
L["Korgran has cared for Mourning Rise longer than his failing memory can reliably hold. The memorial grounds still need tending, kobolds have begun looting the dead, and Urtago is trying to help him hand over a duty he is not ready to lose.\n\nFollow Korgran through the last traditions of his post: honoring the fallen, forging a lantern, and choosing how an earthen says farewell."] = "柯葛蘭照看悼念高地的時間，已經久到他日漸衰退的記憶都無法確切記住。紀念地仍需要打理，狗頭人開始洗劫亡者，而烏塔戈正試著協助他交出這份他還沒準備好放下的職責。\n\n跟隨柯葛蘭完成他職守的最後幾項傳統：緬懷逝者、鍛造一盞燈籠，並選擇一位土靈該如何道別。"
L["Isle of Dorn"] = "多恩島"
L["Before I Depart"] = "我離開之前"
L["Korgran"] = "柯葛蘭"
L["Mourning Rise, Isle of Dorn"] = "悼念高地（多恩島）"
L["Optional breadcrumb: To Mourning Rise may point you here first. The story itself begins with Korgran at Mourning Rise."] = "選擇性的引導任務：「前往悼念高地」可能會先將你指引到這裡。故事本身則從悼念高地的柯葛蘭開始。"
L["Korgran knows his mind is fading, but the Rise still needs a caretaker. Help him and Urtago drive out the kobolds, honor the fallen, and prepare the lantern that will carry his final choice."] = "柯葛蘭知道自己的心智正逐漸衰退，但高地仍需要一位看守者。協助他和烏塔戈趕走狗頭人、緬懷逝者，並準備那盞將承載他最終抉擇的燈籠。"
L["Korgran still called himself caretaker of Mourning Rise, even as Urtago quietly did more and more of the work. Together you cleared kobolds from the memorial, recovered what they had stolen, and saw how often Korgran lost the thread of the present. The duties that defined him were slipping away.\n\nWhen the time came, Korgran chose one more tradition. He forged a lantern, searched for a lost earthen, cleaned ashes from the memorial, and walked toward the coast with Urtago beside him. His farewell was not treated as defeat. It was a final act of care, made in the place he had guarded for so long."] = "柯葛蘭仍自稱是悼念高地的看守者，儘管烏塔戈已默默接手了越來越多的工作。你們一起清除了紀念地的狗頭人，找回了被偷走的東西，也看見柯葛蘭有多常與當下脫節。那些定義了他的職責，正一點一滴地從他身上流失。\n\n時候到了，柯葛蘭選擇再完成一項傳統。他鍛造了一盞燈籠，尋找一位失落的土靈，清理紀念地上的灰燼，然後在烏塔戈的陪伴下走向海岸。他的道別並沒有被視為失敗，而是在他守護了如此之久的地方，最後一次付出的關懷。"
L["Honor Their Memories"] = "榮耀他們的回憶"
L["Urtago"] = "烏塔戈"
L["You No Take Plunder!"] = "你！不能！拿走！劫掠品！"
L["Laws Apply to All"] = "一視同仁的法律"
L["The Great Collapse"] = "大崩塌"
L["Cutting the Wick"] = "修剪燭芯"
L["Who Runs This Fine Establishment?"] = "這個好地方的負責人是誰？"
L["One More Tradition"] = "重現傳統"
L["The Forging of Memories"] = "鍛造記憶"
L["The Last Journey"] = "最後的旅程"
L["The Lost Earthen"] = "走失的土靈"
L["A Change of Tradition"] = "改變傳統"
L["Tools of Declaration"] = "宣示工具"
L["Cleansing Ashes"] = "淨化灰燼"
L["As He Departs"] = "他的離開"
L["The Weight of Duty"] = "責任的重量"
L["Stay a While"] = "稍坐片刻"
L["Ruby Life Pools"] = "晶紅生命之池"
L["At the Ruby Lifeshrine, Veritistrasz asks for something rare in an adventurer's life: time. No army waits, no world-ending machine is counting down, and no one needs a hundred trophies from the local wildlife.\n\nSit with an old red dragon in dwarf form, listen to what he remembers, and help him face the name he has spent ages trying not to say."] = "在晶紅生命聖殿，維里提斯卓茲向你提出了一個冒險者生涯中難得的請求：時間。沒有大軍等著你，沒有毀滅世界的機器在倒數，也沒有人需要你從當地野生動物身上弄來一百件戰利品。\n\n陪一頭化身為矮人的老紅龍坐一會兒，聽聽他記得的往事，並幫助他面對那個他多年來一直不願說出口的名字。"
L["The Waking Shores"] = "甦醒海岸"
L["Veritistrasz"] = "維里提斯卓茲"
L["Ruby Lifeshrine, The Waking Shores"] = "晶紅生命聖殿（甦醒海岸）"
L["Obsidian Citadel, The Waking Shores"] = "黑曜龍堡（甦醒海岸）"
L["Veritistrasz only asks you to sit, listen, and look out over the Waking Shores. What begins as memory becomes grief, and a hidden diary gives him one last truth to carry."] = "維里提斯卓茲只請你坐下、聆聽，並眺望甦醒海岸。起初的回憶逐漸化為悲傷，而一本藏起來的日記，讓他得以帶著最後一個真相繼續前行。"
L["Veritistrasz sat at the Ruby Lifeshrine and asked you to stay. His stories moved gently at first: old homes, old meals, the strange way places change when you are gone too long. Then the memories turned toward the black dragonflight, toward the friend he loved, and toward the betrayal that broke both his family and his certainty.\n\nLater, a damaged diary from the Obsidian Citadel brought the name he could not reach: Distyia. It did not undo what happened, but it gave his grief shape. Veritistrasz remembered the person beneath the corruption, and for a moment the old wound was not quite so alone."] = "維里提斯卓茲坐在晶紅生命聖殿，請你留下來陪他。他的故事起初十分溫和：舊日的家、從前的餐點，以及離開太久之後，那些地方奇妙的變化。接著，回憶轉向了黑龍軍團，轉向他所愛的朋友，也轉向那場摧毀了他的家庭與信念的背叛。\n\n後來，一本來自黑曜龍堡的破損日記，帶回了那個他始終說不出口的名字：迪絲緹婭。它無法挽回已經發生的事，卻讓他的悲傷有了形體。維里提斯卓茲記起了腐化之下真正的她，有那麼一刻，這道舊傷似乎不再那麼孤單。"
L["Memories"] = "回憶"
L["Memories Revived"] = "重生的回憶"
L["Partially Destroyed Diary"] = "部分損毀的日記"
L["Runas the Shamed"] = "『蒙羞者』魯那斯"
L["Azurewing Repose is under pressure from withered nightborne, hungry leyline abuse, and a prince who sees dragons as a resource to drain. In the middle of it all is Runas, a withered exile who still has just enough wit, shame, and courage left to choose who he wants to be.\n\nBegin with Stellagosa's search for the missing whelpling and follow Runas through one last useful, heartbreaking day."] = "蒼翼之憩正承受著重重壓力：凋萎的夜裔精靈、貪婪濫用地脈的行為，還有一位將巨龍視為可供榨取資源的王子。身處這一切中心的是魯那斯——一位遭到放逐的凋萎者，他仍保有剛好足夠的機智、羞恥心與勇氣，去選擇自己想成為什麼樣的人。\n\n從斯黛拉苟莎尋找失蹤幼龍開始，跟隨魯那斯度過最後一個有用又令人心碎的日子。"
L["Azsuna"] = "艾蘇納"
L["Eye of Azshara"] = "艾薩拉之眼"
L["Azurewing Repose, Azsuna"] = "蒼翼之憩（艾蘇納）"
L["Stellagosa sends you after a missing whelpling and you meet Runas, a withered exile who knows the Repose's enemies better than anyone wants to admit."] = "斯黛拉苟莎派你去尋找一隻失蹤的幼龍，你因此遇見了魯那斯。這位遭到放逐的凋萎者對蒼翼之憩的敵人瞭若指掌，熟悉的程度超乎任何人願意承認的地步。"
L["Stellagosa's missing whelpling led you to Runas the Shamed, a withered nightborne with a sharp tongue and a hunger he could barely hold back. He had been cast out, diminished, and written off, but he still understood the leylines, the withered, and the danger gathering around Azurewing Repose.\n\nRunas helped you recover the whelpling and find Stellagosa, even as his own cravings returned. He was not safe. He knew it. Still, he kept choosing to help."] = "斯黛拉苟莎失蹤的幼龍，將你引向了『蒙羞者』魯那斯。這名凋萎的夜裔精靈說話尖酸刻薄，體內的飢渴幾乎壓抑不住。他遭到驅逐、日漸衰弱、被眾人放棄，卻依然了解地脈、了解凋萎者，也明白蒼翼之憩周圍正在聚集的危險。\n\n魯那斯幫你救回了幼龍，也找到了斯黛拉苟莎，即使他自己的渴求又再度襲來。他並不安全，他自己也知道。但他仍一次又一次選擇伸出援手。"
L["The Consumed"] = "受害的幼龍"
L["Mana-Drained Whelpling"] = "法力枯竭的幼龍"
L["Projection of Senegos"] = "賽諾苟斯的幻象"
L["Runas Knows the Way"] = "魯那斯帶路"
L["The Hunger Returns"] = "飢火難遏"
L["Leyline Abuse"] = "濫用地脈"
L["The Nightborne Prince"] = "夜裔親王"
L["Runas guides you into the prince's territory, bargains with his own hunger, and helps expose what the nightborne are doing to the dragons."] = "魯那斯帶你潛入王子的領地，一邊與自己的飢渴討價還價，一邊協助揭露夜裔精靈對巨龍的所作所為。"
L["Runas knew the prince's camp from the inside: the habits, the arrogance, and the weak points. With his guidance, you sabotaged the nightborne, stole what you needed, and found Stellagosa alive but endangered. Runas kept laughing, kept deflecting, and kept moving because stopping would mean feeling the pull of the hunger too clearly.\n\nBy the time you returned to Azurewing Repose, Runas had given the dragons what they needed most: a path to strike back before the prince could feast on them."] = "魯那斯對王子的營地瞭若指掌：那裡的習慣、傲慢與弱點。在他的引導下，你破壞了夜裔精靈的行動，奪走了所需之物，並找到了斯黛拉苟莎——她還活著，卻身陷險境。魯那斯不停地笑、不停地轉移話題、不停地前進，因為一旦停下來，他就會清楚感受到飢渴的拉扯。\n\n當你回到蒼翼之憩時，魯那斯已經給了巨龍們最需要的東西：一條能在王子吞噬他們之前發動反擊的道路。"
L["You Scratch My Back..."] = "你幫了我的忙…"
L["Still Alive"] = "龍命猶存"
L["Hunger's End"] = "飢渴末路"
L["Khadgar and Stellagosa rally the defense. Runas spends his last strength making sure his final hours matter."] = "卡德加與斯黛拉苟莎召集眾人展開防禦。魯那斯則用盡最後的力氣，確保自己的最後時光有所意義。"
L["The nightborne assault reached Azurewing Repose. Khadgar, Stellagosa, and the blue dragons fought to protect Senegos while the withered closed in. Runas was almost out of time. He knew what was coming, and he chose to spend his last clear moments helping instead of hiding.\n\nAt the end, he thanked you for letting his final hours mean something. Then the hunger took him. The victory at Azurewing Repose came with a quiet loss, and Runas the Shamed earned a better name than the one he had carried."] = "夜裔精靈的攻勢抵達了蒼翼之憩。在凋萎者步步逼近之際，卡德加、斯黛拉苟莎和藍龍們奮戰保護賽諾苟斯。魯那斯的時間已所剩無幾。他知道接下來會發生什麼，於是選擇用最後清醒的時刻幫忙，而不是躲藏。\n\n最後，他感謝你讓他的最後時光有了意義。接著，飢渴吞噬了他。蒼翼之憩的勝利伴隨著一份無聲的失去，而『蒙羞者』魯那斯也贏得了一個比他背負已久的稱號更好的名字。"
L["Feasting on the Dragon"] = "今天的主菜是龍"
L["On the Brink"] = "生死邊緣"
L["Cursed to Wither"] = "詛咒下的枯萎"
L["Rhea's Last Egg"] = "瑞亞的最後一顆蛋"
L["Blackrock Caverns"] = "黑石洞穴"
L["In the Badlands, a red dragon hides behind a simple name and a very dangerous plan. Rhea wants to save the future of the black dragonflight from Deathwing's madness, and she needs samples, secrecy, and one gnome scientist who is just strange enough to help.\n\nFollow Rhea's work from Lethlor Ravine to the Hidden Clutch, then stay for the Badlands locals arguing over what really happened when Deathwing came."] = "在荒蕪之地，一頭紅龍藏身於一個簡單的名字與一個極其危險的計畫背後。瑞亞想從死亡之翼的瘋狂中拯救黑龍軍團的未來，為此她需要樣本、保密，以及一位古怪到剛好願意幫忙的地精科學家。\n\n跟隨瑞亞的研究，從萊瑟羅峽谷一路前往隱藏的窩巢，然後別急著離開，聽聽荒蕪之地的居民爭論死亡之翼來襲那天究竟發生了什麼事。"
L["Badlands"] = "荒蕪之地"
L["Cataclysm"] = "浩劫與重生"
L["First Sample: Wild Eggs"] = "最初的樣本:野生的蛋"
L["Rhea"] = "莉雅"
L["Lethlor Ravine, Badlands"] = "萊瑟羅峽谷（荒蕪之地）"
L["Easily Swayed"] = "搖擺不定"
L["Dolph Blastus"] = "道夫‧布拉斯特斯"
L["A Strange Request"] = "奇怪的要求"
L["Fuselight, Badlands"] = "熔絲火光山間營地（荒蕪之地）"
L["Agmond's End, Badlands"] = "埃格蒙德的營地（荒蕪之地）"
L["Dustwind Dig, Badlands"] = "塵風挖掘場（荒蕪之地）"
L["Bloodwatcher Point, Badlands"] = "血腥看守者之尖（荒蕪之地）"
L["Scar of the Worldbreaker, Badlands"] = "碎界者之痕（荒蕪之地）"
L["The Maker's Terrace, Badlands"] = "造物者遺跡（荒蕪之地）"
L["New Kargath, Badlands"] = "新卡加斯（荒蕪之地）"
L["Rhea's Work"] = "瑞亞的研究"
L["If Rhea does not offer these quests yet, complete the Fuselight intro through A Strange Request first."] = "如果瑞亞還沒有提供這些任務，請先完成熔絲火光山間營地的入門任務，直到「奇怪的要求」為止。"
L["Rhea asks for black dragon samples and slowly reveals why she is risking everything in the Badlands."] = "瑞亞請你收集黑龍的樣本，並慢慢揭露她為何要在荒蕪之地賭上一切。"
L["Rhea's errands looked like field work at first: wild eggs, whelps, implanted eggs, and a strange fog that hid more than geography. Then she revealed the truth. She was Rheastrasza, a red dragon trying to rescue the future of the black dragonflight before Deathwing's corruption consumed it forever.\n\nThe samples were not trophies. They were the last chance to create an uncorrupted black dragon egg."] = "瑞亞交代的差事起初看起來就像野外調查：野生的龍蛋、幼龍、被植入的龍蛋，以及一陣掩蓋的不只是地形的怪霧。接著她揭露了真相：她是瑞亞斯塔薩，一頭紅龍，想趕在死亡之翼的腐化永遠吞噬黑龍軍團之前，拯救它的未來。\n\n這些樣本並非戰利品，而是創造一顆未受腐化黑龍蛋的最後機會。"
L["Second Sample: Whelps"] = "第二個樣本:小龍"
L["Lifting the Veil"] = "揭露面紗"
L["Third Sample: Implanted Eggs"] = "第三個樣本:移花接木的蛋"
L["Rhea Revealed"] = "莉雅的真面目"
L["The Venerable Doctor Blam"] = "可敬的碰啪博士"
L["The Hidden Clutch"] = "隱秘窩巢"
L["Dr. Blam takes over the science. Alliance and Horde routes split through rival dig sites before converging on the clutch Rhea is trying to protect."] = "碰啪博士接手了科學研究。聯盟與部落的路線分別經過彼此競爭的挖掘場，最後匯聚於瑞亞想要保護的窩巢。"
L["Dr. Hieronymus Blam was exactly the kind of scientist Rhea needed: brilliant, excitable, and only partly reassuring. His work sent you through trogg trouble, dusty titan ruins, and faction rivalries at Dustwind Dig or Bloodwatcher Point. Stone watchers, ancient games, and old machinery all became part of the same desperate experiment.\n\nEverything pointed back to one thing: a hidden clutch that Deathwing could not be allowed to find."] = "海洛馬斯‧碰啪博士正是瑞亞需要的那種科學家：才華洋溢、容易激動，而且只能讓人放心一半。他的研究讓你一路應付穴居人的麻煩、探索積滿塵土的泰坦遺跡，並在塵風挖掘場或血腥看守者之尖捲入陣營之爭。石之守望者、古老的遊戲和舊機械，全都成了同一場孤注一擲的實驗的一部分。\n\n一切都指向同一件事：一個絕不能讓死亡之翼找到的隱藏窩巢。"
L["Troggish Troubles"] = "穴居怪麻煩"
L["Dr. Hieronymus Blam"] = "海洛馬斯‧碰啪博士"
L["Dustwind Dig"] = "塵風挖掘場"
L["Bloodwatcher Point"] = "血腥看守者之尖"
L["All's Fair in Love, War, and Archaeology"] = "在愛、戰爭和考古學中一切平等"
L["Lead Prospector Durdin"] = "首席勘察員杜爾丁"
L["It's Not About History, It's About Power"] = "和歷史無關，重要的是力量"
L["High Examiner Tae'thelan Bloodwatcher"] = "高階審查員泰瑟連‧血腥看守者"
L["The Warden's Pawn"] = "衛兵兵卒"
L["The Sentinel's Pawn"] = "哨兵兵卒"
L["The Warden's Game"] = "衛兵遊戲"
L["Stone Slab"] = "石板"
L["The Sentinel's Game"] = "哨兵遊戲"
L["Marble Slab"] = "大理石板"
L["Ancient Protectors"] = "遠古保衛者"
L["The Titans' Trove"] = "泰坦的珍寶"
L["Return to Blam"] = "回去找碰啪"
L["Trove of the Watchers"] = "守望者寶庫"
L["Into the Dragon's Mouth"] = "進入龍之口"
L["New Kargath"] = "新卡加斯"
L["Rheastrasza's Gift"] = "莉雅史卓莎的禮物"
L["Rhea gathers unlikely guards for the clutch, but Deathwing's shadow falls over the plan before the egg can be safe."] = "瑞亞為窩巢召集了一群意想不到的守衛，但在龍蛋安全之前，死亡之翼的陰影已籠罩了整個計畫。"
L["Rhea's defense force was improvised in true Badlands fashion. Alliance adventurers recruited Eric, Baelog, and Olaf. Horde adventurers recruited Amakkar, Jurrix, and Gargal. The work was strange, dangerous, and somehow hopeful.\n\nThen Deathwing came. The clutch was exposed, Rhea's plan became a sacrifice, and the last egg had to survive without the dragon who had made it possible."] = "瑞亞的防衛部隊以道地的荒蕪之地風格臨時拼湊而成。聯盟冒險者招募了艾瑞克、貝洛格和奧拉夫，部落冒險者則招募了阿瑪卡、朱瑞克斯和加戈爾。這份工作古怪又危險，卻不知怎地充滿了希望。\n\n接著，死亡之翼來了。窩巢曝光，瑞亞的計畫化為一場犧牲，而最後一顆蛋必須在失去那頭成就它的巨龍之後，獨自存活下去。"
L["The Swift, the Fierce, and the Stout"] = "迅捷、兇猛、健壯"
L["Eric, the Utility Dwarf"] = "艾利克，有用的矮人"
L["Eric \"The Swift\""] = "迅捷的艾瑞克"
L["Baelog, the Glass Cannon"] = "貝洛格，玻璃大砲"
L["Baelog"] = "貝洛格"
L["Olaf, the Big Fella'"] = "奧拉夫，大塊頭"
L["Olaf"] = "奧拉夫"
L["The Wrath of a Dragonflight"] = "龍群之怒"
L["Their Hunt Continues"] = "繼續狩獵"
L["The Sorrow and the Fury"] = "悲傷與狂怒"
L["The Bad Dogs"] = "壞傢伙們"
L["Amakkar, Jack of All Trades"] = "樣樣通的阿瑪卡"
L["Amakkar"] = "阿瑪卡"
L["Jurrix the Striker"] = "『打擊者』朱瑞克斯"
L["Jurrix Whitemane"] = "朱瑞克斯‧白鬃"
L["Gargal, the Behemoth"] = "巨獸加戈爾"
L["Gargal"] = "加戈爾"
L["The Egg Lives On"] = "倖存的龍蛋"
L["Dr. Blam reveals Rhea's final deception and the secret she preserved: one uncorrupted black dragon egg."] = "碰啪博士揭露了瑞亞最後的騙局，以及她所保住的秘密：一顆未受腐化的黑龍蛋。"
L["Deathwing believed he had destroyed Rhea's work. Dr. Blam revealed the truth: Rhea had hidden the real egg and left a false trail behind. Her last act was not only sacrifice, but misdirection.\n\nThe egg lived. Somewhere beyond Deathwing's reach, the future black dragon Wrathion had a chance to exist."] = "死亡之翼以為他已經摧毀了瑞亞的心血。碰啪博士揭露了真相：瑞亞早已將真正的龍蛋藏了起來，只留下一條假線索。她最後的行動不只是犧牲，更是一場聲東擊西。\n\n龍蛋活了下來。在死亡之翼觸及不到的某處，未來的黑龍怒西昂有了誕生的機會。"
L["Devastation"] = "毀滅"
L["The Day that Deathwing Came"] = "死亡之翼降臨的那一天"
L["Theldurin, Lucien, and Martek each explain how they personally survived Deathwing. The stories get less reliable and much funnier as they go."] = "塞爾杜林、盧希恩和馬特克各自講述他們如何親身從死亡之翼的手下倖存。故事越講越不可靠，也越來越好笑。"
L["After the tragedy of Rhea's story, the Badlands gave you its strangest form of grief relief: three locals trying to outdo each other with increasingly impossible versions of the day Deathwing came. Theldurin punched the Destroyer. Lucien improved the story. Martek improved it even more.\n\nNone of it was reliable history. All of it was Badlands truth: when the world breaks, sometimes people survive by turning terror into a story they can laugh at."] = "在瑞亞的悲劇之後，荒蕪之地用它最奇特的方式為你排解悲傷：三位當地人爭相講述死亡之翼來襲那天的故事，一個版本比一個版本更不可思議。塞爾杜林一拳揍了毀滅者，盧希恩把故事加油添醋，馬特克又添得更誇張。\n\n這些全都不是可靠的歷史，卻全都是荒蕪之地的真相：當世界破碎時，人們有時正是靠著把恐懼變成能一笑置之的故事，才得以活下去。"
L["Theldurin the Lost"] = "『迷失者』塞爾杜林"
L["The Day that Deathwing Came: The Real Story"] = "死亡之翼降臨的那一天：真正的故事"
L["Lucien Tosselwrench"] = "盧希恩‧槍穗"
L["The Day that Deathwing Came: What Really Happened"] = "死亡之翼降臨的那一天:實際發生的故事"
L["Martek the Exiled"] = "『流放者』馬特克"
L["A Blue Dawn"] = "藍色黎明"
L["The Azure Vault"] = "蒼藍密庫"
L["The blue dragonflight survived Malygos, the Nexus War, and years of grief by scattering across Azeroth. Kalecgos can lead an Aspect's flight again, but only if the blues choose to become a family instead of a memory.\n\nAnswer Kalecgos's call, search for the lost blue dragons, and help each branch decide whether there is still a home worth returning to."] = "藍龍軍團熬過了瑪里苟斯、魔樞之戰與多年的悲痛，靠的是分散到艾澤拉斯各地。卡雷苟斯能夠再次率領守護巨龍的軍團，但前提是藍龍們願意選擇成為一個家族，而不只是一段回憶。\n\n回應卡雷苟斯的召喚，尋找失散的藍龍，並幫助每一支族系決定，是否還有一個值得回去的家。"
L["The Azure Span / Thaldraszus / Azeroth"] = "蒼藍高地 / 薩爪祖斯 / 艾澤拉斯"
L["Keeper of the Ossuary"] = "骨窖看守者"
L["The Azure Archives, The Azure Span"] = "蒼藍檔案館，蒼藍高地"
L["Algeth'ar Academy, Thaldraszus"] = "阿爾蓋薩學院（薩爪祖斯）"
L["Borean Tundra"] = "北風凍原"
L["Crystalsong Forest"] = "水晶之歌森林"
L["Booty Bay, The Cape of Stranglethorn"] = "藏寶海灣（荊棘谷海角）"
L["Kalecgos begins at the Veiled Ossuary, where memories of Sindragosa, Malygos, Azuregos, and Senegos show how much the blue dragonflight has lost."] = "卡雷苟斯從隱蔽骨窖開始著手，那裡關於辛德拉苟莎、瑪里苟斯、艾索雷苟斯與賽諾苟斯的回憶，訴說著藍龍軍團失去了多少。"
L["Kalecgos called you to the Veiled Ossuary to help tend the memories of the blue dragonflight. With Senegos and Azuregos drawn into the work, the archives became more than a vault. They became a place to face what the blues had survived: Malygos, Sindragosa, exile, war, and the long habit of grieving separately.\n\nBy the time the first memories returned, Kalecgos understood the real task. The flight could not be restored by duty alone. The missing blues had to be found, heard, and invited home."] = "卡雷苟斯召你前往隱蔽骨窖，協助照料藍龍軍團的回憶。隨著賽諾苟斯和艾索雷苟斯也投入其中，這座檔案館不再只是一座寶庫，而成了直面藍龍們熬過的一切之地：瑪里苟斯、辛德拉苟莎、流亡、戰爭，以及長久以來各自哀悼的習慣。\n\n當最初的回憶重現時，卡雷苟斯明白了真正的任務。單憑責任，無法讓這支軍團重生。失散的藍龍必須被找到、被傾聽，並被邀請回家。"
L["On the Trail Again"] = "再次出發"
L["Senegos"] = "賽諾苟斯"
L["Rolling Out"] = "一球帶走"
L["Lest We Forget"] = "不忘先龍"
L["Archives Return"] = "重回文庫"
L["Azuregos's Support"] = "艾索雷苟斯的支援"
L["Unusual Disruptions"] = "不尋常的干擾"
L["Archival Arrival"] = "文庫見聞"
L["Where in the World is a Lost Blue Dragon?"] = "失聯的藍龍到底在哪裡？"
L["Sindragosa and Malygos's Rest"] = "辛德拉苟莎和瑪里苟斯的長眠"
L["Memories of Sindragosa and Malygos"] = "辛德拉苟莎和瑪里苟斯的回憶"
L["The Search for Blue Dragons"] = "搜尋藍龍"
L["Kalecgos begins the search in earnest, naming the scattered blues and sending you across Azeroth to bring their stories back together."] = "卡雷苟斯正式展開搜尋，列出散居各地的藍龍名字，並派你走遍艾澤拉斯，讓他們的故事重新匯聚。"
L["The archives gave Kalecgos names, but names were not enough. The missing blues had built separate lives, separate loyalties, and separate ways of surviving. Some were hiding from pain. Some were trapped in old debts. Some had made peace with never returning.\n\nKalecgos chose to ask rather than command. The blue dragonflight's renewal would be a gathering, not a summons."] = "檔案館給了卡雷苟斯名字，但光有名字還不夠。失散的藍龍各自建立了不同的生活、不同的忠誠，以及不同的生存之道。有些在逃避痛苦，有些被舊債所困，有些則早已坦然接受永不回來。\n\n卡雷苟斯選擇請求，而不是命令。藍龍軍團的重生將是一場聚首，而非一道召令。"
L["Lost Blue Dragons"] = "失聯的藍龍"
L["A Pair of Blue Dragons"] = "兩頭藍龍"
L["The Last Missing Blue Dragon"] = "最後一隻失聯的藍龍"
L["Those We Left Behind"] = "被遺棄的一群"
L["Lanigosa and Surigosa carry the cost of the Nexus War. Help them face a legacy that was never only history."] = "菈妮苟莎與蘇莉苟莎背負著魔樞之戰的代價。幫助她們面對一段從來不只是歷史的遺緒。"
L["Lanigosa's branch of the search led to Crystalsong Forest and Dustwallow Marsh, where grief had hardened around the Nexus War. The losses were personal, not abstract: shattered legacy, arcane echoes, old banners, and survivors who had learned to keep moving because stopping hurt too much.\n\nWith Surigosa and Kalecgos, you helped turn remembrance into release. The past was not erased, but it no longer had to be a prison."] = "菈妮苟莎這條搜尋路線通往水晶之歌森林與塵泥沼澤，那裡的悲傷早已圍繞著魔樞之戰凝結成形。這些失去並不抽象，而是切身之痛：破碎的傳承、秘法的回聲、陳舊的旗幟，以及那些學會不斷前進的倖存者——因為一旦停下來，就太痛了。\n\n你與蘇莉苟莎和卡雷苟斯一同將追憶化為釋懷。過去並未被抹去，卻不必再是一座牢籠。"
L["Lanigosa"] = "菈妮苟莎"
L["A Shattered Legacy"] = "破碎的遺物"
L["An Arcane Requiem"] = "秘法輓歌"
L["Creative Solutions"] = "創意解決方案"
L["Aftershocks"] = "震盪餘波"
L["Surigosa"] = "蘇莉苟莎"
L["The Sound of Silence"] = "寧靜的聲音"
L["Regrets in Crystal"] = "水晶之悔"
L["The Sullied Banner"] = "玷污旌旗"
L["A Moment of Reflection"] = "省思時刻"
L["No Such Thing as Bad Luck"] = "沒有什麼「運氣不好」"
L["Zeros has a debt problem in Booty Bay, which means the blue dragonflight's reunion briefly becomes paperwork, bribery, and goblin accounting."] = "澤羅斯在藏寶海灣欠了一屁股債，這意味著藍龍軍團的重聚，暫時變成了文書作業、賄賂和哥布林式的算帳。"
L["Zeros did not need a grand speech. He needed out of debt. Booty Bay wrapped the search in ledgers, bribes, crystals, and the kind of bargaining that makes dragons wonder why mortals invented money.\n\nSenegos treated the mess with surprising patience, and Zeros eventually found a path back that did not involve running forever. Even the ridiculous errands served the larger truth: every scattered blue had a different reason to stay away."] = "澤羅斯需要的不是慷慨激昂的演說，而是擺脫債務。藏寶海灣讓這場搜尋淹沒在帳本、賄賂、水晶，以及那種會讓巨龍納悶凡人究竟為何要發明金錢的討價還價之中。\n\n賽諾苟斯以出人意料的耐心處理這團混亂，而澤羅斯最終也找到了一條不必永遠逃亡的回家之路。就連這些荒唐的差事，也印證了一個更大的事實：每一頭散居各地的藍龍，都有各自不同的理由遠離家園。"
L["Zeros"] = "澤羅斯"
L["Information is King"] = "情報就是王道"
L["Blixrez Goodstitch"] = "布里克雷茲‧古斯提"
L["Anyway, I Started Bribing"] = "不管怎樣，先賄賂再說"
L["Zeroing Debt"] = "清償債務"
L["Money, Money, Money!"] = "錢、錢、錢！"
L["Crystals Shmystals"] = "水晶大亨"
L["Settled with the Baron"] = "與大財主達成協議"
L["The Booty Bay Journal"] = "藏寶海灣日報"
L["Booty Bay"] = "藏寶海灣"
L["Warm Winds and Water"] = "春江水暖"
L["Kalecgos visits Kirygosa in the Jade Forest, where care, quiet work, and old friendship matter more than speeches."] = "卡雷苟斯前往翠玉林探望琦麗苟莎。在那裡，關懷、安靜的工作與老朋友的情誼，比任何演說都來得重要。"
L["Kirygosa's life in the Jade Forest was not a problem to solve. It was a life she had made. Kalecgos helped with carp, deliveries, and simple comforts because asking someone to come home means respecting the home they already have.\n\nThe visit became a gentle reminder that the blue dragonflight could be wider than one place. Returning did not have to mean abandoning what had healed them."] = "琦麗苟莎在翠玉林的生活並不是一個待解決的問題，而是她親手打造的人生。卡雷苟斯幫忙處理鯉魚、送貨和一些簡單的生活小事，因為請一個人回家，就意味著要尊重對方已經擁有的家。\n\n這次探訪溫柔地提醒了大家：藍龍軍團的範圍可以不只侷限於一個地方。回歸，不一定代表要拋下那些治癒了他們的事物。"
L["Carp Care"] = "呵護鯉魚"
L["Kirygosa"] = "琦麗苟莎"
L["Self Care"] = "珍愛自己"
L["Local Deliveries"] = "鮮採直送"
L["Up, Up, and Home"] = "飛高高到家"
L["A Drink with Kalecgos"] = "與卡雷苟斯小酌"
L["A Protector of Magic"] = "魔法守護者"
L["Sindragosa's simulacrum sends you to Winterspring, where Haleh and old arcane tests reconnect another piece of blue dragon history."] = "辛德拉苟莎的擬像派你前往冬泉谷，在那裡，哈爾琳與古老的秘法試煉將藍龍歷史的另一塊碎片重新串連起來。"
L["The Winterspring branch carried a colder kind of memory. Sindragosa's simulacrum guided the search, Haleh guarded her own piece of the flight's story, and the work moved through tests, artifacts, and old magic rather than open confession.\n\nStill, the pattern held. The scattered blues were not being collected. They were being remembered, respected, and invited to stand together again."] = "冬泉谷這條路線承載著一種更冰冷的回憶。辛德拉苟莎的擬像引導著搜尋，哈爾琳守護著屬於她的那段軍團故事，而這項工作靠的是試煉、神器與古老的魔法，而非坦率的告白。\n\n儘管如此，模式依舊不變。散居各地的藍龍並不是被收集回來的，而是被記住、被尊重，並被邀請再次並肩而立。"
L["Winterspring"] = "冬泉谷"
L["Sindragosa"] = "辛德拉苟莎"
L["Test Subject"] = "測試文物"
L["Owl of a Sudden"] = "天外飛來一梟"
L["A Wyrm Rest"] = "讓飛龍休息"
L["Jade Forest"] = "翠玉林"
L["Blue is My Favorite Color"] = "藍色是我最愛的顏色"
L["Artifacts Abound"] = "大量文物"
L["Back with the Blues"] = "重返藍色陣營"
L["Reunited Again"] = "再度團結重聚"
L["The final trouble at the Veiled Ossuary brings the blues home, not as Malygos left them, but as a flight ready to choose its own future."] = "隱蔽骨窖的最後一場風波讓藍龍們回到了家。他們不再是瑪里苟斯所留下的模樣，而是一支準備好選擇自身未來的軍團。"
L["The Veiled Ossuary's final crisis forced the reunited blues to act together. Azuregos, Senegos, Sindragosa's memory, Kalecgos, and the scattered branches all carried different hurts, but they were no longer isolated by them.\n\nWhen the last conflict ended, the farewell was peaceful. The blue dragonflight did not return to the past. It stepped into a new dawn with grief acknowledged, bonds restored, and Kalecgos no longer trying to hold the flight together alone."] = "隱蔽骨窖的最後一場危機，迫使重聚的藍龍們同心協力。艾索雷苟斯、賽諾苟斯、辛德拉苟莎的回憶、卡雷苟斯，以及散居各地的族系，各自背負著不同的傷痛，卻不再因此而孤立。\n\n當最後的衝突結束時，道別是平靜的。藍龍軍團沒有回到過去，而是邁向新的黎明：悲傷得到正視，羈絆得以修復，卡雷苟斯也不必再獨自撐起整個軍團。"
L["Veiled Trouble"] = "隱蔽的麻煩"
L["Veiled Ossuary Chaos"] = "隱蔽骨窖的混沌"
L["Memories of Old"] = "昔日回憶"
L["What Still Remains"] = "揮之不去"
L["Swiftly to the Archives"] = "火速回到文庫"
L["The Last Conflict"] = "最終衝突"
L["A Peaceful Farewell"] = "平靜的告別"
